window.MT_DATA = window.MT_DATA || {};
window.MT_DATA['ar'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours dans le monde arabe, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Bienvenue à Amman","phrases":[{"fr":"Bienvenue à Amman !","tgt":"أَهْلًا وَسَهْلًا فِي عَمَّانَ!","ro":"Ahlan wa-sahlan fī ʿammāna!","lit":"bienvenue · [et] · aisance · à · Amman !"},{"fr":"Bonjour, je m'appelle Karim.","tgt":"صَبَاحُ الْخَيْرِ، اِسْمِي كَرِيمٌ.","ro":"Ṣabāḥu al-khayri, ismī Karīmun.","lit":"matin · [du] bien · nom-de-moi · Karim"},{"fr":"J'apprends l'arabe.","tgt":"أَتَعَلَّمُ الْعَرَبِيَّةَ.","ro":"Ataʿallamu al-ʿarabiyyata.","lit":"j'apprends · [l']arabe"},{"fr":"L'arabe est une belle langue.","tgt":"الْعَرَبِيَّةُ لُغَةٌ جَمِيلَةٌ.","ro":"Al-ʿarabiyyatu lughatun jamīlatun.","lit":"[l']arabe · langue · belle"},{"fr":"Amman est une grande ville.","tgt":"عَمَّانُ مَدِينَةٌ كَبِيرَةٌ.","ro":"ʿAmmānu madīnatun kabīratun.","lit":"Amman · ville · grande"},{"fr":"La citadelle est là-bas.","tgt":"الْقَلْعَةُ هُنَاكَ.","ro":"Al-qalʿatu hunāka.","lit":"[la] citadelle · là-bas"},{"fr":"Bonsoir, Leïla !","tgt":"مَسَاءُ الْخَيْرِ يَا لَيْلَى!","ro":"Masāʾu al-khayri yā Laylā!","lit":"soir · [du] bien · ô · Leïla !"},{"fr":"Il fait beau à Amman.","tgt":"الْجَوُّ جَمِيلٌ فِي عَمَّانَ.","ro":"Al-jawwu jamīlun fī ʿammāna.","lit":"[le] temps · beau · à · Amman"},{"fr":"Le livre est ici.","tgt":"الْكِتَابُ هُنَا.","ro":"Al-kitābu hunā.","lit":"[le] livre · ici"},{"fr":"À bientôt, Karim !","tgt":"إِلَى اللِّقَاءِ يَا كَرِيمُ!","ro":"Ilā al-liqāʾi yā Karīmu!","lit":"jusqu'à · [la] rencontre · ô · Karim !"}],"tip":{"title":"De droite à gauche, et des voyelles en petits signes","example":"Le livre est ici. — <b>الْكِتَابُ</b> هُنَا.","body":"Bienvenue dans l'arabe ! Première surprise : on écrit et on lit de droite à gauche, donc un livre arabe s'ouvre là où un livre français se termine. Deuxième surprise : l'alphabet note surtout les consonnes et les voyelles longues. Les voyelles courtes, a, i et ou, sont de tout petits signes posés au-dessus ou au-dessous des lettres : un petit trait au-dessus pour a, un petit trait au-dessous pour i, une minuscule boucle au-dessus pour ou. Prenons « al-kitabu », le livre : on voit les lettres k, t et b, avec un petit trait sous le k pour le son i, et un a long écrit en toutes lettres. Dans les journaux, ces petits signes disparaissent souvent, mais dans cette app ils sont toujours là pour vous guider, comme dans « ahlan », bienvenue, ou « hunaka », là-bas. Astuce : voyez ces petits signes comme des notes de musique qui disent comment chanter chaque consonne.","exampleRo":"Al-kitābu hunā.","lit":"[le] livre · ici","say":{"al-kitabu":"الْكِتَابُ","ahlan":"أَهْلًا","hunaka":"هُنَاكَ"}}},{"title":"Un hôtel au centre-ville","phrases":[{"fr":"Je suis étudiant à Amman.","tgt":"أَنَا طَالِبٌ فِي عَمَّانَ.","ro":"Anā ṭālibun fī ʿammāna.","lit":"moi · étudiant · à · Amman"},{"fr":"Je suis fatigué.","tgt":"أَنَا مُتْعَبٌ.","ro":"Anā mutʿabun.","lit":"moi · fatigué"},{"fr":"L'hôtel est près du centre-ville.","tgt":"الْفُنْدُقُ قَرِيبٌ مِنْ وَسَطِ الْمَدِينَةِ.","ro":"Al-funduqu qarībun min wasaṭi al-madīnati.","lit":"[l']hôtel · proche · de · centre · [de la] ville"},{"fr":"La chambre est propre.","tgt":"الْغُرْفَةُ نَظِيفَةٌ.","ro":"Al-ghurfatu naẓīfatun.","lit":"[la] chambre · propre"},{"fr":"L'employé de l'hôtel est gentil.","tgt":"مُوَظَّفُ الْفُنْدُقِ لَطِيفٌ.","ro":"Muwaẓẓafu al-funduqi laṭīfun.","lit":"employé · [de l']hôtel · gentil"},{"fr":"Le petit-déjeuner est délicieux.","tgt":"الْفُطُورُ لَذِيذٌ.","ro":"Al-fuṭūru ladhīdhun.","lit":"[le] petit-déjeuner · délicieux"},{"fr":"Je suis à l'hôtel.","tgt":"أَنَا فِي الْفُنْدُقِ.","ro":"Anā fī al-funduqi.","lit":"moi · dans · [l']hôtel"},{"fr":"Le prix de la chambre est raisonnable.","tgt":"سِعْرُ الْغُرْفَةِ مُنَاسِبٌ.","ro":"Siʿru al-ghurfati munāsibun.","lit":"prix · [de la] chambre · convenable"},{"fr":"Moi, c'est Sami, de Paris.","tgt":"أَنَا سَامِي مِنْ بَارِيسَ.","ro":"Anā Sāmī min Bārīsa.","lit":"moi · Sami · de · Paris"},{"fr":"L'ascenseur est là-bas.","tgt":"الْمِصْعَدُ هُنَاكَ.","ro":"Al-miṣʿadu hunāka.","lit":"[l']ascenseur · là-bas"}],"tip":{"title":"Pas de verbe être au présent","example":"Je suis étudiant à Amman. — <b>أَنَا طَالِبٌ</b> فِي عَمَّانَ.","body":"En arabe, au présent, le verbe être n'apparaît tout simplement pas dans la phrase. Pour dire « je suis étudiant », on pose côte à côte « ana », moi, et « talibun », étudiant : « ana talibun », littéralement moi étudiant. C'est ce qu'on appelle une phrase nominale, une phrase sans verbe. De la même façon, « al-funduqu qaribun » veut dire l'hôtel est proche, mot à mot : l'hôtel, proche. Et « ana fi al-funduqi » se comprend comme moi dans l'hôtel, donc je suis à l'hôtel. Le français a besoin de suis, es ou est, l'arabe s'en passe très bien. Astuce : imaginez que vous écrivez un télégramme où l'on ne garde que les mots utiles, et vous obtenez déjà de l'arabe correct.","exampleRo":"Anā ṭālibun fī ʿammāna.","lit":"moi · étudiant · à · Amman","say":{"ana":"أَنَا","talibun":"طَالِبٌ","ana talibun":"أَنَا طَالِبٌ","al-funduqu qaribun":"الْفُنْدُقُ قَرِيبٌ","ana fi al-funduqi":"أَنَا فِي الْفُنْدُقِ"}}},{"title":"Promenade au centre-ville","phrases":[{"fr":"Le centre-ville est bondé.","tgt":"وَسَطُ الْمَدِينَةِ مُزْدَحِمٌ.","ro":"Wasaṭu al-madīnati muzdaḥimun.","lit":"centre · [de la] ville · bondé"},{"fr":"Le thé est chaud.","tgt":"الشَّايُ سَاخِنٌ.","ro":"Ash-shāyu sākhinun.","lit":"[le] thé · chaud"},{"fr":"Le café est chaud aussi.","tgt":"الْقَهْوَةُ سَاخِنَةٌ أَيْضًا.","ro":"Al-qahwatu sākhinatun ayḍan.","lit":"[le] café · chaud · aussi"},{"fr":"La rue est longue.","tgt":"الشَّارِعُ طَوِيلٌ.","ro":"Ash-shāriʿu ṭawīlun.","lit":"[la] rue · longue"},{"fr":"Le marché est ouvert.","tgt":"السُّوقُ مَفْتُوحٌ.","ro":"As-sūqu maftūḥun.","lit":"[le] marché · ouvert"},{"fr":"Le restaurant est petit.","tgt":"الْمَطْعَمُ صَغِيرٌ.","ro":"Al-maṭʿamu ṣaghīrun.","lit":"[le] restaurant · petit"},{"fr":"Le pain est frais.","tgt":"الْخُبْزُ طَازَجٌ.","ro":"Al-khubzu ṭāzajun.","lit":"[le] pain · frais"},{"fr":"Le houmous est délicieux.","tgt":"الْحُمُّصُ لَذِيذٌ.","ro":"Al-ḥummuṣu ladhīdhun.","lit":"[le] houmous · délicieux"},{"fr":"Le falafel est bon marché.","tgt":"الْفَلَافِلُ رَخِيصَةٌ.","ro":"Al-falāfilu rakhīṣatun.","lit":"[le] falafel · bon-marché"},{"fr":"La nuit est calme.","tgt":"اللَّيْلُ هَادِئٌ.","ro":"Al-laylu hādiʾun.","lit":"[la] nuit · calme"}],"tip":{"title":"L'article « al- » et les lettres solaires","example":"Le thé est chaud. — <b>الشَّايُ</b> سَاخِنٌ.","body":"En arabe, l'article « al- » veut dire le, la et les à la fois, et il se colle au mot : « al-qahwa », le café, « al-kitab », le livre. Mais devant certaines consonnes, le son l disparaît et la consonne suivante se double. On les appelle les lettres solaires, parce que le mot soleil, « ash-shams », en fait partie : on ne dit pas al-shams mais « ash-shams ». Notre exemple, « ash-shayu sakhinun », se lit mot à mot : le thé, chaud, donc le thé est chaud. Comparez avec « al-qahwatu », le café, où le l reste bien audible : le q est une lettre lunaire, comme dans « al-qamar », la lune. D'autres lettres solaires sont s, n, t, d ou r, comme dans « as-suq », le marché, ou « an-nadil », le serveur. Astuce : si la langue touche les dents pour prononcer la première consonne, le l se fond dedans.","exampleRo":"Ash-shāyu sākhinun.","lit":"[le] thé · chaud","say":{"al-qahwa":"الْقَهْوَة","al-kitab":"الْكِتَاب","ash-shams":"الشَّمْس","ash-shayu sakhinun":"الشَّايُ سَاخِنٌ","al-qahwatu":"الْقَهْوَةُ","al-qamar":"الْقَمَر","as-suq":"السُّوق","an-nadil":"النَّادِل"}}},{"title":"Un taxi jaune","phrases":[{"fr":"Il est chauffeur de taxi.","tgt":"هُوَ سَائِقُ تَاكْسِي.","ro":"Huwa sāʾiqu tāksī.","lit":"lui · chauffeur · [de] taxi"},{"fr":"Elle est professeure.","tgt":"هِيَ مُعَلِّمَةٌ.","ro":"Hiya muʿallimatun.","lit":"elle · professeure"},{"fr":"Tu es gentil.","tgt":"أَنْتَ لَطِيفٌ.","ro":"Anta laṭīfun.","lit":"toi (masc.) · gentil"},{"fr":"Tu es gentille, Leïla.","tgt":"أَنْتِ لَطِيفَةٌ يَا لَيْلَى.","ro":"Anti laṭīfatun yā Laylā.","lit":"toi (fém.) · gentille · ô · Leïla"},{"fr":"Je suis pressé.","tgt":"أَنَا مُسْتَعْجِلٌ.","ro":"Anā mustaʿjilun.","lit":"moi · pressé"},{"fr":"Elle est d'Amman.","tgt":"هِيَ مِنْ عَمَّانَ.","ro":"Hiya min ʿammāna.","lit":"elle · de · Amman"},{"fr":"Elle est sur Rainbow Street.","tgt":"هِيَ فِي شَارِعِ الرَّيْنْبُو.","ro":"Hiya fī shāriʿi ar-raynbū.","lit":"elle · dans · rue · [le] Rainbow"},{"fr":"Tu es en retard, Rania.","tgt":"أَنْتِ مُتَأَخِّرَةٌ يَا رَانِيَا.","ro":"Anti mutaʾakhkhiratun yā Rāniyā.","lit":"toi (fém.) · en-retard · ô · Rania"},{"fr":"Moi, je suis prêt.","tgt":"أَنَا جَاهِزٌ.","ro":"Anā jāhizun.","lit":"moi · prêt"},{"fr":"Le taxi est jaune.","tgt":"التَّاكْسِي أَصْفَرُ.","ro":"At-tāksī aṣfaru.","lit":"[le] taxi · jaune"}],"tip":{"title":"Les pronoms : « ana, anta, anti, huwa, hiya »","example":"Tu es gentille, Leïla. — <b>أَنْتِ</b> لَطِيفَةٌ يَا لَيْلَى.","body":"Voici cinq petits mots qui vont vous servir partout. « Ana » veut dire je ou moi, « huwa » il ou lui, et « hiya » elle. Pour dire tu, l'arabe distingue l'homme et la femme : « anta » quand on parle à un homme, « anti » quand on parle à une femme. Notre exemple, « anti latifatun ya Layla », se lit : toi au féminin, gentille, ô Leïla. Le petit mot « ya » sert à interpeller quelqu'un, un peu comme notre ô ou eh. À un chauffeur de taxi, on dirait donc « anta latifun », et à Leïla « anti latifatun ». Et avec « huwa saiqu taksi », lui chauffeur de taxi, on obtient il est chauffeur de taxi. Astuce : « anta » et « anti » ne diffèrent que par la dernière voyelle, a pour un homme, i pour une femme, comme une petite signature.","exampleRo":"Anti laṭīfatun yā Laylā.","lit":"toi (fém.) · gentille · ô · Leïla","say":{"Ana":"أَنَا","huwa":"هُوَ","hiya":"هِيَ","anta":"أَنْتَ","anti":"أَنْتِ","anti latifatun ya Layla":"أَنْتِ لَطِيفَةٌ يَا لَيْلَى","ya":"يَا","anta latifun":"أَنْتَ لَطِيفٌ","anti latifatun":"أَنْتِ لَطِيفَةٌ","huwa saiqu taksi":"هُوَ سَائِقُ تَاكْسِي","ana, anta, anti, huwa, hiya":"أَنَا، أَنْتَ، أَنْتِ، هُوَ، هِيَ"}}},{"title":"Rencontres à Rainbow Street","phrases":[{"fr":"Il est jordanien, elle est jordanienne.","tgt":"هُوَ أُرْدُنِيٌّ وَهِيَ أُرْدُنِيَّةٌ.","ro":"Huwa urduniyyun wa-hiya urduniyyatun.","lit":"lui · jordanien · [et] · elle · jordanienne"},{"fr":"Karim est étudiant, Leïla est étudiante.","tgt":"كَرِيمٌ طَالِبٌ وَلَيْلَى طَالِبَةٌ.","ro":"Karīmun ṭālibun wa-Laylā ṭālibatun.","lit":"Karim · étudiant · [et] · Leïla · étudiante"},{"fr":"Le café est petit.","tgt":"الْمَقْهَى صَغِيرٌ.","ro":"Al-maqhā ṣaghīrun.","lit":"[le] café (lieu) · petit"},{"fr":"La ville est belle.","tgt":"الْمَدِينَةُ جَمِيلَةٌ.","ro":"Al-madīnatu jamīlatun.","lit":"[la] ville · belle"},{"fr":"Le professeur est français.","tgt":"الْمُعَلِّمُ فَرَنْسِيٌّ.","ro":"Al-muʿallimu faransiyyun.","lit":"[le] professeur · français"},{"fr":"La professeure est française.","tgt":"الْمُعَلِّمَةُ فَرَنْسِيَّةٌ.","ro":"Al-muʿallimatu faransiyyatun.","lit":"[la] professeure · française"},{"fr":"Le serveur est rapide.","tgt":"النَّادِلُ سَرِيعٌ.","ro":"An-nādilu sarīʿun.","lit":"[le] serveur · rapide"},{"fr":"La serveuse est rapide aussi.","tgt":"النَّادِلَةُ سَرِيعَةٌ أَيْضًا.","ro":"An-nādilatu sarīʿatun ayḍan.","lit":"[la] serveuse · rapide · aussi"},{"fr":"L'appartement est neuf.","tgt":"الشَّقَّةُ جَدِيدَةٌ.","ro":"Ash-shaqqatu jadīdatun.","lit":"[l']appartement · neuf"},{"fr":"Rainbow Street est très belle le soir.","tgt":"شَارِعُ الرَّيْنْبُو جَمِيلٌ جِدًّا فِي الْمَسَاءِ.","ro":"Shāriʿu ar-raynbū jamīlun jiddan fī al-masāʾi.","lit":"rue · [le] Rainbow · beau · très · dans · [le] soir"}],"tip":{"title":"Masculin et féminin : la terminaison en a","example":"Il est jordanien, elle est jordanienne. — هُوَ أُرْدُنِيٌّ وَهِيَ <b>أُرْدُنِيَّةٌ</b>.","body":"En arabe, comme en français, les noms et les adjectifs ont un genre. La bonne nouvelle, c'est que le féminin se fabrique presque toujours de la même façon : on ajoute la terminaison « -a » au masculin. « Talib », étudiant, devient « taliba », étudiante, et « jamil », beau, devient « jamila », belle. Cette terminaison s'écrit avec une lettre spéciale, un petit h coiffé de deux points, qu'on appelle ta marbuta. Dans notre exemple, « huwa urduniyyun wa hiya urduniyyatun », on lit : lui jordanien, et elle jordanienne. Attention, le genre ne correspond pas toujours au français : la rue, « ash-shari », est masculine en arabe. Astuce : quand vous entendez un a final, pensez féminin, comme dans « madina », la ville, ou « shaqqa », l'appartement.","exampleRo":"Huwa urduniyyun wa-hiya urduniyyatun.","lit":"lui · jordanien · [et] · elle · jordanienne","say":{"Talib":"طَالِب","taliba":"طَالِبَة","jamil":"جَمِيل","jamila":"جَمِيلَة","huwa urduniyyun wa hiya urduniyyatun":"هُوَ أُرْدُنِيٌّ وَهِيَ أُرْدُنِيَّةٌ","ash-shari":"الشَّارِع","madina":"مَدِينَة","shaqqa":"شَقَّة"}}},{"title":"Une pause au café","phrases":[{"fr":"Est-ce que tu es fatigué ?","tgt":"هَلْ أَنْتَ مُتْعَبٌ؟","ro":"Hal anta mutʿabun?","lit":"[question] · toi · fatigué ?"},{"fr":"Tu es jordanien ?","tgt":"هَلْ أَنْتَ أُرْدُنِيٌّ؟","ro":"Hal anta urduniyyun?","lit":"[question] · toi · jordanien ?"},{"fr":"Oui, je suis d'Amman.","tgt":"نَعَمْ، أَنَا مِنْ عَمَّانَ.","ro":"Naʿam, anā min ʿammāna.","lit":"oui · moi · de · Amman"},{"fr":"Du thé à la menthe ?","tgt":"شَايٌ بِالنَّعْنَاعِ؟","ro":"Shāyun bi-n-naʿnāʿi?","lit":"thé · avec · [la] menthe ?"},{"fr":"Oui, s'il te plaît.","tgt":"نَعَمْ، مِنْ فَضْلِكَ.","ro":"Naʿam, min faḍlika.","lit":"oui · de · faveur-de-toi"},{"fr":"Est-ce que c'est loin ?","tgt":"هَلْ هُوَ بَعِيدٌ؟","ro":"Hal huwa baʿīdun?","lit":"[question] · lui · loin ?"},{"fr":"Non, c'est vraiment tout près.","tgt":"لَا، هُوَ قَرِيبٌ جِدًّا.","ro":"Lā, huwa qarībun jiddan.","lit":"non · lui · proche · très"},{"fr":"Tu es étudiant ?","tgt":"أَنْتَ طَالِبٌ؟","ro":"Anta ṭālibun?","lit":"toi · étudiant ?"},{"fr":"Est-ce que tu es prête, Leïla ?","tgt":"هَلْ أَنْتِ جَاهِزَةٌ يَا لَيْلَى؟","ro":"Hal anti jāhizatun yā Laylā?","lit":"[question] · toi (fém.) · prête · ô · Leïla ?"},{"fr":"Est-ce que la knafeh est chaude ?","tgt":"هَلِ الْكُنَافَةُ سَاخِنَةٌ؟","ro":"Hali al-kunāfatu sākhinatun?","lit":"[question] · [la] knafeh · chaude ?"}],"tip":{"title":"Poser une question avec « hal »","example":"Est-ce que tu es fatigué ? — <b>هَلْ</b> أَنْتَ مُتْعَبٌ؟","body":"Pour poser une question fermée, celle qui attend oui ou non, l'arabe place le petit mot « hal » tout au début de la phrase. Il joue le rôle de notre est-ce que. « Anta mutabun » veut dire tu es fatigué, et « hal anta mutabun » veut dire est-ce que tu es fatigué ? Mot à mot : question, toi, fatigué. Rien d'autre ne change, ni l'ordre des mots ni les terminaisons. Dans la conversation, on peut aussi simplement faire monter la voix à la fin, comme en français : « anta talibun ? », tu es étudiant ? Devant un mot qui commence par l'article, « hal » prend un petit i pour faciliter la liaison : « hali al-kunafatu sakhinatun ? ». Pour répondre, « naam » veut dire oui et « la » veut dire non. Astuce : « hal », c'est un drapeau qu'on lève au début pour annoncer une question.","exampleRo":"Hal anta mutʿabun?","lit":"[question] · toi · fatigué ?","say":{"hal":"هَلْ","Anta mutabun":"أَنْتَ مُتْعَبٌ","hal anta mutabun":"هَلْ أَنْتَ مُتْعَبٌ","anta talibun ?":"أَنْتَ طَالِبٌ؟","hali al-kunafatu sakhinatun ?":"هَلِ الْكُنَافَةُ سَاخِنَةٌ؟","naam":"نَعَمْ","la":"لَا"}}},{"title":"Visite de la citadelle","phrases":[{"fr":"Voici la citadelle d'Amman.","tgt":"هَذِهِ قَلْعَةُ عَمَّانَ.","ro":"Hādhihi qalʿatu ʿammāna.","lit":"celle-ci · citadelle · [d']Amman"},{"fr":"C'est un monument ancien.","tgt":"هَذَا مَعْلَمٌ قَدِيمٌ.","ro":"Hādhā maʿlamun qadīmun.","lit":"ceci · monument · ancien"},{"fr":"Ce guide est jordanien.","tgt":"هَذَا الْمُرْشِدُ أُرْدُنِيٌّ.","ro":"Hādhā al-murshidu urduniyyun.","lit":"ce · [le] guide · jordanien"},{"fr":"Cette vue est magnifique.","tgt":"هَذَا الْمَنْظَرُ رَائِعٌ.","ro":"Hādhā al-manẓaru rāʾiʿun.","lit":"ce · [la] vue · magnifique"},{"fr":"Celle-ci, c'est Leïla.","tgt":"هَذِهِ لَيْلَى.","ro":"Hādhihi Laylā.","lit":"celle-ci · Leïla"},{"fr":"Celui-ci, c'est Karim.","tgt":"هَذَا كَرِيمٌ.","ro":"Hādhā Karīmun.","lit":"celui-ci · Karim"},{"fr":"Cette ville est ancienne.","tgt":"هَذِهِ الْمَدِينَةُ قَدِيمَةٌ.","ro":"Hādhihi al-madīnatu qadīmatun.","lit":"cette · [la] ville · ancienne"},{"fr":"C'est un billet d'entrée.","tgt":"هَذِهِ تَذْكِرَةُ دُخُولٍ.","ro":"Hādhihi tadhkiratu dukhūlin.","lit":"celle-ci · billet · [d']entrée"},{"fr":"Ce musée est petit.","tgt":"هَذَا الْمَتْحَفُ صَغِيرٌ.","ro":"Hādhā al-matḥafu ṣaghīrun.","lit":"ce · [le] musée · petit"},{"fr":"Cette photo est belle.","tgt":"هَذِهِ الصُّورَةُ جَمِيلَةٌ.","ro":"Hādhihi aṣ-ṣūratu jamīlatun.","lit":"cette · [la] photo · belle"}],"tip":{"title":"« Hadha » et « hadhihi » : ceci, celui-ci, celle-ci","example":"Cette ville est ancienne. — <b>هَذِهِ</b> الْمَدِينَةُ قَدِيمَةٌ.","body":"Pour montrer quelque chose, l'arabe utilise « hadha » pour le masculin et « hadhihi » pour le féminin. Suivis d'un nom sans article, ils forment une phrase complète : « hadha maalamun », ceci est un monument. Suivis d'un nom avec l'article, ils veulent dire ce ou cette : « hadhihi al-madinatu », cette ville. Notre exemple, « hadhihi al-madinatu qadimatun », se lit donc : cette, la ville, ancienne, c'est-à-dire cette ville est ancienne. Le choix dépend du genre du mot arabe, pas du mot français : « hadha al-manzaru », cette vue, car vue est masculin en arabe. Pour présenter quelqu'un, c'est aussi très pratique : « hadha Karimun », voici Karim, et « hadhihi Layla », voici Leïla. Astuce : « hadhihi » est plus long que « hadha », comme le féminin qui ajoute une syllabe.","exampleRo":"Hādhihi al-madīnatu qadīmatun.","lit":"cette · [la] ville · ancienne","say":{"hadha":"هَذَا","hadhihi":"هَذِهِ","hadha maalamun":"هَذَا مَعْلَمٌ","hadhihi al-madinatu":"هَذِهِ الْمَدِينَةُ","hadhihi al-madinatu qadimatun":"هَذِهِ الْمَدِينَةُ قَدِيمَةٌ","hadha al-manzaru":"هَذَا الْمَنْظَرُ","hadha Karimun":"هَذَا كَرِيمٌ","hadhihi Layla":"هَذِهِ لَيْلَى","Hadha":"هَذَا"}}},{"title":"Au restaurant de falafel","phrases":[{"fr":"Je ne suis pas fatigué.","tgt":"لَسْتُ مُتْعَبًا.","ro":"Lastu mutʿaban.","lit":"[je ne suis pas] · fatigué"},{"fr":"Le repas n'est pas cher.","tgt":"الطَّعَامُ لَيْسَ غَالِيًا.","ro":"Aṭ-ṭaʿāmu laysa ghāliyan.","lit":"[le] repas · [n'est pas] · cher"},{"fr":"Le restaurant n'est pas loin.","tgt":"الْمَطْعَمُ لَيْسَ بَعِيدًا.","ro":"Al-maṭʿamu laysa baʿīdan.","lit":"[le] restaurant · [n'est pas] · loin"},{"fr":"Je ne suis pas jordanien, je suis français.","tgt":"لَسْتُ أُرْدُنِيًّا، أَنَا فَرَنْسِيٌّ.","ro":"Lastu urduniyyan, anā faransiyyun.","lit":"[je ne suis pas] · jordanien · moi · français"},{"fr":"Le houmous n'est pas froid.","tgt":"الْحُمُّصُ لَيْسَ بَارِدًا.","ro":"Al-ḥummuṣu laysa bāridan.","lit":"[le] houmous · [n'est pas] · froid"},{"fr":"Tu n'es pas en retard.","tgt":"لَسْتَ مُتَأَخِّرًا.","ro":"Lasta mutaʾakhkhiran.","lit":"[tu n'es pas] · en-retard"},{"fr":"Elle n'est pas là.","tgt":"هِيَ لَيْسَتْ هُنَا.","ro":"Hiya laysat hunā.","lit":"elle · [n'est pas] · ici"},{"fr":"La table n'est pas libre.","tgt":"الطَّاوِلَةُ لَيْسَتْ فَارِغَةً.","ro":"Aṭ-ṭāwilatu laysat fārighatan.","lit":"[la] table · [n'est pas] · libre"},{"fr":"Ce n'est pas épicé.","tgt":"هَذَا لَيْسَ حَارًّا.","ro":"Hādhā laysa ḥārran.","lit":"ceci · [n'est pas] · épicé"},{"fr":"Leïla, tu n'as pas faim ?","tgt":"لَسْتِ جَائِعَةً يَا لَيْلَى؟","ro":"Lasti jāʾiʿatan yā Laylā?","lit":"[tu n'es pas] · affamée · ô · Leïla ?"}],"tip":{"title":"La négation de la phrase sans verbe : « laysa »","example":"Le repas n'est pas cher. — الطَّعَامُ <b>لَيْسَ</b> غَالِيًا.","body":"Puisqu'il n'y a pas de verbe être au présent, comment dire n'est pas ? L'arabe utilise un mot spécial, « laysa », qui veut dire ne pas être. Il se conjugue comme un petit verbe : « lastu » pour je ne suis pas, « lasta » pour tu n'es pas à un homme, « lasti » à une femme, « laysa » pour il n'est pas et « laysat » pour elle n'est pas. Notre exemple, « at-taamu laysa ghaliyan », se lit : le repas, n'est pas, cher. Remarquez le petit son an qui apparaît à la fin de l'adjectif après « laysa » : « baidun », loin, devient « laysa baidan », il n'est pas loin. De même, « ana mutabun », je suis fatigué, devient « lastu mutaban », je ne suis pas fatigué. Astuce : retenez d'abord « lastu », c'est la forme que vous utiliserez le plus pour parler de vous.","exampleRo":"Aṭ-ṭaʿāmu laysa ghāliyan.","lit":"[le] repas · [n'est pas] · cher","say":{"laysa":"لَيْسَ","lastu":"لَسْتُ","lasta":"لَسْتَ","lasti":"لَسْتِ","laysat":"لَيْسَتْ","at-taamu laysa ghaliyan":"الطَّعَامُ لَيْسَ غَالِيًا","baidun":"بَعِيدٌ","laysa baidan":"لَيْسَ بَعِيدًا","ana mutabun":"أَنَا مُتْعَبٌ","lastu mutaban":"لَسْتُ مُتْعَبًا"}}},{"title":"Mon appartement à Amman","phrases":[{"fr":"Voici mon appartement.","tgt":"هَذِهِ شَقَّتِي.","ro":"Hādhihi shaqqatī.","lit":"celle-ci · appartement-de-moi"},{"fr":"C'est mon livre.","tgt":"هَذَا كِتَابِي.","ro":"Hādhā kitābī.","lit":"ceci · livre-de-moi"},{"fr":"Ton livre est sur la table.","tgt":"كِتَابُكَ عَلَى الطَّاوِلَةِ.","ro":"Kitābuka ʿalā aṭ-ṭāwilati.","lit":"livre-de-toi · sur · [la] table"},{"fr":"Ma chambre est très petite.","tgt":"غُرْفَتِي صَغِيرَةٌ جِدًّا.","ro":"Ghurfatī ṣaghīratun jiddan.","lit":"chambre-de-moi · petite · très"},{"fr":"Ta chambre est grande.","tgt":"غُرْفَتُكَ كَبِيرَةٌ.","ro":"Ghurfatuka kabīratun.","lit":"chambre-de-toi · grande"},{"fr":"Sa maison est à Amman.","tgt":"بَيْتُهُ فِي عَمَّانَ.","ro":"Baytuhu fī ʿammāna.","lit":"maison-de-lui · à · Amman"},{"fr":"Sa cuisine à elle est moderne.","tgt":"مَطْبَخُهَا حَدِيثٌ.","ro":"Maṭbakhuhā ḥadīthun.","lit":"cuisine-d'elle · moderne"},{"fr":"Mon voisin est sympathique.","tgt":"جَارِي لَطِيفٌ.","ro":"Jārī laṭīfun.","lit":"voisin-de-moi · sympathique"},{"fr":"Leïla, ta fenêtre est ouverte.","tgt":"نَافِذَتُكِ مَفْتُوحَةٌ يَا لَيْلَى.","ro":"Nāfidhatuki maftūḥatun yā Laylā.","lit":"fenêtre-de-toi (fém.) · ouverte · ô · Leïla"},{"fr":"Mon balcon est ensoleillé.","tgt":"شُرْفَتِي مُشْمِسَةٌ.","ro":"Shurfatī mushmisatun.","lit":"balcon-de-moi · ensoleillé"}],"tip":{"title":"Les possessifs collés au nom","example":"Ton livre est sur la table. — <b>كِتَابُكَ</b> عَلَى الطَّاوِلَةِ.","body":"En arabe, mon, ton et son ne sont pas des mots séparés : ce sont de petites terminaisons collées à la fin du nom. Avec « kitab », livre, on obtient « kitabi », mon livre, « kitabuka », ton livre quand on parle à un homme, « kitabuki » quand on parle à une femme, « kitabuhu », son livre à lui, et « kitabuha », son livre à elle. Notre exemple, « kitabuka ala at-tawilati », se lit : livre de toi, sur la table, c'est-à-dire ton livre est sur la table. Avec un mot féminin en a, un t caché réapparaît : « ghurfa », chambre, devient « ghurfati », ma chambre, et « shaqqa » devient « shaqqati », mon appartement. Le français place le possessif devant, l'arabe le place derrière. Astuce : le i final, c'est moi, et le ka final, c'est toi.","exampleRo":"Kitābuka ʿalā aṭ-ṭāwilati.","lit":"livre-de-toi · sur · [la] table","say":{"kitab":"كِتَاب","kitabi":"كِتَابِي","kitabuka":"كِتَابُكَ","kitabuki":"كِتَابُكِ","kitabuhu":"كِتَابُهُ","kitabuha":"كِتَابُهَا","kitabuka ala at-tawilati":"كِتَابُكَ عَلَى الطَّاوِلَةِ","ghurfa":"غُرْفَة","ghurfati":"غُرْفَتِي","shaqqa":"شَقَّة","shaqqati":"شَقَّتِي"}}},{"title":"Les clés de l'appartement","phrases":[{"fr":"C'est le livre de l'étudiant.","tgt":"هَذَا كِتَابُ الطَّالِبِ.","ro":"Hādhā kitābu aṭ-ṭālibi.","lit":"ceci · livre · [de l']étudiant"},{"fr":"Voici la clé de l'appartement.","tgt":"هَذَا مِفْتَاحُ الشَّقَّةِ.","ro":"Hādhā miftāḥu ash-shaqqati.","lit":"ceci · clé · [de l']appartement"},{"fr":"La porte de la maison est verte.","tgt":"بَابُ الْبَيْتِ أَخْضَرُ.","ro":"Bābu al-bayti akhḍaru.","lit":"porte · [de la] maison · verte"},{"fr":"Le propriétaire de l'appartement est gentil.","tgt":"صَاحِبُ الشَّقَّةِ لَطِيفٌ.","ro":"Ṣāḥibu ash-shaqqati laṭīfun.","lit":"propriétaire · [de l']appartement · gentil"},{"fr":"Le loyer de l'appartement est raisonnable.","tgt":"إِيجَارُ الشَّقَّةِ مُنَاسِبٌ.","ro":"Ījāru ash-shaqqati munāsibun.","lit":"loyer · [de l']appartement · convenable"},{"fr":"La fenêtre de la cuisine est petite.","tgt":"نَافِذَةُ الْمَطْبَخِ صَغِيرَةٌ.","ro":"Nāfidhatu al-maṭbakhi ṣaghīratun.","lit":"fenêtre · [de la] cuisine · petite"},{"fr":"Le nom de la rue est difficile.","tgt":"اِسْمُ الشَّارِعِ صَعْبٌ.","ro":"Ismu ash-shāriʿi ṣaʿbun.","lit":"nom · [de la] rue · difficile"},{"fr":"Le toit de l'immeuble est grand.","tgt":"سَطْحُ الْعِمَارَةِ كَبِيرٌ.","ro":"Saṭḥu al-ʿimārati kabīrun.","lit":"toit · [de l']immeuble · grand"},{"fr":"Le salon de Karim est confortable.","tgt":"صَالَةُ كَرِيمٍ مُرِيحَةٌ.","ro":"Ṣālatu Karīmin murīḥatun.","lit":"salon · [de] Karim · confortable"},{"fr":"La chambre de Leïla est calme.","tgt":"غُرْفَةُ لَيْلَى هَادِئَةٌ.","ro":"Ghurfatu Laylā hādiʾatun.","lit":"chambre · [de] Leïla · calme"}],"tip":{"title":"Le complément du nom : « kitab at-talib »","example":"C'est le livre de l'étudiant. — هَذَا <b>كِتَابُ الطَّالِبِ</b>.","body":"Pour dire le livre de l'étudiant, le français utilise le petit mot de. L'arabe, lui, se contente de coller deux noms l'un derrière l'autre : « kitabu at-talibi », livre, l'étudiant. C'est ce qu'on appelle l'annexion. Une règle importante : le premier nom ne prend jamais l'article, c'est le second qui rend tout l'ensemble précis. On dit donc « miftahu ash-shaqqati », la clé de l'appartement, sans article devant miftah. Le second nom prend aussi une terminaison en i : « at-talibi », « ash-shaqqati ». Cela marche aussi avec un prénom : « ghurfatu Layla », la chambre de Leïla. Astuce : imaginez un petit train où seul le dernier wagon porte l'article, et c'est lui qui donne son sens précis à tout le convoi.","exampleRo":"Hādhā kitābu aṭ-ṭālibi.","lit":"ceci · livre · [de l']étudiant","say":{"kitabu at-talibi":"كِتَابُ الطَّالِبِ","miftahu ash-shaqqati":"مِفْتَاحُ الشَّقَّةِ","at-talibi":"الطَّالِبِ","ash-shaqqati":"الشَّقَّةِ","ghurfatu Layla":"غُرْفَةُ لَيْلَى","kitab at-talib":"كِتَابُ الطَّالِبِ"}}},{"title":"Questions au marché","phrases":[{"fr":"C'est quoi, ça ?","tgt":"مَا هَذَا؟","ro":"Mā hādhā?","lit":"quoi · ceci ?"},{"fr":"Qui est ce vendeur ?","tgt":"مَنْ هَذَا الْبَائِعُ؟","ro":"Man hādhā al-bāʾiʿu?","lit":"qui · ce · [le] vendeur ?"},{"fr":"Où est le marché ?","tgt":"أَيْنَ السُّوقُ؟","ro":"Ayna as-sūqu?","lit":"où · [le] marché ?"},{"fr":"C'est quand, le rendez-vous ?","tgt":"مَتَى الْمَوْعِدُ؟","ro":"Matā al-mawʿidu?","lit":"quand · [le] rendez-vous ?"},{"fr":"Comment vas-tu ?","tgt":"كَيْفَ حَالُكَ؟","ro":"Kayfa ḥāluka?","lit":"comment · état-de-toi ?"},{"fr":"Quel est le nom de ce café ?","tgt":"مَا اسْمُ هٰذَا الْمَقْهَى؟","ro":"Mā ismu hādhā l-maqhā?","lit":"quoi · nom · ce · [le] café ?"},{"fr":"Où sont les tomates ?","tgt":"أَيْنَ الطَّمَاطِمُ؟","ro":"Ayna aṭ-ṭamāṭimu?","lit":"où · [les] tomates ?"},{"fr":"Qui est cette dame ?","tgt":"مَنْ هَذِهِ السَّيِّدَةُ؟","ro":"Man hādhihi as-sayyidatu?","lit":"qui · cette · [la] dame ?"},{"fr":"Comment est le temps aujourd'hui ?","tgt":"كَيْفَ الْجَوُّ الْيَوْمَ؟","ro":"Kayfa al-jawwu al-yawma?","lit":"comment · [le] temps · [le] jour ?"},{"fr":"Où est le marchand de fruits ?","tgt":"أَيْنَ مَحَلُّ الْفَوَاكِهِ؟","ro":"Ayna maḥallu al-fawākihi?","lit":"où · boutique · [des] fruits ?"}],"tip":{"title":"Les mots interrogatifs : « ma, man, ayna, mata, kayfa »","example":"Comment vas-tu ? — <b>كَيْفَ</b> حَالُكَ؟","body":"Pour poser une question ouverte, l'arabe a cinq petits mots à connaître, toujours placés en tête de phrase. « Ma » veut dire quoi, « man » qui, « ayna » où, « mata » quand, et « kayfa » comment. Notre exemple, « kayfa haluka ? », se lit littéralement : comment, ton état ? C'est la façon la plus courante de demander comment ça va. Avec « ayna », on demande son chemin : « ayna as-suqu ? », où est le marché ? Avec « ma », on demande ce qu'est un objet : « ma hadha ? », c'est quoi, ça ? Et avec « man », on demande qui est quelqu'un : « man hadhihi as-sayyidatu ? », qui est cette dame ? Comme d'habitude, pas besoin du verbe être : le mot interrogatif suffit. Astuce : « man », avec un n, pour une personne, et « ma », sans n, pour une chose.","exampleRo":"Kayfa ḥāluka?","lit":"comment · état-de-toi ?","say":{"Ma":"مَا","man":"مَنْ","ayna":"أَيْنَ","mata":"مَتَى","kayfa":"كَيْفَ","kayfa haluka ?":"كَيْفَ حَالُكَ؟","ayna as-suqu ?":"أَيْنَ السُّوقُ؟","ma":"مَا","ma hadha ?":"مَا هَذَا؟","man hadhihi as-sayyidatu ?":"مَنْ هَذِهِ السَّيِّدَةُ؟","ma, man, ayna, mata, kayfa":"مَا، مَنْ، أَيْنَ، مَتَى، كَيْفَ"}}},{"title":"La routine du matin","phrases":[{"fr":"J'écris une lettre.","tgt":"أَكْتُبُ رِسَالَةً.","ro":"Aktubu risālatan.","lit":"j'écris · lettre"},{"fr":"Tu écris en arabe.","tgt":"تَكْتُبُ بِالْعَرَبِيَّةِ.","ro":"Taktubu bi-l-ʿarabiyyati.","lit":"tu écris · en · [l']arabe"},{"fr":"Karim écrit dans son cahier.","tgt":"يَكْتُبُ كَرِيمٌ فِي دَفْتَرِهِ.","ro":"Yaktubu Karīmun fī daftarihi.","lit":"il écrit · Karim · dans · cahier-de-lui"},{"fr":"Je bois du café le matin.","tgt":"أَشْرَبُ الْقَهْوَةَ فِي الصَّبَاحِ.","ro":"Ashrabu al-qahwata fī aṣ-ṣabāḥi.","lit":"je bois · [le] café · dans · [le] matin"},{"fr":"Elle écrit un court message.","tgt":"هِيَ تَكْتُبُ رِسَالَةً قَصِيرَةً.","ro":"Hiya taktubu risālatan qaṣīratan.","lit":"elle · elle écrit · message · court"},{"fr":"Je me réveille tôt.","tgt":"أَسْتَيْقِظُ مُبَكِّرًا.","ro":"Astayqiẓu mubakkiran.","lit":"je me réveille · tôt"},{"fr":"Il mange du pain et du houmous.","tgt":"يَأْكُلُ خُبْزًا وَحُمُّصًا.","ro":"Yaʾkulu khubzan wa-ḥummuṣan.","lit":"il mange · pain · [et] · houmous"},{"fr":"Je lis le journal.","tgt":"أَقْرَأُ الْجَرِيدَةَ.","ro":"Aqraʾu al-jarīdata.","lit":"je lis · [le] journal"},{"fr":"Leïla boit un café à la cardamome.","tgt":"تَشْرَبُ لَيْلَى قَهْوَةً بِالْهَيْلِ.","ro":"Tashrabu Laylā qahwatan bi-l-hayli.","lit":"elle boit · Leïla · café · avec · [la] cardamome"},{"fr":"Il écrit son nom.","tgt":"يَكْتُبُ اسْمَهُ.","ro":"Yaktubu ismahu.","lit":"il écrit · nom-de-lui"}],"tip":{"title":"Le verbe au présent : « aktubu, taktubu, yaktubu »","example":"Karim écrit dans son cahier. — <b>يَكْتُبُ</b> كَرِيمٌ فِي دَفْتَرِهِ.","body":"Voici enfin des verbes ! En arabe, le présent se forme en ajoutant une petite syllabe au début du verbe. Avec le verbe écrire, on obtient « aktubu », j'écris, « taktubu », tu écris, qui veut aussi dire elle écrit, et « yaktubu », il écrit. Le a du début, c'est je, le ta, c'est tu ou elle, et le ya, c'est il. Notre exemple, « yaktubu Karimun fi daftarihi », se lit : il écrit Karim dans son cahier. Remarquez l'ordre : en arabe, le verbe vient souvent avant le sujet. C'est pareil pour boire : « ashrabu », je bois, et « tashrabu Layla », Leïla boit. Pas besoin non plus de pronom, le verbe contient déjà la personne. Astuce : écoutez bien le tout début du verbe, c'est lui qui vous dit qui fait l'action.","exampleRo":"Yaktubu Karīmun fī daftarihi.","lit":"il écrit · Karim · dans · cahier-de-lui","say":{"aktubu":"أَكْتُبُ","taktubu":"تَكْتُبُ","yaktubu":"يَكْتُبُ","yaktubu Karimun fi daftarihi":"يَكْتُبُ كَرِيمٌ فِي دَفْتَرِهِ","ashrabu":"أَشْرَبُ","tashrabu Layla":"تَشْرَبُ لَيْلَى","aktubu, taktubu, yaktubu":"أَكْتُبُ، تَكْتُبُ، يَكْتُبُ"}}},{"title":"Livres et bureaux","phrases":[{"fr":"Le livre est sur le bureau.","tgt":"الْكِتَابُ عَلَى الْمَكْتَبِ.","ro":"Al-kitābu ʿalā al-maktabi.","lit":"[le] livre · sur · [le] bureau"},{"fr":"L'écrivain est à la bibliothèque.","tgt":"الْكَاتِبُ فِي الْمَكْتَبَةِ.","ro":"Al-kātibu fī al-maktabati.","lit":"[l']écrivain · dans · [la] bibliothèque"},{"fr":"La librairie est près du marché.","tgt":"الْمَكْتَبَةُ قَرِيبَةٌ مِنَ السُّوقِ.","ro":"Al-maktabatu qarībatun mina as-sūqi.","lit":"[la] librairie · proche · de · [le] marché"},{"fr":"J'écris un livre.","tgt":"أَكْتُبُ كِتَابًا.","ro":"Aktubu kitāban.","lit":"j'écris · livre"},{"fr":"Le bureau de poste est fermé.","tgt":"مَكْتَبُ الْبَرِيدِ مُغْلَقٌ.","ro":"Maktabu al-barīdi mughlaqun.","lit":"bureau · [de la] poste · fermé"},{"fr":"C'est un écrivain jordanien.","tgt":"هُوَ كَاتِبٌ أُرْدُنِيٌّ.","ro":"Huwa kātibun urduniyyun.","lit":"lui · écrivain · jordanien"},{"fr":"Ses livres sont célèbres.","tgt":"كُتُبُهُ مَشْهُورَةٌ.","ro":"Kutubuhu mashhūratun.","lit":"livres-de-lui · célèbres"},{"fr":"Le message est écrit en arabe.","tgt":"الرِّسَالَةُ مَكْتُوبَةٌ بِالْعَرَبِيَّةِ.","ro":"Ar-risālatu maktūbatun bi-l-ʿarabiyyati.","lit":"[le] message · écrit · en · [l']arabe"},{"fr":"Le bureau de Leïla est bien rangé.","tgt":"مَكْتَبُ لَيْلَى مُرَتَّبٌ.","ro":"Maktabu Laylā murattabun.","lit":"bureau · [de] Leïla · rangé"},{"fr":"J'aime la bibliothèque.","tgt":"أُحِبُّ الْمَكْتَبَةَ.","ro":"Uḥibbu al-maktabata.","lit":"j'aime · [la] bibliothèque"}],"tip":{"title":"La racine de trois lettres : k, t, b","example":"Le livre est sur le bureau. — <b>الْكِتَابُ</b> عَلَى <b>الْمَكْتَبِ</b>.","body":"Voici le grand secret de l'arabe : la plupart des mots sont construits sur une racine de trois consonnes, qui porte une idée. Avec k, t et b, l'idée est celle de l'écriture. « Kataba » veut dire il a écrit, « kitab » un livre, « katib » un écrivain, « maktab » un bureau, c'est-à-dire l'endroit où l'on écrit, et « maktaba » une bibliothèque ou une librairie. Notre exemple, « al-kitabu ala al-maktabi », se lit : le livre, sur le bureau, et les deux mots importants partagent la même racine. Même « maktub », écrit, en fait partie. Le début en « ma » indique souvent un lieu : « matam », le restaurant, vient de la racine du verbe manger. Astuce : quand vous découvrez un mot nouveau, cherchez ses trois consonnes, et vous devinerez souvent son sens.","exampleRo":"Al-kitābu ʿalā al-maktabi.","lit":"[le] livre · sur · [le] bureau","say":{"Kataba":"كَتَبَ","kitab":"كِتَاب","katib":"كَاتِب","maktab":"مَكْتَب","maktaba":"مَكْتَبَة","al-kitabu ala al-maktabi":"الْكِتَابُ عَلَى الْمَكْتَبِ","maktub":"مَكْتُوب","matam":"مَطْعَم"}}},{"title":"Se déplacer en ville","phrases":[{"fr":"Je vais au centre-ville.","tgt":"أَذْهَبُ إِلَى وَسَطِ الْمَدِينَةِ.","ro":"Adhhabu ilā wasaṭi al-madīnati.","lit":"je vais · vers · centre · [de la] ville"},{"fr":"Le taxi est dans la rue.","tgt":"التَّاكْسِي فِي الشَّارِعِ.","ro":"At-tāksī fī ash-shāriʿi.","lit":"[le] taxi · dans · [la] rue"},{"fr":"Je rentre du marché.","tgt":"أَرْجِعُ مِنَ السُّوقِ.","ro":"Arjiʿu mina as-sūqi.","lit":"je reviens · de · [le] marché"},{"fr":"Les clés sont sur la table.","tgt":"الْمَفَاتِيحُ عَلَى الطَّاوِلَةِ.","ro":"Al-mafātīḥu ʿalā aṭ-ṭāwilati.","lit":"[les] clés · sur · [la] table"},{"fr":"Je vais de l'hôtel à la citadelle.","tgt":"أَذْهَبُ مِنَ الْفُنْدُقِ إِلَى الْقَلْعَةِ.","ro":"Adhhabu mina al-funduqi ilā al-qalʿati.","lit":"je vais · de · [l']hôtel · vers · [la] citadelle"},{"fr":"Le chauffeur est dans la voiture.","tgt":"السَّائِقُ فِي السَّيَّارَةِ.","ro":"As-sāʾiqu fī as-sayyārati.","lit":"[le] chauffeur · dans · [la] voiture"},{"fr":"Le bus va à l'université.","tgt":"الْحَافِلَةُ تَذْهَبُ إِلَى الْجَامِعَةِ.","ro":"Al-ḥāfilatu tadhhabu ilā al-jāmiʿati.","lit":"[le] bus · elle va · vers · [l']université"},{"fr":"Le sac est sur le siège.","tgt":"الْحَقِيبَةُ عَلَى الْمَقْعَدِ.","ro":"Al-ḥaqībatu ʿalā al-maqʿadi.","lit":"[le] sac · sur · [le] siège"},{"fr":"Leïla arrive de l'aéroport.","tgt":"تَصِلُ لَيْلَى مِنَ الْمَطَارِ.","ro":"Taṣilu Laylā mina al-maṭāri.","lit":"elle arrive · Leïla · de · [l']aéroport"},{"fr":"Nous sommes dans le taxi.","tgt":"نَحْنُ فِي التَّاكْسِي.","ro":"Naḥnu fī at-tāksī.","lit":"nous · dans · [le] taxi"}],"tip":{"title":"Les prépositions : « fi, ala, min, ila »","example":"Je vais de l'hôtel à la citadelle. — أَذْهَبُ <b>مِنَ</b> الْفُنْدُقِ <b>إِلَى</b> الْقَلْعَةِ.","body":"Quatre petits mots suffisent pour se repérer en ville. « Fi » veut dire dans ou à, « ala » sur, « min » de ou depuis, et « ila » vers ou jusqu'à. Notre exemple, « adhhabu mina al-funduqi ila al-qalati », se lit : je vais, de l'hôtel, vers la citadelle. Notez que « min » devient « mina » devant l'article, simplement pour faciliter la prononciation. Après une préposition, le nom prend une terminaison en i : « fi ash-sharii », dans la rue, « ala at-tawilati », sur la table. Ces mots fonctionnent très bien sans verbe : « nahnu fi at-taksi », nous dans le taxi, veut dire nous sommes dans le taxi. Astuce : « min » et « ila » vont souvent ensemble, comme le point de départ et le point d'arrivée d'une course en taxi.","exampleRo":"Adhhabu mina al-funduqi ilā al-qalʿati.","lit":"je vais · de · [l']hôtel · vers · [la] citadelle","say":{"Fi":"فِي","ala":"عَلَى","min":"مِنْ","ila":"إِلَى","adhhabu mina al-funduqi ila al-qalati":"أَذْهَبُ مِنَ الْفُنْدُقِ إِلَى الْقَلْعَةِ","mina":"مِنَ","fi ash-sharii":"فِي الشَّارِعِ","ala at-tawilati":"عَلَى الطَّاوِلَةِ","nahnu fi at-taksi":"نَحْنُ فِي التَّاكْسِي","fi, ala, min, ila":"فِي، عَلَى، مِنْ، إِلَى"}}},{"title":"Ce que j'ai","phrases":[{"fr":"J'ai un téléphone neuf.","tgt":"عِنْدِي هَاتِفٌ جَدِيدٌ.","ro":"ʿIndī hātifun jadīdun.","lit":"chez-moi · téléphone · neuf"},{"fr":"Tu as une voiture ?","tgt":"عِنْدَكَ سَيَّارَةٌ؟","ro":"ʿIndaka sayyāratun?","lit":"chez-toi · voiture ?"},{"fr":"Elle a une sœur.","tgt":"عِنْدَهَا أُخْتٌ.","ro":"ʿIndahā ukhtun.","lit":"chez-elle · sœur"},{"fr":"Il a un rendez-vous.","tgt":"عِنْدَهُ مَوْعِدٌ.","ro":"ʿIndahu mawʿidun.","lit":"chez-lui · rendez-vous"},{"fr":"J'ai une question.","tgt":"عِنْدِي سُؤَالٌ.","ro":"ʿIndī suʾālun.","lit":"chez-moi · question"},{"fr":"Leïla, tu as un stylo ?","tgt":"عِنْدَكِ قَلَمٌ يَا لَيْلَى؟","ro":"ʿIndaki qalamun yā Laylā?","lit":"chez-toi (fém.) · stylo · ô · Leïla ?"},{"fr":"J'ai beaucoup de travail.","tgt":"عِنْدِي عَمَلٌ كَثِيرٌ.","ro":"ʿIndī ʿamalun kathīrun.","lit":"chez-moi · travail · nombreux"},{"fr":"Karim a un petit appartement.","tgt":"عِنْدَ كَرِيمٍ شَقَّةٌ صَغِيرَةٌ.","ro":"ʿInda Karīmin shaqqatun ṣaghīratun.","lit":"chez · Karim · appartement · petit"},{"fr":"Je n'ai pas le temps.","tgt":"لَيْسَ عِنْدِي وَقْتٌ.","ro":"Laysa ʿindī waqtun.","lit":"[il n'est pas] · chez-moi · temps"},{"fr":"Tu as son numéro de téléphone ?","tgt":"عِنْدَكَ رَقْمُ هَاتِفِهِ؟","ro":"ʿIndaka raqmu hātifihi?","lit":"chez-toi · numéro · téléphone-de-lui ?"}],"tip":{"title":"« Indi » : j'ai, littéralement chez moi","example":"J'ai un téléphone neuf. — <b>عِنْدِي</b> هَاتِفٌ جَدِيدٌ.","body":"L'arabe n'a pas de verbe avoir au présent. Pour dire j'ai, on dit « indi », littéralement chez moi. « Indi hatifun jadidun » se lit donc : chez moi, un téléphone neuf, c'est-à-dire j'ai un téléphone neuf. On y retrouve les terminaisons des possessifs : « indaka », tu as, à un homme, « indaki » à une femme, « indahu », il a, et « indaha », elle a. Avec un prénom, on dit « inda Karimin », chez Karim, donc Karim a. Pour la négation, on ajoute « laysa » devant : « laysa indi waqtun », je n'ai pas le temps. C'est un peu comme si l'on disait en français : chez moi, il y a un téléphone neuf. Astuce : pensez toujours au mot chez, et vous ne vous tromperez jamais.","exampleRo":"ʿIndī hātifun jadīdun.","lit":"chez-moi · téléphone · neuf","say":{"indi":"عِنْدِي","Indi hatifun jadidun":"عِنْدِي هَاتِفٌ جَدِيدٌ","indaka":"عِنْدَكَ","indaki":"عِنْدَكِ","indahu":"عِنْدَهُ","indaha":"عِنْدَهَا","inda Karimin":"عِنْدَ كَرِيمٍ","laysa":"لَيْسَ","laysa indi waqtun":"لَيْسَ عِنْدِي وَقْتٌ","Indi":"عِنْدِي"}}},{"title":"Les nombres et l'heure","phrases":[{"fr":"Un, deux, trois.","tgt":"وَاحِدٌ، اِثْنَانِ، ثَلَاثَةٌ.","ro":"Wāḥidun, ithnāni, thalāthatun.","lit":"un · deux · trois"},{"fr":"Quatre, cinq, six.","tgt":"أَرْبَعَةٌ، خَمْسَةٌ، سِتَّةٌ.","ro":"Arbaʿatun, khamsatun, sittatun.","lit":"quatre · cinq · six"},{"fr":"Sept, huit, neuf, dix.","tgt":"سَبْعَةٌ، ثَمَانِيَةٌ، تِسْعَةٌ، عَشَرَةٌ.","ro":"Sabʿatun, thamāniyatun, tisʿatun, ʿasharatun.","lit":"sept · huit · neuf · dix"},{"fr":"Il est cinq heures.","tgt":"السَّاعَةُ الْخَامِسَةُ.","ro":"As-sāʿatu al-khāmisatu.","lit":"[l']heure · [la] cinquième"},{"fr":"J'ai deux livres.","tgt":"عِنْدِي كِتَابَانِ.","ro":"ʿIndī kitābāni.","lit":"chez-moi · deux-livres"},{"fr":"Le falafel coûte un dinar.","tgt":"الْفَلَافِلُ بِدِينَارٍ وَاحِدٍ.","ro":"Al-falāfilu bi-dīnārin wāḥidin.","lit":"[le] falafel · pour · dinar · un"},{"fr":"Nous sommes cinq.","tgt":"نَحْنُ خَمْسَةٌ.","ro":"Naḥnu khamsatun.","lit":"nous · cinq"},{"fr":"Karim a trois sœurs.","tgt":"عِنْدَ كَرِيمٍ ثَلَاثُ أَخَوَاتٍ.","ro":"ʿInda Karīmin thalāthu akhawātin.","lit":"chez · Karim · trois · sœurs"},{"fr":"Le taxi coûte quatre dinars.","tgt":"أُجْرَةُ التَّاكْسِي أَرْبَعَةُ دَنَانِيرَ.","ro":"Ujratu at-tāksī arbaʿatu danānīra.","lit":"prix · [du] taxi · quatre · dinars"},{"fr":"Il est dix heures.","tgt":"السَّاعَةُ الْعَاشِرَةُ.","ro":"As-sāʿatu al-ʿāshiratu.","lit":"[l']heure · [la] dixième"}],"tip":{"title":"Compter de un à dix","example":"Un, deux, trois. — <b>وَاحِدٌ، اِثْنَانِ، ثَلَاثَةٌ</b>.","body":"Voici les nombres de un à dix : « wahid », un, « ithnan », deux, « thalatha », trois, « arbaa », quatre, « khamsa », cinq, « sitta », six, « saba », sept, « thamaniya », huit, « tisa », neuf, et « ashara », dix. Dans cette app, on les entend avec leur terminaison complète, par exemple « wahidun, ithnani, thalathatun ». Pour deux objets, l'arabe a une forme spéciale, le duel : au lieu de dire deux livres, on ajoute « ani » au nom, « kitabani ». De trois à dix, une règle étonnante s'applique : avec un nom masculin, le nombre garde sa terminaison en a, comme « arbaatu dananira », quatre dinars, et avec un nom féminin, il la perd, comme « thalathu akhawatin », trois sœurs. Pour l'heure, on utilise l'ordinal : « as-saatu al-ashiratu », l'heure la dixième, donc il est dix heures. Astuce : comptez vos pas en arabe en marchant, de « wahid » à « ashara ».","exampleRo":"Wāḥidun, ithnāni, thalāthatun.","lit":"un · deux · trois","say":{"wahid":"وَاحِد","ithnan":"اِثْنَان","thalatha":"ثَلَاثَة","arbaa":"أَرْبَعَة","khamsa":"خَمْسَة","sitta":"سِتَّة","saba":"سَبْعَة","thamaniya":"ثَمَانِيَة","tisa":"تِسْعَة","ashara":"عَشَرَة","wahidun, ithnani, thalathatun":"وَاحِدٌ، اِثْنَانِ، ثَلَاثَةٌ","kitabani":"كِتَابَانِ","arbaatu dananira":"أَرْبَعَةُ دَنَانِيرَ","thalathu akhawatin":"ثَلَاثُ أَخَوَاتٍ","as-saatu al-ashiratu":"السَّاعَةُ الْعَاشِرَةُ"}}},{"title":"Les vêtements et les couleurs","phrases":[{"fr":"J'ai une chemise blanche.","tgt":"عِنْدِي قَمِيصٌ أَبْيَضُ.","ro":"ʿIndī qamīṣun abyaḍu.","lit":"chez-moi · chemise · blanche"},{"fr":"Elle porte une robe rouge.","tgt":"تَلْبَسُ فُسْتَانًا أَحْمَرَ.","ro":"Talbasu fustānan aḥmara.","lit":"elle porte · robe · rouge"},{"fr":"Le pantalon noir est cher.","tgt":"الْبِنْطَالُ الْأَسْوَدُ غَالٍ.","ro":"Al-binṭālu al-aswadu ghālin.","lit":"[le] pantalon · [le] noir · cher"},{"fr":"La veste verte est belle.","tgt":"السُّتْرَةُ الْخَضْرَاءُ جَمِيلَةٌ.","ro":"As-sutratu al-khaḍrāʾu jamīlatun.","lit":"[la] veste · [la] verte · belle"},{"fr":"Je cherche un grand sac.","tgt":"أَبْحَثُ عَنْ حَقِيبَةٍ كَبِيرَةٍ.","ro":"Abḥathu ʿan ḥaqībatin kabīratin.","lit":"je cherche · [après] · sac · grand"},{"fr":"C'est une petite boutique.","tgt":"هَذَا مَحَلٌّ صَغِيرٌ.","ro":"Hādhā maḥallun ṣaghīrun.","lit":"ceci · boutique · petite"},{"fr":"Mes chaussures neuves sont confortables.","tgt":"حِذَائِي الْجَدِيدُ مُرِيحٌ.","ro":"Ḥidhāʾī al-jadīdu murīḥun.","lit":"chaussures-de-moi · [les] neuves · confortables"},{"fr":"Une écharpe bleue, s'il vous plaît.","tgt":"وِشَاحٌ أَزْرَقُ مِنْ فَضْلِكَ.","ro":"Wishāḥun azraqu min faḍlika.","lit":"écharpe · bleue · de · faveur-de-toi"},{"fr":"Leïla aime la couleur jaune.","tgt":"تُحِبُّ لَيْلَى اللَّوْنَ الْأَصْفَرَ.","ro":"Tuḥibbu Laylā al-lawna al-aṣfara.","lit":"elle aime · Leïla · [la] couleur · [la] jaune"},{"fr":"C'est une jolie couleur.","tgt":"هَذَا لَوْنٌ جَمِيلٌ.","ro":"Hādhā lawnun jamīlun.","lit":"ceci · couleur · jolie"}],"tip":{"title":"L'adjectif se place après le nom et s'accorde","example":"La veste verte est belle. — السُّتْرَةُ <b>الْخَضْرَاءُ</b> جَمِيلَةٌ.","body":"En arabe, l'adjectif se place toujours après le nom, comme souvent en français : « qamisun abyadu », une chemise blanche. Mais il s'accorde en tout : en genre, en nombre, et même avec l'article. Si le nom porte l'article, l'adjectif le prend aussi : « as-sutratu al-khadrau », la veste la verte, c'est-à-dire la veste verte. Sans article sur l'adjectif, on obtient une phrase complète : « as-sutratu jamilatun », la veste est belle. Notre exemple réunit les deux : « as-sutratu al-khadrau jamilatun », la veste verte est belle. Les couleurs ont un féminin particulier : « akhdar », vert, devient « khadra », et « abyad », blanc, devient « bayda ». Astuce : l'article est comme un badge, si le nom le porte, l'adjectif qui l'accompagne doit le porter aussi.","exampleRo":"As-sutratu al-khaḍrāʾu jamīlatun.","lit":"[la] veste · [la] verte · belle","say":{"qamisun abyadu":"قَمِيصٌ أَبْيَضُ","as-sutratu al-khadrau":"السُّتْرَةُ الْخَضْرَاءُ","as-sutratu jamilatun":"السُّتْرَةُ جَمِيلَةٌ","as-sutratu al-khadrau jamilatun":"السُّتْرَةُ الْخَضْرَاءُ جَمِيلَةٌ","akhdar":"أَخْضَر","khadra":"خَضْرَاء","abyad":"أَبْيَض","bayda":"بَيْضَاء"}}},{"title":"La météo à Amman","phrases":[{"fr":"Il y a du soleil aujourd'hui.","tgt":"هُنَاكَ شَمْسٌ الْيَوْمَ.","ro":"Hunāka shamsun al-yawma.","lit":"il y a · soleil · [le] jour"},{"fr":"Il y a un vent fort à la citadelle.","tgt":"هُنَاكَ رِيحٌ قَوِيَّةٌ فِي الْقَلْعَةِ.","ro":"Hunāka rīḥun qawiyyatun fī al-qalʿati.","lit":"il y a · vent · fort · dans · [la] citadelle"},{"fr":"Il y a un marché près d'ici.","tgt":"هُنَاكَ سُوقٌ قَرِيبٌ مِنْ هُنَا.","ro":"Hunāka sūqun qarībun min hunā.","lit":"il y a · marché · proche · de · ici"},{"fr":"Il y a beaucoup de monde dans la rue.","tgt":"هُنَاكَ نَاسٌ كَثِيرُونَ فِي الشَّارِعِ.","ro":"Hunāka nāsun kathīrūna fī ash-shāriʿi.","lit":"il y a · gens · nombreux · dans · [la] rue"},{"fr":"Il fait froid ce soir.","tgt":"الْجَوُّ بَارِدٌ هَذَا الْمَسَاءَ.","ro":"Al-jawwu bāridun hādhā al-masāʾa.","lit":"[le] temps · froid · ce · [le] soir"},{"fr":"Il y a de la neige en hiver.","tgt":"هُنَاكَ ثَلْجٌ فِي الشِّتَاءِ.","ro":"Hunāka thaljun fī ash-shitāʾi.","lit":"il y a · neige · dans · [l']hiver"},{"fr":"Il y a des nuages sur Amman.","tgt":"هُنَاكَ غُيُومٌ فَوْقَ عَمَّانَ.","ro":"Hunāka ghuyūmun fawqa ʿammāna.","lit":"il y a · nuages · au-dessus-de · Amman"},{"fr":"Il y a une pharmacie dans le quartier.","tgt":"هُنَاكَ صَيْدَلِيَّةٌ فِي الْحَيِّ.","ro":"Hunāka ṣaydaliyyatun fī al-ḥayyi.","lit":"il y a · pharmacie · dans · [le] quartier"},{"fr":"Il fait chaud en été.","tgt":"الْجَوُّ حَارٌّ فِي الصَّيْفِ.","ro":"Al-jawwu ḥārrun fī aṣ-ṣayfi.","lit":"[le] temps · chaud · dans · [l']été"},{"fr":"Y a-t-il de la pluie demain ?","tgt":"هَلْ هُنَاكَ مَطَرٌ غَدًا؟","ro":"Hal hunāka maṭarun ghadan?","lit":"[question] · il y a · pluie · demain ?"}],"tip":{"title":"« Hunaka » : il y a","example":"Il y a un marché près d'ici. — <b>هُنَاكَ</b> سُوقٌ قَرِيبٌ مِنْ هُنَا.","body":"Pour dire il y a, l'arabe emploie « hunaka », qui veut dire à l'origine là-bas. On le place en tête de phrase, suivi de ce qui existe : « hunaka suqun », il y a un marché. Notre exemple, « hunaka suqun qaribun min huna », se lit : il y a, un marché, proche, d'ici. Pour parler de la météo, c'est très pratique : « hunaka thaljun fi ash-shitai », il y a de la neige en hiver, ou « hunaka ghuyumun », il y a des nuages. Pour poser la question, on ajoute simplement « hal » devant : « hal hunaka matarun ? », y a-t-il de la pluie ? Ne confondez pas « hunaka », là-bas ou il y a, avec « huna », ici. Astuce : « hunaka » est plus long que « huna », tout comme là-bas est plus loin qu'ici.","exampleRo":"Hunāka sūqun qarībun min hunā.","lit":"il y a · marché · proche · de · ici","say":{"hunaka":"هُنَاكَ","hunaka suqun":"هُنَاكَ سُوقٌ","hunaka suqun qaribun min huna":"هُنَاكَ سُوقٌ قَرِيبٌ مِنْ هُنَا","hunaka thaljun fi ash-shitai":"هُنَاكَ ثَلْجٌ فِي الشِّتَاءِ","hunaka ghuyumun":"هُنَاكَ غُيُومٌ","hal hunaka matarun ?":"هَلْ هُنَاكَ مَطَرٌ؟","huna":"هُنَا","Hunaka":"هُنَاكَ","hal":"هَلْ"}}},{"title":"Une journée de travail","phrases":[{"fr":"Je ne bois pas de café le soir.","tgt":"لَا أَشْرَبُ الْقَهْوَةَ فِي الْمَسَاءِ.","ro":"Lā ashrabu al-qahwata fī al-masāʾi.","lit":"[ne… pas] · je bois · [le] café · dans · [le] soir"},{"fr":"Je ne comprends pas.","tgt":"لَا أَفْهَمُ.","ro":"Lā afhamu.","lit":"[ne… pas] · je comprends"},{"fr":"Il ne travaille pas le vendredi.","tgt":"لَا يَعْمَلُ يَوْمَ الْجُمُعَةِ.","ro":"Lā yaʿmalu yawma al-jumuʿati.","lit":"[ne… pas] · il travaille · jour · [du] vendredi"},{"fr":"Tu ne manges pas de viande ?","tgt":"لَا تَأْكُلُ اللَّحْمَ؟","ro":"Lā taʾkulu al-laḥma?","lit":"[ne… pas] · tu manges · [la] viande ?"},{"fr":"Leïla ne parle pas français.","tgt":"لَا تَتَكَلَّمُ لَيْلَى الْفَرَنْسِيَّةَ.","ro":"Lā tatakallamu Laylā al-faransiyyata.","lit":"[ne… pas] · elle parle · Leïla · [le] français"},{"fr":"Je ne sais pas.","tgt":"لَا أَعْرِفُ.","ro":"Lā aʿrifu.","lit":"[ne… pas] · je sais"},{"fr":"Le bus ne va pas à la citadelle.","tgt":"الْحَافِلَةُ لَا تَذْهَبُ إِلَى الْقَلْعَةِ.","ro":"Al-ḥāfilatu lā tadhhabu ilā al-qalʿati.","lit":"[le] bus · [ne… pas] · elle va · vers · [la] citadelle"},{"fr":"Je ne travaille pas aujourd'hui.","tgt":"لَا أَعْمَلُ الْيَوْمَ.","ro":"Lā aʿmalu al-yawma.","lit":"[ne… pas] · je travaille · [le] jour"},{"fr":"Karim n'habite pas au centre-ville.","tgt":"لَا يَسْكُنُ كَرِيمٌ فِي وَسَطِ الْمَدِينَةِ.","ro":"Lā yaskunu Karīmun fī wasaṭi al-madīnati.","lit":"[ne… pas] · il habite · Karim · dans · centre · [de la] ville"},{"fr":"Je ne regarde pas la télévision.","tgt":"لَا أُشَاهِدُ التِّلْفَازَ.","ro":"Lā ushāhidu at-tilfāza.","lit":"[ne… pas] · je regarde · [la] télévision"}],"tip":{"title":"La négation du verbe au présent : la","example":"Je ne bois pas de café le soir. — <b>لَا</b> أَشْرَبُ الْقَهْوَةَ فِي الْمَسَاءِ.","body":"Pour dire qu'on ne fait pas quelque chose au présent, c'est très simple : on place « la » juste devant le verbe, et rien d'autre ne change. « Ashrabu », je bois, devient « la ashrabu », je ne bois pas. Notre exemple, « la ashrabu al-qahwata fi al-masai », se lit : ne pas, je bois, le café, dans le soir. Le français a besoin de deux morceaux, ne et pas, autour du verbe, alors que l'arabe se contente d'un seul mot placé devant. Deux phrases très utiles pour débuter : « la afhamu », je ne comprends pas, et « la arifu », je ne sais pas. Attention à ne pas confondre avec « laysa », qui sert pour les phrases sans verbe : « lastu mutaban », je ne suis pas fatigué. Astuce : la, c'est aussi le mot pour dire non, un petit non posé devant le verbe.","exampleRo":"Lā ashrabu al-qahwata fī al-masāʾi.","lit":"[ne… pas] · je bois · [le] café · dans · [le] soir","say":{"la":"لَا","Ashrabu":"أَشْرَبُ","la ashrabu":"لَا أَشْرَبُ","la ashrabu al-qahwata fi al-masai":"لَا أَشْرَبُ الْقَهْوَةَ فِي الْمَسَاءِ","la afhamu":"لَا أَفْهَمُ","la arifu":"لَا أَعْرِفُ","laysa":"لَيْسَ","lastu mutaban":"لَسْتُ مُتْعَبًا"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Merci beaucoup !","tgt":"شُكْرًا جَزِيلًا!","ro":"Shukran jazīlan!","lit":"merci · abondant !"},{"fr":"De rien.","tgt":"عَفْوًا.","ro":"ʿAfwan.","lit":"de rien"},{"fr":"Un thé à la menthe, s'il vous plaît.","tgt":"شَايٌ بِالنَّعْنَاعِ مِنْ فَضْلِكَ.","ro":"Shāyun bi-n-naʿnāʿi min faḍlika.","lit":"thé · avec · [la] menthe · de · faveur-de-toi"},{"fr":"Bienvenue à la maison !","tgt":"أَهْلًا وَسَهْلًا فِي الْبَيْتِ!","ro":"Ahlan wa-sahlan fī al-bayti!","lit":"bienvenue · [et] · aisance · dans · [la] maison !"},{"fr":"Je parle un peu arabe maintenant.","tgt":"أَتَكَلَّمُ الْعَرَبِيَّةَ قَلِيلًا الْآنَ.","ro":"Atakallamu al-ʿarabiyyata qalīlan al-āna.","lit":"je parle · [l']arabe · un-peu · maintenant"},{"fr":"J'aime beaucoup Amman.","tgt":"أُحِبُّ عَمَّانَ كَثِيرًا.","ro":"Uḥibbu ʿammāna kathīran.","lit":"j'aime · Amman · beaucoup"},{"fr":"L'arabe n'est pas difficile.","tgt":"الْعَرَبِيَّةُ لَيْسَتْ صَعْبَةً.","ro":"Al-ʿarabiyyatu laysat ṣaʿbatan.","lit":"[l']arabe · [n'est pas] · difficile"},{"fr":"Une knafeh, s'il te plaît, Leïla.","tgt":"كُنَافَةٌ مِنْ فَضْلِكِ يَا لَيْلَى.","ro":"Kunāfatun min faḍliki yā Laylā.","lit":"knafeh · de · faveur-de-toi (fém.) · ô · Leïla"},{"fr":"Merci, et à bientôt !","tgt":"شُكْرًا، وَإِلَى اللِّقَاءِ!","ro":"Shukran, wa-ilā al-liqāʾi!","lit":"merci · [et] · jusqu'à · [la] rencontre !"},{"fr":"Pardon, où est le taxi ?","tgt":"عَفْوًا، أَيْنَ التَّاكْسِي؟","ro":"ʿAfwan, ayna at-tāksī?","lit":"pardon · où · [le] taxi ?"}],"tip":{"title":"Les mots de politesse","example":"Un thé à la menthe, s'il vous plaît. — شَايٌ بِالنَّعْنَاعِ <b>مِنْ فَضْلِكَ</b>.","body":"Pour finir ce module, voici les mots magiques de la politesse arabe. « Min fadlik » veut dire s'il te plaît ou s'il vous plaît, littéralement de ta faveur, et l'on dit « min fadliki » à une femme. « Shukran » veut dire merci, et « shukran jazilan », merci beaucoup. On répond « afwan », de rien, un mot qui sert aussi à dire pardon pour attirer l'attention. Enfin, « ahlan wa sahlan » est la belle formule d'accueil : bienvenue. Notre exemple, « shayun bin-nanai min fadlika », se lit : thé à la menthe, de ta faveur. Bravo, vous avez maintenant les bases pour vous débrouiller à Amman, du marché jusqu'au taxi. Astuce : glissez « min fadlik » et « shukran » dans chaque échange, les sourires suivront.","exampleRo":"Shāyun bi-n-naʿnāʿi min faḍlika.","lit":"thé · avec · [la] menthe · de · faveur-de-toi","say":{"Min fadlik":"مِنْ فَضْلِك","min fadliki":"مِنْ فَضْلِكِ","Shukran":"شُكْرًا","shukran jazilan":"شُكْرًا جَزِيلًا","afwan":"عَفْوًا","ahlan wa sahlan":"أَهْلًا وَسَهْلًا","shayun bin-nanai min fadlika":"شَايٌ بِالنَّعْنَاعِ مِنْ فَضْلِكَ","min fadlik":"مِنْ فَضْلِك","shukran":"شُكْرًا"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus dans le monde arabe.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à l'aéroport de Marrakech","phrases":[{"fr":"Bienvenue au Maroc.","tgt":"مَرْحَبًا بِكَ فِي الْمَغْرِبِ.","ro":"Marḥaban bika fī l-Maghribi.","lit":"bienvenue · [avec] toi · dans · le-Maroc"},{"fr":"C'est l'aéroport de Marrakech.","tgt":"هَذَا مَطَارُ مُرَّاكُشَ.","ro":"Hādhā maṭāru Murrākusha.","lit":"ceci · aéroport · [de] Marrakech"},{"fr":"Où est mon passeport ?","tgt":"أَيْنَ جَوَازُ سَفَرِي؟","ro":"Ayna jawāzu safarī?","lit":"où · permis · [de] voyage-de-moi ?"},{"fr":"Mon passeport est dans mon sac.","tgt":"جَوَازُ سَفَرِي فِي حَقِيبَتِي.","ro":"Jawāzu safarī fī ḥaqībatī.","lit":"permis · [de] voyage-de-moi · dans · sac-de-moi"},{"fr":"Je suis un touriste français.","tgt":"أَنَا سَائِحٌ فَرَنْسِيٌّ.","ro":"Anā sāʾiḥun faransiyyun.","lit":"moi · touriste · français"},{"fr":"La file d'attente à la douane est longue.","tgt":"طَابُورُ الْجَمَارِكِ طَوِيلٌ.","ro":"Ṭābūru l-jamāriki ṭawīlun.","lit":"file · [de] la-douane · longue"},{"fr":"Où est la sortie de l'aéroport ?","tgt":"أَيْنَ مَخْرَجُ الْمَطَارِ؟","ro":"Ayna makhraju l-maṭāri?","lit":"où · sortie · [de] l'aéroport ?"},{"fr":"La sortie est à droite, après la douane.","tgt":"الْمَخْرَجُ عَلَى الْيَمِينِ بَعْدَ الْجَمَارِكِ.","ro":"Al-makhraju ʿalā l-yamīni baʿda l-jamāriki.","lit":"la-sortie · sur · la-droite · après · la-douane"},{"fr":"Il fait chaud à Marrakech.","tgt":"الْجَوُّ حَارٌّ فِي مُرَّاكُشَ.","ro":"Al-jawwu ḥārrun fī Murrākusha.","lit":"le-temps · chaud · dans · Marrakech"},{"fr":"J'ai une réservation dans un riad.","tgt":"عِنْدِي حَجْزٌ فِي رِيَاضٍ.","ro":"ʿIndī ḥajzun fī riyāḍin.","lit":"chez-moi · réservation · dans · riad"}]},{"title":"Le taxi vers la ville rouge","phrases":[{"fr":"Le taxi est devant l'aéroport.","tgt":"سَيَّارَةُ الْأُجْرَةِ أَمَامَ الْمَطَارِ.","ro":"Sayyāratu l-ujrati amāma l-maṭāri.","lit":"voiture · [de] la-location · devant · l'aéroport"},{"fr":"Vers la médina, s'il vous plaît.","tgt":"إِلَى الْمَدِينَةِ الْقَدِيمَةِ، مِنْ فَضْلِكَ.","ro":"Ilā l-madīnati l-qadīmati, min faḍlika.","lit":"vers · la-ville · l'ancienne, · de · faveur-de-toi"},{"fr":"La valise est lourde.","tgt":"الْحَقِيبَةُ ثَقِيلَةٌ.","ro":"Al-ḥaqībatu thaqīlatun.","lit":"la-valise · lourde"},{"fr":"Le chauffeur est sympathique.","tgt":"السَّائِقُ لَطِيفٌ.","ro":"As-sāʾiqu laṭīfun.","lit":"le-chauffeur · sympathique"},{"fr":"Le ciel est bleu et clair.","tgt":"السَّمَاءُ زَرْقَاءُ وَصَافِيَةٌ.","ro":"As-samāʾu zarqāʾu wa-ṣāfiyatun.","lit":"le-ciel · bleu · [et] clair"},{"fr":"Le riad est loin ?","tgt":"هَلِ الرِّيَاضُ بَعِيدٌ؟","ro":"Hali r-riyāḍu baʿīdun?","lit":"[question] · le-riad · loin ?"},{"fr":"Non, il est près de la place.","tgt":"لَا، هُوَ قَرِيبٌ مِنَ السَّاحَةِ.","ro":"Lā, huwa qarībun mina s-sāḥati.","lit":"non, · lui · proche · de · la-place"},{"fr":"La ville est rouge et belle.","tgt":"الْمَدِينَةُ حَمْرَاءُ وَجَمِيلَةٌ.","ro":"Al-madīnatu ḥamrāʾu wa-jamīlatun.","lit":"la-ville · rouge · [et] belle"},{"fr":"Voici la place Jemaa el-Fna.","tgt":"هَذِهِ سَاحَةُ جَامِعِ الْفَنَاءِ.","ro":"Hādhihi sāḥatu Jāmiʿi l-Fanāʾi.","lit":"celle-ci · place · [de] Jemaa · el-Fna"},{"fr":"Le riad est calme à l'intérieur.","tgt":"الرِّيَاضُ هَادِئٌ مِنَ الدَّاخِلِ.","ro":"Ar-riyāḍu hādiʾun mina d-dākhili.","lit":"le-riad · calme · de · l'intérieur"}],"tip":{"title":"Les sons propres à l'arabe : ha profond, ayn, kha, qaf","example":"La valise est lourde. — <b>الْحَقِيبَةُ</b> <b>ثَقِيلَةٌ</b>.","body":"L'arabe possède quelques sons qui n'existent pas en français, et ils changent vraiment le sens des mots. Le « ha profond » est un h soufflé du fond de la gorge, comme quand on souffle sur une vitre pour l'embuer : on l'entend au début de « al-haqiba », la valise. Le « ayn » vient encore plus bas : on serre doucement la gorge, comme pour un petit « a » étranglé ; on l'entend dans « baiid », loin. Le « kha » est un raclement de gorge léger, proche du r parisien mais sans voix, comme dans « ad-dakhil », l'intérieur. Le « qaf », enfin, est un k prononcé tout au fond de la bouche, contre la luette, comme dans « thaqila », lourde, ou « qarib », proche. Notre phrase « al-haqibatu thaqilatun » se dit littéralement : la valise, lourde, sans verbe être. Astuce : exagérez ces sons au début, en imitant le chauffeur de taxi ; avec la répétition, ils deviendront naturels.","exampleRo":"Al-ḥaqībatu thaqīlatun.","lit":"la-valise · lourde","say":{"al-haqiba":"الْحَقِيبَة","baiid":"بَعِيد","ad-dakhil":"الدَّاخِل","thaqila":"ثَقِيلَة","qarib":"قَرِيب","al-haqibatu thaqilatun":"الْحَقِيبَةُ ثَقِيلَةٌ","ayn":"عَيْن","kha":"خَاء","qaf":"قَاف"}}},{"title":"Un riad dans la médina","phrases":[{"fr":"Le riad a un beau patio.","tgt":"فِي الرِّيَاضِ فِنَاءٌ جَمِيلٌ.","ro":"Fī r-riyāḍi fināʾun jamīlun.","lit":"dans · le-riad · patio · beau"},{"fr":"Il y a une fontaine au milieu.","tgt":"هُنَاكَ نَافُورَةٌ فِي الْوَسَطِ.","ro":"Hunāka nāfūratun fī l-wasaṭi.","lit":"il-y-a · fontaine · dans · le-milieu"},{"fr":"Ma chambre est au premier étage.","tgt":"غُرْفَتِي فِي الطَّابِقِ الْأَوَّلِ.","ro":"Ghurfatī fī ṭ-ṭābiqi l-awwali.","lit":"chambre-de-moi · dans · l'étage · le-premier"},{"fr":"Voici la clé de la chambre.","tgt":"هَذَا مِفْتَاحُ الْغُرْفَةِ.","ro":"Hādhā miftāḥu l-ghurfati.","lit":"ceci · clé · [de] la-chambre"},{"fr":"La chambre est propre et calme.","tgt":"الْغُرْفَةُ نَظِيفَةٌ وَهَادِئَةٌ.","ro":"Al-ghurfatu naẓīfatun wa-hādiʾatun.","lit":"la-chambre · propre · [et] calme"},{"fr":"Est-ce qu'il y a une terrasse sur le toit ?","tgt":"هَلْ هُنَاكَ سَطْحٌ؟","ro":"Hal hunāka saṭḥun?","lit":"[question] · il-y-a · terrasse ?"},{"fr":"Oui, la terrasse est en haut.","tgt":"نَعَمْ، السَّطْحُ فِي الْأَعْلَى.","ro":"Naʿam, as-saṭḥu fī l-aʿlā.","lit":"oui, · la-terrasse · dans · le-haut"},{"fr":"Le petit-déjeuner est servi sur la terrasse.","tgt":"الْفُطُورُ عَلَى السَّطْحِ.","ro":"Al-fuṭūru ʿalā s-saṭḥi.","lit":"le-petit-déjeuner · sur · la-terrasse"},{"fr":"La propriétaire du riad s'appelle Nadia.","tgt":"اسْمُ الْمَالِكَةِ نَادِيَةُ.","ro":"Ismu l-mālikati Nādiyatu.","lit":"nom · [de] la-propriétaire · Nadia"},{"fr":"Merci, le riad est magnifique.","tgt":"شُكْرًا، الرِّيَاضُ رَائِعٌ.","ro":"Shukran, ar-riyāḍu rāʾiʿun.","lit":"merci, · le-riad · magnifique"}]},{"title":"Un thé à la menthe sur la place","phrases":[{"fr":"Je veux un thé à la menthe.","tgt":"أُرِيدُ شَايًا بِالنَّعْنَاعِ.","ro":"Urīdu shāyan bi-n-naʿnāʿi.","lit":"je-veux · thé · avec · la-menthe"},{"fr":"Tu veux du sucre ?","tgt":"هَلْ تُرِيدُ سُكَّرًا؟","ro":"Hal turīdu sukkaran?","lit":"[question] · tu-veux · sucre ?"},{"fr":"Oui, je veux un peu de sucre.","tgt":"نَعَمْ، أُرِيدُ قَلِيلًا مِنَ السُّكَّرِ.","ro":"Naʿam, urīdu qalīlan mina s-sukkari.","lit":"oui, · je-veux · peu · de · le-sucre"},{"fr":"Je ne veux pas de café.","tgt":"لَا أُرِيدُ قَهْوَةً.","ro":"Lā urīdu qahwatan.","lit":"[ne… pas] · je-veux · café"},{"fr":"Mon amie veut un jus d'orange.","tgt":"صَدِيقَتِي تُرِيدُ عَصِيرَ بُرْتُقَالٍ.","ro":"Ṣadīqatī turīdu ʿaṣīra burtuqālin.","lit":"amie-de-moi · elle-veut · jus · [d'] orange"},{"fr":"Qu'est-ce que tu veux, Karim ?","tgt":"مَاذَا تُرِيدُ يَا كَرِيمُ؟","ro":"Mādhā turīdu yā Karīmu?","lit":"quoi · tu-veux · [ô] Karim ?"},{"fr":"Je veux une table sur la terrasse.","tgt":"أُرِيدُ طَاوِلَةً عَلَى السَّطْحِ.","ro":"Urīdu ṭāwilatan ʿalā s-saṭḥi.","lit":"je-veux · table · sur · la-terrasse"},{"fr":"Nous voulons une vue sur la place.","tgt":"نُرِيدُ مَنْظَرًا عَلَى السَّاحَةِ.","ro":"Nurīdu manẓaran ʿalā s-sāḥati.","lit":"nous-voulons · vue · sur · la-place"},{"fr":"Il veut de l'eau bien froide.","tgt":"هُوَ يُرِيدُ مَاءً بَارِدًا.","ro":"Huwa yurīdu māʾan bāridan.","lit":"lui · il-veut · eau · froide"},{"fr":"Le thé d'ici est délicieux.","tgt":"الشَّايُ هُنَا لَذِيذٌ.","ro":"Ash-shāyu hunā ladhīdhun.","lit":"le-thé · ici · délicieux"}],"tip":{"title":"« Uridu » : je veux","example":"Je veux un thé à la menthe. — <b>أُرِيدُ</b> شَايًا بِالنَّعْنَاعِ.","body":"Voici sans doute le verbe le plus utile du voyageur : « urid », vouloir. Pour dire je veux, on dit simplement « uridu », et l'on n'a même pas besoin du pronom « ana », moi, car le petit « u » du début indique déjà que c'est je. Tu veux se dit « turidu », il veut « yuridu », et nous voulons « nuridu » : seule la première syllabe change. Ensuite, on pose directement la chose voulue, sans article : « uridu shayan », je veux un thé. Notre phrase « uridu shayan bin-nanaa » se dit littéralement : je veux, thé, avec la menthe. Pour la négation, on place « la » devant : « la uridu qahwatan », je ne veux pas de café. Pour poser la question, on ajoute « hal » au début : « hal turidu sukkaran », est-ce que tu veux du sucre. Astuce : pensez à « u » comme un « je » collé au verbe, et commandez votre thé à voix haute.","exampleRo":"Urīdu shāyan bi-n-naʿnāʿi.","lit":"je-veux · thé · avec · la-menthe","say":{"Uridu":"أُرِيدُ","urid":"أُرِيد","uridu":"أُرِيدُ","ana":"أَنَا","turidu":"تُرِيدُ","yuridu":"يُرِيدُ","nuridu":"نُرِيدُ","uridu shayan":"أُرِيدُ شَايًا","uridu shayan bin-nanaa":"أُرِيدُ شَايًا بِالنَّعْنَاعِ","la":"لَا","la uridu qahwatan":"لَا أُرِيدُ قَهْوَةً","hal":"هَلْ","hal turidu sukkaran":"هَلْ تُرِيدُ سُكَّرًا"}}},{"title":"Jemaa el-Fna à la tombée du jour","phrases":[{"fr":"Le soir, la place est pleine de monde.","tgt":"السَّاحَةُ مُزْدَحِمَةٌ فِي الْمَسَاءِ.","ro":"As-sāḥatu muzdaḥimatun fī l-masāʾi.","lit":"la-place · bondée · dans · le-soir"},{"fr":"Il y a de la musique partout.","tgt":"هُنَاكَ مُوسِيقَى فِي كُلِّ مَكَانٍ.","ro":"Hunāka mūsīqā fī kulli makānin.","lit":"il-y-a · musique · dans · chaque · endroit"},{"fr":"Ce musicien est très doué.","tgt":"هَذَا الْمُوسِيقِيُّ مَاهِرٌ جِدًّا.","ro":"Hādhā l-mūsīqiyyu māhirun jiddan.","lit":"ce · le-musicien · doué · très"},{"fr":"Ce stand vend des escargots.","tgt":"هَذَا الْكُشْكُ يَبِيعُ الْحَلَزُونَ.","ro":"Hādhā l-kushku yabīʿu l-ḥalazūna.","lit":"ce · le-stand · il-vend · l'escargot"},{"fr":"Le jus d'orange coûte quatre dirhams.","tgt":"عَصِيرُ الْبُرْتُقَالِ بِأَرْبَعَةِ دَرَاهِمَ.","ro":"ʿAṣīru l-burtuqāli bi-arbaʿati darāhima.","lit":"jus · [de] l'orange · [à] quatre · dirhams"},{"fr":"L'odeur des grillades est forte.","tgt":"رَائِحَةُ الشِّوَاءِ قَوِيَّةٌ.","ro":"Rāʾiḥatu sh-shiwāʾi qawiyyatun.","lit":"odeur · [de] la-grillade · forte"},{"fr":"Pour l'instant, je n'ai pas faim.","tgt":"الْآنَ لَسْتُ جَائِعًا.","ro":"Al-āna lastu jāʾiʿan.","lit":"maintenant · [ne… pas]-je-suis · affamé"},{"fr":"Nous sommes sur la terrasse d'un café.","tgt":"نَحْنُ عَلَى سَطْحِ مَقْهًى.","ro":"Naḥnu ʿalā saṭḥi maqhan.","lit":"nous · sur · terrasse · [d'un] café"},{"fr":"D'ici, la vue est magnifique.","tgt":"الْمَنْظَرُ رَائِعٌ مِنْ هُنَا.","ro":"Al-manẓaru rāʾiʿun min hunā.","lit":"la-vue · magnifique · de · ici"},{"fr":"Marrakech ne dort pas la nuit.","tgt":"مُرَّاكُشُ لَا تَنَامُ فِي اللَّيْلِ.","ro":"Murrākushu lā tanāmu fī l-layli.","lit":"Marrakech · [ne… pas] · elle-dort · dans · la-nuit"}]},{"title":"Une journée dans les souks","phrases":[{"fr":"Ce matin, j'ai visité le souk.","tgt":"زُرْتُ السُّوقَ هَذَا الصَّبَاحَ.","ro":"Zurtu s-sūqa hādhā ṣ-ṣabāḥa.","lit":"j'ai-visité · le-souk · ce · le-matin"},{"fr":"J'ai écrit une carte postale.","tgt":"كَتَبْتُ بِطَاقَةً بَرِيدِيَّةً.","ro":"Katabtu biṭāqatan barīdiyyatan.","lit":"j'ai-écrit · carte · postale"},{"fr":"Ma sœur a acheté un tapis.","tgt":"اشْتَرَتْ أُخْتِي سَجَّادَةً.","ro":"Ishtarat ukhtī sajjādatan.","lit":"elle-a-acheté · sœur-de-moi · tapis"},{"fr":"Nous avons bu le thé chez le marchand.","tgt":"شَرِبْنَا الشَّايَ عِنْدَ التَّاجِرِ.","ro":"Sharibnā sh-shāya ʿinda t-tājiri.","lit":"nous-avons-bu · le-thé · chez · le-marchand"},{"fr":"Le marchand a souri.","tgt":"ابْتَسَمَ التَّاجِرُ.","ro":"Ibtasama t-tājiru.","lit":"il-a-souri · le-marchand"},{"fr":"Tu as trouvé ton chemin ?","tgt":"هَلْ وَجَدْتَ طَرِيقَكَ؟","ro":"Hal wajadta ṭarīqaka?","lit":"[question] · tu-as-trouvé · chemin-de-toi ?"},{"fr":"Non, je me suis perdu dans la médina.","tgt":"لَا، ضِعْتُ فِي الْمَدِينَةِ الْقَدِيمَةِ.","ro":"Lā, ḍiʿtu fī l-madīnati l-qadīmati.","lit":"non, · je-me-suis-perdu · dans · la-ville · l'ancienne"},{"fr":"Un garçon m'a aidé.","tgt":"سَاعَدَنِي وَلَدٌ.","ro":"Sāʿadanī waladun.","lit":"il-a-aidé-moi · garçon"},{"fr":"Il a écrit l'adresse sur un papier.","tgt":"كَتَبَ الْعُنْوَانَ عَلَى وَرَقَةٍ.","ro":"Kataba l-ʿunwāna ʿalā waraqatin.","lit":"il-a-écrit · l'adresse · sur · papier"},{"fr":"Hier, nous avons mangé un tajine.","tgt":"أَمْسِ أَكَلْنَا طَاجِينًا.","ro":"Amsi akalnā ṭājīnan.","lit":"hier · nous-avons-mangé · tajine"}],"tip":{"title":"Le verbe au passé : « kataba, katabtu »","example":"J'ai écrit une carte postale. — <b>كَتَبْتُ</b> بِطَاقَةً بَرِيدِيَّةً.","body":"Au passé, le verbe arabe part d'une forme de base très simple : « kataba », il a écrit, construite sur la racine k, t, b de l'écriture. Pour changer de personne, on ne met pas de pronom devant, on colle une petite terminaison à la fin. « Katabtu », avec « tu », veut dire j'ai écrit ; « katabta », tu as écrit ; « katabat », elle a écrit ; et « katabna », nous avons écrit. Notre phrase « katabtu bitaqatan baridiyyatan » se dit littéralement : j'ai écrit, carte, postale. Le même moule fonctionne pour d'autres verbes : « sharibna », nous avons bu, ou « akalna », nous avons mangé. Remarquez aussi que l'arabe aime commencer par le verbe : « ishtarat ukhti », a acheté ma sœur. Astuce : retenez « tu » comme le je du passé, et « na » comme le nous, puis racontez votre journée à voix basse.","exampleRo":"Katabtu biṭāqatan barīdiyyatan.","lit":"j'ai-écrit · carte · postale","say":{"kataba":"كَتَبَ","Katabtu":"كَتَبْتُ","katabta":"كَتَبْتَ","katabat":"كَتَبَتْ","katabna":"كَتَبْنَا","katabtu bitaqatan baridiyyatan":"كَتَبْتُ بِطَاقَةً بَرِيدِيَّةً","sharibna":"شَرِبْنَا","akalna":"أَكَلْنَا","ishtarat ukhti":"اِشْتَرَتْ أُخْتِي","kataba, katabtu":"كَتَبَ، كَتَبْتُ"}}},{"title":"En train de Marrakech à Fès","phrases":[{"fr":"Le train pour Fès part le matin.","tgt":"يَنْطَلِقُ الْقِطَارُ إِلَى فَاسَ صَبَاحًا.","ro":"Yanṭaliqu l-qiṭāru ilā Fāsa ṣabāḥan.","lit":"il-part · le-train · vers · Fès · [le] matin"},{"fr":"Où est le guichet des billets ?","tgt":"أَيْنَ شُبَّاكُ التَّذَاكِرِ؟","ro":"Ayna shubbāku t-tadhākiri?","lit":"où · guichet · [de] les-billets ?"},{"fr":"Un billet pour Fès, s'il vous plaît.","tgt":"تَذْكِرَةٌ إِلَى فَاسَ، مِنْ فَضْلِكَ.","ro":"Tadhkiratun ilā Fāsa, min faḍlika.","lit":"billet · vers · Fès, · de · faveur-de-toi"},{"fr":"En première ou en deuxième classe ?","tgt":"فِي الدَّرَجَةِ الْأُولَى أَمِ الثَّانِيَةِ؟","ro":"Fī d-darajati l-ūlā ami th-thāniyati?","lit":"dans · la-classe · la-première · [ou] · la-deuxième ?"},{"fr":"La deuxième classe est moins chère.","tgt":"الدَّرَجَةُ الثَّانِيَةُ أَرْخَصُ.","ro":"Ad-darajatu th-thāniyatu arkhaṣu.","lit":"la-classe · la-deuxième · moins-chère"},{"fr":"Aujourd'hui, le train est à l'heure.","tgt":"الْقِطَارُ فِي مَوْعِدِهِ الْيَوْمَ.","ro":"Al-qiṭāru fī mawʿidihi l-yawma.","lit":"le-train · dans · horaire-de-lui · aujourd'hui"},{"fr":"Ma place est près de la fenêtre.","tgt":"مَقْعَدِي قُرْبَ النَّافِذَةِ.","ro":"Maqʿadī qurba n-nāfidhati.","lit":"siège-de-moi · près · [de] la-fenêtre"},{"fr":"Le trajet est long et agréable.","tgt":"الرِّحْلَةُ طَوِيلَةٌ وَمُمْتِعَةٌ.","ro":"Ar-riḥlatu ṭawīlatun wa-mumtiʿatun.","lit":"le-trajet · long · [et] agréable"},{"fr":"Mon voisin lit un journal.","tgt":"جَارِي يَقْرَأُ جَرِيدَةً.","ro":"Jārī yaqraʾu jarīdatan.","lit":"voisin-de-moi · il-lit · journal"},{"fr":"Nous voilà enfin à Fès !","tgt":"نَحْنُ فِي فَاسَ أَخِيرًا!","ro":"Naḥnu fī Fāsa akhīran!","lit":"nous · dans · Fès · enfin !"}]},{"title":"Deux valises pour Fès","phrases":[{"fr":"J'ai deux valises.","tgt":"عِنْدِي حَقِيبَتَانِ.","ro":"ʿIndī ḥaqībatāni.","lit":"chez-moi · deux-valises"},{"fr":"Les deux valises sont lourdes.","tgt":"الْحَقِيبَتَانِ ثَقِيلَتَانِ.","ro":"Al-ḥaqībatāni thaqīlatāni.","lit":"les-deux-valises · deux-lourdes"},{"fr":"Je veux deux billets pour le musée.","tgt":"أُرِيدُ تَذْكِرَتَيْنِ لِلْمَتْحَفِ.","ro":"Urīdu tadhkiratayni li-l-matḥafi.","lit":"je-veux · deux-billets · pour · le-musée"},{"fr":"Nous restons deux nuits à Fès.","tgt":"نَبْقَى لَيْلَتَيْنِ فِي فَاسَ.","ro":"Nabqā laylatayni fī Fāsa.","lit":"nous-restons · deux-nuits · dans · Fès"},{"fr":"Le riad a deux portes.","tgt":"لِلرِّيَاضِ بَابَانِ.","ro":"Li-r-riyāḍi bābāni.","lit":"[à] le-riad · deux-portes"},{"fr":"Deux guides nous attendent.","tgt":"يَنْتَظِرُنَا مُرْشِدَانِ.","ro":"Yantaẓirunā murshidāni.","lit":"il-attend-nous · deux-guides"},{"fr":"Mes deux amis sont étudiants.","tgt":"صَدِيقَايَ طَالِبَانِ.","ro":"Ṣadīqāya ṭālibāni.","lit":"deux-amis-de-moi · deux-étudiants"},{"fr":"Un livre ou deux livres ?","tgt":"كِتَابٌ أَمْ كِتَابَانِ؟","ro":"Kitābun am kitābāni?","lit":"livre · [ou] · deux-livres ?"},{"fr":"J'ai acheté deux livres sur Fès.","tgt":"اشْتَرَيْتُ كِتَابَيْنِ عَنْ فَاسَ.","ro":"Ishtaraytu kitābayni ʿan Fāsa.","lit":"j'ai-acheté · deux-livres · sur · Fès"},{"fr":"Ces deux portes sont anciennes.","tgt":"هَذَانِ الْبَابَانِ قَدِيمَانِ.","ro":"Hādhāni l-bābāni qadīmāni.","lit":"ces-deux · les-deux-portes · deux-anciennes"}],"tip":{"title":"Le duel : deux, « kitabani »","example":"Un livre ou deux livres ? — <b>كِتَابٌ</b> أَمْ <b>كِتَابَانِ</b>؟","body":"En français, on passe directement du singulier au pluriel. L'arabe, lui, possède une forme spéciale pour exactement deux choses : c'est le duel. Pas besoin du mot deux, il suffit d'ajouter « ani » à la fin du nom. « Kitab », un livre, devient « kitabani », deux livres ; « haqiba », une valise, devient « haqibatani », deux valises. Notre phrase « kitabun am kitabani » se dit littéralement : un livre, ou, deux livres. Après un verbe ou une préposition, la terminaison devient « ayni » : « ishtaraytu kitabayni », j'ai acheté deux livres, ou « laylatayni », pendant deux nuits. L'adjectif suit le même modèle : « al-haqibatani thaqilatani », les deux valises, deux lourdes. Astuce : imaginez que « ani » sonne comme une paire de mains qui tiennent deux objets.","exampleRo":"Kitābun am kitābāni?","lit":"livre · [ou] · deux-livres ?","say":{"Kitab":"كِتَاب","kitabani":"كِتَابَانِ","haqiba":"حَقِيبَة","haqibatani":"حَقِيبَتَانِ","kitabun am kitabani":"كِتَابٌ أَمْ كِتَابَانِ","ishtaraytu kitabayni":"اِشْتَرَيْتُ كِتَابَيْنِ","laylatayni":"لَيْلَتَيْنِ","al-haqibatani thaqilatani":"الْحَقِيبَتَانِ ثَقِيلَتَانِ"}}},{"title":"Perdus dans la médina de Fès","phrases":[{"fr":"La médina de Fès est très ancienne.","tgt":"مَدِينَةُ فَاسَ الْقَدِيمَةُ عَرِيقَةٌ جِدًّا.","ro":"Madīnatu Fāsa l-qadīmatu ʿarīqatun jiddan.","lit":"ville · [de] Fès · l'ancienne · vénérable · très"},{"fr":"Les ruelles sont très étroites.","tgt":"الْأَزِقَّةُ ضَيِّقَةٌ جِدًّا.","ro":"Al-aziqqatu ḍayyiqatun jiddan.","lit":"les-ruelles · étroite · très"},{"fr":"Il y a des ânes dans les ruelles.","tgt":"هُنَاكَ حَمِيرٌ فِي الْأَزِقَّةِ.","ro":"Hunāka ḥamīrun fī l-aziqqati.","lit":"il-y-a · ânes · dans · les-ruelles"},{"fr":"Voici la célèbre tannerie.","tgt":"هَذِهِ هِيَ الدَّبَّاغَةُ الْمَشْهُورَةُ.","ro":"Hādhihi hiya d-dabbāghatu l-mashhūratu.","lit":"celle-ci · elle · la-tannerie · la-célèbre"},{"fr":"L'odeur est un peu forte.","tgt":"الرَّائِحَةُ قَوِيَّةٌ قَلِيلًا.","ro":"Ar-rāʾiḥatu qawiyyatun qalīlan.","lit":"l'odeur · forte · un-peu"},{"fr":"Le cuir de Fès est célèbre.","tgt":"جِلْدُ فَاسَ مَشْهُورٌ.","ro":"Jildu Fāsa mashhūrun.","lit":"cuir · [de] Fès · célèbre"},{"fr":"Ce sac en cuir est joli.","tgt":"هَذِهِ الْحَقِيبَةُ الْجِلْدِيَّةُ جَمِيلَةٌ.","ro":"Hādhihi l-ḥaqībatu l-jildiyyatu jamīlatun.","lit":"ce · le-sac · le-en-cuir · joli"},{"fr":"Notre guide s'appelle Youssef.","tgt":"اسْمُ مُرْشِدِنَا يُوسُفُ.","ro":"Ismu murshidinā Yūsufu.","lit":"nom · guide-de-nous · Youssef"},{"fr":"Il connaît chaque ruelle.","tgt":"يَعْرِفُ كُلَّ زُقَاقٍ.","ro":"Yaʿrifu kulla zuqāqin.","lit":"il-connaît · chaque · ruelle"},{"fr":"La médina est un vrai labyrinthe.","tgt":"الْمَدِينَةُ الْقَدِيمَةُ مَتَاهَةٌ حَقِيقِيَّةٌ.","ro":"Al-madīnatu l-qadīmatu matāhatun ḥaqīqiyyatun.","lit":"la-ville · l'ancienne · labyrinthe · vrai"}]},{"title":"Au souk des artisans","phrases":[{"fr":"J'aime les livres anciens.","tgt":"أُحِبُّ الْكُتُبَ الْقَدِيمَةَ.","ro":"Uḥibbu l-kutuba l-qadīmata.","lit":"j'aime · les-livres · les-anciens"},{"fr":"Ce marchand vend des livres.","tgt":"هَذَا التَّاجِرُ يَبِيعُ كُتُبًا.","ro":"Hādhā t-tājiru yabīʿu kutuban.","lit":"ce · le-marchand · il-vend · livres"},{"fr":"Les souks de Fès sont nombreux.","tgt":"أَسْوَاقُ فَاسَ كَثِيرَةٌ.","ro":"Aswāqu Fāsa kathīratun.","lit":"souks · [de] Fès · nombreux"},{"fr":"Je cherche des cadeaux pour mes amis.","tgt":"أَبْحَثُ عَنْ هَدَايَا لِأَصْدِقَائِي.","ro":"Abḥathu ʿan hadāyā li-aṣdiqāʾī.","lit":"je-cherche · [après] · cadeaux · pour · amis-de-moi"},{"fr":"Ces tapis sont magnifiques.","tgt":"هَذِهِ السَّجَاجِيدُ رَائِعَةٌ.","ro":"Hādhihi s-sajājīdu rāʾiʿatun.","lit":"ces · les-tapis · magnifique"},{"fr":"Les enfants jouent dans la ruelle.","tgt":"الْأَوْلَادُ يَلْعَبُونَ فِي الزُّقَاقِ.","ro":"Al-awlādu yalʿabūna fī z-zuqāqi.","lit":"les-enfants · ils-jouent · dans · la-ruelle"},{"fr":"Les portes sont ornées de motifs.","tgt":"الْأَبْوَابُ مُزَخْرَفَةٌ.","ro":"Al-abwābu muzakhrafatun.","lit":"les-portes · ornée"},{"fr":"J'ai acheté trois livres.","tgt":"اشْتَرَيْتُ ثَلَاثَةَ كُتُبٍ.","ro":"Ishtaraytu thalāthata kutubin.","lit":"j'ai-acheté · trois · livres"},{"fr":"Les touristes sont nombreux aujourd'hui.","tgt":"السُّيَّاحُ كَثِيرُونَ الْيَوْمَ.","ro":"As-suyyāḥu kathīrūna l-yawma.","lit":"les-touristes · nombreux · aujourd'hui"},{"fr":"Les rues de Fès sont pleines de monde.","tgt":"شَوَارِعُ فَاسَ مُزْدَحِمَةٌ.","ro":"Shawāriʿu Fāsa muzdaḥimatun.","lit":"rues · [de] Fès · bondée"}],"tip":{"title":"Les pluriels « brisés » : « kitab, kutub »","example":"J'aime les livres anciens. — أُحِبُّ <b>الْكُتُبَ</b> الْقَدِيمَةَ.","body":"En français, on forme le pluriel en ajoutant un s qu'on n'entend même pas. En arabe, très souvent, on casse le mot de l'intérieur : on garde les consonnes de la racine et on change les voyelles. C'est pour cela qu'on parle de pluriel brisé. « Kitab », un livre, devient « kutub », des livres : les lettres k, t, b restent, seule la mélodie change. De même, « suq » donne « aswaq », les souks, et « bab », une porte, donne « abwab », les portes. Notre phrase « uhibbu l-kutuba l-qadimata » se dit littéralement : j'aime, les livres, les anciens. Détail surprenant : pour des objets au pluriel, l'adjectif se met au féminin singulier, comme si on parlait d'un ensemble. Astuce : apprenez toujours le mot par paire, « kitab, kutub », comme une petite chanson.","exampleRo":"Uḥibbu l-kutuba l-qadīmata.","lit":"j'aime · les-livres · les-anciens","say":{"Kitab":"كِتَاب","kutub":"كُتُب","suq":"سُوق","aswaq":"أَسْوَاق","bab":"بَاب","abwab":"أَبْوَاب","uhibbu l-kutuba l-qadimata":"أُحِبُّ الْكُتُبَ الْقَدِيمَةَ","kitab, kutub":"كِتَاب، كُتُب"}}},{"title":"Chefchaouen, la ville bleue","phrases":[{"fr":"Chefchaouen est une ville bleue.","tgt":"شَفْشَاوَنُ مَدِينَةٌ زَرْقَاءُ.","ro":"Shafshāwanu madīnatun zarqāʾu.","lit":"Chefchaouen · ville · bleue"},{"fr":"Les murs sont peints en bleu.","tgt":"الْجُدْرَانُ زَرْقَاءُ.","ro":"Al-judrānu zarqāʾu.","lit":"les-murs · bleue"},{"fr":"La ville est dans les montagnes.","tgt":"الْمَدِينَةُ فِي الْجِبَالِ.","ro":"Al-madīnatu fī l-jibāli.","lit":"la-ville · dans · les-montagnes"},{"fr":"Ici, l'air est vraiment frais.","tgt":"الْهَوَاءُ هُنَا مُنْعِشٌ حَقًّا.","ro":"Al-hawāʾu hunā munʿishun ḥaqqan.","lit":"l'air · ici · rafraîchissant · vraiment"},{"fr":"Nous prenons des photos partout.","tgt":"نَلْتَقِطُ صُوَرًا فِي كُلِّ مَكَانٍ.","ro":"Naltaqiṭu ṣuwaran fī kulli makānin.","lit":"nous-prenons · photos · dans · chaque · endroit"},{"fr":"Le chat dort sur les marches.","tgt":"الْقِطُّ نَائِمٌ عَلَى الدَّرَجِ.","ro":"Al-qiṭṭu nāʾimun ʿalā d-daraji.","lit":"le-chat · endormi · sur · l'escalier"},{"fr":"Il y a une source près de la ville.","tgt":"هُنَاكَ نَبْعُ مَاءٍ قُرْبَ الْمَدِينَةِ.","ro":"Hunāka nabʿu māʾin qurba l-madīnati.","lit":"il-y-a · source · [d'] eau · près · [de] la-ville"},{"fr":"Le fromage de chèvre est délicieux ici.","tgt":"جُبْنُ الْمَاعِزِ لَذِيذٌ هُنَا.","ro":"Jubnu l-māʿizi ladhīdhun hunā.","lit":"fromage · [de] la-chèvre · délicieux · ici"},{"fr":"Les habitants sont gentils.","tgt":"السُّكَّانُ لُطَفَاءُ.","ro":"As-sukkānu luṭafāʾu.","lit":"les-habitants · gentils"},{"fr":"Je veux rester ici une semaine.","tgt":"أُرِيدُ الْبَقَاءَ هُنَا أُسْبُوعًا.","ro":"Urīdu l-baqāʾa hunā usbūʿan.","lit":"je-veux · le-séjour · ici · semaine"}]},{"title":"Demander son chemin dans le Rif","phrases":[{"fr":"De Fès à Chefchaouen en car.","tgt":"مِنْ فَاسَ إِلَى شَفْشَاوَنَ بِالْحَافِلَةِ.","ro":"Min Fāsa ilā Shafshāwana bi-l-ḥāfilati.","lit":"de · Fès · à · Chefchaouen · avec · le-car"},{"fr":"Le bus va de la gare à la place.","tgt":"الْحَافِلَةُ تَذْهَبُ مِنَ الْمَحَطَّةِ إِلَى السَّاحَةِ.","ro":"Al-ḥāfilatu tadhhabu mina l-maḥaṭṭati ilā s-sāḥati.","lit":"le-bus · il-va · de · la-gare · à · la-place"},{"fr":"Où est la place principale ?","tgt":"أَيْنَ السَّاحَةُ الرَّئِيسِيَّةُ؟","ro":"Ayna s-sāḥatu r-raʾīsiyyatu?","lit":"où · la-place · la-principale ?"},{"fr":"Tout droit, puis à gauche.","tgt":"إِلَى الْأَمَامِ، ثُمَّ إِلَى الْيَسَارِ.","ro":"Ilā l-amāmi, thumma ilā l-yasāri.","lit":"vers · l'avant, · puis · vers · la-gauche"},{"fr":"Le restaurant est à droite de la fontaine.","tgt":"الْمَطْعَمُ عَلَى يَمِينِ النَّافُورَةِ.","ro":"Al-maṭʿamu ʿalā yamīni n-nāfūrati.","lit":"le-restaurant · sur · droite · [de] la-fontaine"},{"fr":"Le petit musée est à gauche.","tgt":"الْمَتْحَفُ الصَّغِيرُ عَلَى الْيَسَارِ.","ro":"Al-matḥafu ṣ-ṣaghīru ʿalā l-yasāri.","lit":"le-musée · le-petit · sur · la-gauche"},{"fr":"Je marche du matin au soir.","tgt":"أَمْشِي مِنَ الصَّبَاحِ إِلَى الْمَسَاءِ.","ro":"Amshī mina ṣ-ṣabāḥi ilā l-masāʾi.","lit":"je-marche · de · le-matin · à · le-soir"},{"fr":"Tanger est au nord.","tgt":"طَنْجَةُ فِي الشَّمَالِ.","ro":"Ṭanjatu fī sh-shamāli.","lit":"Tanger · dans · le-nord"},{"fr":"Le désert est au sud.","tgt":"الصَّحْرَاءُ فِي الْجَنُوبِ.","ro":"Aṣ-ṣaḥrāʾu fī l-janūbi.","lit":"le-désert · dans · le-sud"},{"fr":"La cascade est loin d'ici ?","tgt":"هَلِ الشَّلَّالُ بَعِيدٌ مِنْ هُنَا؟","ro":"Hali sh-shallālu baʿīdun min hunā?","lit":"[question] · la-cascade · loin · de · ici ?"}],"tip":{"title":"« Min… ila » : de… à, et les directions","example":"De Fès à Chefchaouen en car. — <b>مِنْ</b> فَاسَ <b>إِلَى</b> شَفْشَاوَنَ بِالْحَافِلَةِ.","body":"Pour parler d'un trajet, l'arabe utilise deux petits mots très pratiques : « min », qui veut dire de ou depuis, et « ila », qui veut dire vers ou jusqu'à. Ils fonctionnent comme en français, l'un marque le point de départ, l'autre la destination. Notre phrase « min Fasa ila Shafshawana bil-hafilati » se dit littéralement : de Fès, à Chefchaouen, avec le car. On peut aussi les utiliser pour le temps : « mina s-sabahi ila l-masai », du matin au soir. Pour les directions, retenez « al-yamin », la droite, et « al-yasar », la gauche, avec « ala », sur : « ala l-yasari », à gauche. « Ila l-amami » veut dire tout droit, littéralement vers l'avant. Pour les points cardinaux, « ash-shamal » est le nord et « al-janub » le sud. Astuce : « min » commence comme « mine de départ », et « ila » sonne comme « il y va ».","exampleRo":"Min Fāsa ilā Shafshāwana bi-l-ḥāfilati.","lit":"de · Fès · à · Chefchaouen · avec · le-car","say":{"Min… ila":"مِنْ… إِلَى","min":"مِنْ","ila":"إِلَى","min Fasa ila Shafshawana bil-hafilati":"مِنْ فَاسَ إِلَى شَفْشَاوَنَ بِالْحَافِلَةِ","mina s-sabahi ila l-masai":"مِنَ الصَّبَاحِ إِلَى الْمَسَاءِ","al-yamin":"الْيَمِين","al-yasar":"الْيَسَار","ala":"عَلَى","ala l-yasari":"عَلَى الْيَسَارِ","Ila l-amami":"إِلَى الْأَمَامِ","ash-shamal":"الشَّمَال","al-janub":"الْجَنُوب"}}},{"title":"Essaouira, au bord de l'océan","phrases":[{"fr":"Essaouira est au bord de l'océan.","tgt":"الصَّوِيرَةُ عَلَى شَاطِئِ الْمُحِيطِ.","ro":"Aṣ-Ṣawīratu ʿalā shāṭiʾi l-muḥīṭi.","lit":"Essaouira · sur · rivage · [de] l'océan"},{"fr":"Aujourd'hui, le vent est fort.","tgt":"الْيَوْمَ الرِّيحُ قَوِيَّةٌ.","ro":"Al-yawma r-rīḥu qawiyyatun.","lit":"aujourd'hui · le-vent · fort"},{"fr":"Les barques bleues sont dans le port.","tgt":"الْقَوَارِبُ الزَّرْقَاءُ فِي الْمِينَاءِ.","ro":"Al-qawāribu z-zarqāʾu fī l-mīnāʾi.","lit":"les-barques · la-bleue · dans · le-port"},{"fr":"Le poisson est très frais.","tgt":"السَّمَكُ طَازَجٌ جِدًّا.","ro":"As-samaku ṭāzajun jiddan.","lit":"le-poisson · frais · très"},{"fr":"Je veux du poisson grillé.","tgt":"أُرِيدُ سَمَكًا مَشْوِيًّا.","ro":"Urīdu samakan mashwiyyan.","lit":"je-veux · poisson · grillé"},{"fr":"Les mouettes volent au-dessus du port.","tgt":"تَطِيرُ النَّوَارِسُ فَوْقَ الْمِينَاءِ.","ro":"Taṭīru n-nawārisu fawqa l-mīnāʾi.","lit":"elle-vole · les-mouettes · au-dessus · [de] le-port"},{"fr":"La plage est longue et large.","tgt":"الشَّاطِئُ طَوِيلٌ وَوَاسِعٌ.","ro":"Ash-shāṭiʾu ṭawīlun wa-wāsiʿun.","lit":"la-plage · longue · [et] large"},{"fr":"L'eau de l'océan est froide.","tgt":"مَاءُ الْمُحِيطِ بَارِدٌ.","ro":"Māʾu l-muḥīṭi bāridun.","lit":"eau · [de] l'océan · froide"},{"fr":"La médina d'Essaouira est blanche.","tgt":"مَدِينَةُ الصَّوِيرَةِ الْقَدِيمَةُ بَيْضَاءُ.","ro":"Madīnatu ṣ-Ṣawīrati l-qadīmatu bayḍāʾu.","lit":"ville · [d'] Essaouira · l'ancienne · blanche"},{"fr":"Je me sens bien ici.","tgt":"أَشْعُرُ بِالرَّاحَةِ هُنَا.","ro":"Ashʿuru bi-r-rāḥati hunā.","lit":"je-ressens · [avec] le-bien-être · ici"}]},{"title":"Marchander au souk d'Essaouira","phrases":[{"fr":"Combien coûte ce plat en céramique ?","tgt":"بِكَمْ هَذَا الطَّبَقُ الْخَزَفِيُّ؟","ro":"Bi-kam hādhā ṭ-ṭabaqu l-khazafiyyu?","lit":"[à] combien · ce · le-plat · le-en-céramique ?"},{"fr":"Il coûte cinquante dirhams.","tgt":"ثَمَنُهُ خَمْسُونَ دِرْهَمًا.","ro":"Thamanuhu khamsūna dirhaman.","lit":"prix-de-lui · cinquante · dirham"},{"fr":"C'est beaucoup trop cher !","tgt":"هَذَا غَالٍ جِدًّا!","ro":"Hādhā ghālin jiddan!","lit":"ceci · cher · très !"},{"fr":"Je vous en donne trente dirhams.","tgt":"أُعْطِيكَ ثَلَاثِينَ دِرْهَمًا.","ro":"Uʿṭīka thalāthīna dirhaman.","lit":"je-donne-toi · trente · dirham"},{"fr":"D'accord, quarante dirhams.","tgt":"حَسَنًا، أَرْبَعُونَ دِرْهَمًا.","ro":"Ḥasanan, arbaʿūna dirhaman.","lit":"bien, · quarante · dirham"},{"fr":"Ce tapis coûte mille dirhams.","tgt":"هَذِهِ السَّجَّادَةُ بِأَلْفِ دِرْهَمٍ.","ro":"Hādhihi s-sajjādatu bi-alfi dirhamin.","lit":"ce · le-tapis · [à] mille · dirham"},{"fr":"Notre groupe compte quinze personnes.","tgt":"فِي مَجْمُوعَتِنَا خَمْسَةَ عَشَرَ شَخْصًا.","ro":"Fī majmūʿatinā khamsata ʿashara shakhṣan.","lit":"dans · groupe-de-nous · quinze · personne"},{"fr":"Le billet coûte vingt-cinq dirhams.","tgt":"التَّذْكِرَةُ بِخَمْسَةٍ وَعِشْرِينَ دِرْهَمًا.","ro":"At-tadhkiratu bi-khamsatin wa-ʿishrīna dirhaman.","lit":"le-billet · [à] cinq · [et] vingt · dirham"},{"fr":"Voici cent dirhams.","tgt":"هَذِهِ مِئَةُ دِرْهَمٍ.","ro":"Hādhihi miʾatu dirhamin.","lit":"celle-ci · cent · dirham"},{"fr":"Votre monnaie : onze dirhams.","tgt":"الْبَاقِي أَحَدَ عَشَرَ دِرْهَمًا.","ro":"Al-bāqī aḥada ʿashara dirhaman.","lit":"le-reste · onze · dirham"}],"tip":{"title":"Les nombres au-delà de dix et les prix","example":"Il coûte cinquante dirhams. — ثَمَنُهُ <b>خَمْسُونَ</b> <b>دِرْهَمًا</b>.","body":"Au souk, les prix dépassent vite dix, alors voici la logique. Les dizaines se forment en ajoutant « una » à un chiffre que vous connaissez déjà : « thalatha », trois, donne « thalathuna », trente ; « arbaa », quatre, donne « arbauna », quarante ; et « khamsa », cinq, donne « khamsuna », cinquante. Seul vingt est un peu à part : « ishruna ». Pour vingt-cinq, on dit comme autrefois en français, cinq et vingt : « khamsatun wa ishruna ». Surprise : après onze, le nom reste au singulier ! Notre phrase « thamanuhu khamsuna dirhaman » se dit littéralement : son prix, cinquante, dirham. Retenez aussi « mia », cent, et « alf », mille. Pour demander le prix, la question magique est « bikam », à combien. Astuce : entraînez-vous en lisant à voix haute les prix sur les étiquettes de vos courses.","exampleRo":"Thamanuhu khamsūna dirhaman.","lit":"prix-de-lui · cinquante · dirham","say":{"thalatha":"ثَلَاثَة","thalathuna":"ثَلَاثُونَ","arbaa":"أَرْبَعَة","arbauna":"أَرْبَعُونَ","khamsa":"خَمْسَة","khamsuna":"خَمْسُونَ","ishruna":"عِشْرُونَ","khamsatun wa ishruna":"خَمْسَةٌ وَعِشْرُونَ","thamanuhu khamsuna dirhaman":"ثَمَنُهُ خَمْسُونَ دِرْهَمًا","mia":"مِئَة","alf":"أَلْف","bikam":"بِكَمْ"}}},{"title":"Route vers le désert de Merzouga","phrases":[{"fr":"Nous partons vers le désert de Merzouga.","tgt":"نَذْهَبُ إِلَى صَحْرَاءِ مَرْزُوكَةَ.","ro":"Nadhhabu ilā ṣaḥrāʾi Marzūkata.","lit":"nous-allons · vers · désert · [de] Merzouga"},{"fr":"La route traverse l'Atlas.","tgt":"الطَّرِيقُ يَعْبُرُ جِبَالَ الْأَطْلَسِ.","ro":"Aṭ-ṭarīqu yaʿburu jibāla l-Aṭlasi.","lit":"la-route · elle-traverse · montagnes · [de] l'Atlas"},{"fr":"Le paysage change beaucoup.","tgt":"يَتَغَيَّرُ الْمَنْظَرُ كَثِيرًا.","ro":"Yataghayyaru l-manẓaru kathīran.","lit":"il-change · le-paysage · beaucoup"},{"fr":"Le chauffeur connaît bien la route.","tgt":"السَّائِقُ يَعْرِفُ الطَّرِيقَ جَيِّدًا.","ro":"As-sāʾiqu yaʿrifu ṭ-ṭarīqa jayyidan.","lit":"le-chauffeur · il-connaît · la-route · bien"},{"fr":"Nous faisons une pause à Ouarzazate.","tgt":"نَتَوَقَّفُ فِي وَرْزَازَاتَ.","ro":"Natawaqqafu fī Warzāzāta.","lit":"nous-nous-arrêtons · dans · Ouarzazate"},{"fr":"Il fait très chaud dans la voiture.","tgt":"الْجَوُّ حَارٌّ جِدًّا فِي السَّيَّارَةِ.","ro":"Al-jawwu ḥārrun jiddan fī s-sayyārati.","lit":"le-temps · chaud · très · dans · la-voiture"},{"fr":"Tu as de l'eau avec toi ?","tgt":"هَلْ عِنْدَكَ مَاءٌ؟","ro":"Hal ʿindaka māʾun?","lit":"[question] · chez-toi · eau ?"},{"fr":"Oui, j'ai deux bouteilles.","tgt":"نَعَمْ، عِنْدِي زُجَاجَتَانِ.","ro":"Naʿam, ʿindī zujājatāni.","lit":"oui, · chez-moi · deux-bouteilles"},{"fr":"Les dunes sont dorées.","tgt":"الْكُثْبَانُ ذَهَبِيَّةٌ.","ro":"Al-kuthbānu dhahabiyyatun.","lit":"les-dunes · dorée"},{"fr":"Le silence du désert est impressionnant.","tgt":"صَمْتُ الصَّحْرَاءِ مُدْهِشٌ.","ro":"Ṣamtu ṣ-ṣaḥrāʾi mudhishun.","lit":"silence · [du] le-désert · impressionnant"}]},{"title":"Une nuit sous les étoiles","phrases":[{"fr":"Nous allons dormir sous une tente.","tgt":"سَنَنَامُ فِي خَيْمَةٍ.","ro":"Sananāmu fī khaymatin.","lit":"nous-dormirons · dans · tente"},{"fr":"Demain, je monterai sur un chameau.","tgt":"غَدًا سَأَرْكَبُ جَمَلًا.","ro":"Ghadan saʾarkabu jamalan.","lit":"demain · je-monterai · chameau"},{"fr":"Nous verrons le lever du soleil.","tgt":"سَنَرَى شُرُوقَ الشَّمْسِ.","ro":"Sanarā shurūqa sh-shamsi.","lit":"nous-verrons · lever · [de] le-soleil"},{"fr":"Le guide préparera le dîner.","tgt":"سَيُحَضِّرُ الْمُرْشِدُ الْعَشَاءَ.","ro":"Sayuḥaḍḍiru l-murshidu l-ʿashāʾa.","lit":"il-préparera · le-guide · le-dîner"},{"fr":"Nous mangerons un tajine sous les étoiles.","tgt":"سَنَأْكُلُ طَاجِينًا تَحْتَ النُّجُومِ.","ro":"Sanaʾkulu ṭājīnan taḥta n-nujūmi.","lit":"nous-mangerons · tajine · sous · les-étoiles"},{"fr":"La nuit, il fera froid.","tgt":"سَيَكُونُ الْجَوُّ بَارِدًا فِي اللَّيْلِ.","ro":"Sayakūnu l-jawwu bāridan fī l-layli.","lit":"il-sera · le-temps · froid · dans · la-nuit"},{"fr":"Je prendrai une veste chaude.","tgt":"سَآخُذُ سُتْرَةً دَافِئَةً.","ro":"Saʾākhudhu sutratan dāfiʾatan.","lit":"je-prendrai · veste · chaude"},{"fr":"J'écrirai sur ce voyage.","tgt":"سَوْفَ أَكْتُبُ عَنْ هَذِهِ الرِّحْلَةِ.","ro":"Sawfa aktubu ʿan hādhihi r-riḥlati.","lit":"[futur] · j'écris · sur · ce · le-voyage"},{"fr":"Nous partirons à l'aube.","tgt":"سَوْفَ نَنْطَلِقُ عِنْدَ الْفَجْرِ.","ro":"Sawfa nanṭaliqu ʿinda l-fajri.","lit":"[futur] · nous-partons · à · l'aube"},{"fr":"Le ciel sera plein d'étoiles.","tgt":"سَتَكُونُ السَّمَاءُ مَلِيئَةً بِالنُّجُومِ.","ro":"Satakūnu s-samāʾu malīʾatan bi-n-nujūmi.","lit":"elle-sera · le-ciel · plein · [de] les-étoiles"}],"tip":{"title":"Le futur avec « sa- » et « sawfa »","example":"Nous allons dormir sous une tente. — <b>سَنَنَامُ</b> فِي خَيْمَةٍ.","body":"Bonne nouvelle : pour parler du futur en arabe, il n'y a presque rien à apprendre de nouveau. On prend le verbe au présent, que vous connaissez déjà, et on colle simplement « sa » devant. « Nanamu », nous dormons, devient « sananamu », nous dormirons. « Arkabu », je monte, devient « saarkabu », je monterai. Notre phrase « sananamu fi khaymatin » se dit littéralement : nous dormirons, dans, une tente. Il existe aussi un petit mot séparé, « sawfa », qui a le même sens et se place devant le verbe : « sawfa aktubu », j'écrirai. « Sa » est court et très courant à l'oral, « sawfa » sonne un peu plus solennel, comme une promesse. Astuce : pensez au « sa » comme à un petit pas en avant, qui pousse le verbe vers demain.","exampleRo":"Sananāmu fī khaymatin.","lit":"nous-dormirons · dans · tente","say":{"sawfa":"سَوْفَ","Nanamu":"نَنَامُ","sananamu":"سَنَنَامُ","Arkabu":"أَرْكَبُ","saarkabu":"سَأَرْكَبُ","sananamu fi khaymatin":"سَنَنَامُ فِي خَيْمَةٍ","sawfa aktubu":"سَوْفَ أَكْتُبُ"}}},{"title":"Un petit souci à la pharmacie","phrases":[{"fr":"Depuis hier, j'ai mal au ventre.","tgt":"مُنْذُ أَمْسِ عِنْدِي أَلَمٌ فِي الْبَطْنِ.","ro":"Mundhu amsi ʿindī alamun fī l-baṭni.","lit":"depuis · hier · chez-moi · douleur · dans · le-ventre"},{"fr":"Où est la pharmacie la plus proche ?","tgt":"أَيْنَ أَقْرَبُ صَيْدَلِيَّةٍ؟","ro":"Ayna aqrabu ṣaydaliyyatin?","lit":"où · plus-proche · pharmacie ?"},{"fr":"La pharmacie est en face de l'office du tourisme.","tgt":"الصَّيْدَلِيَّةُ أَمَامَ مَكْتَبِ السِّيَاحَةِ.","ro":"Aṣ-ṣaydaliyyatu amāma maktabi s-siyāḥati.","lit":"la-pharmacie · devant · bureau · [de] le-tourisme"},{"fr":"J'ai peut-être trop mangé de couscous.","tgt":"رُبَّمَا أَكَلْتُ كَثِيرًا مِنَ الْكُسْكُسِ.","ro":"Rubbamā akaltu kathīran mina l-kuskusi.","lit":"peut-être · j'ai-mangé · beaucoup · de · le-couscous"},{"fr":"Vous avez un médicament pour le ventre ?","tgt":"هَلْ عِنْدَكَ دَوَاءٌ لِلْبَطْنِ؟","ro":"Hal ʿindaka dawāʾun li-l-baṭni?","lit":"[question] · chez-toi · médicament · pour · le-ventre ?"},{"fr":"Un comprimé après chaque repas.","tgt":"قُرْصٌ بَعْدَ كُلِّ وَجْبَةٍ.","ro":"Qurṣun baʿda kulli wajbatin.","lit":"comprimé · après · chaque · repas"},{"fr":"L'eau est importante en été.","tgt":"الْمَاءُ مُهِمٌّ فِي الصَّيْفِ.","ro":"Al-māʾu muhimmun fī ṣ-ṣayfi.","lit":"l'eau · importante · dans · l'été"},{"fr":"J'ai aussi un coup de soleil.","tgt":"عِنْدِي أَيْضًا حُرُوقُ شَمْسٍ.","ro":"ʿIndī ayḍan ḥurūqu shamsin.","lit":"chez-moi · aussi · brûlures · [de] soleil"},{"fr":"Cette pommade est très efficace.","tgt":"هَذَا الْمَرْهَمُ فَعَّالٌ جِدًّا.","ro":"Hādhā l-marhamu faʿʿālun jiddan.","lit":"cette · la-pommade · efficace · très"},{"fr":"Merci, le pharmacien est très gentil.","tgt":"شُكْرًا، الصَّيْدَلِيُّ لَطِيفٌ جِدًّا.","ro":"Shukran, aṣ-ṣaydaliyyu laṭīfun jiddan.","lit":"merci, · le-pharmacien · gentil · très"}]},{"title":"À l'office du tourisme","phrases":[{"fr":"Est-ce que je peux prendre un plan ?","tgt":"هَلْ يُمْكِنُنِي أَنْ آخُذَ خَرِيطَةً؟","ro":"Hal yumkinunī an ākhudha kharīṭatan?","lit":"[question] · il-m'est-possible · [que] · je-prenne · plan ?"},{"fr":"Est-ce que je peux poser une question ?","tgt":"هَلْ يُمْكِنُنِي أَنْ أَسْأَلَ سُؤَالًا؟","ro":"Hal yumkinunī an asʾala suʾālan?","lit":"[question] · il-m'est-possible · [que] · je-demande · question ?"},{"fr":"Bien sûr, je vous en prie.","tgt":"طَبْعًا، تَفَضَّلْ.","ro":"Ṭabʿan, tafaḍḍal.","lit":"bien-sûr, · je-t'en-prie"},{"fr":"Est-ce que je peux visiter le palais aujourd'hui ?","tgt":"هَلْ يُمْكِنُنِي أَنْ أَزُورَ الْقَصْرَ الْيَوْمَ؟","ro":"Hal yumkinunī an azūra l-qaṣra l-yawma?","lit":"[question] · il-m'est-possible · [que] · je-visite · le-palais · aujourd'hui ?"},{"fr":"Est-ce que nous pouvons payer par carte ?","tgt":"هَلْ يُمْكِنُنَا أَنْ نَدْفَعَ بِالْبِطَاقَةِ؟","ro":"Hal yumkinunā an nadfaʿa bi-l-biṭāqati?","lit":"[question] · il-nous-est-possible · [que] · nous-payions · avec · la-carte ?"},{"fr":"Est-ce que je peux laisser mon bagage ici ?","tgt":"هَلْ يُمْكِنُنِي أَنْ أَتْرُكَ حَقِيبَتِي هُنَا؟","ro":"Hal yumkinunī an atruka ḥaqībatī hunā?","lit":"[question] · il-m'est-possible · [que] · je-laisse · bagage-de-moi · ici ?"},{"fr":"Oui, c'est gratuit.","tgt":"نَعَمْ، هَذَا مَجَّانِيٌّ.","ro":"Naʿam, hādhā majjāniyyun.","lit":"oui, · ceci · gratuit"},{"fr":"Est-ce que je peux réserver une excursion ?","tgt":"هَلْ يُمْكِنُنِي أَنْ أَحْجِزَ جَوْلَةً؟","ro":"Hal yumkinunī an aḥjiza jawlatan?","lit":"[question] · il-m'est-possible · [que] · je-réserve · excursion ?"},{"fr":"Est-ce que tu peux écrire l'adresse du riad ?","tgt":"هَلْ يُمْكِنُكَ أَنْ تَكْتُبَ عُنْوَانَ الرِّيَاضِ؟","ro":"Hal yumkinuka an taktuba ʿunwāna r-riyāḍi?","lit":"[question] · il-t'est-possible · [que] · tu-écrives · adresse · [de] le-riad ?"},{"fr":"Merci beaucoup pour le plan.","tgt":"شُكْرًا جَزِيلًا عَلَى الْخَرِيطَةِ.","ro":"Shukran jazīlan ʿalā l-kharīṭati.","lit":"merci · abondant · pour · le-plan"}],"tip":{"title":"Demander poliment : « hal yumkinuni », est-ce que je peux","example":"Est-ce que je peux prendre un plan ? — <b>هَلْ</b> <b>يُمْكِنُنِي</b> أَنْ آخُذَ خَرِيطَةً؟","body":"Pour demander quelque chose avec politesse, l'arabe utilise une formule toute faite qu'il vaut mieux apprendre d'un bloc : « hal yumkinuni an », est-ce que je peux. Vous connaissez déjà « hal », le mot qui transforme une phrase en question. « Yumkinuni » veut dire littéralement : il m'est possible, avec « ni », moi, collé à la fin. Puis vient « an », que, suivi du verbe au présent, avec un petit « a » final. Notre phrase « hal yumkinuni an akhudha kharitatan » se dit donc mot à mot : est-ce que, il m'est possible, que je prenne, un plan. Pour dire nous, on remplace « ni » par « na » : « hal yumkinuna », est-ce que nous pouvons. Pour demander à quelqu'un, on dit « hal yumkinuka », est-ce que tu peux. Astuce : prononcez la formule comme un seul long mot, et changez seulement le verbe à la fin.","exampleRo":"Hal yumkinunī an ākhudha kharīṭatan?","lit":"[question] · il-m'est-possible · [que] · je-prenne · plan ?","say":{"hal yumkinuni":"هَلْ يُمْكِنُنِي","hal yumkinuni an":"هَلْ يُمْكِنُنِي أَنْ","hal":"هَلْ","Yumkinuni":"يُمْكِنُنِي","an":"أَنْ","hal yumkinuni an akhudha kharitatan":"هَلْ يُمْكِنُنِي أَنْ آخُذَ خَرِيطَةً","hal yumkinuna":"هَلْ يُمْكِنُنَا","hal yumkinuka":"هَلْ يُمْكِنُكَ"}}},{"title":"Un bagage égaré et un train en retard","phrases":[{"fr":"Ma valise a disparu.","tgt":"حَقِيبَتِي ضَائِعَةٌ.","ro":"Ḥaqībatī ḍāʾiʿatun.","lit":"valise-de-moi · perdue"},{"fr":"Elle est rouge et grande.","tgt":"هِيَ حَمْرَاءُ وَكَبِيرَةٌ.","ro":"Hiya ḥamrāʾu wa-kabīratun.","lit":"elle · rouge · [et] grande"},{"fr":"Voici mon nom et mon adresse.","tgt":"هَذَا اسْمِي وَعُنْوَانِي.","ro":"Hādhā smī wa-ʿunwānī.","lit":"ceci · nom-de-moi · [et] adresse-de-moi"},{"fr":"Mon riad est dans la médina de Marrakech.","tgt":"رِيَاضِي فِي مَدِينَةِ مُرَّاكُشَ الْقَدِيمَةِ.","ro":"Riyāḍī fī madīnati Murrākusha l-qadīmati.","lit":"riad-de-moi · dans · ville · [de] Marrakech · l'ancienne"},{"fr":"Nous allons chercher votre valise.","tgt":"سَنَبْحَثُ عَنْ حَقِيبَتِكَ.","ro":"Sanabḥathu ʿan ḥaqībatika.","lit":"nous-chercherons · [après] · valise-de-toi"},{"fr":"Elle arrivera demain matin.","tgt":"سَتَصِلُ غَدًا صَبَاحًا.","ro":"Sataṣilu ghadan ṣabāḥan.","lit":"elle-arrivera · demain · matin"},{"fr":"Le train pour Casablanca est en retard.","tgt":"قِطَارُ الدَّارِ الْبَيْضَاءِ مُتَأَخِّرٌ.","ro":"Qiṭāru d-Dāri l-Bayḍāʾi mutaʾakhkhirun.","lit":"train · [de] Casablanca · en-retard"},{"fr":"Il a une heure de retard.","tgt":"هُوَ مُتَأَخِّرٌ سَاعَةً.","ro":"Huwa mutaʾakhkhirun sāʿatan.","lit":"lui · en-retard · heure"},{"fr":"Pas de problème, nous attendons.","tgt":"لَا بَأْسَ، نَنْتَظِرُ.","ro":"Lā baʾsa, nantaẓiru.","lit":"[pas] · mal, · nous-attendons"},{"fr":"Les imprévus font partie du voyage.","tgt":"الْمُفَاجَآتُ جُزْءٌ مِنَ السَّفَرِ.","ro":"Al-mufājaʾātu juzʾun mina s-safari.","lit":"les-surprises · partie · de · le-voyage"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Il est trois heures.","tgt":"السَّاعَةُ الثَّالِثَةُ.","ro":"As-sāʿatu th-thālithatu.","lit":"l'heure · la-troisième"},{"fr":"Mon avion décolle à cinq heures.","tgt":"تُقْلِعُ طَائِرَتِي فِي السَّاعَةِ الْخَامِسَةِ.","ro":"Tuqliʿu ṭāʾiratī fī s-sāʿati l-khāmisati.","lit":"elle-décolle · avion-de-moi · dans · l'heure · la-cinquième"},{"fr":"Quelle heure est-il à Marrakech ?","tgt":"كَمِ السَّاعَةُ فِي مُرَّاكُشَ؟","ro":"Kami s-sāʿatu fī Murrākusha?","lit":"combien · l'heure · dans · Marrakech ?"},{"fr":"Il est quatre heures et demie.","tgt":"السَّاعَةُ الرَّابِعَةُ وَالنِّصْفُ.","ro":"As-sāʿatu r-rābiʿatu wa-n-niṣfu.","lit":"l'heure · la-quatrième · [et] la-moitié"},{"fr":"Mon voyage au Maroc était magnifique.","tgt":"كَانَتْ رِحْلَتِي إِلَى الْمَغْرِبِ رَائِعَةً.","ro":"Kānat riḥlatī ilā l-Maghribi rāʾiʿatan.","lit":"elle-était · voyage-de-moi · vers · le-Maroc · magnifique"},{"fr":"J'ai appris beaucoup de mots en arabe.","tgt":"تَعَلَّمْتُ كَلِمَاتٍ كَثِيرَةً بِالْعَرَبِيَّةِ.","ro":"Taʿallamtu kalimātin kathīratan bi-l-ʿarabiyyati.","lit":"j'ai-appris · mots · nombreux · en · l'arabe"},{"fr":"Maintenant, je parle un peu l'arabe.","tgt":"الْآنَ أَتَكَلَّمُ الْعَرَبِيَّةَ قَلِيلًا.","ro":"Al-āna atakallamu l-ʿarabiyyata qalīlan.","lit":"maintenant · je-parle · l'arabe · un-peu"},{"fr":"Le prochain module parle de rencontres.","tgt":"الْوَحْدَةُ الْقَادِمَةُ عَنِ اللِّقَاءَاتِ.","ro":"Al-waḥdatu l-qādimatu ʿani l-liqāʾāti.","lit":"le-module · le-prochain · sur · les-rencontres"},{"fr":"Je reviendrai au Maroc un jour.","tgt":"سَأَعُودُ إِلَى الْمَغْرِبِ يَوْمًا مَا.","ro":"Saʾaʿūdu ilā l-Maghribi yawman mā.","lit":"je-reviendrai · vers · le-Maroc · jour · [un]"},{"fr":"À bientôt pour la suite !","tgt":"إِلَى اللِّقَاءِ قَرِيبًا!","ro":"Ilā l-liqāʾi qarīban!","lit":"à · la-rencontre · bientôt !"}],"tip":{"title":"Dire l'heure : « as-saa ath-thalitha »","example":"Il est trois heures. — <b>السَّاعَةُ</b> <b>الثَّالِثَةُ</b>.","body":"Pour dire l'heure, l'arabe ne compte pas les heures comme nous, il les range dans l'ordre. Au lieu de dire il est trois heures, on dit littéralement : l'heure, la troisième. Notre phrase « as-saatu th-thalithatu » se décompose ainsi : « as-saa », l'heure, puis « ath-thalitha », la troisième. Comme « saa » est féminin, le nombre prend lui aussi la forme féminine en « a ». Quatre heures se dit « as-saatu r-rabia », cinq heures « as-saatu l-khamisa ». Pour la demie, on ajoute « wa n-nisf », et la moitié ; pour le quart, « wa r-rub ». Et pour demander l'heure, on dit « kami s-saa », combien l'heure. Astuce : imaginez que les heures font la queue devant vous, la première, la deuxième, la troisième, et appelez simplement la bonne.","exampleRo":"As-sāʿatu th-thālithatu.","lit":"l'heure · la-troisième","say":{"as-saa ath-thalitha":"السَّاعَة الثَّالِثَة","as-saatu th-thalithatu":"السَّاعَةُ الثَّالِثَةُ","as-saa":"السَّاعَة","ath-thalitha":"الثَّالِثَة","saa":"سَاعَة","as-saatu r-rabia":"السَّاعَةُ الرَّابِعَة","as-saatu l-khamisa":"السَّاعَةُ الْخَامِسَة","wa n-nisf":"وَالنِّصْف","wa r-rub":"وَالرُّبْع","kami s-saa":"كَمِ السَّاعَة"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Faire connaissance à Sidi Bou Saïd","phrases":[{"fr":"Bonjour, moi c'est Karim.","tgt":"مَرْحَبًا، أَنَا كَرِيمٌ.","ro":"Marḥaban, anā Karīmun.","lit":"bonjour · moi · Karim"},{"fr":"Ravie de te rencontrer, je suis Leïla.","tgt":"فُرْصَةٌ سَعِيدَةٌ، أَنَا لَيْلَى.","ro":"Furṣatun saʿīdatun, anā Laylā.","lit":"occasion · heureuse · moi · Leïla"},{"fr":"Tu es d'ici ?","tgt":"هَلْ أَنْتَ مِنْ هُنَا؟","ro":"Hal anta min hunā?","lit":"[question] · toi · de · ici ?"},{"fr":"Oui, je suis de Tunis.","tgt":"نَعَمْ، أَنَا مِنْ تُونِسَ.","ro":"Naʿam, anā min Tūnisa.","lit":"oui · moi · de · Tunis"},{"fr":"Et toi, tu es français ?","tgt":"وَأَنْتَ، هَلْ أَنْتَ فَرَنْسِيٌّ؟","ro":"Wa anta, hal anta faransiyyun?","lit":"[et] toi · [question] · toi · français ?"},{"fr":"Oui, je viens de Marseille.","tgt":"نَعَمْ، أَنَا مِنْ مَرْسِيلْيَا.","ro":"Naʿam, anā min Marsīliyā.","lit":"oui · moi · de · Marseille"},{"fr":"Sidi Bou Saïd est un très joli village.","tgt":"سِيدِي بُو سَعِيدْ قَرْيَةٌ جَمِيلَةٌ جِدًّا.","ro":"Sīdī Bū Saʿīd qaryatun jamīlatun jiddan.","lit":"Sidi Bou Saïd · village · joli · très"},{"fr":"Les maisons sont blanches et bleues.","tgt":"الْبُيُوتُ بَيْضَاءُ وَزَرْقَاءُ.","ro":"Al-buyūtu bayḍāʾu wa zarqāʾu.","lit":"les-maisons · blanche · [et] bleue"},{"fr":"Tu es ici en vacances ?","tgt":"هَلْ أَنْتَ هُنَا فِي عُطْلَةٍ؟","ro":"Hal anta hunā fī ʿuṭlatin?","lit":"[question] · toi · ici · dans · vacances ?"},{"fr":"Non, je suis ici pour le travail.","tgt":"لَا، أَنَا هُنَا لِلْعَمَلِ.","ro":"Lā, anā hunā lil-ʿamali.","lit":"non · moi · ici · pour-le-travail"}]},{"title":"Mon nom est…","phrases":[{"fr":"Quel est ton nom ?","tgt":"مَا اسْمُكَ؟","ro":"Mā ismuka?","lit":"quoi · nom-de-toi ?"},{"fr":"Mon nom est Sami.","tgt":"اِسْمِي سَامِي.","ro":"Ismī Sāmī.","lit":"nom-de-moi · Sami"},{"fr":"Et toi, quel est ton nom ?","tgt":"وَأَنْتَ، مَا اسْمُكَ؟","ro":"Wa anta, mā ismuka?","lit":"[et] toi · quoi · nom-de-toi ?"},{"fr":"Mon nom est Hichem, enchanté.","tgt":"اِسْمِي هِشَامٌ، فُرْصَةٌ سَعِيدَةٌ.","ro":"Ismī Hishāmun, furṣatun saʿīdatun.","lit":"nom-de-moi · Hichem · occasion · heureuse"},{"fr":"Quel est le nom de ton ami ?","tgt":"مَا اسْمُ صَدِيقِكَ؟","ro":"Mā ismu ṣadīqika?","lit":"quoi · nom · ami-de-toi ?"},{"fr":"Son nom est Amine.","tgt":"اِسْمُهُ أَمِينٌ.","ro":"Ismuhu Amīnun.","lit":"nom-de-lui · Amine"},{"fr":"Et elle, quel est son nom ?","tgt":"وَمَا اسْمُهَا؟","ro":"Wa mā ismuhā?","lit":"[et] · quoi · nom-d'elle ?"},{"fr":"Elle s'appelle Salma.","tgt":"اِسْمُهَا سَلْمَى.","ro":"Ismuhā Salmā.","lit":"nom-d'elle · Salma"},{"fr":"Mon nom de famille est Haddad.","tgt":"اِسْمُ عَائِلَتِي حَدَّادٌ.","ro":"Ismu ʿāʾilatī Ḥaddādun.","lit":"nom · famille-de-moi · Haddad"},{"fr":"Ton prénom est très joli.","tgt":"اِسْمُكَ جَمِيلٌ جِدًّا.","ro":"Ismuka jamīlun jiddan.","lit":"nom-de-toi · joli · très"}],"tip":{"title":"Se présenter : « ismi », mon nom","example":"Mon nom est Sami. — <b>اِسْمِي</b> سَامِي.","body":"Pour dire comment on s'appelle, l'arabe ne dit pas « je m'appelle » : il dit simplement « mon nom, Sami ». Le mot « ism » veut dire nom, et on lui colle la petite terminaison « i », qui signifie « à moi ». « Ismi Sami » se dit donc littéralement : nom de moi, Sami. Il n'y a pas de verbe être au présent, la phrase est complète ainsi. Pour demander, on dit « ma ismuka ? », mot à mot : quoi, ton nom ? On peut aussi parler des autres : « ismuhu Amine », son nom à lui est Amine, et « ismuha Salma », son nom à elle est Salma. Astuce pour retenir : « ismi », c'est « ism » suivi d'un petit « i » qui vous désigne, comme une étiquette que vous portez sur vous.","exampleRo":"Ismī Sāmī.","lit":"nom-de-moi · Sami","say":{"ismi":"اِسْمِي","ism":"اِسْم","Ismi Sami":"اِسْمِي سَامِي","ma ismuka ?":"مَا اسْمُكَ؟","ismuhu Amine":"اِسْمُهُ أَمِين","ismuha Salma":"اِسْمُهَا سَلْمَى"}}},{"title":"Parler de son travail","phrases":[{"fr":"Quel est ton travail ?","tgt":"مَا عَمَلُكَ؟","ro":"Mā ʿamaluka?","lit":"quoi · travail-de-toi ?"},{"fr":"Je suis ingénieur à Tunis.","tgt":"أَنَا مُهَنْدِسٌ فِي تُونِسَ.","ro":"Anā muhandisun fī Tūnisa.","lit":"moi · ingénieur · dans · Tunis"},{"fr":"Je travaille dans une banque.","tgt":"أَعْمَلُ فِي بَنْكٍ.","ro":"Aʿmalu fī bankin.","lit":"je-travaille · dans · banque"},{"fr":"Mon bureau est près de la médina.","tgt":"مَكْتَبِي قَرِيبٌ مِنَ الْمَدِينَةِ الْعَتِيقَةِ.","ro":"Maktabī qarībun mina al-madīnati al-ʿatīqati.","lit":"bureau-de-moi · proche · de · la-médina · l'-ancienne"},{"fr":"Ma sœur est médecin à La Marsa.","tgt":"أُخْتِي طَبِيبَةٌ فِي الْمَرْسَى.","ro":"Ukhtī ṭabībatun fī al-Marsā.","lit":"sœur-de-moi · médecin · dans · La Marsa"},{"fr":"Ton travail est difficile ?","tgt":"هَلْ عَمَلُكَ صَعْبٌ؟","ro":"Hal ʿamaluka ṣaʿbun?","lit":"[question] · travail-de-toi · difficile ?"},{"fr":"Non, il est facile et agréable.","tgt":"لَا، هُوَ سَهْلٌ وَمُمْتِعٌ.","ro":"Lā, huwa sahlun wa mumtiʿun.","lit":"non · lui · facile · [et] agréable"},{"fr":"Je commence le travail à huit heures.","tgt":"أَبْدَأُ الْعَمَلَ فِي السَّاعَةِ الثَّامِنَةِ.","ro":"Abdaʾu al-ʿamala fī as-sāʿati ath-thāminati.","lit":"je-commence · le-travail · dans · l'-heure · la-huitième"},{"fr":"Mon collègue Karim est très gentil.","tgt":"زَمِيلِي كَرِيمٌ لَطِيفٌ جِدًّا.","ro":"Zamīlī Karīmun laṭīfun jiddan.","lit":"collègue-de-moi · Karim · gentil · très"},{"fr":"Nous déjeunons ensemble au bureau.","tgt":"نَتَغَدَّى مَعًا فِي الْمَكْتَبِ.","ro":"Nataghaddā maʿan fī al-maktabi.","lit":"nous-déjeunons · ensemble · dans · le-bureau"}]},{"title":"Une amie de La Marsa","phrases":[{"fr":"Salma, tu es de La Marsa ?","tgt":"سَلْمَى، هَلْ أَنْتِ مِنَ الْمَرْسَى؟","ro":"Salmā, hal anti mina al-Marsā?","lit":"Salma · [question] · toi (f.) · de · La Marsa ?"},{"fr":"Oui, j'habite à La Marsa.","tgt":"نَعَمْ، أَسْكُنُ فِي الْمَرْسَى.","ro":"Naʿam, askunu fī al-Marsā.","lit":"oui · j'habite · dans · La Marsa"},{"fr":"Tu es étudiante, Leïla ?","tgt":"هَلْ أَنْتِ طَالِبَةٌ يَا لَيْلَى؟","ro":"Hal anti ṭālibatun yā Laylā?","lit":"[question] · toi (f.) · étudiante · [ô] · Leïla ?"},{"fr":"Non, je suis professeure.","tgt":"لَا، أَنَا مُعَلِّمَةٌ.","ro":"Lā, anā muʿallimatun.","lit":"non · moi · professeure"},{"fr":"Comment vas-tu, Houda ?","tgt":"كَيْفَ حَالُكِ يَا هُدَى؟","ro":"Kayfa ḥāluki yā Hudā?","lit":"comment · état-de-toi (f.) · [ô] · Houda ?"},{"fr":"Où travailles-tu, Mouna ?","tgt":"أَيْنَ تَعْمَلِينَ يَا مُنَى؟","ro":"Ayna taʿmalīna yā Munā?","lit":"où · tu-travailles (f.) · [ô] · Mouna ?"},{"fr":"Ta robe est très jolie, Salma.","tgt":"فُسْتَانُكِ جَمِيلٌ جِدًّا يَا سَلْمَى.","ro":"Fustānuki jamīlun jiddan yā Salmā.","lit":"robe-de-toi (f.) · jolie · très · [ô] · Salma"},{"fr":"Tu parles bien le français !","tgt":"تَتَكَلَّمِينَ الْفَرَنْسِيَّةَ جَيِّدًا!","ro":"Tatakallamīna al-faransiyyata jayyidan!","lit":"tu-parles (f.) · le-français · bien !"},{"fr":"Tu es tunisienne ?","tgt":"هَلْ أَنْتِ تُونِسِيَّةٌ؟","ro":"Hal anti tūnisiyyatun?","lit":"[question] · toi (f.) · tunisienne ?"},{"fr":"Bienvenue chez nous, Leïla.","tgt":"أَهْلًا بِكِ عِنْدَنَا يَا لَيْلَى.","ro":"Ahlan biki ʿindanā yā Laylā.","lit":"bienvenue · à-toi (f.) · chez-nous · [ô] · Leïla"}],"tip":{"title":"Parler à une femme : « anti » et les terminaisons féminines","example":"Tu es étudiante, Leïla ? — هَلْ <b>أَنْتِ</b> <b>طَالِبَةٌ</b> يَا لَيْلَى؟","body":"En arabe, le « tu » change selon qu'on parle à un homme ou à une femme. À un homme, on dit « anta » ; à une femme, on dit « anti ». Les petites terminaisons suivent la même logique : « kayfa haluka » pour un homme devient « kayfa haluki » pour une femme, littéralement : comment, ton état ? Avec les verbes, on ajoute « ina » à la fin : « taamalina », tu travailles, quand on parle à une femme. Les adjectifs prennent aussi la marque du féminin, un petit « a » final : « talib », étudiant, devient « taliba », étudiante. Ainsi « hal anti taliba, ya Layla ? » se dit mot à mot : est-ce que, toi, étudiante, ô Leïla ? Le petit mot « ya » sert à appeler quelqu'un par son prénom. Astuce : le son « i » est la signature du féminin quand on s'adresse à quelqu'un, « anti, haluki, taamalina ».","exampleRo":"Hal anti ṭālibatun yā Laylā?","lit":"[question] · toi (f.) · étudiante · [ô] · Leïla ?","say":{"anti":"أَنْتِ","anta":"أَنْتَ","kayfa haluka":"كَيْفَ حَالُكَ","kayfa haluki":"كَيْفَ حَالُكِ","taamalina":"تَعْمَلِينَ","talib":"طَالِب","taliba":"طَالِبَة","hal anti taliba, ya Layla ?":"هَلْ أَنْتِ طَالِبَة، يَا لَيْلَى؟","ya":"يَا","anti, haluki, taamalina":"أَنْتِ، حَالُكِ، تَعْمَلِينَ"}}},{"title":"Les loisirs à La Marsa","phrases":[{"fr":"Que fais-tu pendant le week-end ?","tgt":"مَاذَا تَفْعَلُ فِي عُطْلَةِ نِهَايَةِ الْأُسْبُوعِ؟","ro":"Mādhā tafʿalu fī ʿuṭlati nihāyati al-usbūʿi?","lit":"quoi · tu-fais · dans · congé · fin · la-semaine ?"},{"fr":"Je marche sur la corniche de La Marsa.","tgt":"أَمْشِي عَلَى كُورْنِيشِ الْمَرْسَى.","ro":"Amshī ʿalā kūrnīshi al-Marsā.","lit":"je-marche · sur · corniche · La Marsa"},{"fr":"Je lis beaucoup le soir.","tgt":"أَقْرَأُ كَثِيرًا فِي الْمَسَاءِ.","ro":"Aqraʾu kathīran fī al-masāʾi.","lit":"je-lis · beaucoup · dans · le-soir"},{"fr":"Mon frère joue au football.","tgt":"أَخِي يَلْعَبُ كُرَةَ الْقَدَمِ.","ro":"Akhī yalʿabu kurata al-qadami.","lit":"frère-de-moi · il-joue · ballon · le-pied"},{"fr":"Tu nages en été ?","tgt":"هَلْ تَسْبَحُ فِي الصَّيْفِ؟","ro":"Hal tasbaḥu fī aṣ-ṣayfi?","lit":"[question] · tu-nages · dans · l'-été ?"},{"fr":"Oui, la mer est tout près.","tgt":"نَعَمْ، الْبَحْرُ قَرِيبٌ جِدًّا.","ro":"Naʿam, al-baḥru qarībun jiddan.","lit":"oui · la-mer · proche · très"},{"fr":"Ma sœur dessine dans le jardin.","tgt":"أُخْتِي تَرْسُمُ فِي الْحَدِيقَةِ.","ro":"Ukhtī tarsumu fī al-ḥadīqati.","lit":"sœur-de-moi · elle-dessine · dans · le-jardin"},{"fr":"Le vendredi, je fais du vélo.","tgt":"يَوْمَ الْجُمُعَةِ أَرْكَبُ الدَّرَّاجَةَ.","ro":"Yawma al-jumuʿati arkabu ad-darrājata.","lit":"jour · le-vendredi · je-monte · la-bicyclette"},{"fr":"Quel est ton loisir préféré ?","tgt":"مَا هِوَايَتُكَ الْمُفَضَّلَةُ؟","ro":"Mā hiwāyatuka al-mufaḍḍalatu?","lit":"quoi · loisir-de-toi · le-préféré ?"},{"fr":"Mon loisir préféré, c'est la photographie.","tgt":"هِوَايَتِي الْمُفَضَّلَةُ هِيَ التَّصْوِيرُ.","ro":"Hiwāyatī al-mufaḍḍalatu hiya at-taṣwīru.","lit":"loisir-de-moi · le-préféré · elle · la-photographie"}]},{"title":"Ce que j'aime","phrases":[{"fr":"J'aime le thé à la menthe.","tgt":"أُحِبُّ الشَّايَ بِالنَّعْنَاعِ.","ro":"Uḥibbu ash-shāya bin-naʿnāʿi.","lit":"j'aime · le-thé · avec-la-menthe"},{"fr":"J'aime beaucoup Sidi Bou Saïd.","tgt":"أُحِبُّ سِيدِي بُو سَعِيدْ كَثِيرًا.","ro":"Uḥibbu Sīdī Bū Saʿīd kathīran.","lit":"j'aime · Sidi Bou Saïd · beaucoup"},{"fr":"Tu aimes le couscous ?","tgt":"هَلْ تُحِبُّ الْكُسْكُسَ؟","ro":"Hal tuḥibbu al-kuskusa?","lit":"[question] · tu-aimes · le-couscous ?"},{"fr":"Oui, j'aime le couscous au poisson.","tgt":"نَعَمْ، أُحِبُّ الْكُسْكُسَ بِالسَّمَكِ.","ro":"Naʿam, uḥibbu al-kuskusa bis-samaki.","lit":"oui · j'aime · le-couscous · avec-le-poisson"},{"fr":"Je n'aime pas le café sans sucre.","tgt":"لَا أُحِبُّ الْقَهْوَةَ بِدُونِ سُكَّرٍ.","ro":"Lā uḥibbu al-qahwata bidūni sukkarin.","lit":"[ne… pas] · j'aime · le-café · sans · sucre"},{"fr":"Ma mère aime les fleurs de jasmin.","tgt":"أُمِّي تُحِبُّ زُهُورَ الْيَاسَمِينِ.","ro":"Ummī tuḥibbu zuhūra al-yāsamīni.","lit":"mère-de-moi · elle-aime · fleurs · le-jasmin"},{"fr":"Est-ce que tu aimes la mer ?","tgt":"هَلْ تُحِبُّ الْبَحْرَ؟","ro":"Hal tuḥibbu al-baḥra?","lit":"[question] · tu-aimes · la-mer ?"},{"fr":"J'aime nager le matin.","tgt":"أُحِبُّ السِّبَاحَةَ فِي الصَّبَاحِ.","ro":"Uḥibbu as-sibāḥata fī aṣ-ṣabāḥi.","lit":"j'aime · la-natation · dans · le-matin"},{"fr":"Sami aime la musique tunisienne.","tgt":"سَامِي يُحِبُّ الْمُوسِيقَى التُّونِسِيَّةَ.","ro":"Sāmī yuḥibbu al-mūsīqā at-tūnisiyyata.","lit":"Sami · il-aime · la-musique · la-tunisienne"},{"fr":"Leïla, tu aimes le thé ?","tgt":"هَلْ تُحِبِّينَ الشَّايَ يَا لَيْلَى؟","ro":"Hal tuḥibbīna ash-shāya yā Laylā?","lit":"[question] · tu-aimes (f.) · le-thé · [ô] · Leïla ?"}],"tip":{"title":"« Uhibbu » : j'aime","example":"J'aime le thé à la menthe. — <b>أُحِبُّ</b> الشَّايَ بِالنَّعْنَاعِ.","body":"Pour dire « j'aime », l'arabe utilise un seul mot : « uhibbu ». Le « u » du début signifie déjà « je », il n'est donc pas nécessaire d'ajouter « ana ». Ensuite, on met directement la chose aimée, avec son article « al » : « uhibbu ash-shay », j'aime le thé. Mot à mot, « uhibbu ash-shay bin-nanaa » donne : j'aime, le thé, avec la menthe. Pour « tu aimes », on change seulement le début : « tuhibbu » pour un homme, et « tuhibbina » pour une femme. Pour « il aime », on dit « yuhibbu ». Pour dire qu'on n'aime pas, on place simplement « la » devant : « la uhibbu », je n'aime pas. Astuce : beaucoup de Français connaissent déjà le mot « habibi », mon chéri ; il vient de la même racine que « uhibbu ».","exampleRo":"Uḥibbu ash-shāya bin-naʿnāʿi.","lit":"j'aime · le-thé · avec-la-menthe","say":{"Uhibbu":"أُحِبُّ","uhibbu":"أُحِبُّ","ana":"أَنَا","uhibbu ash-shay":"أُحِبُّ الشَّاي","uhibbu ash-shay bin-nanaa":"أُحِبُّ الشَّايَ بِالنَّعْنَاعِ","tuhibbu":"تُحِبُّ","tuhibbina":"تُحِبِّينَ","yuhibbu":"يُحِبُّ","la":"لَا","la uhibbu":"لَا أُحِبُّ","habibi":"حَبِيبِي"}}},{"title":"Les saisons à Tunis","phrases":[{"fr":"L'été est très chaud à Tunis.","tgt":"الصَّيْفُ حَارٌّ جِدًّا فِي تُونِسَ.","ro":"Aṣ-ṣayfu ḥārrun jiddan fī Tūnisa.","lit":"l'-été · chaud · très · dans · Tunis"},{"fr":"L'hiver est doux et pluvieux.","tgt":"الشِّتَاءُ مُعْتَدِلٌ وَمُمْطِرٌ.","ro":"Ash-shitāʾu muʿtadilun wa mumṭirun.","lit":"l'-hiver · doux · [et] pluvieux"},{"fr":"Quelle est ta saison préférée ?","tgt":"مَا فَصْلُكَ الْمُفَضَّلُ؟","ro":"Mā faṣluka al-mufaḍḍalu?","lit":"quoi · saison-de-toi · la-préférée ?"},{"fr":"Je préfère le printemps.","tgt":"أُفَضِّلُ الرَّبِيعَ.","ro":"Ufaḍḍilu ar-rabīʿa.","lit":"je-préfère · le-printemps"},{"fr":"Au printemps, il y a des fleurs partout.","tgt":"فِي الرَّبِيعِ الزُّهُورُ فِي كُلِّ مَكَانٍ.","ro":"Fī ar-rabīʿi az-zuhūru fī kulli makānin.","lit":"dans · le-printemps · les-fleurs · dans · chaque · endroit"},{"fr":"En automne, il fait beau.","tgt":"الطَّقْسُ جَمِيلٌ فِي الْخَرِيفِ.","ro":"Aṭ-ṭaqsu jamīlun fī al-kharīfi.","lit":"le-temps · beau · dans · l'-automne"},{"fr":"Il pleut beaucoup en janvier ?","tgt":"هَلْ تُمْطِرُ كَثِيرًا فِي يَنَايِرَ؟","ro":"Hal tumṭiru kathīran fī yanāyira?","lit":"[question] · il-pleut · beaucoup · dans · janvier ?"},{"fr":"Non, pas tellement.","tgt":"لَا، لَيْسَ كَثِيرًا.","ro":"Lā, laysa kathīran.","lit":"non · [ne… pas] · beaucoup"},{"fr":"En août, la plage est bondée.","tgt":"فِي أُغُسْطُسَ الشَّاطِئُ مُزْدَحِمٌ.","ro":"Fī ughusṭusa ash-shāṭiʾu muzdaḥimun.","lit":"dans · août · la-plage · bondée"},{"fr":"Le ciel est bleu aujourd'hui.","tgt":"السَّمَاءُ زَرْقَاءُ الْيَوْمَ.","ro":"As-samāʾu zarqāʾu al-yawma.","lit":"le-ciel · bleu · aujourd'hui"}]},{"title":"Ma famille","phrases":[{"fr":"Voici mon père.","tgt":"هَذَا أَبِي.","ro":"Hādhā abī.","lit":"voici · père-de-moi"},{"fr":"Mon père est pêcheur à Hammamet.","tgt":"أَبِي صَيَّادٌ فِي الْحَمَّامَاتِ.","ro":"Abī ṣayyādun fī al-Ḥammāmāti.","lit":"père-de-moi · pêcheur · dans · Hammamet"},{"fr":"Ma mère est infirmière.","tgt":"أُمِّي مُمَرِّضَةٌ.","ro":"Ummī mumarriḍatun.","lit":"mère-de-moi · infirmière"},{"fr":"Mon frère s'appelle Amine.","tgt":"أَخِي اسْمُهُ أَمِينٌ.","ro":"Akhī ismuhu Amīnun.","lit":"frère-de-moi · nom-de-lui · Amine"},{"fr":"Tu as des frères ?","tgt":"هَلْ عِنْدَكَ إِخْوَةٌ؟","ro":"Hal ʿindaka ikhwatun?","lit":"[question] · chez-toi · frères ?"},{"fr":"J'ai un frère et une sœur.","tgt":"عِنْدِي أَخٌ وَأُخْتٌ.","ro":"ʿIndī akhun wa ukhtun.","lit":"chez-moi · frère · [et] sœur"},{"fr":"Ma sœur habite à Carthage.","tgt":"أُخْتِي تَسْكُنُ فِي قَرْطَاجَ.","ro":"Ukhtī taskunu fī Qarṭāja.","lit":"sœur-de-moi · elle-habite · dans · Carthage"},{"fr":"Comment va ton père ?","tgt":"كَيْفَ حَالُ أَبِيكَ؟","ro":"Kayfa ḥālu abīka?","lit":"comment · état · père-de-toi ?"},{"fr":"Ma grand-mère vit avec nous.","tgt":"جَدَّتِي تَسْكُنُ مَعَنَا.","ro":"Jaddatī taskunu maʿanā.","lit":"grand-mère-de-moi · elle-habite · avec-nous"},{"fr":"Ma famille est grande.","tgt":"عَائِلَتِي كَبِيرَةٌ.","ro":"ʿĀʾilatī kabīratun.","lit":"famille-de-moi · grande"}],"tip":{"title":"La famille et les possessifs : « abi, ummi, akhi »","example":"Mon père est pêcheur à Hammamet. — <b>أَبِي</b> صَيَّادٌ فِي الْحَمَّامَاتِ.","body":"Les mots de la famille fonctionnent avec les possessifs collés que vous connaissez déjà. « Ab » veut dire père et devient « abi », mon père ; « umm » veut dire mère et devient « ummi », ma mère ; « akh », le frère, devient « akhi », mon frère. La sœur se dit « ukht », et ma sœur, « ukhti ». Ainsi « abi sayyad fi al-Hammamat » se dit mot à mot : père de moi, pêcheur, dans Hammamet. Il n'y a ni « est » ni « un » : l'arabe pose simplement les mots côte à côte. Pour « ton père », on entend souvent « abika », comme dans « kayfa halu abika ? », comment va ton père ? Astuce : le petit « i » final veut toujours dire « mon » ou « ma », que ce soit pour le père, la mère, le frère ou la sœur.","exampleRo":"Abī ṣayyādun fī al-Ḥammāmāti.","lit":"père-de-moi · pêcheur · dans · Hammamet","say":{"Ab":"أَب","abi":"أَبِي","umm":"أُمّ","ummi":"أُمِّي","akh":"أَخ","akhi":"أَخِي","ukht":"أُخْت","ukhti":"أُخْتِي","abi sayyad fi al-Hammamat":"أَبِي صَيَّاد فِي الْحَمَّامَات","abika":"أَبِيكَ","kayfa halu abika ?":"كَيْفَ حَالُ أَبِيكَ؟","abi, ummi, akhi":"أَبِي، أُمِّي، أَخِي"}}},{"title":"Un café entre amis à Sidi Bou Saïd","phrases":[{"fr":"On prend un café à Sidi Bou Saïd ?","tgt":"هَلْ نَشْرَبُ قَهْوَةً فِي سِيدِي بُو سَعِيدْ؟","ro":"Hal nashrabu qahwatan fī Sīdī Bū Saʿīd?","lit":"[question] · nous-buvons · café · dans · Sidi Bou Saïd ?"},{"fr":"Bonne idée, j'arrive !","tgt":"فِكْرَةٌ جَيِّدَةٌ، أَنَا قَادِمٌ!","ro":"Fikratun jayyidatun, anā qādimun!","lit":"idée · bonne · moi · arrivant !"},{"fr":"Le café a une belle vue sur la mer.","tgt":"لِلْمَقْهَى مَنْظَرٌ جَمِيلٌ عَلَى الْبَحْرِ.","ro":"Lil-maqhā manẓarun jamīlun ʿalā al-baḥri.","lit":"à-le-café · vue · belle · sur · la-mer"},{"fr":"Qu'est-ce que tu bois ?","tgt":"مَاذَا تَشْرَبُ؟","ro":"Mādhā tashrabu?","lit":"quoi · tu-bois ?"},{"fr":"Un thé aux pignons, s'il te plaît.","tgt":"شَايٌ بِالصَّنَوْبَرِ مِنْ فَضْلِكَ.","ro":"Shāyun biṣ-ṣanawbari min faḍlika.","lit":"thé · avec-les-pignons · de · faveur-de-toi"},{"fr":"Tu veux un makroud ?","tgt":"هَلْ تُرِيدُ مَقْرُوضًا؟","ro":"Hal turīdu maqrūḍan?","lit":"[question] · tu-veux · makroud ?"},{"fr":"Non merci, je n'ai pas faim.","tgt":"لَا شُكْرًا، لَسْتُ جَائِعًا.","ro":"Lā shukran, lastu jāʾiʿan.","lit":"non · merci · [ne… pas]-je-suis · affamé"},{"fr":"Le café est plein à craquer ce soir.","tgt":"الْمَقْهَى مُزْدَحِمٌ هَذَا الْمَسَاءَ.","ro":"Al-maqhā muzdaḥimun hādhā al-masāʾa.","lit":"le-café · bondé · ce · le-soir"},{"fr":"Où est le serveur ?","tgt":"أَيْنَ النَّادِلُ؟","ro":"Ayna an-nādilu?","lit":"où · le-serveur ?"},{"fr":"C'est moi qui paie aujourd'hui.","tgt":"أَنَا أَدْفَعُ الْيَوْمَ.","ro":"Anā adfaʿu al-yawma.","lit":"moi · je-paie · aujourd'hui"}]},{"title":"Souvenirs de Carthage","phrases":[{"fr":"Hier, j'étais à Carthage.","tgt":"كُنْتُ فِي قَرْطَاجَ أَمْسِ.","ro":"Kuntu fī Qarṭāja amsi.","lit":"j'étais · dans · Carthage · hier"},{"fr":"Le site était magnifique.","tgt":"كَانَ الْمَوْقِعُ رَائِعًا.","ro":"Kāna al-mawqiʿu rāʾiʿan.","lit":"était · le-site · magnifique"},{"fr":"Il faisait très chaud.","tgt":"كَانَ الْجَوُّ حَارًّا جِدًّا.","ro":"Kāna al-jawwu ḥārran jiddan.","lit":"était · le-temps · chaud · très"},{"fr":"Tu étais avec ta famille ?","tgt":"هَلْ كُنْتَ مَعَ عَائِلَتِكَ؟","ro":"Hal kunta maʿa ʿāʾilatika?","lit":"[question] · tu-étais · avec · famille-de-toi ?"},{"fr":"Non, j'étais avec un collègue.","tgt":"لَا، كُنْتُ مَعَ زَمِيلٍ.","ro":"Lā, kuntu maʿa zamīlin.","lit":"non · j'étais · avec · collègue"},{"fr":"Le musée était fermé.","tgt":"كَانَ الْمَتْحَفُ مُغْلَقًا.","ro":"Kāna al-matḥafu mughlaqan.","lit":"était · le-musée · fermé"},{"fr":"Ma grand-mère était professeure.","tgt":"كَانَتْ جَدَّتِي مُعَلِّمَةً.","ro":"Kānat jaddatī muʿallimatan.","lit":"était (f.) · grand-mère-de-moi · professeure"},{"fr":"Carthage était une grande ville.","tgt":"كَانَتْ قَرْطَاجُ مَدِينَةً كَبِيرَةً.","ro":"Kānat Qarṭāju madīnatan kabīratan.","lit":"était (f.) · Carthage · ville · grande"},{"fr":"Où étais-tu ce matin ?","tgt":"أَيْنَ كُنْتَ هَذَا الصَّبَاحَ؟","ro":"Ayna kunta hādhā aṣ-ṣabāḥa?","lit":"où · tu-étais · ce · le-matin ?"},{"fr":"J'étais au souk de la médina.","tgt":"كُنْتُ فِي سُوقِ الْمَدِينَةِ.","ro":"Kuntu fī sūqi al-madīnati.","lit":"j'étais · dans · souk · la-médina"}],"tip":{"title":"« Kana » : le verbe être au passé","example":"Le site était magnifique. — <b>كَانَ</b> الْمَوْقِعُ رَائِعًا.","body":"Au présent, l'arabe n'a pas besoin du verbe être : on dit « al-jaww harr », mot à mot : le temps, chaud. Mais au passé, il faut un verbe, et c'est « kana », il était. On le place en général au début de la phrase : « kana al-mawqiu raian », le site était magnifique, se dit mot à mot : était, le site, magnifique. Remarquez que l'adjectif change un peu de terminaison et finit par « an » après « kana ». Pour « j'étais », on dit « kuntu », et pour « tu étais », « kunta ». Au féminin, « kana » devient « kanat », comme dans « kanat jaddati muallima », ma grand-mère était professeure. Astuce : « kuntu » commence comme le mot « content » ; hier, j'étais à Carthage, et j'étais content.","exampleRo":"Kāna al-mawqiʿu rāʾiʿan.","lit":"était · le-site · magnifique","say":{"Kana":"كَانَ","al-jaww harr":"الْجَوّ حَارّ","kana":"كَانَ","kana al-mawqiu raian":"كَانَ الْمَوْقِعُ رَائِعًا","kuntu":"كُنْتُ","kunta":"كُنْتَ","kanat":"كَانَتْ","kanat jaddati muallima":"كَانَتْ جَدَّتِي مُعَلِّمَة"}}},{"title":"Entre collègues","phrases":[{"fr":"Voici ma nouvelle collègue, Houda.","tgt":"هَذِهِ زَمِيلَتِي الْجَدِيدَةُ هُدَى.","ro":"Hādhihi zamīlatī al-jadīdatu Hudā.","lit":"voici · collègue-de-moi · la-nouvelle · Houda"},{"fr":"Elle travaille avec nous depuis lundi.","tgt":"تَعْمَلُ مَعَنَا مُنْذُ يَوْمِ الِاثْنَيْنِ.","ro":"Taʿmalu maʿanā mundhu yawmi al-ithnayni.","lit":"elle-travaille · avec-nous · depuis · jour · le-lundi"},{"fr":"Mes collègues sont sympathiques.","tgt":"زُمَلَائِي لُطَفَاءُ.","ro":"Zumalāʾī luṭafāʾu.","lit":"collègues-de-moi · gentils"},{"fr":"Mon chef est très sérieux.","tgt":"مُدِيرِي جَادٌّ جِدًّا.","ro":"Mudīrī jāddun jiddan.","lit":"directeur-de-moi · sérieux · très"},{"fr":"La réunion est à dix heures.","tgt":"الِاجْتِمَاعُ فِي السَّاعَةِ الْعَاشِرَةِ.","ro":"Al-ijtimāʿu fī as-sāʿati al-ʿāshirati.","lit":"la-réunion · dans · l'-heure · la-dixième"},{"fr":"Karim, tu as un stylo ?","tgt":"هَلْ عِنْدَكَ قَلَمٌ يَا كَرِيمُ؟","ro":"Hal ʿindaka qalamun yā Karīmu?","lit":"[question] · chez-toi · stylo · [ô] · Karim ?"},{"fr":"Oui, prends celui-ci.","tgt":"نَعَمْ، خُذْ هَذَا.","ro":"Naʿam, khudh hādhā.","lit":"oui · prends · celui-ci"},{"fr":"Nous prenons un café à midi.","tgt":"نَشْرَبُ قَهْوَةً عِنْدَ الظُّهْرِ.","ro":"Nashrabu qahwatan ʿinda aẓ-ẓuhri.","lit":"nous-buvons · café · à · le-midi"},{"fr":"Mon collègue habite à Hammamet.","tgt":"زَمِيلِي يَسْكُنُ فِي الْحَمَّامَاتِ.","ro":"Zamīlī yaskunu fī al-Ḥammāmāti.","lit":"collègue-de-moi · il-habite · dans · Hammamet"},{"fr":"Le bureau est fermé le dimanche.","tgt":"الْمَكْتَبُ مُغْلَقٌ يَوْمَ الْأَحَدِ.","ro":"Al-maktabu mughlaqun yawma al-aḥadi.","lit":"le-bureau · fermé · jour · le-dimanche"}]},{"title":"Comparer Hammamet et La Marsa","phrases":[{"fr":"Tunis est plus grande que Hammamet.","tgt":"تُونِسُ أَكْبَرُ مِنَ الْحَمَّامَاتِ.","ro":"Tūnisu akbaru mina al-Ḥammāmāti.","lit":"Tunis · plus-grande · de · Hammamet"},{"fr":"Mon frère est plus âgé que moi.","tgt":"أَخِي أَكْبَرُ مِنِّي.","ro":"Akhī akbaru minnī.","lit":"frère-de-moi · plus-grand · de-moi"},{"fr":"La Marsa est plus proche que Hammamet.","tgt":"الْمَرْسَى أَقْرَبُ مِنَ الْحَمَّامَاتِ.","ro":"Al-Marsā aqrabu mina al-Ḥammāmāti.","lit":"La Marsa · plus-proche · de · Hammamet"},{"fr":"La mer est plus chaude en août.","tgt":"الْبَحْرُ أَدْفَأُ فِي أُغُسْطُسَ.","ro":"Al-baḥru adfaʾu fī ughusṭusa.","lit":"la-mer · plus-chaude · dans · août"},{"fr":"Le thé est moins cher que le café.","tgt":"الشَّايُ أَرْخَصُ مِنَ الْقَهْوَةِ.","ro":"Ash-shāyu arkhaṣu mina al-qahwati.","lit":"le-thé · moins-cher · de · le-café"},{"fr":"Ma sœur est plus jeune que moi.","tgt":"أُخْتِي أَصْغَرُ مِنِّي.","ro":"Ukhtī aṣgharu minnī.","lit":"sœur-de-moi · plus-petite · de-moi"},{"fr":"Cette plage est plus belle.","tgt":"هَذَا الشَّاطِئُ أَجْمَلُ.","ro":"Hādhā ash-shāṭiʾu ajmalu.","lit":"cette · la-plage · plus-belle"},{"fr":"L'été est plus long que l'hiver.","tgt":"الصَّيْفُ أَطْوَلُ مِنَ الشِّتَاءِ.","ro":"Aṣ-ṣayfu aṭwalu mina ash-shitāʾi.","lit":"l'-été · plus-long · de · l'-hiver"},{"fr":"Quelle ville est la plus belle ?","tgt":"أَيُّ مَدِينَةٍ أَجْمَلُ؟","ro":"Ayyu madīnatin ajmalu?","lit":"quelle · ville · plus-belle ?"},{"fr":"Sidi Bou Saïd est plus calme que la médina.","tgt":"سِيدِي بُو سَعِيدْ أَهْدَأُ مِنَ الْمَدِينَةِ.","ro":"Sīdī Bū Saʿīd ahdaʾu mina al-madīnati.","lit":"Sidi Bou Saïd · plus-calme · de · la-médina"}],"tip":{"title":"Comparer : « akbar min », plus grand que","example":"Tunis est plus grande que Hammamet. — تُونِسُ <b>أَكْبَرُ</b> <b>مِنَ</b> الْحَمَّامَاتِ.","body":"Pour comparer, l'arabe transforme l'adjectif selon un moule très régulier, qui commence toujours par un « a ». « Kabir », grand, devient « akbar », plus grand ; « saghir », petit, devient « asghar », plus petit ; « jamil », beau, devient « ajmal », plus beau. Ensuite, on ajoute « min », qui veut dire « de », et qui joue ici le rôle de notre « que ». « Tunis akbar mina al-Hammamat » se dit donc mot à mot : Tunis, plus grande, de Hammamet. Il n'y a pas de verbe être, et la forme ne change pas au féminin : Tunis est une ville, mais on dit quand même « akbar ». Pour « que moi », on colle le pronom : « minni ». Ainsi « akhi akbar minni » veut dire : mon frère est plus âgé que moi. Astuce : entendez le « a » du début comme un « encore plus » : « akbar, ajmal, aqrab ».","exampleRo":"Tūnisu akbaru mina al-Ḥammāmāti.","lit":"Tunis · plus-grande · de · Hammamet","say":{"akbar min":"أَكْبَر مِنْ","Kabir":"كَبِير","akbar":"أَكْبَر","saghir":"صَغِير","asghar":"أَصْغَر","jamil":"جَمِيل","ajmal":"أَجْمَل","min":"مِنْ","Tunis akbar mina al-Hammamat":"تُونِس أَكْبَر مِنَ الْحَمَّامَات","minni":"مِنِّي","akhi akbar minni":"أَخِي أَكْبَر مِنِّي","akbar, ajmal, aqrab":"أَكْبَر، أَجْمَل، أَقْرَب"}}},{"title":"Une invitation à dîner","phrases":[{"fr":"Tu es libre ce samedi soir ?","tgt":"هَلْ أَنْتَ مُتَفَرِّغٌ مَسَاءَ السَّبْتِ؟","ro":"Hal anta mutafarrighun masāʾa as-sabti?","lit":"[question] · toi · libre · soir · le-samedi ?"},{"fr":"Je t'invite à dîner chez moi.","tgt":"أَدْعُوكَ إِلَى الْعَشَاءِ فِي بَيْتِي.","ro":"Adʿūka ilā al-ʿashāʾi fī baytī.","lit":"je-t'invite · à · le-dîner · dans · maison-de-moi"},{"fr":"Merci beaucoup, avec grand plaisir !","tgt":"شُكْرًا جَزِيلًا، بِكُلِّ سُرُورٍ!","ro":"Shukran jazīlan, bikulli surūrin!","lit":"merci · abondant · avec-tout · plaisir !"},{"fr":"Ma mère prépare le couscous.","tgt":"أُمِّي تُحَضِّرُ الْكُسْكُسَ.","ro":"Ummī tuḥaḍḍiru al-kuskusa.","lit":"mère-de-moi · elle-prépare · le-couscous"},{"fr":"Je viens à quelle heure ?","tgt":"مَتَى آتِي؟","ro":"Matā ātī?","lit":"quand · je-viens ?"},{"fr":"Viens à huit heures.","tgt":"تَعَالَ فِي السَّاعَةِ الثَّامِنَةِ.","ro":"Taʿāla fī as-sāʿati ath-thāminati.","lit":"viens · dans · l'-heure · la-huitième"},{"fr":"Où est ta maison ?","tgt":"أَيْنَ بَيْتُكَ؟","ro":"Ayna baytuka?","lit":"où · maison-de-toi ?"},{"fr":"Ma maison est près de la plage de La Marsa.","tgt":"بَيْتِي قُرْبَ شَاطِئِ الْمَرْسَى.","ro":"Baytī qurba shāṭiʾi al-Marsā.","lit":"maison-de-moi · près · plage · La Marsa"},{"fr":"J'apporte le dessert ?","tgt":"هَلْ أُحْضِرُ الْحَلْوَى؟","ro":"Hal uḥḍiru al-ḥalwā?","lit":"[question] · j'apporte · le-dessert ?"},{"fr":"Non, ta présence suffit.","tgt":"لَا، حُضُورُكَ يَكْفِي.","ro":"Lā, ḥuḍūruka yakfī.","lit":"non · présence-de-toi · suffit"}]},{"title":"Pourquoi j'aime Tunis","phrases":[{"fr":"J'aime Tunis parce que c'est une ville vivante.","tgt":"أُحِبُّ تُونِسَ لِأَنَّهَا مَدِينَةٌ حَيَّةٌ.","ro":"Uḥibbu Tūnisa li-annahā madīnatun ḥayyatun.","lit":"j'aime · Tunis · parce-que-elle · ville · vivante"},{"fr":"Pourquoi est-ce que tu apprends l'arabe ?","tgt":"لِمَاذَا تَتَعَلَّمُ الْعَرَبِيَّةَ؟","ro":"Limādhā tataʿallamu al-ʿarabiyyata?","lit":"pourquoi · tu-apprends · l'-arabe ?"},{"fr":"Parce que j'aime cette langue.","tgt":"لِأَنَّنِي أُحِبُّ هَذِهِ اللُّغَةَ.","ro":"Li-annanī uḥibbu hādhihi al-lughata.","lit":"parce-que-moi · j'aime · cette · la-langue"},{"fr":"Je suis fatigué parce que je travaille beaucoup.","tgt":"أَنَا مُتْعَبٌ لِأَنَّنِي أَعْمَلُ كَثِيرًا.","ro":"Anā mutʿabun li-annanī aʿmalu kathīran.","lit":"moi · fatigué · parce-que-moi · je-travaille · beaucoup"},{"fr":"Je vais à la plage parce qu'il fait chaud.","tgt":"أَذْهَبُ إِلَى الشَّاطِئِ لِأَنَّ الْجَوَّ حَارٌّ.","ro":"Adhhabu ilā ash-shāṭiʾi li-anna al-jawwa ḥārrun.","lit":"je-vais · vers · la-plage · parce-que · le-temps · chaud"},{"fr":"Pourquoi es-tu en retard ?","tgt":"لِمَاذَا أَنْتَ مُتَأَخِّرٌ؟","ro":"Limādhā anta mutaʾakhkhirun?","lit":"pourquoi · toi · en-retard ?"},{"fr":"Parce que la route était encombrée.","tgt":"لِأَنَّ الطَّرِيقَ كَانَ مُزْدَحِمًا.","ro":"Li-anna aṭ-ṭarīqa kāna muzdaḥiman.","lit":"parce-que · la-route · était · encombrée"},{"fr":"Sami est content parce qu'il est en vacances.","tgt":"سَامِي سَعِيدٌ لِأَنَّهُ فِي عُطْلَةٍ.","ro":"Sāmī saʿīdun li-annahu fī ʿuṭlatin.","lit":"Sami · content · parce-que-lui · dans · vacances"},{"fr":"J'aime La Marsa parce qu'elle est calme.","tgt":"أُحِبُّ الْمَرْسَى لِأَنَّهَا هَادِئَةٌ.","ro":"Uḥibbu al-Marsā li-annahā hādiʾatun.","lit":"j'aime · La Marsa · parce-que-elle · calme"},{"fr":"Je ne mange pas, parce que j'ai mangé tout à l'heure.","tgt":"لَا آكُلُ لِأَنَّنِي أَكَلْتُ قَبْلَ قَلِيلٍ.","ro":"Lā ākulu li-annanī akaltu qabla qalīlin.","lit":"[ne… pas] · je-mange · parce-que-moi · j'ai-mangé · avant · peu"}],"tip":{"title":"« Li-anna » : parce que","example":"Je vais à la plage parce qu'il fait chaud. — أَذْهَبُ إِلَى الشَّاطِئِ <b>لِأَنَّ</b> الْجَوَّ حَارٌّ.","body":"Pour donner une raison, on utilise « li-anna », qui veut dire parce que. Ce mot est formé de « li », pour, et de « anna », que, un peu comme « parce que » colle deux petits mots en français. Juste après « li-anna », on met le sujet : « li-anna al-jawwa harr », parce que le temps est chaud, se dit mot à mot : parce que, le temps, chaud. Si le sujet est un pronom, il se colle directement au mot : « li-annani », parce que je, « li-annahu », parce que lui, « li-annaha », parce qu'elle. Pour poser la question, on dit « limadha », pourquoi. Voici une mini-conversation : « limadha ? », pourquoi ? « li-annani mutab », parce que je suis fatigué. Astuce : « limadha » demande et « li-anna » répond, et les deux commencent par le même petit « li ».","exampleRo":"Adhhabu ilā ash-shāṭiʾi li-anna al-jawwa ḥārrun.","lit":"je-vais · vers · la-plage · parce-que · le-temps · chaud","say":{"Li-anna":"لِأَنَّ","li-anna":"لِأَنَّ","anna":"أَنَّ","li-anna al-jawwa harr":"لِأَنَّ الْجَوَّ حَارّ","li-annani":"لِأَنَّنِي","li-annahu":"لِأَنَّهُ","li-annaha":"لِأَنَّهَا","limadha":"لِمَاذَا","limadha ?":"لِمَاذَا؟","li-annani mutab":"لِأَنَّنِي مُتْعَب"}}},{"title":"Offrir un cadeau","phrases":[{"fr":"C'est un cadeau pour toi.","tgt":"هَذِهِ هَدِيَّةٌ لَكَ.","ro":"Hādhihi hadiyyatun laka.","lit":"ceci · cadeau · pour-toi"},{"fr":"Merci, tu es vraiment gentil !","tgt":"شُكْرًا، أَنْتَ لَطِيفٌ جِدًّا!","ro":"Shukran, anta laṭīfun jiddan!","lit":"merci · toi · gentil · très !"},{"fr":"J'ai acheté ce plat à Nabeul.","tgt":"اِشْتَرَيْتُ هَذَا الصَّحْنَ فِي نَابُلَ.","ro":"Ishtaraytu hādhā aṣ-ṣaḥna fī Nābula.","lit":"j'ai-acheté · ce · le-plat · dans · Nabeul"},{"fr":"Il est fait à la main.","tgt":"هُوَ مَصْنُوعٌ بِالْيَدِ.","ro":"Huwa maṣnūʿun bil-yadi.","lit":"lui · fabriqué · avec-la-main"},{"fr":"J'offre des fleurs à ma mère.","tgt":"أُهْدِي أُمِّي زُهُورًا.","ro":"Uhdī ummī zuhūran.","lit":"j'offre · mère-de-moi · fleurs"},{"fr":"Un parfum au jasmin pour Leïla.","tgt":"عِطْرٌ بِالْيَاسَمِينِ لِلَيْلَى.","ro":"ʿIṭrun bil-yāsamīni li-Laylā.","lit":"parfum · avec-le-jasmin · pour-Leïla"},{"fr":"Le cadeau était cher ?","tgt":"هَلْ كَانَتِ الْهَدِيَّةُ غَالِيَةً؟","ro":"Hal kānati al-hadiyyatu ghāliyatan?","lit":"[question] · était (f.) · le-cadeau · cher ?"},{"fr":"Non, seulement dix dinars.","tgt":"لَا، عَشَرَةُ دَنَانِيرَ فَقَطْ.","ro":"Lā, ʿasharatu danānīra faqaṭ.","lit":"non · dix · dinars · seulement"},{"fr":"J'aime beaucoup ce cadeau.","tgt":"أُحِبُّ هَذِهِ الْهَدِيَّةَ كَثِيرًا.","ro":"Uḥibbu hādhihi al-hadiyyata kathīran.","lit":"j'aime · ce · le-cadeau · beaucoup"},{"fr":"Tu as un cadeau pour Sami ?","tgt":"هَلْ عِنْدَكَ هَدِيَّةٌ لِسَامِي؟","ro":"Hal ʿindaka hadiyyatun li-Sāmī?","lit":"[question] · chez-toi · cadeau · pour-Sami ?"}]},{"title":"Nous, vous, ils","phrases":[{"fr":"Nous sommes de Tunis.","tgt":"نَحْنُ مِنْ تُونِسَ.","ro":"Naḥnu min Tūnisa.","lit":"nous · de · Tunis"},{"fr":"Et vous, vous êtes d'où ?","tgt":"وَأَنْتُمْ، مِنْ أَيْنَ أَنْتُمْ؟","ro":"Wa antum, min ayna antum?","lit":"[et] vous · de · où · vous ?"},{"fr":"Nous sommes français.","tgt":"نَحْنُ فَرَنْسِيُّونَ.","ro":"Naḥnu faransiyyūna.","lit":"nous · français"},{"fr":"Ce sont nos voisins à La Marsa.","tgt":"هُمْ جِيرَانُنَا فِي الْمَرْسَى.","ro":"Hum jīrānunā fī al-Marsā.","lit":"eux · voisins-de-nous · dans · La Marsa"},{"fr":"Vous êtes en vacances ?","tgt":"هَلْ أَنْتُمْ فِي عُطْلَةٍ؟","ro":"Hal antum fī ʿuṭlatin?","lit":"[question] · vous · dans · vacances ?"},{"fr":"Oui, nous sommes ici pour une semaine.","tgt":"نَعَمْ، نَحْنُ هُنَا لِأُسْبُوعٍ.","ro":"Naʿam, naḥnu hunā li-usbūʿin.","lit":"oui · nous · ici · pour-semaine"},{"fr":"Ils travaillent à Hammamet.","tgt":"هُمْ يَعْمَلُونَ فِي الْحَمَّامَاتِ.","ro":"Hum yaʿmalūna fī al-Ḥammāmāti.","lit":"eux · ils-travaillent · dans · Hammamet"},{"fr":"Nous aimons beaucoup la médina.","tgt":"نُحِبُّ الْمَدِينَةَ الْعَتِيقَةَ كَثِيرًا.","ro":"Nuḥibbu al-madīnata al-ʿatīqata kathīran.","lit":"nous-aimons · la-médina · l'-ancienne · beaucoup"},{"fr":"Vous parlez arabe, vous ?","tgt":"هَلْ تَتَكَلَّمُونَ الْعَرَبِيَّةَ؟","ro":"Hal tatakallamūna al-ʿarabiyyata?","lit":"[question] · vous-parlez · l'-arabe ?"},{"fr":"Ils sont très généreux.","tgt":"هُمْ كُرَمَاءُ جِدًّا.","ro":"Hum kuramāʾu jiddan.","lit":"eux · généreux · très"}],"tip":{"title":"Le pluriel des personnes : « nahnu, antum, hum »","example":"Nous sommes de Tunis. — <b>نَحْنُ</b> مِنْ تُونِسَ.","body":"Vous connaissez déjà « ana », « anta », « huwa » et « hiya ». Au pluriel, on dit « nahnu » pour nous, « antum » pour vous, et « hum » pour ils. Comme au singulier, il n'y a pas de verbe être au présent : « nahnu min Tunis » se dit mot à mot : nous, de Tunis. Les verbes, eux, portent la marque du pluriel : « nuhibbu », nous aimons, commence par un « n » comme « nahnu » ; « yamaluna », ils travaillent, et « tatakallamuna », vous parlez, se terminent par « una ». Les adjectifs se mettent aussi au pluriel, parfois avec « una », comme « faransiyyuna », Français, parfois par un pluriel brisé, comme « kurama », généreux. Astuce : « nahnu » et « nuhibbu » commencent tous les deux par « n », la lettre du nous, comme en français.","exampleRo":"Naḥnu min Tūnisa.","lit":"nous · de · Tunis","say":{"ana":"أَنَا","anta":"أَنْتَ","huwa":"هُوَ","hiya":"هِيَ","nahnu":"نَحْنُ","antum":"أَنْتُمْ","hum":"هُمْ","nahnu min Tunis":"نَحْنُ مِنْ تُونِس","nuhibbu":"نُحِبُّ","yamaluna":"يَعْمَلُونَ","tatakallamuna":"تَتَكَلَّمُونَ","faransiyyuna":"فَرَنْسِيُّونَ","kurama":"كُرَمَاء","nahnu, antum, hum":"نَحْنُ، أَنْتُمْ، هُمْ"}}},{"title":"Parler de musique","phrases":[{"fr":"Quelle musique écoutes-tu ?","tgt":"أَيَّ مُوسِيقَى تَسْمَعُ؟","ro":"Ayya mūsīqā tasmaʿu?","lit":"quelle · musique · tu-écoutes ?"},{"fr":"J'écoute le malouf tunisien.","tgt":"أَسْمَعُ الْمَالُوفَ التُّونِسِيَّ.","ro":"Asmaʿu al-mālūfa at-tūnisiyya.","lit":"j'écoute · le-malouf · le-tunisien"},{"fr":"Mon père joue du oud.","tgt":"أَبِي يَعْزِفُ عَلَى الْعُودِ.","ro":"Abī yaʿzifu ʿalā al-ʿūdi.","lit":"père-de-moi · il-joue · sur · le-oud"},{"fr":"Ce chanteur est célèbre.","tgt":"هَذَا الْمُغَنِّي مَشْهُورٌ.","ro":"Hādhā al-mughannī mashhūrun.","lit":"ce · le-chanteur · célèbre"},{"fr":"Il y a un concert à Carthage ce soir.","tgt":"هُنَاكَ حَفْلَةٌ فِي قَرْطَاجَ هَذَا الْمَسَاءَ.","ro":"Hunāka ḥaflatun fī Qarṭāja hādhā al-masāʾa.","lit":"il-y-a · concert · dans · Carthage · ce · le-soir"},{"fr":"Le festival de Carthage a lieu en été.","tgt":"مِهْرَجَانُ قَرْطَاجَ فِي الصَّيْفِ.","ro":"Mihrajānu Qarṭāja fī aṣ-ṣayfi.","lit":"festival · Carthage · dans · l'-été"},{"fr":"Tu as une belle voix !","tgt":"صَوْتُكَ جَمِيلٌ!","ro":"Ṣawtuka jamīlun!","lit":"voix-de-toi · belle !"},{"fr":"Ma sœur apprend le piano.","tgt":"أُخْتِي تَتَعَلَّمُ الْبِيَانُو.","ro":"Ukhtī tataʿallamu al-biyānū.","lit":"sœur-de-moi · elle-apprend · le-piano"},{"fr":"La musique est forte ici.","tgt":"الْمُوسِيقَى عَالِيَةٌ هُنَا.","ro":"Al-mūsīqā ʿāliyatun hunā.","lit":"la-musique · haute · ici"},{"fr":"J'adore cette chanson !","tgt":"أُحِبُّ هَذِهِ الْأُغْنِيَةَ كَثِيرًا!","ro":"Uḥibbu hādhihi al-ughniyata kathīran!","lit":"j'aime · cette · la-chanson · beaucoup !"}]},{"title":"Une journée à la plage de Hammamet","phrases":[{"fr":"Je vais à la plage avec mes amis.","tgt":"أَذْهَبُ إِلَى الشَّاطِئِ مَعَ أَصْدِقَائِي.","ro":"Adhhabu ilā ash-shāṭiʾi maʿa aṣdiqāʾī.","lit":"je-vais · vers · la-plage · avec · amis-de-moi"},{"fr":"Tu viens avec nous ?","tgt":"هَلْ تَأْتِي مَعَنَا؟","ro":"Hal taʾtī maʿanā?","lit":"[question] · tu-viens · avec-nous ?"},{"fr":"Oui, je viens avec ma sœur.","tgt":"نَعَمْ، آتِي مَعَ أُخْتِي.","ro":"Naʿam, ātī maʿa ukhtī.","lit":"oui · je-viens · avec · sœur-de-moi"},{"fr":"Le poisson grillé au citron, c'est délicieux.","tgt":"السَّمَكُ الْمَشْوِيُّ مَعَ اللَّيْمُونِ لَذِيذٌ.","ro":"As-samaku al-mashwiyyu maʿa al-laymūni ladhīdhun.","lit":"le-poisson · le-grillé · avec · le-citron · délicieux"},{"fr":"Sami est avec sa famille à Hammamet.","tgt":"سَامِي مَعَ عَائِلَتِهِ فِي الْحَمَّامَاتِ.","ro":"Sāmī maʿa ʿāʾilatihi fī al-Ḥammāmāti.","lit":"Sami · avec · famille-de-lui · dans · Hammamet"},{"fr":"Avec qui es-tu ?","tgt":"مَعَ مَنْ أَنْتَ؟","ro":"Maʿa man anta?","lit":"avec · qui · toi ?"},{"fr":"Je suis avec Karim et Leïla.","tgt":"أَنَا مَعَ كَرِيمٍ وَلَيْلَى.","ro":"Anā maʿa Karīmin wa Laylā.","lit":"moi · avec · Karim · [et] Leïla"},{"fr":"Je nage avec mon frère le matin.","tgt":"أَسْبَحُ مَعَ أَخِي فِي الصَّبَاحِ.","ro":"Asbaḥu maʿa akhī fī aṣ-ṣabāḥi.","lit":"je-nage · avec · frère-de-moi · dans · le-matin"},{"fr":"Je joue au ballon avec les enfants.","tgt":"أَلْعَبُ بِالْكُرَةِ مَعَ الْأَطْفَالِ.","ro":"Alʿabu bil-kurati maʿa al-aṭfāli.","lit":"je-joue · avec-le-ballon · avec · les-enfants"},{"fr":"Viens avec moi au port !","tgt":"تَعَالَ مَعِي إِلَى الْمِينَاءِ!","ro":"Taʿāla maʿī ilā al-mīnāʾi!","lit":"viens · avec-moi · vers · le-port !"}],"tip":{"title":"« Maa » : avec","example":"Je vais à la plage avec mes amis. — أَذْهَبُ إِلَى الشَّاطِئِ <b>مَعَ</b> أَصْدِقَائِي.","body":"« Maa » veut dire avec. C'est un petit mot très simple qui se place devant le nom, exactement comme en français : « maa ukhti », avec ma sœur. Ainsi « adhhabu ila ash-shati maa asdiqai » se dit mot à mot : je vais, vers, la plage, avec, mes amis. On peut aussi lui coller directement les pronoms : « maï », avec moi, « maaka », avec toi, et « maana », avec nous. Pour demander avec qui, on dit « maa man ? ». Vous retrouverez aussi ce mot dans la formule « maa as-salama », au revoir, qui veut dire littéralement : avec la paix. Astuce : imaginez deux amis sur la plage de Hammamet ; l'un demande « maa man ? », avec qui, et l'autre répond « maaka », avec toi.","exampleRo":"Adhhabu ilā ash-shāṭiʾi maʿa aṣdiqāʾī.","lit":"je-vais · vers · la-plage · avec · amis-de-moi","say":{"Maa":"مَعَ","maa ukhti":"مَعَ أُخْتِي","adhhabu ila ash-shati maa asdiqai":"أَذْهَبُ إِلَى الشَّاطِئِ مَعَ أَصْدِقَائِي","maï":"مَعِي","maaka":"مَعَكَ","maana":"مَعَنَا","maa man ?":"مَعَ مَنْ؟","maa as-salama":"مَعَ السَّلَامَة"}}},{"title":"Se dire au revoir après une soirée","phrases":[{"fr":"Il est tard, j'y vais.","tgt":"الْوَقْتُ مُتَأَخِّرٌ، أَنَا ذَاهِبٌ.","ro":"Al-waqtu mutaʾakhkhirun, anā dhāhibun.","lit":"le-temps · tardif · moi · partant"},{"fr":"Merci pour le délicieux dîner.","tgt":"شُكْرًا عَلَى الْعَشَاءِ اللَّذِيذِ.","ro":"Shukran ʿalā al-ʿashāʾi al-ladhīdhi.","lit":"merci · sur · le-dîner · le-délicieux"},{"fr":"La soirée était très belle.","tgt":"كَانَتِ السَّهْرَةُ جَمِيلَةً جِدًّا.","ro":"Kānati as-sahratu jamīlatan jiddan.","lit":"était (f.) · la-soirée · belle · très"},{"fr":"Merci d'être venu.","tgt":"شُكْرًا عَلَى حُضُورِكَ.","ro":"Shukran ʿalā ḥuḍūrika.","lit":"merci · sur · présence-de-toi"},{"fr":"Comment tu rentres chez toi ?","tgt":"كَيْفَ تَرْجِعُ إِلَى الْبَيْتِ؟","ro":"Kayfa tarjiʿu ilā al-bayti?","lit":"comment · tu-rentres · vers · la-maison ?"},{"fr":"Je prends le train jusqu'à La Marsa.","tgt":"آخُذُ الْقِطَارَ إِلَى الْمَرْسَى.","ro":"Ākhudhu al-qiṭāra ilā al-Marsā.","lit":"je-prends · le-train · vers · La Marsa"},{"fr":"Bonne nuit, Leïla.","tgt":"تُصْبِحِينَ عَلَى خَيْرٍ يَا لَيْلَى.","ro":"Tuṣbiḥīna ʿalā khayrin yā Laylā.","lit":"tu-te-réveilles (f.) · sur · bien · [ô] · Leïla"},{"fr":"Bonne nuit à toi aussi.","tgt":"وَأَنْتَ مِنْ أَهْلِهِ.","ro":"Wa anta min ahlihi.","lit":"[et] toi · de · gens-de-lui"},{"fr":"À bientôt à Sidi Bou Saïd !","tgt":"نَرَاكَ قَرِيبًا فِي سِيدِي بُو سَعِيدْ!","ro":"Narāka qarīban fī Sīdī Bū Saʿīd!","lit":"nous-te-voyons · bientôt · dans · Sidi Bou Saïd !"},{"fr":"Salue ta famille de ma part.","tgt":"سَلِّمْ لِي عَلَى عَائِلَتِكَ.","ro":"Sallim lī ʿalā ʿāʾilatika.","lit":"salue · pour-moi · sur · famille-de-toi"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Enchanté, Sami.","tgt":"تَشَرَّفْنَا يَا سَامِي.","ro":"Tasharrafnā yā Sāmī.","lit":"nous-avons-été-honorés · [ô] · Sami"},{"fr":"Au revoir, et à demain !","tgt":"مَعَ السَّلَامَةِ، وَإِلَى الْغَدِ!","ro":"Maʿa as-salāmati, wa ilā al-ghadi!","lit":"avec · la-paix · [et] jusqu'à · demain !"},{"fr":"Au revoir, à la semaine prochaine.","tgt":"إِلَى اللِّقَاءِ فِي الْأُسْبُوعِ الْقَادِمِ.","ro":"Ilā al-liqāʾi fī al-usbūʿi al-qādimi.","lit":"jusqu'à · la-rencontre · dans · la-semaine · la-prochaine"},{"fr":"Maintenant, je parle un peu arabe.","tgt":"الْآنَ أَتَكَلَّمُ الْعَرَبِيَّةَ قَلِيلًا.","ro":"Al-āna atakallamu al-ʿarabiyyata qalīlan.","lit":"maintenant · je-parle · l'-arabe · un-peu"},{"fr":"Je sais me présenter en arabe.","tgt":"أَعْرِفُ كَيْفَ أُقَدِّمُ نَفْسِي بِالْعَرَبِيَّةِ.","ro":"Aʿrifu kayfa uqaddimu nafsī bil-ʿarabiyyati.","lit":"je-sais · comment · je-présente · moi-même · en-l'-arabe"},{"fr":"Je parle de ma famille et de mon travail.","tgt":"أَتَكَلَّمُ عَنْ عَائِلَتِي وَعَنْ عَمَلِي.","ro":"Atakallamu ʿan ʿāʾilatī wa ʿan ʿamalī.","lit":"je-parle · de · famille-de-moi · [et] de · travail-de-moi"},{"fr":"L'arabe est une langue magnifique.","tgt":"الْعَرَبِيَّةُ لُغَةٌ رَائِعَةٌ.","ro":"Al-ʿarabiyyatu lughatun rāʾiʿatun.","lit":"l'-arabe · langue · magnifique"},{"fr":"J'aime apprendre l'arabe chaque jour.","tgt":"أُحِبُّ تَعَلُّمَ الْعَرَبِيَّةِ كُلَّ يَوْمٍ.","ro":"Uḥibbu taʿalluma al-ʿarabiyyati kulla yawmin.","lit":"j'aime · apprentissage · l'-arabe · chaque · jour"},{"fr":"Le niveau un est terminé !","tgt":"اِنْتَهَى الْمُسْتَوَى الْأَوَّلُ!","ro":"Intahā al-mustawā al-awwalu!","lit":"s'est-terminé · le-niveau · le-premier !"},{"fr":"Bravo, et à bientôt !","tgt":"أَحْسَنْتَ، وَإِلَى اللِّقَاءِ!","ro":"Aḥsanta, wa ilā al-liqāʾi!","lit":"tu-as-bien-fait · [et] jusqu'à · la-rencontre !"}],"tip":{"title":"Les formules de la conversation : « tasharrafna, maa as-salama, ila al-liqa »","example":"Au revoir, et à demain ! — <b>مَعَ السَّلَامَةِ</b>، وَإِلَى الْغَدِ!","body":"Pour finir ce premier niveau, voici les formules qui ouvrent et ferment une conversation. Quand on rencontre quelqu'un, on dit « tasharrafna », qui veut dire mot à mot : nous avons été honorés ; c'est notre « enchanté ». Pour partir, on dit « maa as-salama », littéralement : avec la paix, et la personne qui reste répond souvent la même chose. On peut aussi dire « ila al-liqa », jusqu'à la rencontre, c'est-à-dire au revoir et à bientôt. On remplace volontiers la rencontre par un moment précis : « ila al-ghad », à demain. Ces petites phrases rendent votre arabe chaleureux et poli, et on vous les rendra toujours avec un sourire, à Tunis comme ailleurs. Astuce : « liqa » ressemble un peu à « lien » ; on se quitte en gardant le lien jusqu'à la prochaine rencontre.","exampleRo":"Maʿa as-salāmati, wa ilā al-ghadi!","lit":"avec · la-paix · [et] jusqu'à · demain !","say":{"tasharrafna":"تَشَرَّفْنَا","maa as-salama":"مَعَ السَّلَامَة","ila al-liqa":"إِلَى اللِّقَاء","ila al-ghad":"إِلَى الْغَد","liqa":"لِقَاء","tasharrafna, maa as-salama, ila al-liqa":"تَشَرَّفْنَا، مَعَ السَّلَامَة، إِلَى اللِّقَاء"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un appartement à Zamalek","phrases":[{"fr":"Nous avons loué un appartement à Zamalek.","tgt":"اِسْتَأْجَرْنَا شَقَّةً فِي الزَّمَالِكِ.","ro":"Istaʾjarnā shaqqatan fī az-Zamāliki."},{"fr":"L'appartement est au quatrième étage.","tgt":"الشَّقَّةُ فِي الطَّابِقِ الرَّابِعِ.","ro":"Ash-shaqqatu fī aṭ-ṭābiqi ar-rābiʿi."},{"fr":"Il a un grand balcon qui donne sur le Nil.","tgt":"فِيهَا شُرْفَةٌ كَبِيرَةٌ تُطِلُّ عَلَى النِّيلِ.","ro":"Fīhā shurfatun kabīratun tuṭillu ʿalā an-Nīli."},{"fr":"Le loyer est de huit mille livres par mois.","tgt":"الْإِيجَارُ ثَمَانِيَةُ آلَافِ جُنَيْهٍ فِي الشَّهْرِ.","ro":"Al-ījāru thamāniyatu ālāfi junayhin fī ash-shahri."},{"fr":"Le propriétaire habite dans le même immeuble.","tgt":"يَسْكُنُ الْمَالِكُ فِي الْعِمَارَةِ نَفْسِهَا.","ro":"Yaskunu al-māliku fī al-ʿimārati nafsihā."},{"fr":"Les meubles sont anciens mais confortables.","tgt":"الْأَثَاثُ قَدِيمٌ لَكِنَّهُ مُرِيحٌ.","ro":"Al-athāthu qadīmun lākinnahu murīḥun."},{"fr":"La cuisine est petite mais très propre.","tgt":"الْمَطْبَخُ صَغِيرٌ لَكِنَّهُ نَظِيفٌ جِدًّا.","ro":"Al-maṭbakhu ṣaghīrun lākinnahu naẓīfun jiddan."},{"fr":"Hier, nous avons acheté des rideaux neufs.","tgt":"أَمْسِ، اِشْتَرَيْنَا سَتَائِرَ جَدِيدَةً.","ro":"Amsi, ishtaraynā satāʾira jadīdatan."},{"fr":"Le quartier est calme et plein d'arbres.","tgt":"الْحَيُّ هَادِئٌ وَمَلِيءٌ بِالْأَشْجَارِ.","ro":"Al-ḥayyu hādiʾun wa-malīʾun bil-ashjāri."},{"fr":"Ici, je me sens vraiment chez moi.","tgt":"أَشْعُرُ هُنَا حَقًّا أَنَّنِي فِي بَيْتِي.","ro":"Ashʿuru hunā ḥaqqan annanī fī baytī."}]},{"title":"Ouvrir un compte à la banque","phrases":[{"fr":"Je veux ouvrir un compte en banque.","tgt":"أُرِيدُ أَنْ أَفْتَحَ حِسَابًا فِي الْبَنْكِ.","ro":"Urīdu an aftaḥa ḥisāban fī al-banki."},{"fr":"Vous devez d'abord remplir ce formulaire.","tgt":"يَجِبُ أَنْ تَمْلَأَ هَذِهِ الِاسْتِمَارَةَ أَوَّلًا.","ro":"Yajibu an tamlaʾa hādhihi al-istimārata awwalan."},{"fr":"Je voudrais aussi demander une carte bancaire.","tgt":"أَوَدُّ أَيْضًا أَنْ أَطْلُبَ بِطَاقَةً مَصْرِفِيَّةً.","ro":"Awaddu ayḍan an aṭluba biṭāqatan maṣrifiyyatan."},{"fr":"Pouvez-vous me donner votre passeport ?","tgt":"هَلْ يُمْكِنُكَ أَنْ تُعْطِيَنِي جَوَازَ سَفَرِكَ؟","ro":"Hal yumkinuka an tuʿṭiyanī jawāza safarika?"},{"fr":"L'employé va vous aider tout de suite.","tgt":"سَيُسَاعِدُكَ الْمُوَظَّفُ حَالًا.","ro":"Sayusāʿiduka al-muwaẓẓafu ḥālan."},{"fr":"Il faut attendre une semaine pour la carte.","tgt":"يَجِبُ أَنْ تَنْتَظِرَ أُسْبُوعًا لِلْبِطَاقَةِ.","ro":"Yajibu an tantaẓira usbūʿan lil-biṭāqati."},{"fr":"Je préfère retirer l'argent au guichet.","tgt":"أُفَضِّلُ أَنْ أَسْحَبَ الْمَالَ مِنَ الشُّبَّاكِ.","ro":"Ufaḍḍilu an asḥaba al-māla mina ash-shubbāki."},{"fr":"Ma femme aimerait ouvrir un compte, elle aussi.","tgt":"تُحِبُّ زَوْجَتِي أَنْ تَفْتَحَ حِسَابًا أَيْضًا.","ro":"Tuḥibbu zawjatī an taftaḥa ḥisāban ayḍan."},{"fr":"Nous ne voulons pas payer de frais mensuels.","tgt":"لَا نُرِيدُ أَنْ نَدْفَعَ رُسُومًا شَهْرِيَّةً.","ro":"Lā nurīdu an nadfaʿa rusūman shahriyyatan."},{"fr":"Merci, je reviendrai demain avec les papiers.","tgt":"شُكْرًا، سَأَعُودُ غَدًا مَعَ الْأَوْرَاقِ.","ro":"Shukran, saʾaʿūdu ghadan maʿa al-awrāqi."}],"tip":{"title":"« An » suivi du subjonctif","example":"Je veux ouvrir un compte en banque. — أُرِيدُ <b>أَنْ أَفْتَحَ</b> حِسَابًا فِي الْبَنْكِ.","body":"Après des verbes comme « urīdu » (je veux) ou « yajibu » (il faut), l'arabe n'a pas d'infinitif : il dit « que », puis un verbe conjugué. Ce « que » se dit « an », et le verbe qui le suit passe au subjonctif : sa dernière voyelle « ou » devient « a ». Ainsi « aftahu » (j'ouvre) devient « an aftaha », et « Urīdu an aftaha hisāban » se dit littéralement : je veux que j'ouvre un compte. De la même façon, « urīdu an adhhaba » veut dire je veux aller, et « yajibu an tashraba » veut dire tu dois boire. Pour retenir : derrière « an », le verbe ouvre la bouche et finit sur un « a ».","exampleRo":"Urīdu an aftaḥa ḥisāban fī al-banki.","lit":"je-veux · [que] · j'ouvre · compte · dans · la-banque","say":{"An":"أَنْ","urīdu":"أُرِيدُ","yajibu":"يَجِبُ","an":"أَنْ","aftahu":"أَفْتَحُ","an aftaha":"أَنْ أَفْتَحَ","Urīdu an aftaha hisāban":"أُرِيدُ أَنْ أَفْتَحَ حِسَابًا","urīdu an adhhaba":"أُرِيدُ أَنْ أَذْهَبَ","yajibu an tashraba":"يَجِبُ أَنْ تَشْرَبَ"}}},{"title":"À la clinique du quartier","phrases":[{"fr":"J'ai mal à la tête depuis trois jours.","tgt":"أَشْعُرُ بِصُدَاعٍ مُنْذُ ثَلَاثَةِ أَيَّامٍ.","ro":"Ashʿuru bi-ṣudāʿin mundhu thalāthati ayyāmin."},{"fr":"Le médecin est disponible à dix heures.","tgt":"الطَّبِيبُ مُتَاحٌ فِي السَّاعَةِ الْعَاشِرَةِ.","ro":"Aṭ-ṭabību mutāḥun fī as-sāʿati al-ʿāshirati."},{"fr":"Avez-vous de la fièvre ou de la toux ?","tgt":"هَلْ عِنْدَكَ حُمَّى أَوْ سُعَالٌ؟","ro":"Hal ʿindaka ḥummā aw suʿālun?"},{"fr":"J'ai un peu de fièvre depuis hier soir.","tgt":"عِنْدِي حُمَّى خَفِيفَةٌ مُنْذُ مَسَاءِ أَمْسِ.","ro":"ʿIndī ḥummā khafīfatun mundhu masāʾi amsi."},{"fr":"L'infirmière a vérifié ma tension.","tgt":"فَحَصَتِ الْمُمَرِّضَةُ ضَغْطِي.","ro":"Faḥaṣati al-mumarriḍatu ḍaghṭī."},{"fr":"C'est peut-être à cause de la chaleur.","tgt":"رُبَّمَا بِسَبَبِ الْحَرِّ.","ro":"Rubbamā bi-sababi al-ḥarri."},{"fr":"Vous devez boire beaucoup d'eau.","tgt":"يَجِبُ أَنْ تَشْرَبَ مَاءً كَثِيرًا.","ro":"Yajibu an tashraba māʾan kathīran."},{"fr":"Je vais vous prescrire un médicament léger.","tgt":"سَأَكْتُبُ لَكَ دَوَاءً خَفِيفًا.","ro":"Saʾaktubu laka dawāʾan khafīfan."},{"fr":"Vous irez mieux dans deux jours.","tgt":"سَتَتَحَسَّنُ بَعْدَ يَوْمَيْنِ.","ro":"Satataḥassanu baʿda yawmayni."},{"fr":"Merci docteur, je suis rassuré maintenant.","tgt":"شُكْرًا يَا دُكْتُورُ، أَنَا مُطْمَئِنٌّ الْآنَ.","ro":"Shukran yā duktūru, anā muṭmaʾinnun al-āna."}]},{"title":"Un koshari au centre-ville","phrases":[{"fr":"On mange un koshari ce midi ?","tgt":"هَلْ نَأْكُلُ الْكُشَرِي عَلَى الْغَدَاءِ؟","ro":"Hal naʾkulu al-kusharī ʿalā al-ghadāʾi?"},{"fr":"Je connais un restaurant célèbre au centre-ville.","tgt":"أَعْرِفُ مَطْعَمًا مَشْهُورًا فِي وَسَطِ الْبَلَدِ.","ro":"Aʿrifu maṭʿaman mashhūran fī wasaṭi al-baladi."},{"fr":"Le koshari mélange riz, lentilles et pâtes.","tgt":"يَجْمَعُ الْكُشَرِي الْأَرُزَّ وَالْعَدَسَ وَالْمَعْكَرُونَةَ.","ro":"Yajmaʿu al-kusharī al-aruzza wal-ʿadasa wal-maʿkarūnata."},{"fr":"On ajoute une sauce tomate épicée.","tgt":"نُضِيفُ صَلْصَةَ طَمَاطِمَ حَارَّةً.","ro":"Nuḍīfu ṣalṣata ṭamāṭima ḥārratan."},{"fr":"La grande assiette coûte trente livres.","tgt":"الطَّبَقُ الْكَبِيرُ بِثَلَاثِينَ جُنَيْهًا.","ro":"Aṭ-ṭabaqu al-kabīru bi-thalāthīna junayhan."},{"fr":"Le serveur a apporté l'eau rapidement.","tgt":"أَحْضَرَ النَّادِلُ الْمَاءَ بِسُرْعَةٍ.","ro":"Aḥḍara an-nādilu al-māʾa bi-surʿatin."},{"fr":"Le restaurant était plein d'étudiants et d'employés.","tgt":"كَانَ الْمَطْعَمُ مَلِيئًا بِالطُّلَّابِ وَالْمُوَظَّفِينَ.","ro":"Kāna al-maṭʿamu malīʾan biṭ-ṭullābi wal-muwaẓẓafīna."},{"fr":"Tu veux encore un peu d'oignons frits ?","tgt":"هَلْ تُرِيدُ مَزِيدًا مِنَ الْبَصَلِ الْمَقْلِيِّ؟","ro":"Hal turīdu mazīdan mina al-baṣali al-maqliyyi?"},{"fr":"C'est le meilleur plat pour un petit budget.","tgt":"هَذَا أَفْضَلُ طَبَقٍ لِمِيزَانِيَّةٍ صَغِيرَةٍ.","ro":"Hādhā afḍalu ṭabaqin li-mīzāniyyatin ṣaghīratin."},{"fr":"Je reviendrai ici la semaine prochaine.","tgt":"سَأَعُودُ إِلَى هُنَا الْأُسْبُوعَ الْقَادِمَ.","ro":"Saʾaʿūdu ilā hunā al-usbūʿa al-qādima."}]},{"title":"Hier au bureau","phrases":[{"fr":"Hier, j'ai marché jusqu'au bureau.","tgt":"أَمْسِ، مَشَيْتُ إِلَى الْمَكْتَبِ.","ro":"Amsi, mashaytu ilā al-maktabi."},{"fr":"Je marche chaque matin au bord du Nil.","tgt":"أَمْشِي كُلَّ صَبَاحٍ عَلَى ضِفَّةِ النِّيلِ.","ro":"Amshī kulla ṣabāḥin ʿalā ḍiffati an-Nīli."},{"fr":"Le directeur a dit que la réunion était annulée.","tgt":"قَالَ الْمُدِيرُ إِنَّ الِاجْتِمَاعَ مُلْغًى.","ro":"Qāla al-mudīru inna al-ijtimāʿa mulghan."},{"fr":"Qu'est-ce qu'il dit dans son message ?","tgt":"مَاذَا يَقُولُ فِي رِسَالَتِهِ؟","ro":"Mādhā yaqūlu fī risālatihi?"},{"fr":"Il dit que le projet avance bien.","tgt":"يَقُولُ إِنَّ الْمَشْرُوعَ يَتَقَدَّمُ جَيِّدًا.","ro":"Yaqūlu inna al-mashrūʿa yataqaddamu jayyidan."},{"fr":"Je suis rentré à la maison à sept heures.","tgt":"عُدْتُ إِلَى الْبَيْتِ فِي السَّاعَةِ السَّابِعَةِ.","ro":"ʿUdtu ilā al-bayti fī as-sāʿati as-sābiʿati."},{"fr":"Ma collègue est restée tard au bureau.","tgt":"بَقِيَتْ زَمِيلَتِي فِي الْمَكْتَبِ حَتَّى وَقْتٍ مُتَأَخِّرٍ.","ro":"Baqiyat zamīlatī fī al-maktabi ḥattā waqtin mutaʾakhkhirin."},{"fr":"J'ai dormi tôt parce que j'étais fatigué.","tgt":"نِمْتُ مُبَكِّرًا لِأَنَّنِي كُنْتُ مُتْعَبًا.","ro":"Nimtu mubakkiran li-annanī kuntu mutʿaban."},{"fr":"Qu'as-tu dit au directeur ?","tgt":"مَاذَا قُلْتَ لِلْمُدِيرِ؟","ro":"Mādhā qulta lil-mudīri?"},{"fr":"J'ai dit que j'étais prêt pour demain.","tgt":"قُلْتُ إِنَّنِي مُسْتَعِدٌّ لِلْغَدِ.","ro":"Qultu innanī mustaʿiddun lil-ghadi."}],"tip":{"title":"Les verbes à voyelle longue","example":"Hier, j'ai marché jusqu'au bureau. — أَمْسِ، <b>مَشَيْتُ</b> إِلَى الْمَكْتَبِ.","body":"Certains verbes très fréquents ont une voyelle longue au cœur de leur racine. « Qāla » (il a dit) devient « yaqūlu » au présent (il dit) : le « ā » se change en « ū ». Quand une consonne suit, cette voyelle se raccourcit : « qultu », j'ai dit. D'autres verbes finissent par une voyelle longue, comme « mashā » (il a marché) et « yamshī » (il marche) ; au passé avec « je », on entend un « y » : « mashaytu ». Ainsi « Amsi, mashaytu ilā al-maktabi » se dit littéralement : hier, j'ai marché vers le bureau. Astuce : vous connaissez déjà « kāna » et « kuntu », qui suivent exactement la même logique que « qāla » et « qultu ».","exampleRo":"Amsi, mashaytu ilā al-maktabi.","lit":"hier · j'ai-marché · vers · le-bureau","say":{"Qāla":"قَالَ","yaqūlu":"يَقُولُ","qultu":"قُلْتُ","mashā":"مَشَى","yamshī":"يَمْشِي","mashaytu":"مَشَيْتُ","Amsi, mashaytu ilā al-maktabi":"أَمْسِ، مَشَيْتُ إِلَى الْمَكْتَبِ","kāna":"كَانَ","kuntu":"كُنْتُ","qāla":"قَالَ"}}},{"title":"Le chemin du métro","phrases":[{"fr":"Pardon, où se trouve la station de métro la plus proche ?","tgt":"عَفْوًا، أَيْنَ أَقْرَبُ مَحَطَّةِ مِتْرُو؟","ro":"ʿAfwan, ayna aqrabu maḥaṭṭati mitrū?"},{"fr":"Va tout droit, puis prends la première rue à gauche.","tgt":"اِذْهَبْ مُبَاشَرَةً، ثُمَّ خُذْ أَوَّلَ شَارِعٍ عَلَى الْيَسَارِ.","ro":"Idhhab mubāsharatan, thumma khudh awwala shāriʿin ʿalā al-yasāri."},{"fr":"Marche environ cinq minutes.","tgt":"اِمْشِ حَوَالَيْ خَمْسِ دَقَائِقَ.","ro":"Imshi ḥawālay khamsi daqāʾiqa."},{"fr":"Écris-moi l'adresse sur ce papier, s'il te plaît.","tgt":"اُكْتُبْ لِي الْعُنْوَانَ عَلَى هَذِهِ الْوَرَقَةِ مِنْ فَضْلِكَ.","ro":"Uktub lī al-ʿunwāna ʿalā hādhihi al-waraqati min faḍlika."},{"fr":"Tenez, voici votre ticket.","tgt":"تَفَضَّلْ، هَذِهِ تَذْكِرَتُكَ.","ro":"Tafaḍḍal, hādhihi tadhkiratuka."},{"fr":"Descends à la station Attaba.","tgt":"اِنْزِلْ فِي مَحَطَّةِ الْعَتَبَةِ.","ro":"Inzil fī maḥaṭṭati al-ʿAtabati."},{"fr":"Ne prends pas de taxi, c'est cher.","tgt":"لَا تَأْخُذْ سَيَّارَةَ أُجْرَةٍ، إِنَّهَا غَالِيَةٌ.","ro":"Lā taʾkhudh sayyārata ujratin, innahā ghāliyatun."},{"fr":"Demande au gardien si tu te perds.","tgt":"اِسْأَلِ الْحَارِسَ إِذَا ضَلَلْتَ الطَّرِيقَ.","ro":"Isʾali al-ḥārisa idhā ḍalalta aṭ-ṭarīqa."},{"fr":"Entre, assieds-toi un moment.","tgt":"تَفَضَّلْ، اِجْلِسْ قَلِيلًا.","ro":"Tafaḍḍal, ijlis qalīlan."},{"fr":"Merci, tu m'as vraiment aidé.","tgt":"شُكْرًا، لَقَدْ سَاعَدْتَنِي كَثِيرًا.","ro":"Shukran, laqad sāʿadtanī kathīran."}],"tip":{"title":"L'impératif","example":"Va tout droit, puis prends la première rue à gauche. — <b>اِذْهَبْ</b> مُبَاشَرَةً، ثُمَّ <b>خُذْ</b> أَوَّلَ شَارِعٍ عَلَى الْيَسَارِ.","body":"Pour donner un ordre ou un conseil, l'arabe part du présent. Prenez « tadhhabu » (tu vas) : on enlève le « ta » du début et le « u » final, puis on ajoute une petite voyelle d'appui devant, ce qui donne « idhhab », va ! De la même façon, « taktubu » (tu écris) devient « uktub », écris : quand la voyelle du milieu est un « u », la voyelle d'appui est aussi un « u ». « Idhhab mubāsharatan » se dit littéralement : va directement. Certains impératifs sont tout courts, comme « khudh » (prends). Et retenez le précieux « tafaddal », qui veut dire tenez, entrez ou je vous en prie, selon la situation.","exampleRo":"Idhhab mubāsharatan, thumma khudh awwala shāriʿin ʿalā al-yasāri.","lit":"va · directement · puis · prends · première · rue · sur · la-gauche","say":{"tadhhabu":"تَذْهَبُ","idhhab":"اِذْهَبْ","taktubu":"تَكْتُبُ","uktub":"اُكْتُبْ","Idhhab mubāsharatan":"اِذْهَبْ مُبَاشَرَةً","khudh":"خُذْ","tafaddal":"تَفَضَّلْ"}}},{"title":"Au marché du quartier","phrases":[{"fr":"Le marché ouvre très tôt le matin.","tgt":"تَفْتَحُ السُّوقُ أَبْوَابَهَا مُبَكِّرًا جِدًّا.","ro":"Taftaḥu as-sūqu abwābahā mubakkiran jiddan."},{"fr":"Les tomates sont moins chères aujourd'hui.","tgt":"الطَّمَاطِمُ أَرْخَصُ الْيَوْمَ.","ro":"Aṭ-ṭamāṭimu arkhaṣu al-yawma."},{"fr":"Combien coûte le kilo de mangues ?","tgt":"بِكَمْ كِيلُو الْمَانْجُو؟","ro":"Bi-kam kīlū al-mānjū?"},{"fr":"Le vendeur m'a fait un bon prix.","tgt":"أَعْطَانِي الْبَائِعُ سِعْرًا جَيِّدًا.","ro":"Aʿṭānī al-bāʾiʿu siʿran jayyidan."},{"fr":"Je voudrais deux kilos de pommes de terre.","tgt":"أُرِيدُ كِيلُوَيْنِ مِنَ الْبَطَاطِسِ.","ro":"Urīdu kīlūwayni mina al-baṭāṭisi."},{"fr":"Ces oranges viennent de la campagne.","tgt":"هَذَا الْبُرْتُقَالُ مِنَ الرِّيفِ.","ro":"Hādhā al-burtuqālu mina ar-rīfi."},{"fr":"On trouve les herbes fraîches au fond du marché.","tgt":"نَجِدُ الْأَعْشَابَ الطَّازَجَةَ فِي آخِرِ السُّوقِ.","ro":"Najidu al-aʿshāba aṭ-ṭāzajata fī ākhiri as-sūqi."},{"fr":"J'ai oublié mon panier à la maison.","tgt":"نَسِيتُ سَلَّتِي فِي الْبَيْتِ.","ro":"Nasītu sallatī fī al-bayti."},{"fr":"Par chance, le vendeur a des sacs en papier.","tgt":"لِحُسْنِ الْحَظِّ، عِنْدَ الْبَائِعِ أَكْيَاسٌ وَرَقِيَّةٌ.","ro":"Li-ḥusni al-ḥaẓẓi, ʿinda al-bāʾiʿi akyāsun waraqiyyatun."},{"fr":"Le samedi, le marché est toujours bondé.","tgt":"يَوْمَ السَّبْتِ، تَكُونُ السُّوقُ مُزْدَحِمَةً دَائِمًا.","ro":"Yawma as-sabti, takūnu as-sūqu muzdaḥimatan dāʾiman."}]},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Notre voisin du dessus est très gentil.","tgt":"جَارُنَا فِي الطَّابِقِ الْعُلْوِيِّ لَطِيفٌ جِدًّا.","ro":"Jārunā fī aṭ-ṭābiqi al-ʿulwiyyi laṭīfun jiddan."},{"fr":"Il nous a invités à prendre le thé.","tgt":"دَعَانَا إِلَى شُرْبِ الشَّايِ.","ro":"Daʿānā ilā shurbi ash-shāyi."},{"fr":"Sa femme prépare de délicieuses pâtisseries.","tgt":"تُحَضِّرُ زَوْجَتُهُ حَلَوِيَّاتٍ لَذِيذَةً.","ro":"Tuḥaḍḍiru zawjatuhu ḥalawiyyātin ladhīdhatan."},{"fr":"Leurs enfants jouent dans l'escalier.","tgt":"يَلْعَبُ أَوْلَادُهُمَا عَلَى الدَّرَجِ.","ro":"Yalʿabu awlāduhumā ʿalā ad-daraji."},{"fr":"Le gardien de l'immeuble s'appelle Am Saïd.","tgt":"اِسْمُ بَوَّابِ الْعِمَارَةِ عَمُّ سَعِيدٍ.","ro":"Ismu bawwābi al-ʿimārati ʿammu Saʿīdin."},{"fr":"Il porte nos courses jusqu'à l'ascenseur.","tgt":"يَحْمِلُ مُشْتَرَيَاتِنَا إِلَى الْمِصْعَدِ.","ro":"Yaḥmilu mushtarayātinā ilā al-miṣʿadi."},{"fr":"Hier, nos voisins ont fait beaucoup de bruit.","tgt":"أَمْسِ، أَحْدَثَ جِيرَانُنَا ضَجِيجًا كَبِيرًا.","ro":"Amsi, aḥdatha jīrānunā ḍajījan kabīran."},{"fr":"Ils fêtaient l'anniversaire de leur fille.","tgt":"كَانُوا يَحْتَفِلُونَ بِعِيدِ مِيلَادِ بِنْتِهِمْ.","ro":"Kānū yaḥtafilūna bi-ʿīdi mīlādi bintihim."},{"fr":"Ils nous ont apporté un morceau de gâteau.","tgt":"أَحْضَرُوا لَنَا قِطْعَةً مِنَ الْكَعْكَةِ.","ro":"Aḥḍarū lanā qiṭʿatan mina al-kaʿkati."},{"fr":"C'est agréable d'avoir de bons voisins.","tgt":"مِنَ الْجَمِيلِ أَنْ يَكُونَ لَنَا جِيرَانٌ طَيِّبُونَ.","ro":"Mina al-jamīli an yakūna lanā jīrānun ṭayyibūna."}]},{"title":"La chaleur de l'été","phrases":[{"fr":"En août, il fait quarante degrés au Caire.","tgt":"فِي أُغُسْطُسَ، تَبْلُغُ الْحَرَارَةُ أَرْبَعِينَ دَرَجَةً فِي الْقَاهِرَةِ.","ro":"Fī ughusṭusa, tablughu al-ḥarāratu arbaʿīna darajatan fī al-Qāhirati."},{"fr":"Je ne sors pas l'après-midi à cause de la chaleur.","tgt":"لَا أَخْرُجُ بَعْدَ الظُّهْرِ بِسَبَبِ الْحَرِّ.","ro":"Lā akhruju baʿda aẓ-ẓuhri bi-sababi al-ḥarri."},{"fr":"Le climatiseur de la chambre est en panne.","tgt":"الْمُكَيِّفُ فِي الْغُرْفَةِ مُعَطَّلٌ.","ro":"Al-mukayyifu fī al-ghurfati muʿaṭṭalun."},{"fr":"Le technicien viendra demain matin.","tgt":"سَيَأْتِي الْفَنِّيُّ صَبَاحَ الْغَدِ.","ro":"Sayaʾtī al-fanniyyu ṣabāḥa al-ghadi."},{"fr":"Nous dormons sur le balcon quand il fait trop chaud.","tgt":"نَنَامُ عَلَى الشُّرْفَةِ عِنْدَمَا يَشْتَدُّ الْحَرُّ.","ro":"Nanāmu ʿalā ash-shurfati ʿindamā yashtaddu al-ḥarru."},{"fr":"Le soir, les familles se promènent au bord du Nil.","tgt":"فِي الْمَسَاءِ، تَتَنَزَّهُ الْعَائِلَاتُ عَلَى ضِفَّةِ النِّيلِ.","ro":"Fī al-masāʾi, tatanazzahu al-ʿāʾilātu ʿalā ḍiffati an-Nīli."},{"fr":"Je bois un jus de canne à sucre bien frais.","tgt":"أَشْرَبُ عَصِيرَ قَصَبِ السُّكَّرِ الْبَارِدَ.","ro":"Ashrabu ʿaṣīra qaṣabi as-sukkari al-bārida."},{"fr":"Tu dois toujours avoir une bouteille d'eau sur toi.","tgt":"يَجِبُ أَنْ تَحْمِلَ دَائِمًا زُجَاجَةَ مَاءٍ.","ro":"Yajibu an taḥmila dāʾiman zujājata māʾin."},{"fr":"L'été dernier était encore plus chaud.","tgt":"كَانَ الصَّيْفُ الْمَاضِي أَشَدَّ حَرًّا.","ro":"Kāna aṣ-ṣayfu al-māḍī ashadda ḥarran."},{"fr":"Heureusement, les nuits sont un peu plus fraîches.","tgt":"لِحُسْنِ الْحَظِّ، اللَّيَالِي أَبْرَدُ قَلِيلًا.","ro":"Li-ḥusni al-ḥaẓẓi, al-layālī abradu qalīlan."}]},{"title":"À la pharmacie","phrases":[{"fr":"Bonsoir, avez-vous quelque chose contre la toux ?","tgt":"مَسَاءَ الْخَيْرِ، هَلْ عِنْدَكُمْ دَوَاءٌ لِلسُّعَالِ؟","ro":"Masāʾa al-khayri, hal ʿindakum dawāʾun lis-suʿāli?"},{"fr":"Voici un sirop très efficace.","tgt":"هَذَا شَرَابٌ فَعَّالٌ جِدًّا.","ro":"Hādhā sharābun faʿʿālun jiddan."},{"fr":"Prenez-en une cuillère trois fois par jour.","tgt":"خُذْ مِنْهُ مِلْعَقَةً ثَلَاثَ مَرَّاتٍ فِي الْيَوْمِ.","ro":"Khudh minhu milʿaqatan thalātha marrātin fī al-yawmi."},{"fr":"Faut-il une ordonnance pour ce médicament ?","tgt":"هَلْ يَحْتَاجُ هَذَا الدَّوَاءُ إِلَى وَصْفَةٍ طِبِّيَّةٍ؟","ro":"Hal yaḥtāju hādhā ad-dawāʾu ilā waṣfatin ṭibbiyyatin?"},{"fr":"Non, vous pouvez l'acheter sans ordonnance.","tgt":"لَا، يُمْكِنُكَ أَنْ تَشْتَرِيَهُ بِدُونِ وَصْفَةٍ.","ro":"Lā, yumkinuka an tashtariyahu bi-dūni waṣfatin."},{"fr":"Je voudrais aussi de la crème solaire.","tgt":"أُرِيدُ أَيْضًا وَاقِيًا مِنَ الشَّمْسِ.","ro":"Urīdu ayḍan wāqiyan mina ash-shamsi."},{"fr":"Le pharmacien parle un peu français.","tgt":"يَتَكَلَّمُ الصَّيْدَلِيُّ الْفَرَنْسِيَّةَ قَلِيلًا.","ro":"Yatakallamu aṣ-ṣaydaliyyu al-faransiyyata qalīlan."},{"fr":"Cette pharmacie est ouverte toute la nuit.","tgt":"هَذِهِ الصَّيْدَلِيَّةُ مَفْتُوحَةٌ طُوَالَ اللَّيْلِ.","ro":"Hādhihi aṣ-ṣaydaliyyatu maftūḥatun ṭuwāla al-layli."},{"fr":"Ça fait combien pour le sirop et la crème ?","tgt":"كَمْ ثَمَنُ الشَّرَابِ وَالْوَاقِي؟","ro":"Kam thamanu ash-sharābi wal-wāqī?"},{"fr":"Soixante-cinq livres, s'il vous plaît.","tgt":"خَمْسَةٌ وَسِتُّونَ جُنَيْهًا مِنْ فَضْلِكَ.","ro":"Khamsatun wa-sittūna junayhan min faḍlika."}]},{"title":"Une felouque sur le Nil","phrases":[{"fr":"Dimanche, nous avons loué une felouque.","tgt":"يَوْمَ الْأَحَدِ، اِسْتَأْجَرْنَا فَلُوكَةً.","ro":"Yawma al-aḥadi, istaʾjarnā falūkatan."},{"fr":"Le batelier connaît très bien le fleuve.","tgt":"يَعْرِفُ صَاحِبُ الْقَارِبِ النَّهْرَ جَيِّدًا.","ro":"Yaʿrifu ṣāḥibu al-qāribi an-nahra jayyidan."},{"fr":"Le vent était doux et rafraîchissant.","tgt":"كَانَتِ الرِّيحُ لَطِيفَةً وَمُنْعِشَةً.","ro":"Kānati ar-rīḥu laṭīfatan wa-munʿishatan."},{"fr":"On voyait la tour du Caire au loin.","tgt":"كُنَّا نَرَى بُرْجَ الْقَاهِرَةِ مِنْ بَعِيدٍ.","ro":"Kunnā narā burja al-Qāhirati min baʿīdin."},{"fr":"Les enfants ont salué les autres bateaux.","tgt":"لَوَّحَ الْأَطْفَالُ لِلْقَوَارِبِ الْأُخْرَى.","ro":"Lawwaḥa al-aṭfālu lil-qawāribi al-ukhrā."},{"fr":"Nous avons apporté des sandwichs et des fruits.","tgt":"أَحْضَرْنَا شَطَائِرَ وَفَوَاكِهَ.","ro":"Aḥḍarnā shaṭāʾira wa-fawākiha."},{"fr":"Le coucher de soleil sur le fleuve était magnifique.","tgt":"كَانَ غُرُوبُ الشَّمْسِ عَلَى النَّهْرِ رَائِعًا.","ro":"Kāna ghurūbu ash-shamsi ʿalā an-nahri rāʾiʿan."},{"fr":"La promenade a duré deux heures.","tgt":"اِسْتَمَرَّتِ النُّزْهَةُ سَاعَتَيْنِ.","ro":"Istamarrati an-nuzhatu sāʿatayni."},{"fr":"Chaque passager a payé cinquante livres.","tgt":"دَفَعَ كُلُّ رَاكِبٍ خَمْسِينَ جُنَيْهًا.","ro":"Dafaʿa kullu rākibin khamsīna junayhan."},{"fr":"Nous referons cette promenade avec nos amis.","tgt":"سَنُكَرِّرُ هَذِهِ النُّزْهَةَ مَعَ أَصْدِقَائِنَا.","ro":"Sanukarriru hādhihi an-nuzhata maʿa aṣdiqāʾinā."}]},{"title":"Au Khan el-Khalili","phrases":[{"fr":"J'ai vu un joli coffret en bois sculpté.","tgt":"رَأَيْتُ صُنْدُوقًا جَمِيلًا مِنَ الْخَشَبِ الْمَنْقُوشِ.","ro":"Raʾaytu ṣundūqan jamīlan mina al-khashabi al-manqūshi."},{"fr":"Je l'ai vu hier dans cette boutique.","tgt":"رَأَيْتُهُ أَمْسِ فِي هَذَا الدُّكَّانِ.","ro":"Raʾaytuhu amsi fī hādhā ad-dukkāni."},{"fr":"Le vendeur nous a accueillis chaleureusement.","tgt":"اِسْتَقْبَلَنَا الْبَائِعُ بِحَرَارَةٍ.","ro":"Istaqbalanā al-bāʾiʿu bi-ḥarāratin."},{"fr":"Il nous a servi un thé à la menthe.","tgt":"قَدَّمَ لَنَا شَايًا بِالنَّعْنَاعِ.","ro":"Qaddama lanā shāyan bin-naʿnāʿi."},{"fr":"Ce collier est magnifique, je le prends.","tgt":"هَذِهِ الْقِلَادَةُ رَائِعَةٌ، سَآخُذُهَا.","ro":"Hādhihi al-qilādatu rāʾiʿatun, saʾākhudhuhā."},{"fr":"Ma sœur va l'adorer.","tgt":"سَتُحِبُّهَا أُخْتِي كَثِيرًا.","ro":"Satuḥibbuhā ukhtī kathīran."},{"fr":"Le vendeur l'a emballé dans du papier.","tgt":"لَفَّهَا الْبَائِعُ فِي وَرَقٍ.","ro":"Laffahā al-bāʾiʿu fī waraqin."},{"fr":"Tu connais le café le plus célèbre du Khan el-Khalili ?","tgt":"هَلْ تَعْرِفُ أَشْهَرَ مَقْهًى فِي خَانِ الْخَلِيلِيِّ؟","ro":"Hal taʿrifu ashhara maqhan fī Khāni al-Khalīliyyi?"},{"fr":"Oui, je le connais depuis mon enfance.","tgt":"نَعَمْ، أَعْرِفُهُ مُنْذُ طُفُولَتِي.","ro":"Naʿam, aʿrifuhu mundhu ṭufūlatī."},{"fr":"Mon père m'y emmenait souvent.","tgt":"كَانَ أَبِي يَأْخُذُنِي إِلَيْهِ كَثِيرًا.","ro":"Kāna abī yaʾkhudhunī ilayhi kathīran."}],"tip":{"title":"Les pronoms compléments collés au verbe","example":"Je l'ai vu hier dans cette boutique. — <b>رَأَيْتُهُ</b> أَمْسِ فِي هَذَا الدُّكَّانِ.","body":"En arabe, les pronoms « le », « la », « me » ou « nous » ne se placent pas devant le verbe comme en français : ils se collent à la fin du verbe. « Raaytu » veut dire j'ai vu ; en ajoutant « hu » (le), on obtient « raaytuhu », je l'ai vu. Avec « hā » (la), on dit « raaytuhā », je l'ai vue, et avec « nā » (nous), « istaqbalanā », il nous a accueillis. La phrase « Raaytuhu amsi » se dit donc littéralement : j'ai vu-le hier. Astuce pour retenir : ce sont presque les mêmes terminaisons que les possessifs, comme dans « baytuhu », sa maison ; seul « moi » change, avec « nī » au lieu de « ī ».","exampleRo":"Raʾaytuhu amsi fī hādhā ad-dukkāni.","lit":"j'ai-vu-le · hier · dans · cette · la-boutique","say":{"Raaytu":"رَأَيْتُ","raaytuhu":"رَأَيْتُهُ","raaytuhā":"رَأَيْتُهَا","istaqbalanā":"اِسْتَقْبَلَنَا","Raaytuhu amsi":"رَأَيْتُهُ أَمْسِ","baytuhu":"بَيْتُهُ"}}},{"title":"Coupures d'eau et d'électricité","phrases":[{"fr":"L'eau a été coupée ce matin dans tout l'immeuble.","tgt":"اِنْقَطَعَ الْمَاءُ هَذَا الصَّبَاحَ فِي الْعِمَارَةِ كُلِّهَا.","ro":"Inqaṭaʿa al-māʾu hādhā aṣ-ṣabāḥa fī al-ʿimārati kullihā."},{"fr":"Le gardien a appelé la compagnie des eaux.","tgt":"اِتَّصَلَ الْبَوَّابُ بِشَرِكَةِ الْمِيَاهِ.","ro":"Ittaṣala al-bawwābu bi-sharikati al-miyāhi."},{"fr":"Ils disent que la réparation prendra trois heures.","tgt":"يَقُولُونَ إِنَّ الْإِصْلَاحَ سَيَسْتَغْرِقُ ثَلَاثَ سَاعَاتٍ.","ro":"Yaqūlūna inna al-iṣlāḥa sayastaghriqu thalātha sāʿātin."},{"fr":"Nous avons rempli quelques seaux hier soir.","tgt":"مَلَأْنَا بَعْضَ الدِّلَاءِ مَسَاءَ أَمْسِ.","ro":"Malaʾnā baʿḍa ad-dilāʾi masāʾa amsi."},{"fr":"En plus, l'électricité est coupée depuis une heure.","tgt":"وَفَوْقَ ذَلِكَ، الْكَهْرَبَاءُ مَقْطُوعَةٌ مُنْذُ سَاعَةٍ.","ro":"Wa-fawqa dhālika, al-kahrabāʾu maqṭūʿatun mundhu sāʿatin."},{"fr":"Où sont les bougies et la lampe de poche ?","tgt":"أَيْنَ الشُّمُوعُ وَالْمِصْبَاحُ الْيَدَوِيُّ؟","ro":"Ayna ash-shumūʿu wal-miṣbāḥu al-yadawiyyu?"},{"fr":"Garde le réfrigérateur bien fermé.","tgt":"أَبْقِ الثَّلَّاجَةَ مُغْلَقَةً.","ro":"Abqi ath-thallājata mughlaqatan."},{"fr":"Les voisins sont descendus dans la rue.","tgt":"نَزَلَ الْجِيرَانُ إِلَى الشَّارِعِ.","ro":"Nazala al-jīrānu ilā ash-shāriʿi."},{"fr":"Le courant est revenu vers midi.","tgt":"عَادَتِ الْكَهْرَبَاءُ نَحْوَ الظُّهْرِ.","ro":"ʿĀdati al-kahrabāʾu naḥwa aẓ-ẓuhri."},{"fr":"Tout le monde a applaudi dans l'immeuble.","tgt":"صَفَّقَ الْجَمِيعُ فِي الْعِمَارَةِ.","ro":"Ṣaffaqa al-jamīʿu fī al-ʿimārati."}]},{"title":"Le métro aux heures de pointe","phrases":[{"fr":"Je prends le métro chaque jour pour aller au travail.","tgt":"أَرْكَبُ الْمِتْرُو كُلَّ يَوْمٍ إِلَى الْعَمَلِ.","ro":"Arkabu al-mitrū kulla yawmin ilā al-ʿamali."},{"fr":"À huit heures, les rames sont bondées.","tgt":"فِي السَّاعَةِ الثَّامِنَةِ، تَكُونُ الْقِطَارَاتُ مُزْدَحِمَةً.","ro":"Fī as-sāʿati ath-thāminati, takūnu al-qiṭārātu muzdaḥimatan."},{"fr":"Il y a une voiture réservée aux femmes.","tgt":"هُنَاكَ عَرَبَةٌ مُخَصَّصَةٌ لِلنِّسَاءِ.","ro":"Hunāka ʿarabatun mukhaṣṣaṣatun lin-nisāʾi."},{"fr":"Le ticket ne coûte que quelques livres.","tgt":"ثَمَنُ التَّذْكِرَةِ بِضْعَةُ جُنَيْهَاتٍ فَقَطْ.","ro":"Thamanu at-tadhkirati biḍʿatu junayhātin faqaṭ."},{"fr":"Ma station est la troisième après Attaba.","tgt":"مَحَطَّتِي هِيَ الثَّالِثَةُ بَعْدَ الْعَتَبَةِ.","ro":"Maḥaṭṭatī hiya ath-thālithatu baʿda al-ʿAtabati."},{"fr":"Un jeune homme m'a laissé sa place.","tgt":"تَرَكَ لِي شَابٌّ مَكَانَهُ.","ro":"Taraka lī shābbun makānahu."},{"fr":"Ici, le métro est bien plus rapide que le bus.","tgt":"الْمِتْرُو هُنَا أَسْرَعُ بِكَثِيرٍ مِنَ الْحَافِلَةِ.","ro":"Al-mitrū hunā asraʿu bi-kathīrin mina al-ḥāfilati."},{"fr":"J'écoute des podcasts en arabe dans le métro.","tgt":"أَسْتَمِعُ إِلَى بَرَامِجَ صَوْتِيَّةٍ بِالْعَرَبِيَّةِ فِي الْمِتْرُو.","ro":"Astamiʿu ilā barāmija ṣawtiyyatin bil-ʿarabiyyati fī al-mitrū."},{"fr":"Attention, les portes vont se fermer !","tgt":"اِنْتَبِهْ، سَتَنْغَلِقُ الْأَبْوَابُ!","ro":"Intabih, satanghaliqu al-abwābu!"},{"fr":"Je suis arrivé au bureau juste à l'heure.","tgt":"وَصَلْتُ إِلَى الْمَكْتَبِ فِي الْوَقْتِ تَمَامًا.","ro":"Waṣaltu ilā al-maktabi fī al-waqti tamāman."}]},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, nous habitions à Choubra.","tgt":"عِنْدَمَا كُنْتُ صَغِيرًا، كُنَّا نَسْكُنُ فِي شُبْرَا.","ro":"ʿIndamā kuntu ṣaghīran, kunnā naskunu fī Shubrā."},{"fr":"Notre maison était près d'un grand jardin.","tgt":"كَانَ بَيْتُنَا قَرِيبًا مِنْ حَدِيقَةٍ كَبِيرَةٍ.","ro":"Kāna baytunā qarīban min ḥadīqatin kabīratin."},{"fr":"Je jouais au football avec mes cousins.","tgt":"كُنْتُ أَلْعَبُ كُرَةَ الْقَدَمِ مَعَ أَبْنَاءِ عَمِّي.","ro":"Kuntu alʿabu kurata al-qadami maʿa abnāʾi ʿammī."},{"fr":"Ma grand-mère racontait de belles histoires.","tgt":"كَانَتْ جَدَّتِي تَحْكِي قِصَصًا جَمِيلَةً.","ro":"Kānat jaddatī taḥkī qiṣaṣan jamīlatan."},{"fr":"L'été, nous allions à Alexandrie.","tgt":"فِي الصَّيْفِ، كُنَّا نَذْهَبُ إِلَى الْإِسْكَنْدَرِيَّةِ.","ro":"Fī aṣ-ṣayfi, kunnā nadhhabu ilā al-Iskandariyyati."},{"fr":"Mon père m'achetait des glaces sur la corniche.","tgt":"كَانَ أَبِي يَشْتَرِي لِي الْمُثَلَّجَاتِ عَلَى الْكُورْنِيشِ.","ro":"Kāna abī yashtarī lī al-muthallajāti ʿalā al-kūrnīshi."},{"fr":"J'avais peur des chiens du quartier.","tgt":"كُنْتُ أَخَافُ مِنْ كِلَابِ الْحَيِّ.","ro":"Kuntu akhāfu min kilābi al-ḥayyi."},{"fr":"L'école était à dix minutes à pied.","tgt":"كَانَتِ الْمَدْرَسَةُ عَلَى بُعْدِ عَشْرِ دَقَائِقَ سَيْرًا.","ro":"Kānati al-madrasatu ʿalā buʿdi ʿashri daqāʾiqa sayran."},{"fr":"Hassan, mon ami d'enfance, habite toujours à Choubra.","tgt":"صَدِيقُ طُفُولَتِي حَسَنٌ مَا زَالَ يَسْكُنُ فِي شُبْرَا.","ro":"Ṣadīqu ṭufūlatī Ḥasanun mā zāla yaskunu fī Shubrā."},{"fr":"Ces souvenirs me rendent heureux.","tgt":"هَذِهِ الذِّكْرَيَاتُ تُسْعِدُنِي.","ro":"Hādhihi adh-dhikrayātu tusʿidunī."}]},{"title":"Un document à l'administration","phrases":[{"fr":"Je dois renouveler mon permis de séjour.","tgt":"يَجِبُ أَنْ أُجَدِّدَ إِقَامَتِي.","ro":"Yajibu an ujaddida iqāmatī."},{"fr":"Le bureau ouvre à neuf heures et ferme à deux heures.","tgt":"يَفْتَحُ الْمَكْتَبُ فِي التَّاسِعَةِ وَيُغْلِقُ فِي الثَّانِيَةِ.","ro":"Yaftaḥu al-maktabu fī at-tāsiʿati wa-yughliqu fī ath-thāniyati."},{"fr":"Il y avait une longue file devant la porte.","tgt":"كَانَ هُنَاكَ طَابُورٌ طَوِيلٌ أَمَامَ الْبَابِ.","ro":"Kāna hunāka ṭābūrun ṭawīlun amāma al-bābi."},{"fr":"Prenez un numéro et attendez votre tour.","tgt":"خُذْ رَقْمًا وَانْتَظِرْ دَوْرَكَ.","ro":"Khudh raqman wa-ntaẓir dawraka."},{"fr":"L'employée a demandé deux photos d'identité.","tgt":"طَلَبَتِ الْمُوَظَّفَةُ صُورَتَيْنِ شَخْصِيَّتَيْنِ.","ro":"Ṭalabati al-muwaẓẓafatu ṣūratayni shakhṣiyyatayni."},{"fr":"Il me manque une copie du contrat de location.","tgt":"تَنْقُصُنِي نُسْخَةٌ مِنْ عَقْدِ الْإِيجَارِ.","ro":"Tanquṣunī nuskhatun min ʿaqdi al-ījāri."},{"fr":"Il y a une photocopieuse au rez-de-chaussée.","tgt":"تُوجَدُ آلَةُ تَصْوِيرٍ فِي الطَّابِقِ الْأَرْضِيِّ.","ro":"Tūjadu ālatu taṣwīrin fī aṭ-ṭābiqi al-arḍiyyi."},{"fr":"Revenez la semaine prochaine pour le récupérer.","tgt":"عُدْ فِي الْأُسْبُوعِ الْقَادِمِ لِتَسْتَلِمَهُ.","ro":"ʿUd fī al-usbūʿi al-qādimi li-tastalimahu."},{"fr":"Cette démarche m'a pris toute la matinée.","tgt":"اِسْتَغْرَقَ هَذَا الْإِجْرَاءُ الصَّبَاحَ كُلَّهُ.","ro":"Istaghraqa hādhā al-ijrāʾu aṣ-ṣabāḥa kullahu."},{"fr":"Mais finalement, tout est en règle.","tgt":"لَكِنْ فِي النِّهَايَةِ، كُلُّ شَيْءٍ عَلَى مَا يُرَامُ.","ro":"Lākin fī an-nihāyati, kullu shayʾin ʿalā mā yurāmu."}]},{"title":"Un petit-déjeuner de foul","phrases":[{"fr":"Le matin, je mange du foul avec du pain.","tgt":"فِي الصَّبَاحِ، آكُلُ الْفُولَ مَعَ الْخُبْزِ.","ro":"Fī aṣ-ṣabāḥi, ākulu al-fūla maʿa al-khubzi."},{"fr":"Le vendeur de foul est au coin de la rue.","tgt":"بَائِعُ الْفُولِ عِنْدَ زَاوِيَةِ الشَّارِعِ.","ro":"Bāʾiʿu al-fūli ʿinda zāwiyati ash-shāriʿi."},{"fr":"Il fait cuire les fèves toute la nuit.","tgt":"يَطْبُخُ الْفُولَ طُوَالَ اللَّيْلِ.","ro":"Yaṭbukhu al-fūla ṭuwāla al-layli."},{"fr":"On ajoute de l'huile d'olive et du cumin.","tgt":"نُضِيفُ زَيْتَ الزَّيْتُونِ وَالْكَمُّونَ.","ro":"Nuḍīfu zayta az-zaytūni wal-kammūna."},{"fr":"Je prends aussi deux falafels bien chauds.","tgt":"آخُذُ أَيْضًا قِطْعَتَيْنِ مِنَ الْفَلَافِلِ السَّاخِنَةِ.","ro":"Ākhudhu ayḍan qiṭʿatayni mina al-falāfili as-sākhinati."},{"fr":"Le sandwich coûte cinq livres seulement.","tgt":"ثَمَنُ السَّنْدَوِيتْشِ خَمْسَةُ جُنَيْهَاتٍ فَقَطْ.","ro":"Thamanu as-sandawītshi khamsatu junayhātin faqaṭ."},{"fr":"Les ouvriers mangent debout près du chariot.","tgt":"يَأْكُلُ الْعُمَّالُ وَاقِفِينَ قُرْبَ الْعَرَبَةِ.","ro":"Yaʾkulu al-ʿummālu wāqifīna qurba al-ʿarabati."},{"fr":"Donne-moi un peu plus de citron, s'il te plaît.","tgt":"أَعْطِنِي قَلِيلًا مِنَ اللَّيْمُونِ مِنْ فَضْلِكَ.","ro":"Aʿṭinī qalīlan mina al-laymūni min faḍlika."},{"fr":"Ce petit-déjeuner me donne de l'énergie jusqu'au soir.","tgt":"هَذَا الْفُطُورُ يُعْطِينِي طَاقَةً حَتَّى الْمَسَاءِ.","ro":"Hādhā al-fuṭūru yuʿṭīnī ṭāqatan ḥattā al-masāʾi."},{"fr":"Ici, riches et pauvres mangent du foul.","tgt":"هُنَا، يَأْكُلُ الْفُولَ الْأَغْنِيَاءُ وَالْفُقَرَاءُ.","ro":"Hunā, yaʾkulu al-fūla al-aghniyāʾu wal-fuqarāʾu."}]},{"title":"Une réunion au travail","phrases":[{"fr":"La réunion importante commence à onze heures.","tgt":"يَبْدَأُ الِاجْتِمَاعُ الْمُهِمُّ فِي السَّاعَةِ الْحَادِيَةَ عَشْرَةَ.","ro":"Yabdaʾu al-ijtimāʿu al-muhimmu fī as-sāʿati al-ḥādiyata ʿashrata."},{"fr":"La directrice a présenté les résultats du premier trimestre.","tgt":"قَدَّمَتِ الْمُدِيرَةُ نَتَائِجَ الرُّبْعِ الْأَوَّلِ.","ro":"Qaddamati al-mudīratu natāʾija ar-rubʿi al-awwali."},{"fr":"Les ventes ont augmenté de dix pour cent.","tgt":"اِرْتَفَعَتِ الْمَبِيعَاتُ بِنِسْبَةِ عَشَرَةٍ فِي الْمِئَةِ.","ro":"Irtafaʿati al-mabīʿātu bi-nisbati ʿasharatin fī al-miʾati."},{"fr":"Mon collègue Karim prend des notes.","tgt":"يُدَوِّنُ زَمِيلِي كَرِيمٌ الْمُلَاحَظَاتِ.","ro":"Yudawwinu zamīlī Karīmun al-mulāḥaẓāti."},{"fr":"Nous devons finir le rapport avant jeudi.","tgt":"يَجِبُ أَنْ نُنْهِيَ التَّقْرِيرَ قَبْلَ يَوْمِ الْخَمِيسِ.","ro":"Yajibu an nunhiya at-taqrīra qabla yawmi al-khamīsi."},{"fr":"Qui va présenter le projet aux clients ?","tgt":"مَنْ سَيُقَدِّمُ الْمَشْرُوعَ لِلْعُمَلَاءِ؟","ro":"Man sayuqaddimu al-mashrūʿa lil-ʿumalāʾi?"},{"fr":"Je m'en occupe, je connais bien le dossier.","tgt":"سَأَتَوَلَّى ذَلِكَ، فَأَنَا أَعْرِفُ الْمَلَفَّ جَيِّدًا.","ro":"Saʾatawallā dhālika, fa-anā aʿrifu al-malaffa jayyidan."},{"fr":"La climatisation de la salle est trop forte.","tgt":"التَّكْيِيفُ فِي الْقَاعَةِ قَوِيٌّ جِدًّا.","ro":"At-takyīfu fī al-qāʿati qawiyyun jiddan."},{"fr":"Après la réunion, nous avons déjeuné ensemble.","tgt":"بَعْدَ الِاجْتِمَاعِ، تَنَاوَلْنَا الْغَدَاءَ مَعًا.","ro":"Baʿda al-ijtimāʿi, tanāwalnā al-ghadāʾa maʿan."},{"fr":"C'était une journée longue mais utile.","tgt":"كَانَ يَوْمًا طَوِيلًا لَكِنَّهُ مُفِيدٌ.","ro":"Kāna yawman ṭawīlan lākinnahu mufīdun."}]},{"title":"Chercher un nouvel appartement","phrases":[{"fr":"Je n'ai pas encore trouvé d'appartement.","tgt":"لَمْ أَجِدْ شَقَّةً بَعْدُ.","ro":"Lam ajid shaqqatan baʿdu."},{"fr":"L'agent immobilier n'a pas répondu hier.","tgt":"لَمْ يَرُدَّ السِّمْسَارُ أَمْسِ.","ro":"Lam yarudda as-simsāru amsi."},{"fr":"Le premier appartement ne m'a pas plu.","tgt":"لَمْ تُعْجِبْنِي الشَّقَّةُ الْأُولَى.","ro":"Lam tuʿjibnī ash-shaqqatu al-ūlā."},{"fr":"La cuisine n'avait pas de fenêtre.","tgt":"لَمْ يَكُنْ فِي الْمَطْبَخِ نَافِذَةٌ.","ro":"Lam yakun fī al-maṭbakhi nāfidhatun."},{"fr":"Nous n'avons pas encore visité le quartier de Maadi.","tgt":"لَمْ نَزُرْ حَيَّ الْمَعَادِي بَعْدُ.","ro":"Lam nazur ḥayya al-Maʿādī baʿdu."},{"fr":"Pourquoi n'as-tu pas signé le contrat ?","tgt":"لِمَاذَا لَمْ تُوَقِّعِ الْعَقْدَ؟","ro":"Limādhā lam tuwaqqiʿi al-ʿaqda?"},{"fr":"Le propriétaire n'a pas accepté de baisser le loyer.","tgt":"لَمْ يَقْبَلِ الْمَالِكُ أَنْ يُخَفِّضَ الْإِيجَارَ.","ro":"Lam yaqbali al-māliku an yukhaffiḍa al-ījāra."},{"fr":"Je n'ai pas dormi de la nuit à cause du bruit.","tgt":"لَمْ أَنَمْ طُوَالَ اللَّيْلِ بِسَبَبِ الضَّجِيجِ.","ro":"Lam anam ṭuwāla al-layli bi-sababi aḍ-ḍajīji."},{"fr":"Il n'a rien dit au sujet des charges.","tgt":"لَمْ يَقُلْ شَيْئًا عَنِ الْمَصَارِيفِ.","ro":"Lam yaqul shayʾan ʿani al-maṣārīfi."},{"fr":"Finalement, nous avons trouvé un appartement à Dokki.","tgt":"أَخِيرًا، وَجَدْنَا شَقَّةً فِي الدُّقِّي.","ro":"Akhīran, wajadnā shaqqatan fī ad-Duqqī."}],"tip":{"title":"« Lam » : la négation du passé","example":"Je n'ai pas encore trouvé d'appartement. — <b>لَمْ أَجِدْ</b> شَقَّةً بَعْدُ.","body":"Pour dire qu'une action n'a pas eu lieu, l'arabe littéraire utilise un petit mot surprenant : « lam ». Le plus étonnant, c'est qu'on ne le met pas devant un verbe au passé, mais devant le présent, dont on retire la dernière voyelle. « Ajidu » (je trouve) devient ainsi « lam ajid », je n'ai pas trouvé. La phrase « Lam ajid shaqqatan badu » se dit littéralement : ne pas je trouve appartement encore. Avec les verbes à voyelle longue, le mot se raccourcit aussi : « yaqūlu » devient « lam yaqul », il n'a pas dit, et « anāmu » devient « lam anam », je n'ai pas dormi. Retenez simplement : « lam » plus un présent raccourci, cela donne un passé négatif.","exampleRo":"Lam ajid shaqqatan baʿdu.","lit":"[ne… pas] · je-trouve · appartement · encore","say":{"Lam":"لَمْ","lam":"لَمْ","Ajidu":"أَجِدُ","lam ajid":"لَمْ أَجِدْ","Lam ajid shaqqatan badu":"لَمْ أَجِدْ شَقَّةً بَعْدُ","yaqūlu":"يَقُولُ","lam yaqul":"لَمْ يَقُلْ","anāmu":"أَنَامُ","lam anam":"لَمْ أَنَمْ"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module sur la vie quotidienne au Caire est terminé.","tgt":"اِنْتَهَتْ هَذِهِ الْوَحْدَةُ عَنِ الْحَيَاةِ الْيَوْمِيَّةِ فِي الْقَاهِرَةِ.","ro":"Intahat hādhihi al-waḥdatu ʿani al-ḥayāti al-yawmiyyati fī al-Qāhirati."},{"fr":"Tu sais maintenant parler de ton appartement.","tgt":"أَصْبَحْتَ الْآنَ تَعْرِفُ كَيْفَ تَتَحَدَّثُ عَنْ شَقَّتِكَ.","ro":"Aṣbaḥta al-āna taʿrifu kayfa tataḥaddathu ʿan shaqqatika."},{"fr":"Tu peux aller seul à la banque et à la pharmacie.","tgt":"يُمْكِنُكَ أَنْ تَذْهَبَ وَحْدَكَ إِلَى الْبَنْكِ وَالصَّيْدَلِيَّةِ.","ro":"Yumkinuka an tadhhaba waḥdaka ilā al-banki waṣ-ṣaydaliyyati."},{"fr":"Tu as appris à raconter ce que tu as fait hier.","tgt":"تَعَلَّمْتَ أَنْ تَحْكِيَ مَا فَعَلْتَهُ أَمْسِ.","ro":"Taʿallamta an taḥkiya mā faʿaltahu amsi."},{"fr":"L'impératif t'aide à donner des conseils.","tgt":"يُسَاعِدُكَ فِعْلُ الْأَمْرِ عَلَى تَقْدِيمِ النَّصَائِحِ.","ro":"Yusāʿiduka fiʿlu al-amri ʿalā taqdīmi an-naṣāʾiḥi."},{"fr":"Tu comprends maintenant la négation du passé.","tgt":"أَنْتَ تَفْهَمُ الْآنَ نَفْيَ الْمَاضِي.","ro":"Anta tafhamu al-āna nafya al-māḍī."},{"fr":"L'arabe devient plus clair chaque jour.","tgt":"تُصْبِحُ الْعَرَبِيَّةُ أَوْضَحَ كُلَّ يَوْمٍ.","ro":"Tuṣbiḥu al-ʿarabiyyatu awḍaḥa kulla yawmin."},{"fr":"Écoute ces leçons encore une fois dans le métro.","tgt":"اِسْتَمِعْ إِلَى هَذِهِ الدُّرُوسِ مَرَّةً أُخْرَى فِي الْمِتْرُو.","ro":"Istamiʿ ilā hādhihi ad-durūsi marratan ukhrā fī al-mitrū."},{"fr":"Je n'ai pas regretté une seule minute.","tgt":"لَمْ أَنْدَمْ عَلَى دَقِيقَةٍ وَاحِدَةٍ.","ro":"Lam andam ʿalā daqīqatin wāḥidatin."},{"fr":"Prochain module : le voyage !","tgt":"الْوَحْدَةُ الْقَادِمَةُ: السَّفَرُ!","ro":"Al-waḥdatu al-qādimatu: as-safaru!"}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Louxor","phrases":[{"fr":"Notre avion a atterri à Louxor ce matin.","tgt":"هَبَطَتْ طَائِرَتُنَا فِي الْأُقْصُرِ هَذَا الصَّبَاحَ.","ro":"Habaṭat ṭāʾiratunā fī al-Uqṣuri hādhā aṣ-ṣabāḥa."},{"fr":"Il fait très chaud dès la sortie de l'aéroport.","tgt":"الْحَرُّ شَدِيدٌ عِنْدَ الْخُرُوجِ مِنَ الْمَطَارِ.","ro":"Al-ḥarru shadīdun ʿinda al-khurūji mina al-maṭāri."},{"fr":"Un chauffeur de l'hôtel nous attend avec une pancarte.","tgt":"يَنْتَظِرُنَا سَائِقٌ مِنَ الْفُنْدُقِ وَمَعَهُ لَافِتَةٌ.","ro":"Yantaẓirunā sāʾiqun mina al-funduqi wa-maʿahu lāfitatun."},{"fr":"Le trajet jusqu'à l'hôtel dure vingt minutes.","tgt":"الرِّحْلَةُ إِلَى الْفُنْدُقِ تَسْتَغْرِقُ عِشْرِينَ دَقِيقَةً.","ro":"Ar-riḥlatu ilā al-funduqi tastaghriqu ʿishrīna daqīqatan."},{"fr":"Notre chambre donne directement sur le Nil.","tgt":"تُطِلُّ غُرْفَتُنَا مُبَاشَرَةً عَلَى النِّيلِ.","ro":"Tuṭillu ghurfatunā mubāsharatan ʿalā an-Nīli."},{"fr":"Le réceptionniste nous donne les clés et un plan de la ville.","tgt":"يُعْطِينَا مُوَظَّفُ الِاسْتِقْبَالِ الْمَفَاتِيحَ وَخَرِيطَةً لِلْمَدِينَةِ.","ro":"Yuʿṭīnā muwaẓẓafu al-istiqbāli al-mafātīḥa wa-kharīṭatan lil-madīnati."},{"fr":"Le petit-déjeuner est sur la terrasse à partir de sept heures.","tgt":"الْفُطُورُ عَلَى الشُّرْفَةِ مِنَ السَّاعَةِ السَّابِعَةِ.","ro":"Al-fuṭūru ʿalā ash-shurfati mina as-sāʿati as-sābiʿati."},{"fr":"On se repose un peu avant de sortir.","tgt":"نَرْتَاحُ قَلِيلًا قَبْلَ الْخُرُوجِ.","ro":"Nartāḥu qalīlan qabla al-khurūji."},{"fr":"Ce soir, nous dînerons au bord du Nil.","tgt":"سَنَتَعَشَّى اللَّيْلَةَ عَلَى ضِفَّةِ النِّيلِ.","ro":"Sanataʿashshā al-laylata ʿalā ḍiffati an-Nīli."},{"fr":"Louxor est vraiment une ville magnifique.","tgt":"الْأُقْصُرُ مَدِينَةٌ رَائِعَةٌ حَقًّا.","ro":"Al-Uqṣuru madīnatun rāʾiʿatun ḥaqqan."}]},{"title":"Le temple de Karnak","phrases":[{"fr":"Nous visitons le temple de Karnak avec un guide.","tgt":"نَزُورُ مَعْبَدَ الْكَرْنَكِ مَعَ مُرْشِدٍ.","ro":"Nazūru maʿbada al-Karnaki maʿa murshidin."},{"fr":"Notre guide s'appelle Ahmed, il parle bien français.","tgt":"اسْمُ مُرْشِدِنَا أَحْمَدُ، وَهُوَ يَتَكَلَّمُ الْفَرَنْسِيَّةَ جَيِّدًا.","ro":"Ismu murshidinā Aḥmadu, wa-huwa yatakallamu al-faransiyyata jayyidan."},{"fr":"Les colonnes sont immenses et très anciennes.","tgt":"الْأَعْمِدَةُ ضَخْمَةٌ وَقَدِيمَةٌ جِدًّا.","ro":"Al-aʿmidatu ḍakhmatun wa-qadīmatun jiddan."},{"fr":"Ce temple a plus de quatre mille ans.","tgt":"عُمْرُ هَذَا الْمَعْبَدِ أَكْثَرُ مِنْ أَرْبَعَةِ آلَافِ سَنَةٍ.","ro":"ʿUmru hādhā al-maʿbadi aktharu min arbaʿati ālāfi sanatin."},{"fr":"Regarde ces dessins sur les murs !","tgt":"انْظُرْ إِلَى هَذِهِ الرُّسُومِ عَلَى الْجُدْرَانِ!","ro":"Unẓur ilā hādhihi ar-rusūmi ʿalā al-judrāni!"},{"fr":"Les couleurs sont encore visibles par endroits.","tgt":"مَا زَالَتِ الْأَلْوَانُ وَاضِحَةً فِي بَعْضِ الْأَمَاكِنِ.","ro":"Mā zālati al-alwānu wāḍiḥatan fī baʿḍi al-amākini."},{"fr":"Il y a beaucoup de touristes à midi.","tgt":"هُنَاكَ سُيَّاحٌ كَثِيرُونَ عِنْدَ الظُّهْرِ.","ro":"Hunāka suyyāḥun kathīrūna ʿinda aẓ-ẓuhri."},{"fr":"On cherche un peu d'ombre près de l'obélisque.","tgt":"نَبْحَثُ عَنْ قَلِيلٍ مِنَ الظِّلِّ قُرْبَ الْمِسَلَّةِ.","ro":"Nabḥathu ʿan qalīlin mina aẓ-ẓilli qurba al-misallati."},{"fr":"Je prends des photos de chaque statue.","tgt":"أَلْتَقِطُ صُوَرًا لِكُلِّ تِمْثَالٍ.","ro":"Altaqiṭu ṣuwaran li-kulli timthālin."},{"fr":"Le soir, nous reviendrons pour le spectacle son et lumière.","tgt":"فِي الْمَسَاءِ، سَنَعُودُ لِعَرْضِ الصَّوْتِ وَالضَّوْءِ.","ro":"Fī al-masāʾi, sanaʿūdu li-ʿarḍi aṣ-ṣawti wa-aḍ-ḍawʾi."}]},{"title":"En route pour Abou Simbel","phrases":[{"fr":"Il faut se lever à trois heures du matin.","tgt":"يَجِبُ أَنْ نَسْتَيْقِظَ فِي السَّاعَةِ الثَّالِثَةِ صَبَاحًا.","ro":"Yajibu an nastayqiẓa fī as-sāʿati ath-thālithati ṣabāḥan."},{"fr":"Le bus part d'Assouan à quatre heures.","tgt":"تَنْطَلِقُ الْحَافِلَةُ مِنْ أَسْوَانَ فِي السَّاعَةِ الرَّابِعَةِ.","ro":"Tanṭaliqu al-ḥāfilatu min Aswāna fī as-sāʿati ar-rābiʿati."},{"fr":"Il faut prendre de l'eau et un chapeau.","tgt":"يَجِبُ أَنْ نَأْخُذَ مَاءً وَقُبَّعَةً.","ro":"Yajibu an naʾkhudha māʾan wa-qubbaʿatan."},{"fr":"Tu dois garder ton passeport sur toi.","tgt":"يَجِبُ أَنْ تَحْمِلَ جَوَازَ سَفَرِكَ مَعَكَ.","ro":"Yajibu an taḥmila jawāza safarika maʿaka."},{"fr":"La route traverse le désert pendant trois heures.","tgt":"يَمُرُّ الطَّرِيقُ عَبْرَ الصَّحْرَاءِ لِمُدَّةِ ثَلَاثِ سَاعَاتٍ.","ro":"Yamurru aṭ-ṭarīqu ʿabra aṣ-ṣaḥrāʾi li-muddati thalāthi sāʿātin."},{"fr":"Il faut arriver avant la chaleur.","tgt":"يَجِبُ أَنْ نَصِلَ قَبْلَ الْحَرِّ.","ro":"Yajibu an naṣila qabla al-ḥarri."},{"fr":"Le guide dit qu'il faut rester avec le groupe.","tgt":"يَقُولُ الْمُرْشِدُ إِنَّهُ يَجِبُ أَنْ نَبْقَى مَعَ الْمَجْمُوعَةِ.","ro":"Yaqūlu al-murshidu innahu yajibu an nabqā maʿa al-majmūʿati."},{"fr":"Tu ne dois pas oublier ton billet.","tgt":"يَجِبُ أَلَّا تَنْسَى تَذْكِرَتَكَ.","ro":"Yajibu allā tansā tadhkirataka."},{"fr":"Je dois dormir tôt ce soir.","tgt":"يَجِبُ أَنْ أَنَامَ مُبَكِّرًا اللَّيْلَةَ.","ro":"Yajibu an anāma mubakkiran al-laylata."},{"fr":"Nous devons payer l'entrée en livres égyptiennes.","tgt":"يَجِبُ أَنْ نَدْفَعَ ثَمَنَ الدُّخُولِ بِالْجُنَيْهِ الْمِصْرِيِّ.","ro":"Yajibu an nadfaʿa thamana ad-dukhūli bil-junayhi al-miṣriyyi."}],"tip":{"title":"« Yajibu an » : il faut","example":"Il faut se lever à trois heures du matin. — <b>يَجِبُ أَنْ</b> نَسْتَيْقِظَ فِي السَّاعَةِ الثَّالِثَةِ صَبَاحًا.","body":"Pour dire « il faut », l'arabe utilise « yajibu », qui veut dire à peu près « il est nécessaire », suivi de « an » et d'un verbe au subjonctif, comme vous l'avez déjà vu. « Yajibu an nastayqiza » se dit littéralement : il faut que nous nous réveillions. Le verbe change selon la personne qui doit agir : « yajibu an anama », je dois dormir, « yajibu an tahmila », tu dois porter. Pour une interdiction, « an » et « la » se soudent en « alla » : « yajibu alla tansa », tu ne dois pas oublier. Astuce : imaginez « yajibu » comme une porte qui s'ouvre toujours sur « an ».","exampleRo":"Yajibu an nastayqiẓa fī as-sāʿati ath-thālithati ṣabāḥan.","lit":"il-faut · que · nous-nous-réveillions · à · l'heure · la-troisième · au-matin","say":{"yajibu":"يَجِبُ","an":"أَنْ","Yajibu an nastayqiza":"يَجِبُ أَنْ نَسْتَيْقِظَ","yajibu an anama":"يَجِبُ أَنْ أَنَامَ","yajibu an tahmila":"يَجِبُ أَنْ تَحْمِلَ","la":"لَا","alla":"أَلَّا","yajibu alla tansa":"يَجِبُ أَلَّا تَنْسَى","Yajibu an":"يَجِبُ أَنْ"}}},{"title":"La vallée des Rois","phrases":[{"fr":"La vallée des Rois se trouve sur la rive ouest.","tgt":"يَقَعُ وَادِي الْمُلُوكِ عَلَى الضِّفَّةِ الْغَرْبِيَّةِ.","ro":"Yaqaʿu wādī al-mulūki ʿalā aḍ-ḍiffati al-gharbiyyati."},{"fr":"On traverse le Nil en petit bateau.","tgt":"نَعْبُرُ النِّيلَ فِي قَارِبٍ صَغِيرٍ.","ro":"Naʿburu an-Nīla fī qāribin ṣaghīrin."},{"fr":"Le billet permet de voir trois tombeaux.","tgt":"تَسْمَحُ التَّذْكِرَةُ بِزِيَارَةِ ثَلَاثِ مَقَابِرَ.","ro":"Tasmaḥu at-tadhkiratu bi-ziyārati thalāthi maqābira."},{"fr":"La photo est interdite dans certaines tombes.","tgt":"التَّصْوِيرُ مَمْنُوعٌ فِي بَعْضِ الْمَقَابِرِ.","ro":"At-taṣwīru mamnūʿun fī baʿḍi al-maqābiri."},{"fr":"L'air est lourd à l'intérieur.","tgt":"الْهَوَاءُ ثَقِيلٌ فِي الدَّاخِلِ.","ro":"Al-hawāʾu thaqīlun fī ad-dākhili."},{"fr":"Les peintures du plafond sont incroyables.","tgt":"رُسُومُ السَّقْفِ مُدْهِشَةٌ.","ro":"Rusūmu as-saqfi mudhishatun."},{"fr":"J'ai enfin vu le tombeau de Toutânkhamon.","tgt":"أَخِيرًا رَأَيْتُ مَقْبَرَةَ تُوتْ عَنْخْ آمُونَ.","ro":"Akhīran raʾaytu maqbarata Tūt ʿAnkh Āmūna."},{"fr":"En sortant, nous avons bu un thé à l'ombre.","tgt":"عِنْدَ الْخُرُوجِ، شَرِبْنَا شَايًا فِي الظِّلِّ.","ro":"ʿInda al-khurūji, sharibnā shāyan fī aẓ-ẓilli."},{"fr":"Un vendeur m'a proposé un petit scarabée en pierre.","tgt":"عَرَضَ عَلَيَّ بَائِعٌ جُعْرَانًا صَغِيرًا مِنَ الْحَجَرِ.","ro":"ʿAraḍa ʿalayya bāʾiʿun juʿrānan ṣaghīran mina al-ḥajari."},{"fr":"Je ne l'ai pas acheté, c'était trop cher.","tgt":"لَمْ أَشْتَرِهِ، فَقَدْ كَانَ غَالِيًا جِدًّا.","ro":"Lam ashtarihi, fa-qad kāna ghāliyan jiddan."}]},{"title":"Le guide raconte son enfance","phrases":[{"fr":"Ahmed a grandi dans un village près d'Assouan.","tgt":"نَشَأَ أَحْمَدُ فِي قَرْيَةٍ قُرْبَ أَسْوَانَ.","ro":"Nashaʾa Aḥmadu fī qaryatin qurba Aswāna."},{"fr":"Enfant, il nageait dans le Nil chaque été.","tgt":"فِي طُفُولَتِهِ، كَانَ يَسْبَحُ فِي النِّيلِ كُلَّ صَيْفٍ.","ro":"Fī ṭufūlatihi, kāna yasbaḥu fī an-Nīli kulla ṣayfin."},{"fr":"Son père travaillait sur une felouque.","tgt":"كَانَ أَبُوهُ يَعْمَلُ عَلَى فَلُوكَةٍ.","ro":"Kāna abūhu yaʿmalu ʿalā falūkatin."},{"fr":"Il transportait les touristes d'une rive à l'autre.","tgt":"كَانَ يَنْقُلُ السُّيَّاحَ مِنْ ضِفَّةٍ إِلَى أُخْرَى.","ro":"Kāna yanqulu as-suyyāḥa min ḍiffatin ilā ukhrā."},{"fr":"Le soir, la famille mangeait ensemble dans la cour.","tgt":"فِي الْمَسَاءِ، كَانَتِ الْعَائِلَةُ تَأْكُلُ مَعًا فِي الْفِنَاءِ.","ro":"Fī al-masāʾi, kānati al-ʿāʾilatu taʾkulu maʿan fī al-fināʾi."},{"fr":"Sa grand-mère racontait de vieilles histoires.","tgt":"كَانَتْ جَدَّتُهُ تَحْكِي قِصَصًا قَدِيمَةً.","ro":"Kānat jaddatuhu taḥkī qiṣaṣan qadīmatan."},{"fr":"Il apprenait le français à l'école.","tgt":"كَانَ يَتَعَلَّمُ الْفَرَنْسِيَّةَ فِي الْمَدْرَسَةِ.","ro":"Kāna yataʿallamu al-faransiyyata fī al-madrasati."},{"fr":"Il parlait avec les touristes pour s'entraîner.","tgt":"كَانَ يَتَحَدَّثُ مَعَ السُّيَّاحِ لِيَتَدَرَّبَ.","ro":"Kāna yataḥaddathu maʿa as-suyyāḥi li-yatadarraba."},{"fr":"Moi, je passais mes vacances à la montagne.","tgt":"وَأَنَا كُنْتُ أَقْضِي عُطْلَتِي فِي الْجِبَالِ.","ro":"Wa-anā kuntu aqḍī ʿuṭlatī fī al-jibāli."},{"fr":"Aujourd'hui encore, il aime beaucoup le fleuve.","tgt":"مَا زَالَ يُحِبُّ النَّهْرَ كَثِيرًا حَتَّى الْيَوْمَ.","ro":"Mā zāla yuḥibbu an-nahra kathīran ḥattā al-yawma."}],"tip":{"title":"« Kana » suivi du présent : l'habitude au passé","example":"Son père travaillait sur une felouque. — <b>كَانَ</b> أَبُوهُ <b>يَعْمَلُ</b> عَلَى فَلُوكَةٍ.","body":"L'arabe n'a pas d'imparfait comme le français. Pour dire qu'une chose se répétait dans le passé, on place « kana », était, devant un verbe au présent. « Kana abuhu yamalu » se dit littéralement : était son père, il travaille, autrement dit son père travaillait. « Kana » s'accorde avec le sujet : « kuntu aqdi », je passais, « kanat tahki », elle racontait, « kunna nadhhabu », nous allions. Astuce : « kana » pose le décor dans le passé, et le verbe au présent montre l'action qui se répète, comme un film qu'on rembobine.","exampleRo":"Kāna abūhu yaʿmalu ʿalā falūkatin.","lit":"était · son-père · travaille · sur · une-felouque","say":{"kana":"كَانَ","Kana abuhu yamalu":"كَانَ أَبُوهُ يَعْمَلُ","Kana":"كَانَ","kuntu aqdi":"كُنْتُ أَقْضِي","kanat tahki":"كَانَتْ تَحْكِي","kunna nadhhabu":"كُنَّا نَذْهَبُ"}}},{"title":"Une felouque sur le Nil","phrases":[{"fr":"Nous louons une felouque cet après-midi.","tgt":"نَسْتَأْجِرُ فَلُوكَةً بَعْدَ الظُّهْرِ.","ro":"Nastaʾjiru falūkatan baʿda aẓ-ẓuhri."},{"fr":"Le capitaine demande deux cents livres.","tgt":"يَطْلُبُ الرُّبَّانُ مِئَتَيْ جُنَيْهٍ.","ro":"Yaṭlubu ar-rubbānu miʾatay junayhin."},{"fr":"On négocie un peu, puis on accepte.","tgt":"نُفَاوِضُ قَلِيلًا ثُمَّ نَقْبَلُ.","ro":"Nufāwiḍu qalīlan thumma naqbalu."},{"fr":"Il n'y a pas de moteur, seulement le vent.","tgt":"لَا يُوجَدُ مُحَرِّكٌ، بَلِ الرِّيحُ فَقَطْ.","ro":"Lā yūjadu muḥarrikun, bali ar-rīḥu faqaṭ."},{"fr":"La voile blanche se gonfle doucement.","tgt":"يَنْتَفِخُ الشِّرَاعُ الْأَبْيَضُ بِهُدُوءٍ.","ro":"Yantafikhu ash-shirāʿu al-abyaḍu bi-hudūʾin."},{"fr":"Nous passons devant de petites îles vertes.","tgt":"نَمُرُّ أَمَامَ جُزُرٍ صَغِيرَةٍ خَضْرَاءَ.","ro":"Namurru amāma juzurin ṣaghīratin khaḍrāʾa."},{"fr":"Des enfants nous saluent depuis la rive.","tgt":"يُحَيِّينَا أَطْفَالٌ مِنَ الضِّفَّةِ.","ro":"Yuḥayyīnā aṭfālun mina aḍ-ḍiffati."},{"fr":"Le capitaine chante une chanson nubienne.","tgt":"يُغَنِّي الرُّبَّانُ أُغْنِيَةً نُوبِيَّةً.","ro":"Yughannī ar-rubbānu ughniyatan nūbiyyatan."},{"fr":"Le soleil se couche derrière les dunes.","tgt":"تَغْرُبُ الشَّمْسُ خَلْفَ الْكُثْبَانِ.","ro":"Taghrubu ash-shamsu khalfa al-kuthbāni."},{"fr":"Je n'oublierai jamais ce moment.","tgt":"لَنْ أَنْسَى هَذِهِ اللَّحْظَةَ أَبَدًا.","ro":"Lan ansā hādhihi al-laḥẓata abadan."}]},{"title":"Un village nubien","phrases":[{"fr":"Le bateau nous dépose dans un village nubien.","tgt":"يُنْزِلُنَا الْقَارِبُ فِي قَرْيَةٍ نُوبِيَّةٍ.","ro":"Yunzilunā al-qāribu fī qaryatin nūbiyyatin."},{"fr":"Les maisons sont peintes en bleu et en jaune.","tgt":"الْبُيُوتُ مُلَوَّنَةٌ بِالْأَزْرَقِ وَالْأَصْفَرِ.","ro":"Al-buyūtu mulawwanatun bil-azraqi wa-al-aṣfari."},{"fr":"Une famille nous invite à boire le thé.","tgt":"تَدْعُونَا عَائِلَةٌ إِلَى شُرْبِ الشَّايِ.","ro":"Tadʿūnā ʿāʾilatun ilā shurbi ash-shāyi."},{"fr":"Ils élèvent un petit crocodile chez eux !","tgt":"يُرَبُّونَ تِمْسَاحًا صَغِيرًا فِي الْبَيْتِ!","ro":"Yurabbūna timsāḥan ṣaghīran fī al-bayti!"},{"fr":"N'aie pas peur, il est très calme.","tgt":"لَا تَخَفْ، إِنَّهُ هَادِئٌ جِدًّا.","ro":"Lā takhaf, innahu hādiʾun jiddan."},{"fr":"Les femmes vendent des colliers et des tissus.","tgt":"تَبِيعُ النِّسَاءُ قَلَائِدَ وَأَقْمِشَةً.","ro":"Tabīʿu an-nisāʾu qalāʾida wa-aqmishatan."},{"fr":"J'achète un foulard pour ma sœur.","tgt":"أَشْتَرِي وِشَاحًا لِأُخْتِي.","ro":"Ashtarī wishāḥan li-ukhtī."},{"fr":"La langue nubienne est différente de l'arabe.","tgt":"اللُّغَةُ النُّوبِيَّةُ مُخْتَلِفَةٌ عَنِ الْعَرَبِيَّةِ.","ro":"Al-lughatu an-nūbiyyatu mukhtalifatun ʿani al-ʿarabiyyati."},{"fr":"Notre hôte nous apprend quelques mots.","tgt":"يُعَلِّمُنَا مُضِيفُنَا بَعْضَ الْكَلِمَاتِ.","ro":"Yuʿallimunā muḍīfunā baʿḍa al-kalimāti."},{"fr":"Nous rentrons avant la tombée de la nuit.","tgt":"نَعُودُ قَبْلَ حُلُولِ اللَّيْلِ.","ro":"Naʿūdu qabla ḥulūli al-layli."}]},{"title":"Les temples d'Abou Simbel","phrases":[{"fr":"Voici le temple que le roi Ramsès a construit.","tgt":"هَذَا هُوَ الْمَعْبَدُ الَّذِي بَنَاهُ الْمَلِكُ رَمْسِيسُ.","ro":"Hādhā huwa al-maʿbadu alladhī banāhu al-maliku Ramsīsu."},{"fr":"Les statues qui gardent l'entrée mesurent vingt mètres.","tgt":"التَّمَاثِيلُ الَّتِي تَحْرُسُ الْمَدْخَلَ طُولُهَا عِشْرُونَ مِتْرًا.","ro":"At-tamāthīlu allatī taḥrusu al-madkhala ṭūluhā ʿishrūna mitran."},{"fr":"Le petit temple est celui qu'il a offert à la reine Néfertari.","tgt":"الْمَعْبَدُ الصَّغِيرُ هُوَ الَّذِي أَهْدَاهُ إِلَى الْمَلِكَةِ نِفِرْتَارِي.","ro":"Al-maʿbadu aṣ-ṣaghīru huwa alladhī ahdāhu ilā al-malikati Nifirtārī."},{"fr":"La femme qui vend les billets parle français.","tgt":"الْمَرْأَةُ الَّتِي تَبِيعُ التَّذَاكِرَ تَتَكَلَّمُ الْفَرَنْسِيَّةَ.","ro":"Al-marʾatu allatī tabīʿu at-tadhākira tatakallamu al-faransiyyata."},{"fr":"Le guide qui nous accompagne connaît tous les détails.","tgt":"الْمُرْشِدُ الَّذِي يُرَافِقُنَا يَعْرِفُ كُلَّ التَّفَاصِيلِ.","ro":"Al-murshidu alladhī yurāfiqunā yaʿrifu kulla at-tafāṣīli."},{"fr":"Des ingénieurs ont déplacé le temple, qui était menacé par les eaux.","tgt":"نَقَلَ الْمُهَنْدِسُونَ الْمَعْبَدَ الَّذِي كَانَ مُهَدَّدًا بِالْمِيَاهِ.","ro":"Naqala al-muhandisūna al-maʿbada alladhī kāna muhaddadan bil-miyāhi."},{"fr":"Le lac que tu vois derrière nous, c'est le lac Nasser.","tgt":"الْبُحَيْرَةُ الَّتِي تَرَاهَا خَلْفَنَا هِيَ بُحَيْرَةُ نَاصِرٍ.","ro":"Al-buḥayratu allatī tarāhā khalfanā hiya buḥayratu Nāṣirin."},{"fr":"La lumière qui entre dans le temple est magique.","tgt":"الضَّوْءُ الَّذِي يَدْخُلُ الْمَعْبَدَ سَاحِرٌ.","ro":"Aḍ-ḍawʾu alladhī yadkhulu al-maʿbada sāḥirun."},{"fr":"C'est la photo que je préfère.","tgt":"هَذِهِ هِيَ الصُّورَةُ الَّتِي أُفَضِّلُهَا.","ro":"Hādhihi hiya aṣ-ṣūratu allatī ufaḍḍiluhā."},{"fr":"Le bus qui nous ramène part à midi.","tgt":"الْحَافِلَةُ الَّتِي تُعِيدُنَا تَنْطَلِقُ ظُهْرًا.","ro":"Al-ḥāfilatu allatī tuʿīdunā tanṭaliqu ẓuhran."}],"tip":{"title":"Les relatifs : « alladhi » et « allati »","example":"La femme qui vend les billets parle français. — الْمَرْأَةُ <b>الَّتِي</b> تَبِيعُ التَّذَاكِرَ تَتَكَلَّمُ الْفَرَنْسِيَّةَ.","body":"Pour dire « qui » ou « que », l'arabe utilise « alladhi » après un nom masculin et « allati » après un nom féminin. Le relatif s'accorde donc avec le nom qu'il complète : « al-murshidu alladhi », le guide qui, mais « al-maratu allati », la femme qui. Attention, un pluriel de choses compte comme un féminin : « at-tamathilu allati », les statues qui. Quand le relatif veut dire « que », l'arabe rappelle le nom par un petit pronom collé au verbe : « as-suratu allati ufaddiluha » se dit littéralement : la photo que je la préfère. Astuce : ces mots ne s'emploient qu'après un nom défini, celui qui porte « al ».","exampleRo":"Al-marʾatu allatī tabīʿu at-tadhākira tatakallamu al-faransiyyata.","lit":"la-femme · qui · vend · les-billets · parle · le-français","say":{"alladhi":"الَّذِي","allati":"الَّتِي","al-murshidu alladhi":"الْمُرْشِدُ الَّذِي","al-maratu allati":"الْمَرْأَةُ الَّتِي","at-tamathilu allati":"التَّمَاثِيلُ الَّتِي","as-suratu allati ufaddiluha":"الصُّورَةُ الَّتِي أُفَضِّلُهَا"}}},{"title":"Arrivée à Amman","phrases":[{"fr":"Nous prenons l'avion du Caire à Amman.","tgt":"نُسَافِرُ بِالطَّائِرَةِ مِنَ الْقَاهِرَةِ إِلَى عَمَّانَ.","ro":"Nusāfiru biṭ-ṭāʾirati mina al-Qāhirati ilā ʿAmmāna."},{"fr":"Le vol ne dure qu'une heure et demie.","tgt":"تَسْتَغْرِقُ الرِّحْلَةُ سَاعَةً وَنِصْفًا فَقَطْ.","ro":"Tastaghriqu ar-riḥlatu sāʿatan wa-niṣfan faqaṭ."},{"fr":"À l'aéroport, j'achète un visa au guichet.","tgt":"فِي الْمَطَارِ، أَشْتَرِي تَأْشِيرَةً مِنَ الشُّبَّاكِ.","ro":"Fī al-maṭāri, ashtarī taʾshīratan mina ash-shubbāki."},{"fr":"L'employé me demande : combien de jours vas-tu rester ?","tgt":"يَسْأَلُنِي الْمُوَظَّفُ: كَمْ يَوْمًا سَتَبْقَى؟","ro":"Yasʾalunī al-muwaẓẓafu: kam yawman satabqā?"},{"fr":"Je réponds : deux semaines en tout.","tgt":"أُجِيبُ: أُسْبُوعَيْنِ فِي الْمَجْمُوعِ.","ro":"Ujību: usbūʿayni fī al-majmūʿi."},{"fr":"Amman est construite sur plusieurs collines.","tgt":"عَمَّانُ مَبْنِيَّةٌ عَلَى عِدَّةِ تِلَالٍ.","ro":"ʿAmmānu mabniyyatun ʿalā ʿiddati tilālin."},{"fr":"Nous changeons nos euros en dinars jordaniens.","tgt":"نُصَرِّفُ الْيُورُو إِلَى دَنَانِيرَ أُرْدُنِيَّةٍ.","ro":"Nuṣarrifu al-yūrū ilā danānīra urduniyyatin."},{"fr":"Un taxi jaune nous emmène à l'hôtel.","tgt":"تَأْخُذُنَا سَيَّارَةُ أُجْرَةٍ صَفْرَاءُ إِلَى الْفُنْدُقِ.","ro":"Taʾkhudhunā sayyāratu ujratin ṣafrāʾu ilā al-funduqi."},{"fr":"Le chauffeur nous conseille un restaurant de falafels.","tgt":"يَنْصَحُنَا السَّائِقُ بِمَطْعَمٍ لِلْفَلَافِلِ.","ro":"Yanṣaḥunā as-sāʾiqu bi-maṭʿamin lil-falāfili."},{"fr":"Demain, nous partons vers le sud du pays.","tgt":"غَدًا نَنْطَلِقُ نَحْوَ جَنُوبِ الْبِلَادِ.","ro":"Ghadan nanṭaliqu naḥwa janūbi al-bilādi."}]},{"title":"Le bus de nuit vers Pétra","phrases":[{"fr":"Nous prenons le bus de nuit pour Pétra.","tgt":"نَرْكَبُ حَافِلَةَ اللَّيْلِ إِلَى الْبَتْرَاءِ.","ro":"Narkabu ḥāfilata al-layli ilā al-Batrāʾi."},{"fr":"Le départ est à onze heures du soir.","tgt":"الِانْطِلَاقُ فِي السَّاعَةِ الْحَادِيَةَ عَشْرَةَ لَيْلًا.","ro":"Al-inṭilāqu fī as-sāʿati al-ḥādiyata ʿashrata laylan."},{"fr":"J'ai réservé deux places près de la fenêtre.","tgt":"حَجَزْتُ مَقْعَدَيْنِ قُرْبَ النَّافِذَةِ.","ro":"Ḥajaztu maqʿadayni qurba an-nāfidhati."},{"fr":"Mets ton sac sous le siège.","tgt":"ضَعْ حَقِيبَتَكَ تَحْتَ الْمَقْعَدِ.","ro":"Ḍaʿ ḥaqībataka taḥta al-maqʿadi."},{"fr":"La climatisation est trop forte, j'ai froid.","tgt":"التَّكْيِيفُ قَوِيٌّ جِدًّا، أَشْعُرُ بِالْبَرْدِ.","ro":"At-takyīfu qawiyyun jiddan, ashʿuru bil-bardi."},{"fr":"Heureusement, j'ai pris une couverture.","tgt":"لِحُسْنِ الْحَظِّ، أَخَذْتُ بَطَّانِيَّةً.","ro":"Li-ḥusni al-ḥaẓẓi, akhadhtu baṭṭāniyyatan."},{"fr":"Le bus s'arrête une seule fois pour une pause.","tgt":"تَتَوَقَّفُ الْحَافِلَةُ مَرَّةً وَاحِدَةً لِلِاسْتِرَاحَةِ.","ro":"Tatawaqqafu al-ḥāfilatu marratan wāḥidatan lil-istirāḥati."},{"fr":"Je n'ai pas réussi à dormir.","tgt":"لَمْ أَسْتَطِعْ أَنْ أَنَامَ.","ro":"Lam astaṭiʿ an anāma."},{"fr":"Par la fenêtre, on voit des milliers d'étoiles.","tgt":"مِنَ النَّافِذَةِ نَرَى آلَافَ النُّجُومِ.","ro":"Mina an-nāfidhati narā ālāfa an-nujūmi."},{"fr":"Nous arrivons à Wadi Moussa à l'aube.","tgt":"نَصِلُ إِلَى وَادِي مُوسَى عِنْدَ الْفَجْرِ.","ro":"Naṣilu ilā Wādī Mūsā ʿinda al-fajri."}]},{"title":"Pétra : le Siq et le Trésor","phrases":[{"fr":"On entre dans Pétra par un long canyon, le Siq.","tgt":"نَدْخُلُ الْبَتْرَاءَ عَبْرَ مَمَرٍّ طَوِيلٍ اسْمُهُ السِّيقُ.","ro":"Nadkhulu al-Batrāʾa ʿabra mamarrin ṭawīlin ismuhu as-Sīqu."},{"fr":"Les parois de roche sont roses et très hautes.","tgt":"جُدْرَانُ الصَّخْرِ وَرْدِيَّةٌ وَعَالِيَةٌ جِدًّا.","ro":"Judrānu aṣ-ṣakhri wardiyyatun wa-ʿāliyatun jiddan."},{"fr":"On marche presque deux kilomètres.","tgt":"نَمْشِي حَوَالَيْ كِيلُومِتْرَيْنِ.","ro":"Namshī ḥawālay kīlūmitrayni."},{"fr":"Soudain, le Trésor apparaît devant nous.","tgt":"فَجْأَةً تَظْهَرُ الْخَزْنَةُ أَمَامَنَا.","ro":"Fajʾatan taẓharu al-Khaznatu amāmanā."},{"fr":"Sa façade est sculptée dans la roche.","tgt":"وَاجِهَتُهَا مَنْحُوتَةٌ فِي الصَّخْرِ.","ro":"Wājihatuhā manḥūtatun fī aṣ-ṣakhri."},{"fr":"Les Nabatéens ont fondé cette ville il y a très longtemps.","tgt":"أَسَّسَ الْأَنْبَاطُ هَذِهِ الْمَدِينَةَ مُنْذُ زَمَنٍ بَعِيدٍ.","ro":"Assasa al-Anbāṭu hādhihi al-madīnata mundhu zamanin baʿīdin."},{"fr":"Un Bédouin propose une balade à dos d'âne.","tgt":"يَعْرِضُ بَدَوِيٌّ جَوْلَةً عَلَى ظَهْرِ حِمَارٍ.","ro":"Yaʿriḍu badawiyyun jawlatan ʿalā ẓahri ḥimārin."},{"fr":"Non merci, nous préférons marcher.","tgt":"لَا، شُكْرًا، نُفَضِّلُ الْمَشْيَ.","ro":"Lā, shukran, nufaḍḍilu al-mashya."},{"fr":"Le site est immense, il faut au moins deux jours.","tgt":"الْمَوْقِعُ وَاسِعٌ جِدًّا، يَلْزَمُ يَوْمَانِ عَلَى الْأَقَلِّ.","ro":"Al-mawqiʿu wāsiʿun jiddan, yalzamu yawmāni ʿalā al-aqalli."},{"fr":"Nous achetons un billet pour deux jours.","tgt":"نَشْتَرِي تَذْكِرَةً لِيَوْمَيْنِ.","ro":"Nashtarī tadhkiratan li-yawmayni."}]},{"title":"Le Monastère, au sommet de Pétra","phrases":[{"fr":"Aujourd'hui, nous montons au Monastère.","tgt":"الْيَوْمَ نَصْعَدُ إِلَى الدَّيْرِ.","ro":"Al-yawma naṣʿadu ilā ad-Dayri."},{"fr":"C'est la plus longue marche de notre voyage.","tgt":"هَذِهِ أَطْوَلُ مَسِيرَةٍ فِي رِحْلَتِنَا.","ro":"Hādhihi aṭwalu masīratin fī riḥlatinā."},{"fr":"Il y a plus de huit cents marches.","tgt":"هُنَاكَ أَكْثَرُ مِنْ ثَمَانِمِئَةِ دَرَجَةٍ.","ro":"Hunāka aktharu min thamānimiʾati darajatin."},{"fr":"C'est la partie la plus difficile.","tgt":"هَذَا هُوَ الْجُزْءُ الْأَصْعَبُ.","ro":"Hādhā huwa al-juzʾu al-aṣʿabu."},{"fr":"Le Monastère est plus grand que le Trésor.","tgt":"الدَّيْرُ أَكْبَرُ مِنَ الْخَزْنَةِ.","ro":"Ad-Dayru akbaru mina al-Khaznati."},{"fr":"C'est le plus grand monument de Pétra.","tgt":"هُوَ أَكْبَرُ مَعْلَمٍ فِي الْبَتْرَاءِ.","ro":"Huwa akbaru maʿlamin fī al-Batrāʾi."},{"fr":"C'est la plus belle vue de toute la région.","tgt":"هَذَا أَجْمَلُ مَنْظَرٍ فِي الْمِنْطَقَةِ كُلِّهَا.","ro":"Hādhā ajmalu manẓarin fī al-minṭaqati kullihā."},{"fr":"Le meilleur moment, c'est la fin de la journée.","tgt":"أَفْضَلُ وَقْتٍ هُوَ آخِرُ النَّهَارِ.","ro":"Afḍalu waqtin huwa ākhiru an-nahāri."},{"fr":"Le thé de ce petit café est le plus sucré du monde !","tgt":"شَايُ هَذَا الْمَقْهَى الصَّغِيرِ أَحْلَى شَايٍ فِي الْعَالَمِ!","ro":"Shāyu hādhā al-maqhā aṣ-ṣaghīri aḥlā shāyin fī al-ʿālami!"},{"fr":"Pétra est le plus bel endroit que j'aie jamais vu.","tgt":"الْبَتْرَاءُ أَجْمَلُ مَكَانٍ رَأَيْتُهُ فِي حَيَاتِي.","ro":"Al-Batrāʾu ajmalu makānin raʾaytuhu fī ḥayātī."}],"tip":{"title":"Le superlatif : « akbar, ajmal »","example":"Pétra est le plus bel endroit que j'aie jamais vu. — الْبَتْرَاءُ <b>أَجْمَلُ</b> مَكَانٍ رَأَيْتُهُ فِي حَيَاتِي.","body":"En arabe, beaucoup d'adjectifs ont une forme spéciale qui commence par « a » : « kabir », grand, donne « akbar », « jamil », beau, donne « ajmal », « tawil », long, donne « atwal ». Suivie de « min », cette forme veut dire plus que : « ad-dayru akbaru mina al-khazna », le Monastère est plus grand que le Trésor. Placée juste devant un nom sans article, elle devient un superlatif : « ajmalu makanin » se dit littéralement : le plus beau d'endroit, c'est-à-dire le plus bel endroit. On peut aussi la mettre après un nom défini, avec l'article : « al-funduqu al-akbaru », le plus grand hôtel. Astuce : retenez le moule « a, consonne, consonne, a, consonne », que l'on retrouve dans « akbar, ajmal » et « aqrab ».","exampleRo":"Al-Batrāʾu ajmalu makānin raʾaytuhu fī ḥayātī.","lit":"Pétra · le-plus-beau · endroit · je-l'ai-vu · dans · ma-vie","say":{"kabir":"كَبِير","akbar":"أَكْبَر","jamil":"جَمِيل","ajmal":"أَجْمَل","tawil":"طَوِيل","atwal":"أَطْوَل","min":"مِنْ","ad-dayru akbaru mina al-khazna":"الدَّيْرُ أَكْبَرُ مِنَ الْخَزْنَة","ajmalu makanin":"أَجْمَلُ مَكَانٍ","al-funduqu al-akbaru":"الْفُنْدُقُ الْأَكْبَرُ","akbar, ajmal":"أَكْبَر، أَجْمَل","aqrab":"أَقْرَب"}}},{"title":"Une nuit dans le Wadi Rum","phrases":[{"fr":"Le Wadi Rum ressemble à la planète Mars.","tgt":"يُشْبِهُ وَادِي رَمّ كَوْكَبَ الْمِرِّيخِ.","ro":"Yushbihu Wādī Ramm kawkaba al-Mirrīkhi."},{"fr":"Un Bédouin nous conduit en jeep dans le désert.","tgt":"يَقُودُنَا بَدَوِيٌّ بِسَيَّارَةِ جِيبٍ فِي الصَّحْرَاءِ.","ro":"Yaqūdunā badawiyyun bi-sayyārati jībin fī aṣ-ṣaḥrāʾi."},{"fr":"Le sable est rouge, presque orange.","tgt":"الرَّمْلُ أَحْمَرُ، بَلْ بُرْتُقَالِيٌّ تَقْرِيبًا.","ro":"Ar-ramlu aḥmaru, bal burtuqāliyyun taqrīban."},{"fr":"Nous grimpons sur une grande dune.","tgt":"نَتَسَلَّقُ كَثِيبًا كَبِيرًا.","ro":"Natasallaqu kathīban kabīran."},{"fr":"Ce soir, nous dormons dans un camp bédouin.","tgt":"نَنَامُ اللَّيْلَةَ فِي مُخَيَّمٍ بَدَوِيٍّ.","ro":"Nanāmu al-laylata fī mukhayyamin badawiyyin."},{"fr":"Le dîner cuit sous le sable.","tgt":"يَنْضَجُ الْعَشَاءُ تَحْتَ الرَّمْلِ.","ro":"Yanḍaju al-ʿashāʾu taḥta ar-ramli."},{"fr":"Nos hôtes servent du thé à la sauge.","tgt":"يُقَدِّمُ مُضِيفُونَا شَايًا بِالْمَرْيَمِيَّةِ.","ro":"Yuqaddimu muḍīfūnā shāyan bil-maryamiyyati."},{"fr":"Les nuits sont froides dans le désert.","tgt":"اللَّيَالِي بَارِدَةٌ فِي الصَّحْرَاءِ.","ro":"Al-layālī bāridatun fī aṣ-ṣaḥrāʾi."},{"fr":"Autour du feu, quelqu'un joue du oud.","tgt":"حَوْلَ النَّارِ، يَعْزِفُ أَحَدُهُمْ عَلَى الْعُودِ.","ro":"Ḥawla an-nāri, yaʿzifu aḥaduhum ʿalā al-ʿūdi."},{"fr":"Je n'ai jamais vu un ciel aussi pur.","tgt":"لَمْ أَرَ سَمَاءً صَافِيَةً هَكَذَا مِنْ قَبْلُ.","ro":"Lam ara samāʾan ṣāfiyatan hākadhā min qablu."}]},{"title":"Randonnée dans le désert","phrases":[{"fr":"Nous partons marcher tôt le matin.","tgt":"نَنْطَلِقُ فِي رِحْلَةِ مَشْيٍ فِي الصَّبَاحِ الْبَاكِرِ.","ro":"Nanṭaliqu fī riḥlati mashyin fī aṣ-ṣabāḥi al-bākiri."},{"fr":"Notre guide connaît tous les sentiers.","tgt":"يَعْرِفُ مُرْشِدُنَا كُلَّ الْمَسَالِكِ.","ro":"Yaʿrifu murshidunā kulla al-masāliki."},{"fr":"Prends assez d'eau, au moins trois litres.","tgt":"خُذْ مَاءً كَافِيًا، ثَلَاثَةَ لِتْرَاتٍ عَلَى الْأَقَلِّ.","ro":"Khudh māʾan kāfiyan, thalāthata litrātin ʿalā al-aqalli."},{"fr":"Le chemin monte entre les rochers.","tgt":"يَصْعَدُ الطَّرِيقُ بَيْنَ الصُّخُورِ.","ro":"Yaṣʿadu aṭ-ṭarīqu bayna aṣ-ṣukhūri."},{"fr":"Nous traversons un pont de pierre naturel.","tgt":"نَعْبُرُ جِسْرًا صَخْرِيًّا طَبِيعِيًّا.","ro":"Naʿburu jisran ṣakhriyyan ṭabīʿiyyan."},{"fr":"Attention, la pente est glissante ici.","tgt":"انْتَبِهْ، الْمُنْحَدَرُ زَلِقٌ هُنَا.","ro":"Intabih, al-munḥadaru zaliqun hunā."},{"fr":"On fait une pause à l'ombre d'un rocher.","tgt":"نَسْتَرِيحُ فِي ظِلِّ صَخْرَةٍ.","ro":"Nastarīḥu fī ẓilli ṣakhratin."},{"fr":"Le guide nous montre des inscriptions anciennes.","tgt":"يُرِينَا الْمُرْشِدُ نُقُوشًا قَدِيمَةً.","ro":"Yurīnā al-murshidu nuqūshan qadīmatan."},{"fr":"Mes jambes sont fatiguées, mais je suis heureux.","tgt":"سَاقَايَ مُتْعَبَتَانِ، لَكِنِّي سَعِيدٌ.","ro":"Sāqāya mutʿabatāni, lākinnī saʿīdun."},{"fr":"Nous rentrons au camp au coucher du soleil.","tgt":"نَعُودُ إِلَى الْمُخَيَّمِ عِنْدَ الْغُرُوبِ.","ro":"Naʿūdu ilā al-mukhayyami ʿinda al-ghurūbi."}]},{"title":"Flotter sur la mer Morte","phrases":[{"fr":"La mer Morte est le point le plus bas de la Terre.","tgt":"الْبَحْرُ الْمَيِّتُ أَخْفَضُ نُقْطَةٍ عَلَى الْأَرْضِ.","ro":"Al-Baḥru al-Mayyitu akhfaḍu nuqṭatin ʿalā al-arḍi."},{"fr":"L'eau est très salée, alors on flotte sans effort.","tgt":"الْمَاءُ مَالِحٌ جِدًّا، فَنَطْفُو دُونَ جُهْدٍ.","ro":"Al-māʾu māliḥun jiddan, fa-naṭfū dūna juhdin."},{"fr":"Ne mets pas la tête sous l'eau !","tgt":"لَا تَضَعْ رَأْسَكَ تَحْتَ الْمَاءِ!","ro":"Lā taḍaʿ raʾsaka taḥta al-māʾi!"},{"fr":"Le sel fait mal aux yeux.","tgt":"الْمِلْحُ يُؤْلِمُ الْعُيُونَ.","ro":"Al-milḥu yuʾlimu al-ʿuyūna."},{"fr":"Les gens se couvrent le corps de boue noire.","tgt":"يُغَطِّي النَّاسُ أَجْسَامَهُمْ بِالطِّينِ الْأَسْوَدِ.","ro":"Yughaṭṭī an-nāsu ajsāmahum biṭ-ṭīni al-aswadi."},{"fr":"On dit que c'est bon pour la peau.","tgt":"يُقَالُ إِنَّهُ مُفِيدٌ لِلْبَشَرَةِ.","ro":"Yuqālu innahu mufīdun lil-basharati."},{"fr":"Il fait trente-cinq degrés à l'ombre.","tgt":"دَرَجَةُ الْحَرَارَةِ خَمْسٌ وَثَلَاثُونَ فِي الظِّلِّ.","ro":"Darajatu al-ḥarārati khamsun wa-thalāthūna fī aẓ-ẓilli."},{"fr":"Après la baignade, on prend une douche d'eau douce.","tgt":"بَعْدَ السِّبَاحَةِ، نَسْتَحِمُّ بِمَاءٍ عَذْبٍ.","ro":"Baʿda as-sibāḥati, nastaḥimmu bi-māʾin ʿadhbin."},{"fr":"J'ai acheté du savon au sel de la mer Morte.","tgt":"اشْتَرَيْتُ صَابُونًا بِمِلْحِ الْبَحْرِ الْمَيِّتِ.","ro":"Ishtaraytu ṣābūnan bi-milḥi al-Baḥri al-Mayyiti."},{"fr":"Le niveau de la mer baisse chaque année.","tgt":"يَنْخَفِضُ مُسْتَوَى الْبَحْرِ كُلَّ عَامٍ.","ro":"Yankhafiḍu mustawā al-baḥri kulla ʿāmin."}]},{"title":"Plongée à Aqaba","phrases":[{"fr":"Nous arrivons à Aqaba, au bord de la mer Rouge.","tgt":"نَصِلُ إِلَى الْعَقَبَةِ عَلَى شَاطِئِ الْبَحْرِ الْأَحْمَرِ.","ro":"Naṣilu ilā al-ʿAqabati ʿalā shāṭiʾi al-Baḥri al-Aḥmari."},{"fr":"Si tu aimes la mer, tu vas adorer cette ville.","tgt":"إِذَا كُنْتَ تُحِبُّ الْبَحْرَ، فَسَتُحِبُّ هَذِهِ الْمَدِينَةَ كَثِيرًا.","ro":"Idhā kunta tuḥibbu al-baḥra, fa-satuḥibbu hādhihi al-madīnata kathīran."},{"fr":"Si le temps est beau demain, nous ferons de la plongée.","tgt":"إِذَا كَانَ الْجَوُّ جَمِيلًا غَدًا، فَسَنَغُوصُ.","ro":"Idhā kāna al-jawwu jamīlan ghadan, fa-sanaghūṣu."},{"fr":"Quand on plonge, on voit des poissons de toutes les couleurs.","tgt":"إِذَا غُصْنَا، نَرَى أَسْمَاكًا بِكُلِّ الْأَلْوَانِ.","ro":"Idhā ghuṣnā, narā asmākan bi-kulli al-alwāni."},{"fr":"Si tu as peur, reste près du moniteur.","tgt":"إِذَا خِفْتَ، فَابْقَ قُرْبَ الْمُدَرِّبِ.","ro":"Idhā khifta, fa-ibqa qurba al-mudarribi."},{"fr":"Si tu ne sais pas nager, prends un gilet de sauvetage.","tgt":"إِذَا كُنْتَ لَا تَعْرِفُ السِّبَاحَةَ، فَخُذْ سُتْرَةَ نَجَاةٍ.","ro":"Idhā kunta lā taʿrifu as-sibāḥata, fa-khudh sutrata najātin."},{"fr":"Ne touche pas le corail, il est fragile.","tgt":"لَا تَلْمِسِ الْمَرْجَانَ، فَهُوَ هَشٌّ.","ro":"Lā talmisi al-marjāna, fa-huwa hashshun."},{"fr":"Quand il fait trop chaud, nous restons à l'ombre.","tgt":"إِذَا اشْتَدَّ الْحَرُّ، نَبْقَى فِي الظِّلِّ.","ro":"Idhā ishtadda al-ḥarru, nabqā fī aẓ-ẓilli."},{"fr":"Si nous avons le temps, nous prendrons un bateau à fond de verre.","tgt":"إِذَا كَانَ لَدَيْنَا وَقْتٌ، فَسَنَرْكَبُ قَارِبًا ذَا قَاعٍ زُجَاجِيٍّ.","ro":"Idhā kāna ladaynā waqtun, fa-sanarkabu qāriban dhā qāʿin zujājiyyin."},{"fr":"Le soir, on mange du poisson grillé sur le port.","tgt":"فِي الْمَسَاءِ، نَأْكُلُ سَمَكًا مَشْوِيًّا فِي الْمِينَاءِ.","ro":"Fī al-masāʾi, naʾkulu samakan mashwiyyan fī al-mīnāʾi."}],"tip":{"title":"« Idha » : si, quand","example":"Si le temps est beau demain, nous ferons de la plongée. — <b>إِذَا</b> كَانَ الْجَوُّ جَمِيلًا غَدًا، فَسَنَغُوصُ.","body":"Le mot « idha » veut dire à la fois si et quand : il présente une situation que l'on attend ou qui arrive souvent. Particularité étonnante, après « idha » le verbe se met en général au passé, même quand on parle de l'avenir. « Idha ghusna » se dit littéralement : si nous avons plongé, et signifie quand on plonge. Quand la suite commence par un futur ou par un ordre, on ajoute « fa », alors : « fa-sanaghusu », alors nous plongerons, « fa-khudh », alors prends. Astuce : « idha » regarde vers ce qui va probablement arriver, et le petit « fa » fait le pont entre la condition et sa conséquence.","exampleRo":"Idhā kāna al-jawwu jamīlan ghadan, fa-sanaghūṣu.","lit":"si · était · le-temps · beau · demain · [alors]-nous-plongerons","say":{"idha":"إِذَا","Idha ghusna":"إِذَا غُصْنَا","fa-sanaghusu":"فَسَنَغُوصُ","fa-khudh":"فَخُذْ","Idha":"إِذَا"}}},{"title":"Un sac oublié dans le taxi","phrases":[{"fr":"Zut, j'ai oublié mon sac dans le taxi !","tgt":"لَقَدْ نَسِيتُ حَقِيبَتِي فِي سَيَّارَةِ الْأُجْرَةِ!","ro":"Laqad nasītu ḥaqībatī fī sayyārati al-ujrati!"},{"fr":"Mon appareil photo était dedans.","tgt":"كَانَتْ آلَةُ تَصْوِيرِي فِيهَا.","ro":"Kānat ālatu taṣwīrī fīhā."},{"fr":"Tu te souviens du numéro de la voiture ?","tgt":"هَلْ تَتَذَكَّرُ رَقْمَ السَّيَّارَةِ؟","ro":"Hal tatadhakkaru raqma as-sayyārati?"},{"fr":"Non, mais j'ai gardé le reçu.","tgt":"لَا، لَكِنِّي احْتَفَظْتُ بِالْإِيصَالِ.","ro":"Lā, lākinnī iḥtafaẓtu bil-īṣāli."},{"fr":"Le réceptionniste appelle la compagnie de taxis.","tgt":"يَتَّصِلُ مُوَظَّفُ الِاسْتِقْبَالِ بِشَرِكَةِ سَيَّارَاتِ الْأُجْرَةِ.","ro":"Yattaṣilu muwaẓẓafu al-istiqbāli bi-sharikati sayyārāti al-ujrati."},{"fr":"Le chauffeur a trouvé le sac sur le siège arrière.","tgt":"وَجَدَ السَّائِقُ الْحَقِيبَةَ عَلَى الْمَقْعَدِ الْخَلْفِيِّ.","ro":"Wajada as-sāʾiqu al-ḥaqībata ʿalā al-maqʿadi al-khalfiyyi."},{"fr":"Il va la rapporter dans une heure.","tgt":"سَيُعِيدُهَا بَعْدَ سَاعَةٍ.","ro":"Sayuʿīduhā baʿda sāʿatin."},{"fr":"Je veux lui donner un pourboire pour le remercier.","tgt":"أُرِيدُ أَنْ أُعْطِيَهُ إِكْرَامِيَّةً لِأَشْكُرَهُ.","ro":"Urīdu an uʿṭiyahu ikrāmiyyatan li-ashkurahu."},{"fr":"Ici, les gens sont vraiment honnêtes.","tgt":"النَّاسُ هُنَا أُمَنَاءُ حَقًّا.","ro":"An-nāsu hunā umanāʾu ḥaqqan."},{"fr":"La prochaine fois, je ferai plus attention.","tgt":"فِي الْمَرَّةِ الْقَادِمَةِ، سَأَنْتَبِهُ أَكْثَرَ.","ro":"Fī al-marrati al-qādimati, sa-antabihu akthara."}]},{"title":"Une insolation à la pharmacie","phrases":[{"fr":"J'ai pris une insolation à la plage.","tgt":"أُصِبْتُ بِضَرْبَةِ شَمْسٍ عَلَى الشَّاطِئِ.","ro":"Uṣibtu bi-ḍarbati shamsin ʿalā ash-shāṭiʾi."},{"fr":"J'ai mal à la tête et un peu de fièvre.","tgt":"عِنْدِي صُدَاعٌ وَحُمَّى خَفِيفَةٌ.","ro":"ʿIndī ṣudāʿun wa-ḥummā khafīfatun."},{"fr":"Où se trouve la pharmacie la plus proche d'ici ?","tgt":"أَيْنَ أَقْرَبُ صَيْدَلِيَّةٍ مِنْ هُنَا؟","ro":"Ayna aqrabu ṣaydaliyyatin min hunā?"},{"fr":"Le pharmacien me pose quelques questions.","tgt":"يَطْرَحُ عَلَيَّ الصَّيْدَلِيُّ بَعْضَ الْأَسْئِلَةِ.","ro":"Yaṭraḥu ʿalayya aṣ-ṣaydaliyyu baʿḍa al-asʾilati."},{"fr":"Tu as bu assez d'eau aujourd'hui ?","tgt":"هَلْ شَرِبْتَ مَاءً كَافِيًا الْيَوْمَ؟","ro":"Hal sharibta māʾan kāfiyan al-yawma?"},{"fr":"Prends ce médicament deux fois par jour.","tgt":"خُذْ هَذَا الدَّوَاءَ مَرَّتَيْنِ فِي الْيَوْمِ.","ro":"Khudh hādhā ad-dawāʾa marratayni fī al-yawmi."},{"fr":"Repose-toi dans une chambre fraîche.","tgt":"اسْتَرِحْ فِي غُرْفَةٍ بَارِدَةٍ.","ro":"Istariḥ fī ghurfatin bāridatin."},{"fr":"Et évite le soleil pendant deux jours.","tgt":"وَتَجَنَّبِ الشَّمْسَ لِمُدَّةِ يَوْمَيْنِ.","ro":"Wa-tajannabi ash-shamsa li-muddati yawmayni."},{"fr":"Le médicament coûte trois dinars.","tgt":"يُكَلِّفُ الدَّوَاءُ ثَلَاثَةَ دَنَانِيرَ.","ro":"Yukallifu ad-dawāʾu thalāthata danānīra."},{"fr":"Le lendemain, je me sens beaucoup mieux.","tgt":"فِي الْيَوْمِ التَّالِي، أَشْعُرُ بِتَحَسُّنٍ كَبِيرٍ.","ro":"Fī al-yawmi at-tālī, ashʿuru bi-taḥassunin kabīrin."}]},{"title":"Les derniers souvenirs à Amman","phrases":[{"fr":"Avant de partir, on fait un tour au souk d'Amman.","tgt":"قَبْلَ السَّفَرِ، نَتَجَوَّلُ فِي سُوقِ عَمَّانَ.","ro":"Qabla as-safari, natajawwalu fī sūqi ʿAmmāna."},{"fr":"Je cherche un cadeau pour mes parents.","tgt":"أَبْحَثُ عَنْ هَدِيَّةٍ لِوَالِدَيَّ.","ro":"Abḥathu ʿan hadiyyatin li-wālidayya."},{"fr":"Ces bouteilles de sable coloré sont magnifiques.","tgt":"زُجَاجَاتُ الرَّمْلِ الْمُلَوَّنِ هَذِهِ رَائِعَةٌ.","ro":"Zujājātu ar-ramli al-mulawwani hādhihi rāʾiʿatun."},{"fr":"L'artisan dessine un chameau avec du sable.","tgt":"يَرْسُمُ الْحِرَفِيُّ جَمَلًا بِالرَّمْلِ.","ro":"Yarsumu al-ḥirafiyyu jamalan bir-ramli."},{"fr":"Il peut écrire mon prénom dans la bouteille.","tgt":"يَسْتَطِيعُ أَنْ يَكْتُبَ اسْمِي فِي الزُّجَاجَةِ.","ro":"Yastaṭīʿu an yaktuba ismī fī az-zujājati."},{"fr":"J'achète aussi du café à la cardamome.","tgt":"أَشْتَرِي أَيْضًا قَهْوَةً بِالْهَيْلِ.","ro":"Ashtarī ayḍan qahwatan bil-hayli."},{"fr":"Le vendeur me fait goûter des dattes.","tgt":"يُذِيقُنِي الْبَائِعُ بَعْضَ التَّمْرِ.","ro":"Yudhīqunī al-bāʾiʿu baʿḍa at-tamri."},{"fr":"Fais-moi un bon prix, j'en prends deux.","tgt":"أَعْطِنِي سِعْرًا خَاصًّا، سَآخُذُ اثْنَتَيْنِ.","ro":"Aʿṭinī siʿran khāṣṣan, saʾākhudhu ithnatayni."},{"fr":"D'accord, dix dinars pour les deux.","tgt":"حَسَنًا، عَشَرَةُ دَنَانِيرَ لِلِاثْنَتَيْنِ.","ro":"Ḥasanan, ʿasharatu danānīra lil-ithnatayni."},{"fr":"Ma valise est maintenant bien trop lourde !","tgt":"أَصْبَحَتْ حَقِيبَتِي ثَقِيلَةً جِدًّا الْآنَ!","ro":"Aṣbaḥat ḥaqībatī thaqīlatan jiddan al-āna!"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce voyage nous a menés de Louxor à Aqaba.","tgt":"أَخَذَتْنَا هَذِهِ الرِّحْلَةُ مِنَ الْأُقْصُرِ إِلَى الْعَقَبَةِ.","ro":"Akhadhatnā hādhihi ar-riḥlatu mina al-Uqṣuri ilā al-ʿAqabati."},{"fr":"Nous avons appris à dire ce qu'il faut faire.","tgt":"تَعَلَّمْنَا أَنْ نَقُولَ مَا يَجِبُ أَنْ نَفْعَلَهُ.","ro":"Taʿallamnā an naqūla mā yajibu an nafʿalahu."},{"fr":"Nous savons aussi raconter nos anciennes habitudes.","tgt":"نَعْرِفُ أَيْضًا كَيْفَ نَحْكِي عَنْ عَادَاتِنَا الْقَدِيمَةِ.","ro":"Naʿrifu ayḍan kayfa naḥkī ʿan ʿādātinā al-qadīmati."},{"fr":"Nous utilisons maintenant les relatifs sans difficulté.","tgt":"نَسْتَعْمِلُ الْآنَ الْأَسْمَاءَ الْمَوْصُولَةَ بِسُهُولَةٍ.","ro":"Nastaʿmilu al-āna al-asmāʾa al-mawṣūlata bi-suhūlatin."},{"fr":"L'arabe devient un peu plus familier chaque jour.","tgt":"تُصْبِحُ الْعَرَبِيَّةُ مَأْلُوفَةً أَكْثَرَ كُلَّ يَوْمٍ.","ro":"Tuṣbiḥu al-ʿarabiyyatu maʾlūfatan akthara kulla yawmin."},{"fr":"Le plus beau souvenir, c'est peut-être la nuit dans le désert.","tgt":"أَجْمَلُ ذِكْرَى هِيَ رُبَّمَا اللَّيْلَةُ فِي الصَّحْرَاءِ.","ro":"Ajmalu dhikrā hiya rubbamā al-laylatu fī aṣ-ṣaḥrāʾi."},{"fr":"Si tu révises un peu chaque jour, tu progresseras vite.","tgt":"إِذَا رَاجَعْتَ قَلِيلًا كُلَّ يَوْمٍ، فَسَتَتَقَدَّمُ بِسُرْعَةٍ.","ro":"Idhā rājaʿta qalīlan kulla yawmin, fa-satataqaddamu bi-surʿatin."},{"fr":"Félicitations, tu as fait un grand pas.","tgt":"مَبْرُوكٌ، لَقَدْ خَطَوْتَ خُطْوَةً كَبِيرَةً.","ro":"Mabrūkun, laqad khaṭawta khuṭwatan kabīratan."},{"fr":"Prends le temps de te reposer un peu.","tgt":"خُذْ وَقْتَكَ لِتَرْتَاحَ قَلِيلًا.","ro":"Khudh waqtaka li-tartāḥa qalīlan."},{"fr":"Rendez-vous au prochain module pour parler avec les gens.","tgt":"نَلْتَقِي فِي الْوَحْدَةِ الْقَادِمَةِ لِنَتَحَدَّثَ مَعَ النَّاسِ.","ro":"Naltaqī fī al-waḥdati al-qādimati li-nataḥaddatha maʿa an-nāsi."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un café sur la corniche","phrases":[{"fr":"On se retrouve sur la corniche ce soir ?","tgt":"هَلْ نَلْتَقِي عَلَى الْكُورْنِيشِ هَذَا الْمَسَاءَ؟","ro":"Hal naltaqī ʿalā al-kūrnīshi hādhā al-masāʾa?"},{"fr":"Oui, vers six heures, près du phare.","tgt":"نَعَمْ، نَحْوَ السَّاعَةِ السَّادِسَةِ، قُرْبَ الْمَنَارَةِ.","ro":"Naʿam, naḥwa as-sāʿati as-sādisati, qurba al-manārati."},{"fr":"J'adore marcher au bord de la mer à Beyrouth.","tgt":"أُحِبُّ الْمَشْيَ عَلَى شَاطِئِ الْبَحْرِ فِي بَيْرُوتَ.","ro":"Uḥibbu al-mashya ʿalā shāṭiʾi al-baḥri fī bayrūta."},{"fr":"L'endroit est bondé le dimanche.","tgt":"يَكُونُ الْمَكَانُ مُزْدَحِمًا يَوْمَ الْأَحَدِ.","ro":"Yakūnu al-makānu muzdaḥiman yawma al-aḥadi."},{"fr":"Allez, on boit un café chez le vendeur ambulant.","tgt":"هَيَّا نَشْرَبُ قَهْوَةً عِنْدَ الْبَائِعِ الْمُتَجَوِّلِ.","ro":"Hayyā nashrabu qahwatan ʿinda al-bāʾiʿi al-mutajawwili."},{"fr":"Le coucher de soleil est magnifique d'ici.","tgt":"غُرُوبُ الشَّمْسِ رَائِعٌ مِنْ هُنَا.","ro":"Ghurūbu ash-shamsi rāʾiʿun min hunā."},{"fr":"Tu viens souvent ici avec tes amis ?","tgt":"هَلْ تَأْتِي إِلَى هُنَا كَثِيرًا مَعَ أَصْدِقَائِكَ؟","ro":"Hal taʾtī ilā hunā kathīran maʿa aṣdiqāʾika?"},{"fr":"Oui, c'est notre endroit préféré depuis l'époque de l'université.","tgt":"نَعَمْ، هَذَا مَكَانُنَا الْمُفَضَّلُ مُنْذُ أَيَّامِ الْجَامِعَةِ.","ro":"Naʿam, hādhā makānunā al-mufaḍḍalu mundhu ayyāmi al-jāmiʿati."},{"fr":"Regarde, les pêcheurs rentrent au port.","tgt":"اُنْظُرْ، الصَّيَّادُونَ يَعُودُونَ إِلَى الْمِينَاءِ.","ro":"Unẓur, aṣ-ṣayyādūna yaʿūdūna ilā al-mīnāʾi."},{"fr":"Cette promenade me fait toujours du bien.","tgt":"هَذِهِ النُّزْهَةُ تُرِيحُنِي دَائِمًا.","ro":"Hādhihi an-nuzhatu turīḥunī dāʾiman."}]},{"title":"Que penses-tu de Beyrouth ?","phrases":[{"fr":"Je pense que Beyrouth est une ville unique.","tgt":"أَظُنُّ أَنَّ بَيْرُوتَ مَدِينَةٌ فَرِيدَةٌ.","ro":"Aẓunnu anna bayrūta madīnatun farīdatun."},{"fr":"Je pense que la vie ici est un peu chère.","tgt":"أَظُنُّ أَنَّ الْحَيَاةَ هُنَا غَالِيَةٌ قَلِيلًا.","ro":"Aẓunnu anna al-ḥayāta hunā ghāliyatun qalīlan."},{"fr":"Tu penses que les gens sont généreux ?","tgt":"هَلْ تَظُنُّ أَنَّ النَّاسَ كُرَمَاءُ؟","ro":"Hal taẓunnu anna an-nāsa kuramāʾu?"},{"fr":"Oui, je pense qu'ils adorent recevoir des invités.","tgt":"نَعَمْ، أَظُنُّ أَنَّهُمْ يُحِبُّونَ اسْتِقْبَالَ الضُّيُوفِ كَثِيرًا.","ro":"Naʿam, aẓunnu annahum yuḥibbūna istiqbāla aḍ-ḍuyūfi kathīran."},{"fr":"Ma sœur pense que la circulation est terrible.","tgt":"تَظُنُّ أُخْتِي أَنَّ زَحْمَةَ السَّيْرِ فَظِيعَةٌ.","ro":"Taẓunnu ukhtī anna zaḥmata as-sayri faẓīʿatun."},{"fr":"Je ne pense pas que ce soit un problème le soir.","tgt":"لَا أَظُنُّ أَنَّ ذَلِكَ مُشْكِلَةٌ فِي الْمَسَاءِ.","ro":"Lā aẓunnu anna dhālika mushkilatun fī al-masāʾi."},{"fr":"Nous pensons que le quartier de Gemmayzé est le plus vivant.","tgt":"نَظُنُّ أَنَّ حَيَّ الْجُمَّيْزَةِ هُوَ الْأَكْثَرُ حَيَوِيَّةً.","ro":"Naẓunnu anna ḥayya al-jummayzati huwa al-aktharu ḥayawiyyatan."},{"fr":"Mes parents pensent que la ville a beaucoup changé.","tgt":"يَظُنُّ وَالِدَايَ أَنَّ الْمَدِينَةَ تَغَيَّرَتْ كَثِيرًا.","ro":"Yaẓunnu wālidāya anna al-madīnata taghayyarat kathīran."},{"fr":"Je pense que tu vas aimer le vieux quartier.","tgt":"أَظُنُّ أَنَّكَ سَتُحِبُّ الْحَيَّ الْقَدِيمَ.","ro":"Aẓunnu annaka satuḥibbu al-ḥayya al-qadīma."},{"fr":"Moi aussi, je pense que c'est le cœur de la ville.","tgt":"أَنَا أَيْضًا أَظُنُّ أَنَّهُ قَلْبُ الْمَدِينَةِ.","ro":"Anā ayḍan aẓunnu annahu qalbu al-madīnati."}],"tip":{"title":"« Azunnu anna » : je pense que","example":"Je pense que Beyrouth est une ville unique. — <b>أَظُنُّ أَنَّ</b> بَيْرُوتَ مَدِينَةٌ فَرِيدَةٌ.","body":"Pour donner ton avis, l'arabe utilise « azunnu », je pense, suivi de « anna », que. Notre exemple se lit littéralement : je pense que Beyrouth, ville unique, sans verbe être, comme toujours au présent. Après « anna », le nom prend la terminaison en a : on dit « anna Bayrouta », et non « Bayroutou ». Avec un pronom, « anna » se soude à lui : « annahu », qu'il, « annaka », que tu, « annahum », qu'ils. Le verbe se conjugue normalement : « tazunnu », tu penses, « nazunnu », nous pensons, et pour la négation on ajoute « la » devant : « la azunnu », je ne pense pas. Astuce : retiens « azunnu anna » comme une petite porte qui s'ouvre sur ton opinion.","exampleRo":"Aẓunnu anna bayrūta madīnatun farīdatun.","lit":"je-pense · que · Beyrouth · ville · unique","say":{"Azunnu anna":"أَظُنُّ أَنَّ","azunnu":"أَظُنُّ","anna":"أَنَّ","anna Bayrouta":"أَنَّ بَيْرُوتَ","Bayroutou":"بَيْرُوتُ","annahu":"أَنَّهُ","annaka":"أَنَّكَ","annahum":"أَنَّهُمْ","tazunnu":"تَظُنُّ","nazunnu":"نَظُنُّ","la":"لَا","la azunnu":"لَا أَظُنُّ","azunnu anna":"أَظُنُّ أَنَّ"}}},{"title":"Une soirée mezzé","phrases":[{"fr":"Ce soir, on dîne dans un restaurant libanais.","tgt":"اللَّيْلَةَ نَتَعَشَّى فِي مَطْعَمٍ لُبْنَانِيٍّ.","ro":"Al-laylata nataʿashshā fī maṭʿamin lubnāniyyin."},{"fr":"Nous allons commander beaucoup de mezzé à partager.","tgt":"سَنَطْلُبُ أَطْبَاقًا كَثِيرَةً مِنَ الْمَازَةِ لِنَتَقَاسَمَهَا.","ro":"Sanaṭlubu aṭbāqan kathīratan mina al-māzati li-nataqāsamahā."},{"fr":"Le houmous et le moutabal sont délicieux ici.","tgt":"الْحُمُّصُ وَالْمُتَبَّلُ لَذِيذَانِ هُنَا.","ro":"Al-ḥummuṣu wa-l-mutabbalu ladhīdhāni hunā."},{"fr":"N'oublie pas de goûter les feuilles de vigne.","tgt":"لَا تَنْسَ أَنْ تَتَذَوَّقَ وَرَقَ الْعِنَبِ.","ro":"Lā tansa an tatadhawwaqa waraqa al-ʿinabi."},{"fr":"Le pain est chaud, il vient de sortir du four.","tgt":"الْخُبْزُ سَاخِنٌ، خَرَجَ مِنَ الْفُرْنِ الْآنَ.","ro":"Al-khubzu sākhinun, kharaja mina al-furni al-āna."},{"fr":"Qui veut encore du fattouche ?","tgt":"مَنْ يُرِيدُ مَزِيدًا مِنَ الْفَتُّوشِ؟","ro":"Man yurīdu mazīdan mina al-fattūshi?"},{"fr":"Au Liban, on mange lentement et on parle beaucoup.","tgt":"فِي لُبْنَانَ نَأْكُلُ بِبُطْءٍ وَنَتَكَلَّمُ كَثِيرًا.","ro":"Fī lubnāna naʾkulu bi-buṭʾin wa-natakallamu kathīran."},{"fr":"Ce repas dure souvent plusieurs heures.","tgt":"تَسْتَمِرُّ هَذِهِ الْوَجْبَةُ عِدَّةَ سَاعَاتٍ غَالِبًا.","ro":"Tastamirru hādhihi al-wajbatu ʿiddata sāʿātin ghāliban."},{"fr":"Pour le dessert, je recommande les fruits frais.","tgt":"لِلْحَلْوَى أَنْصَحُ بِالْفَوَاكِهِ الطَّازَجَةِ.","ro":"Li-l-ḥalwā anṣaḥu bi-l-fawākihi aṭ-ṭāzajati."},{"fr":"Quelle belle soirée, merci de nous avoir invités !","tgt":"يَا لَهَا مِنْ سَهْرَةٍ جَمِيلَةٍ، شُكْرًا لِأَنَّكَ دَعَوْتَنَا!","ro":"Yā lahā min sahratin jamīlatin, shukran li-annaka daʿawtanā!"}]},{"title":"Préparer le taboulé","phrases":[{"fr":"Ma grand-mère fait le meilleur taboulé du monde.","tgt":"جَدَّتِي تُحَضِّرُ أَطْيَبَ تَبُّولَةٍ فِي الْعَالَمِ.","ro":"Jaddatī tuḥaḍḍiru aṭyaba tabbūlatin fī al-ʿālami."},{"fr":"Elle m'a donné sa recette quand j'étais petit.","tgt":"أَعْطَتْنِي وَصْفَتَهَا عِنْدَمَا كُنْتُ صَغِيرًا.","ro":"Aʿṭatnī waṣfatahā ʿindamā kuntu ṣaghīran."},{"fr":"Il faut mettre beaucoup de persil et un peu de boulgour.","tgt":"يَجِبُ أَنْ نَضَعَ كَثِيرًا مِنَ الْبَقْدُونِسِ وَقَلِيلًا مِنَ الْبُرْغُلِ.","ro":"Yajibu an naḍaʿa kathīran mina al-baqdūnisi wa-qalīlan mina al-burghuli."},{"fr":"Coupe les tomates en petits morceaux.","tgt":"قَطِّعِ الطَّمَاطِمَ قِطَعًا صَغِيرَةً.","ro":"Qaṭṭiʿi aṭ-ṭamāṭima qiṭaʿan ṣaghīratan."},{"fr":"Ajoute le jus de citron et l'huile d'olive.","tgt":"أَضِفْ عَصِيرَ اللَّيْمُونِ وَزَيْتَ الزَّيْتُونِ.","ro":"Aḍif ʿaṣīra al-laymūni wa-zayta az-zaytūni."},{"fr":"Le secret, c'est la menthe fraîche.","tgt":"السِّرُّ هُوَ النَّعْنَاعُ الطَّازَجُ.","ro":"As-sirru huwa an-naʿnāʿu aṭ-ṭāzaju."},{"fr":"Goûte et dis-moi s'il manque du sel.","tgt":"ذُقْ وَقُلْ لِي إِنْ كَانَ يَنْقُصُهُ الْمِلْحُ.","ro":"Dhuq wa-qul lī in kāna yanquṣuhu al-milḥu."},{"fr":"C'est parfait, il n'a besoin de rien.","tgt":"إِنَّهُ مُمْتَازٌ، لَا يَحْتَاجُ إِلَى شَيْءٍ.","ro":"Innahu mumtāzun, lā yaḥtāju ilā shayʾin."},{"fr":"On le sert avec des feuilles de laitue.","tgt":"نُقَدِّمُهُ مَعَ أَوْرَاقِ الْخَسِّ.","ro":"Nuqaddimuhu maʿa awrāqi al-khassi."},{"fr":"Tu me montreras comment le préparer la prochaine fois ?","tgt":"هَلْ سَتُرِينِي كَيْفَ أُحَضِّرُهُ فِي الْمَرَّةِ الْقَادِمَةِ؟","ro":"Hal saturīnī kayfa uḥaḍḍiruhu fī al-marrati al-qādimati?"}]},{"title":"Une journée à Byblos","phrases":[{"fr":"J'ai déjà visité Byblos deux fois.","tgt":"قَدْ زُرْتُ جُبَيْلَ مَرَّتَيْنِ.","ro":"Qad zurtu jubayla marratayni."},{"fr":"Le port a vraiment gardé son charme d'autrefois.","tgt":"لَقَدْ حَافَظَ الْمِينَاءُ عَلَى سِحْرِهِ الْقَدِيمِ.","ro":"Laqad ḥāfaẓa al-mīnāʾu ʿalā siḥrihi al-qadīmi."},{"fr":"Les archéologues ont déjà découvert des trésors ici.","tgt":"قَدِ اكْتَشَفَ عُلَمَاءُ الْآثَارِ كُنُوزًا هُنَا.","ro":"Qadi ktashafa ʿulamāʾu al-āthāri kunūzan hunā."},{"fr":"On dit que c'est l'une des plus vieilles villes du monde.","tgt":"يُقَالُ إِنَّهَا مِنْ أَقْدَمِ الْمُدُنِ فِي الْعَالَمِ.","ro":"Yuqālu innahā min aqdami al-muduni fī al-ʿālami."},{"fr":"Est-ce que tu as déjà vu le vieux château ?","tgt":"هَلْ سَبَقَ أَنْ رَأَيْتَ الْقَلْعَةَ الْقَدِيمَةَ؟","ro":"Hal sabaqa an raʾayta al-qalʿata al-qadīmata?"},{"fr":"Oui, je l'ai déjà visité avec ma classe.","tgt":"نَعَمْ، قَدْ زُرْتُهَا مَعَ صَفِّي.","ro":"Naʿam, qad zurtuhā maʿa ṣaffī."},{"fr":"Le poisson était vraiment délicieux.","tgt":"لَقَدْ كَانَ السَّمَكُ لَذِيذًا حَقًّا.","ro":"Laqad kāna as-samaku ladhīdhan ḥaqqan."},{"fr":"Les boutiques du souk ont déjà fermé.","tgt":"قَدْ أَغْلَقَتْ مَحَلَّاتُ السُّوقِ أَبْوَابَهَا.","ro":"Qad aghlaqat maḥallātu as-sūqi abwābahā."},{"fr":"Heureusement, j'ai déjà acheté un souvenir ce matin.","tgt":"لِحُسْنِ الْحَظِّ، قَدِ اشْتَرَيْتُ تِذْكَارًا هَذَا الصَّبَاحَ.","ro":"Li-ḥusni al-ḥaẓẓi, qadi shtaraytu tidhkāran hādhā aṣ-ṣabāḥa."},{"fr":"Cette journée à Byblos m'a vraiment plu.","tgt":"لَقَدْ أَعْجَبَنِي هَذَا الْيَوْمُ فِي جُبَيْلَ كَثِيرًا.","ro":"Laqad aʿjabanī hādhā al-yawmu fī jubayla kathīran."}],"tip":{"title":"« Qad » suivi du passé : déjà, vraiment","example":"J'ai déjà visité Byblos deux fois. — <b>قَدْ</b> زُرْتُ جُبَيْلَ مَرَّتَيْنِ.","body":"Le petit mot « qad », placé devant un verbe au passé, insiste sur le fait que l'action est bien accomplie. Selon le contexte, on le traduit par déjà ou par vraiment. Notre exemple se décompose ainsi : « qad », déjà, « zurtu », j'ai visité, « Jubayla », Byblos, « marratayni », deux fois. Tu entendras aussi « laqad », encore plus fort, au début d'une phrase : « laqad kana ladhidhan », c'était vraiment délicieux. Quand le mot suivant commence par une voyelle muette, « qad » devient « qadi » pour la liaison, comme dans « qadi shtaraytu », j'ai déjà acheté. Astuce : pense à « qad » comme à un tampon qui certifie que c'est fait.","exampleRo":"Qad zurtu jubayla marratayni.","lit":"[déjà] · j'ai-visité · Byblos · deux-fois","say":{"Qad":"قَدْ","qad":"قَدْ","zurtu":"زُرْتُ","Jubayla":"جُبَيْلَ","marratayni":"مَرَّتَيْنِ","laqad":"لَقَدْ","laqad kana ladhidhan":"لَقَدْ كَانَ لَذِيذًا","qadi":"قَدِ","qadi shtaraytu":"قَدِ اشْتَرَيْتُ"}}},{"title":"Le festival de Baalbek","phrases":[{"fr":"Cet été, nous irons au festival de Baalbek.","tgt":"فِي هَذَا الصَّيْفِ سَنَذْهَبُ إِلَى مِهْرَجَانِ بَعْلَبَكَّ.","ro":"Fī hādhā aṣ-ṣayfi sanadhhabu ilā mihrajāni baʿlabakka."},{"fr":"Les concerts ont lieu au milieu des ruines romaines.","tgt":"تُقَامُ الْحَفَلَاتُ بَيْنَ الْآثَارِ الرُّومَانِيَّةِ.","ro":"Tuqāmu al-ḥafalātu bayna al-āthāri ar-rūmāniyyati."},{"fr":"Les colonnes sont immenses, tu verras.","tgt":"الْأَعْمِدَةُ ضَخْمَةٌ جِدًّا، سَتَرَى.","ro":"Al-aʿmidatu ḍakhmatun jiddan, satarā."},{"fr":"Quel chanteur va chanter cette année ?","tgt":"أَيُّ مُغَنٍّ سَيُغَنِّي هَذَا الْعَامَ؟","ro":"Ayyu mughannin sayughannī hādhā al-ʿāma?"},{"fr":"Je ne sais pas encore, le programme n'est pas sorti.","tgt":"لَا أَعْرِفُ بَعْدُ، فَالْبَرْنَامَجُ لَمْ يَصْدُرْ.","ro":"Lā aʿrifu baʿdu, fa-l-barnāmaju lam yaṣdur."},{"fr":"Il faut réserver les billets très tôt.","tgt":"يَجِبُ أَنْ نَحْجِزَ التَّذَاكِرَ مُبَكِّرًا جِدًّا.","ro":"Yajibu an naḥjiza at-tadhākira mubakkiran jiddan."},{"fr":"La route vers la Békaa prend environ deux heures.","tgt":"تَسْتَغْرِقُ الطَّرِيقُ إِلَى الْبِقَاعِ نَحْوَ سَاعَتَيْنِ.","ro":"Tastaghriqu aṭ-ṭarīqu ilā al-biqāʿi naḥwa sāʿatayni."},{"fr":"On pourrait dormir chez mon oncle à Zahlé.","tgt":"يُمْكِنُنَا أَنْ نَنَامَ عِنْدَ عَمِّي فِي زَحْلَةَ.","ro":"Yumkinunā an nanāma ʿinda ʿammī fī zaḥlata."},{"fr":"La musique sous les étoiles, c'est magique.","tgt":"الْمُوسِيقَى تَحْتَ النُّجُومِ شَيْءٌ سِحْرِيٌّ.","ro":"Al-mūsīqā taḥta an-nujūmi shayʾun siḥriyyun."},{"fr":"J'ai vraiment hâte d'y être !","tgt":"أَنَا مُتَشَوِّقٌ جِدًّا لِذَلِكَ!","ro":"Anā mutashawwiqun jiddan li-dhālika!"}]},{"title":"Un week-end à la montagne","phrases":[{"fr":"Ce week-end, nous montons à la montagne.","tgt":"فِي عُطْلَةِ نِهَايَةِ الْأُسْبُوعِ نَصْعَدُ إِلَى الْجَبَلِ.","ro":"Fī ʿuṭlati nihāyati al-usbūʿi naṣʿadu ilā al-jabali."},{"fr":"Il fait plus frais là-haut qu'à Beyrouth.","tgt":"الْجَوُّ هُنَاكَ أَبْرَدُ مِنْ بَيْرُوتَ.","ro":"Al-jawwu hunāka abradu min bayrūta."},{"fr":"Mes cousins ont une maison en pierre près de la forêt des cèdres.","tgt":"لِأَبْنَاءِ عَمِّي بَيْتٌ حَجَرِيٌّ قُرْبَ غَابَةِ الْأَرْزِ.","ro":"Li-abnāʾi ʿammī baytun ḥajariyyun qurba ghābati al-arzi."},{"fr":"Le matin, on boit le café sur la terrasse.","tgt":"فِي الصَّبَاحِ نَشْرَبُ الْقَهْوَةَ عَلَى الشُّرْفَةِ.","ro":"Fī aṣ-ṣabāḥi nashrabu al-qahwata ʿalā ash-shurfati."},{"fr":"L'après-midi, on fait une longue randonnée à pied.","tgt":"بَعْدَ الظُّهْرِ نَقُومُ بِنُزْهَةٍ طَوِيلَةٍ سَيْرًا عَلَى الْأَقْدَامِ.","ro":"Baʿda aẓ-ẓuhri naqūmu bi-nuzhatin ṭawīlatin sayran ʿalā al-aqdāmi."},{"fr":"De là-haut, on voit la mer et les villages.","tgt":"مِنْ هُنَاكَ نَرَى الْبَحْرَ وَالْقُرَى.","ro":"Min hunāka narā al-baḥra wa-l-qurā."},{"fr":"En hiver, il neige souvent sur les sommets.","tgt":"فِي الشِّتَاءِ يَتَسَاقَطُ الثَّلْجُ كَثِيرًا عَلَى الْقِمَمِ.","ro":"Fī ash-shitāʾi yatasāqaṭu ath-thalju kathīran ʿalā al-qimami."},{"fr":"On peut skier le matin et nager l'après-midi.","tgt":"يُمْكِنُ أَنْ نَتَزَلَّجَ صَبَاحًا وَأَنْ نَسْبَحَ بَعْدَ الظُّهْرِ.","ro":"Yumkinu an natazallaja ṣabāḥan wa-an nasbaḥa baʿda aẓ-ẓuhri."},{"fr":"Le soir, on joue aux cartes près du feu.","tgt":"فِي الْمَسَاءِ نَلْعَبُ الْوَرَقَ قُرْبَ النَّارِ.","ro":"Fī al-masāʾi nalʿabu al-waraqa qurba an-nāri."},{"fr":"Le calme de la montagne me repose vraiment.","tgt":"هُدُوءُ الْجَبَلِ يُرِيحُنِي حَقًّا.","ro":"Hudūʾu al-jabali yurīḥunī ḥaqqan."}]},{"title":"Parler de cinéma","phrases":[{"fr":"Tu as vu le nouveau film libanais ?","tgt":"هَلْ شَاهَدْتَ الْفِيلْمَ اللُّبْنَانِيَّ الْجَدِيدَ؟","ro":"Hal shāhadta al-fīlma al-lubnāniyya al-jadīda?"},{"fr":"Je ne l'ai pas encore vu, il est bien ?","tgt":"لَمْ أُشَاهِدْهُ بَعْدُ، هَلْ هُوَ جَيِّدٌ؟","ro":"Lam ushāhidhu baʿdu, hal huwa jayyidun?"},{"fr":"Il raconte l'histoire d'une famille de Beyrouth.","tgt":"يَحْكِي قِصَّةَ عَائِلَةٍ مِنْ بَيْرُوتَ.","ro":"Yaḥkī qiṣṣata ʿāʾilatin min bayrūta."},{"fr":"Les acteurs jouent de façon très naturelle.","tgt":"يُمَثِّلُ الْمُمَثِّلُونَ بِطَرِيقَةٍ طَبِيعِيَّةٍ جِدًّا.","ro":"Yumaththilu al-mumaththilūna bi-ṭarīqatin ṭabīʿiyyatin jiddan."},{"fr":"La fin m'a fait pleurer.","tgt":"النِّهَايَةُ جَعَلَتْنِي أَبْكِي.","ro":"An-nihāyatu jaʿalatnī abkī."},{"fr":"Je préfère les comédies, j'ai besoin de rire.","tgt":"أُفَضِّلُ الْأَفْلَامَ الْكُومِيدِيَّةَ، أَحْتَاجُ إِلَى الضَّحِكِ.","ro":"Ufaḍḍilu al-aflāma al-kūmīdiyyata, aḥtāju ilā aḍ-ḍaḥiki."},{"fr":"On va au cinéma de Hamra samedi ?","tgt":"هَلْ نَذْهَبُ إِلَى سِينَمَا الْحَمْرَاءِ يَوْمَ السَّبْتِ؟","ro":"Hal nadhhabu ilā sīnamā al-ḥamrāʾi yawma as-sabti?"},{"fr":"La séance commence à neuf heures.","tgt":"يَبْدَأُ الْعَرْضُ فِي السَّاعَةِ التَّاسِعَةِ.","ro":"Yabdaʾu al-ʿarḍu fī as-sāʿati at-tāsiʿati."},{"fr":"J'achèterai le pop-corn, et toi les boissons.","tgt":"سَأَشْتَرِي الْفُشَارَ، وَأَنْتَ تَشْتَرِي الْمَشْرُوبَاتِ.","ro":"Saʾashtarī al-fushāra, wa-anta tashtarī al-mashrūbāti."},{"fr":"Après le film, on en discutera autour d'un dîner.","tgt":"بَعْدَ الْفِيلْمِ سَنَتَحَدَّثُ عَنْهُ عَلَى الْعَشَاءِ.","ro":"Baʿda al-fīlmi sanataḥaddathu ʿanhu ʿalā al-ʿashāʾi."}]},{"title":"Un match de basket","phrases":[{"fr":"Le basket est très populaire au Liban.","tgt":"كُرَةُ السَّلَّةِ شَعْبِيَّةٌ جِدًّا فِي لُبْنَانَ.","ro":"Kuratu as-sallati shaʿbiyyatun jiddan fī lubnāna."},{"fr":"Ce soir, il y a un grand match à Beyrouth.","tgt":"هُنَاكَ مُبَارَاةٌ كَبِيرَةٌ فِي بَيْرُوتَ هَذَا الْمَسَاءَ.","ro":"Hunāka mubārātun kabīratun fī bayrūta hādhā al-masāʾa."},{"fr":"Quelle équipe est-ce que tu soutiens ?","tgt":"أَيَّ فَرِيقٍ تُشَجِّعُ؟","ro":"Ayya farīqin tushajjiʿu?"},{"fr":"Je soutiens l'équipe de mon quartier depuis mon enfance.","tgt":"أُشَجِّعُ فَرِيقَ حَيِّي مُنْذُ الصِّغَرِ.","ro":"Ushajjiʿu farīqa ḥayyī mundhu aṣ-ṣighari."},{"fr":"L'ambiance dans la salle est incroyable.","tgt":"الْأَجْوَاءُ فِي الْقَاعَةِ مُذْهِلَةٌ.","ro":"Al-ajwāʾu fī al-qāʿati mudhhilatun."},{"fr":"Les supporters chantent pendant tout le match.","tgt":"يُغَنِّي الْمُشَجِّعُونَ طَوَالَ الْمُبَارَاةِ.","ro":"Yughannī al-mushajjiʿūna ṭawāla al-mubārāti."},{"fr":"Tu joues au basket, toi aussi ?","tgt":"هَلْ تَلْعَبُ كُرَةَ السَّلَّةِ أَنْتَ أَيْضًا؟","ro":"Hal talʿabu kurata as-sallati anta ayḍan?"},{"fr":"Non, moi je préfère le football et la natation.","tgt":"لَا، أَنَا أُفَضِّلُ كُرَةَ الْقَدَمِ وَالسِّبَاحَةَ.","ro":"Lā, anā ufaḍḍilu kurata al-qadami wa-s-sibāḥata."},{"fr":"Nous avons gagné de trois points seulement !","tgt":"فُزْنَا بِفَارِقِ ثَلَاثِ نِقَاطٍ فَقَطْ!","ro":"Fuznā bi-fāriqi thalāthi niqāṭin faqaṭ!"},{"fr":"Allons fêter la victoire avec les autres.","tgt":"هَيَّا نَحْتَفِلُ بِالْفَوْزِ مَعَ الْآخَرِينَ.","ro":"Hayyā naḥtafilu bi-l-fawzi maʿa al-ākharīna."}]},{"title":"Une invitation à un mariage","phrases":[{"fr":"Rami et Lina vont se marier en juin.","tgt":"سَيَتَزَوَّجُ رَامِي وَلِينَا فِي شَهْرِ حُزَيْرَانَ.","ro":"Sayatazawwaju rāmī wa-līnā fī shahri ḥuzayrāna."},{"fr":"J'ai reçu leur invitation ce matin.","tgt":"وَصَلَتْنِي دَعْوَتُهُمَا هَذَا الصَّبَاحَ.","ro":"Waṣalatnī daʿwatuhumā hādhā aṣ-ṣabāḥa."},{"fr":"La fête aura lieu dans un jardin à la montagne.","tgt":"سَيُقَامُ الْحَفْلُ فِي حَدِيقَةٍ فِي الْجَبَلِ.","ro":"Sayuqāmu al-ḥaflu fī ḥadīqatin fī al-jabali."},{"fr":"Qu'est-ce que tu vas porter ce jour-là ?","tgt":"مَاذَا سَتَلْبَسُ فِي ذَلِكَ الْيَوْمِ؟","ro":"Mādhā satalbasu fī dhālika al-yawmi?"},{"fr":"Je dois acheter un costume neuf.","tgt":"يَجِبُ أَنْ أَشْتَرِيَ بَدْلَةً جَدِيدَةً.","ro":"Yajibu an ashtariya badlatan jadīdatan."},{"fr":"Et quel cadeau allons-nous leur offrir ?","tgt":"وَأَيَّ هَدِيَّةٍ سَنُقَدِّمُ لَهُمَا؟","ro":"Wa-ayya hadiyyatin sanuqaddimu lahumā?"},{"fr":"Ils ont une liste de cadeaux dans un magasin.","tgt":"لَدَيْهِمَا قَائِمَةُ هَدَايَا فِي مَتْجَرٍ.","ro":"Ladayhimā qāʾimatu hadāyā fī matjarin."},{"fr":"Il y aura au moins trois cents invités.","tgt":"سَيَكُونُ هُنَاكَ ثَلَاثُمِئَةِ ضَيْفٍ عَلَى الْأَقَلِّ.","ro":"Sayakūnu hunāka thalāthumiʾati ḍayfin ʿalā al-aqalli."},{"fr":"Les mariages libanais sont célèbres pour leur ambiance.","tgt":"الْأَعْرَاسُ اللُّبْنَانِيَّةُ مَشْهُورَةٌ بِأَجْوَائِهَا.","ro":"Al-aʿrāsu al-lubnāniyyatu mashhūratun bi-ajwāʾihā."},{"fr":"Prépare-toi à danser toute la nuit !","tgt":"اِسْتَعِدَّ لِلرَّقْصِ طَوَالَ اللَّيْلِ!","ro":"Istaʿidda li-r-raqṣi ṭawāla al-layli!"}]},{"title":"Le soir du mariage","phrases":[{"fr":"La mariée est arrivée sous les applaudissements.","tgt":"وَصَلَتِ الْعَرُوسُ وَسَطَ التَّصْفِيقِ.","ro":"Waṣalati al-ʿarūsu wasaṭa at-taṣfīqi."},{"fr":"Elle portait une longue robe blanche.","tgt":"كَانَتْ تَلْبَسُ فُسْتَانًا أَبْيَضَ طَوِيلًا.","ro":"Kānat talbasu fustānan abyaḍa ṭawīlan."},{"fr":"Les musiciens jouaient de la derbouka et du oud.","tgt":"كَانَ الْمُوسِيقِيُّونَ يَعْزِفُونَ عَلَى الدِّرْبَكَّةِ وَالْعُودِ.","ro":"Kāna al-mūsīqiyyūna yaʿzifūna ʿalā ad-dirbakkati wa-l-ʿūdi."},{"fr":"Tout le monde a dansé la dabké en cercle.","tgt":"رَقَصَ الْجَمِيعُ الدَّبْكَةَ فِي دَائِرَةٍ.","ro":"Raqaṣa al-jamīʿu ad-dabkata fī dāʾiratin."},{"fr":"Le père du marié a fait un discours émouvant.","tgt":"أَلْقَى وَالِدُ الْعَرِيسِ كَلِمَةً مُؤَثِّرَةً.","ro":"Alqā wālidu al-ʿarīsi kalimatan muʾaththiratan."},{"fr":"Le gâteau avait sept étages !","tgt":"كَانَتْ لِلْكَعْكَةِ سَبْعُ طَبَقَاتٍ!","ro":"Kānat li-l-kaʿkati sabʿu ṭabaqātin!"},{"fr":"J'ai retrouvé des amis que je n'avais pas vus depuis longtemps.","tgt":"اِلْتَقَيْتُ أَصْدِقَاءَ لَمْ أَرَهُمْ مُنْذُ زَمَنٍ طَوِيلٍ.","ro":"Iltaqaytu aṣdiqāʾa lam arahum mundhu zamanin ṭawīlin."},{"fr":"Nous avons pris beaucoup de photos ensemble.","tgt":"اِلْتَقَطْنَا صُوَرًا كَثِيرَةً مَعًا.","ro":"Iltaqaṭnā ṣuwaran kathīratan maʿan."},{"fr":"La fête s'est terminée à trois heures du matin.","tgt":"اِنْتَهَى الْحَفْلُ فِي السَّاعَةِ الثَّالِثَةِ فَجْرًا.","ro":"Intahā al-ḥaflu fī as-sāʿati ath-thālithati fajran."},{"fr":"Je souhaite beaucoup de bonheur aux mariés.","tgt":"أَتَمَنَّى لِلْعَرُوسَيْنِ سَعَادَةً كَبِيرَةً.","ro":"Atamannā li-l-ʿarūsayni saʿādatan kabīratan."}]},{"title":"Des promesses entre amis","phrases":[{"fr":"Je n'oublierai jamais cette soirée.","tgt":"لَنْ أَنْسَى هَذِهِ السَّهْرَةَ أَبَدًا.","ro":"Lan ansā hādhihi as-sahrata abadan."},{"fr":"Nous ne quitterons pas Beyrouth cet été.","tgt":"لَنْ نُغَادِرَ بَيْرُوتَ هَذَا الصَّيْفَ.","ro":"Lan nughādira bayrūta hādhā aṣ-ṣayfa."},{"fr":"Ne t'inquiète pas, je ne serai pas en retard.","tgt":"لَا تَقْلَقْ، لَنْ أَتَأَخَّرَ.","ro":"Lā taqlaq, lan ataʾakhkhara."},{"fr":"Elle ne changera pas d'avis facilement.","tgt":"لَنْ تُغَيِّرَ رَأْيَهَا بِسُهُولَةٍ.","ro":"Lan tughayyira raʾyahā bi-suhūlatin."},{"fr":"Ils ne viendront pas à la fête demain.","tgt":"لَنْ يَأْتُوا إِلَى الْحَفْلَةِ غَدًا.","ro":"Lan yaʾtū ilā al-ḥaflati ghadan."},{"fr":"Tu ne regretteras pas ce voyage, crois-moi.","tgt":"لَنْ تَنْدَمَ عَلَى هَذِهِ الرِّحْلَةِ، صَدِّقْنِي.","ro":"Lan tandama ʿalā hādhihi ar-riḥlati, ṣaddiqnī."},{"fr":"Je ne dirai ton secret à personne.","tgt":"لَنْ أَقُولَ سِرَّكَ لِأَحَدٍ.","ro":"Lan aqūla sirraka li-aḥadin."},{"fr":"Nous ne trouverons pas de meilleur taboulé ailleurs.","tgt":"لَنْ نَجِدَ تَبُّولَةً أَطْيَبَ فِي مَكَانٍ آخَرَ.","ro":"Lan najida tabbūlatan aṭyaba fī makānin ākhara."},{"fr":"Le restaurant ne fermera pas avant minuit.","tgt":"لَنْ يُغْلِقَ الْمَطْعَمُ قَبْلَ مُنْتَصَفِ اللَّيْلِ.","ro":"Lan yughliqa al-maṭʿamu qabla muntaṣafi al-layli."},{"fr":"Notre amitié ne changera jamais.","tgt":"لَنْ تَتَغَيَّرَ صَدَاقَتُنَا أَبَدًا.","ro":"Lan tataghayyara ṣadāqatunā abadan."}],"tip":{"title":"« Lan » : la négation du futur","example":"Je n'oublierai jamais cette soirée. — <b>لَنْ</b> أَنْسَى هَذِهِ السَّهْرَةَ أَبَدًا.","body":"Pour dire ce qui n'arrivera pas, l'arabe utilise « lan » devant le verbe au présent. Attention, le petit préfixe du futur, « sa », disparaît : « sa-ansa », j'oublierai, devient « lan ansa », je n'oublierai pas. Notre exemple se lit mot à mot : ne pas, j'oublie, cette soirée, jamais. Comme après « an », le verbe prend la terminaison en a : « lan nughadira », nous ne partirons pas, « lan tandama », tu ne regretteras pas. Tu connais maintenant les trois négations du verbe : « la » pour le présent, « lam » pour le passé et « lan » pour le futur. Astuce : « lan » et « jamais » finissent tous deux par un son nasal, c'est la négation qui regarde loin devant.","exampleRo":"Lan ansā hādhihi as-sahrata abadan.","lit":"[ne… pas, futur] · j'oublie · cette · soirée · jamais","say":{"Lan":"لَنْ","lan":"لَنْ","sa-ansa":"سَأَنْسَى","lan ansa":"لَنْ أَنْسَى","an":"أَنْ","lan nughadira":"لَنْ نُغَادِرَ","lan tandama":"لَنْ تَنْدَمَ","la":"لَا","lam":"لَمْ"}}},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais enfant, j'habitais à Achrafieh.","tgt":"عِنْدَمَا كُنْتُ طِفْلًا كُنْتُ أَسْكُنُ فِي الْأَشْرَفِيَّةِ.","ro":"ʿIndamā kuntu ṭiflan kuntu askunu fī al-ashrafiyyati."},{"fr":"Nous jouions au ballon dans la rue jusqu'au soir.","tgt":"كُنَّا نَلْعَبُ بِالْكُرَةِ فِي الشَّارِعِ حَتَّى الْمَسَاءِ.","ro":"Kunnā nalʿabu bi-l-kurati fī ash-shāriʿi ḥattā al-masāʾi."},{"fr":"Ma mère nous appelait depuis le balcon.","tgt":"كَانَتْ أُمِّي تُنَادِينَا مِنَ الشُّرْفَةِ.","ro":"Kānat ummī tunādīnā mina ash-shurfati."},{"fr":"Le dimanche, on allait chez nos grands-parents.","tgt":"فِي أَيَّامِ الْأَحَدِ كُنَّا نَذْهَبُ إِلَى بَيْتِ جَدَّيْنَا.","ro":"Fī ayyāmi al-aḥadi kunnā nadhhabu ilā bayti jaddaynā."},{"fr":"Mon grand-père racontait des histoires incroyables.","tgt":"كَانَ جَدِّي يَحْكِي قِصَصًا عَجِيبَةً.","ro":"Kāna jaddī yaḥkī qiṣaṣan ʿajībatan."},{"fr":"Te souviens-tu de notre première école ?","tgt":"هَلْ تَتَذَكَّرُ مَدْرَسَتَنَا الْأُولَى؟","ro":"Hal tatadhakkaru madrasatanā al-ūlā?"},{"fr":"Bien sûr, je me souviens même du nom de la maîtresse.","tgt":"طَبْعًا، أَتَذَكَّرُ حَتَّى اسْمَ الْمُعَلِّمَةِ.","ro":"Ṭabʿan, atadhakkaru ḥattā isma al-muʿallimati."},{"fr":"On achetait du kaak au vendeur près de l'école.","tgt":"كُنَّا نَشْتَرِي الْكَعْكَ مِنَ الْبَائِعِ قُرْبَ الْمَدْرَسَةِ.","ro":"Kunnā nashtarī al-kaʿka mina al-bāʾiʿi qurba al-madrasati."},{"fr":"Ces années étaient simples et heureuses.","tgt":"كَانَتْ تِلْكَ السَّنَوَاتُ بَسِيطَةً وَسَعِيدَةً.","ro":"Kānat tilka as-sanawātu basīṭatan wa-saʿīdatan."},{"fr":"Parfois, j'aimerais revenir à cette époque.","tgt":"أَحْيَانًا أَتَمَنَّى أَنْ أَعُودَ إِلَى ذَلِكَ الزَّمَنِ.","ro":"Aḥyānan atamannā an aʿūda ilā dhālika az-zamani."}]},{"title":"Un ami part enseigner à Dubaï","phrases":[{"fr":"Mon ami Karim enseigne les mathématiques.","tgt":"صَدِيقِي كَرِيمٌ يُعَلِّمُ الرِّيَاضِيَّاتِ.","ro":"Ṣadīqī karīmun yuʿallimu ar-riyāḍiyyāti."},{"fr":"Il va partir pour Dubaï le mois prochain.","tgt":"سَيُسَافِرُ إِلَى دُبَيٍّ فِي الشَّهْرِ الْقَادِمِ.","ro":"Sayusāfiru ilā dubayyin fī ash-shahri al-qādimi."},{"fr":"Une école là-bas lui a proposé un poste.","tgt":"عَرَضَتْ عَلَيْهِ مَدْرَسَةٌ هُنَاكَ وَظِيفَةً.","ro":"ʿAraḍat ʿalayhi madrasatun hunāka waẓīfatan."},{"fr":"Il a enseigné dix ans à Tripoli.","tgt":"عَلَّمَ عَشْرَ سَنَوَاتٍ فِي طَرَابُلُسَ.","ro":"ʿAllama ʿashra sanawātin fī ṭarābulusa."},{"fr":"Sa femme voyagera avec lui.","tgt":"سَتُسَافِرُ زَوْجَتُهُ مَعَهُ.","ro":"Satusāfiru zawjatuhu maʿahu."},{"fr":"Ses élèves lui ont dit au revoir avec une belle fête.","tgt":"وَدَّعَهُ تَلَامِيذُهُ بِحَفْلَةٍ جَمِيلَةٍ.","ro":"Waddaʿahu talāmīdhuhu bi-ḥaflatin jamīlatin."},{"fr":"Nous l'aiderons à préparer ses valises.","tgt":"سَنُسَاعِدُهُ فِي تَحْضِيرِ حَقَائِبِهِ.","ro":"Sanusāʿiduhu fī taḥḍīri ḥaqāʾibihi."},{"fr":"J'ai appris beaucoup de choses avec lui.","tgt":"تَعَلَّمْتُ مِنْهُ أَشْيَاءَ كَثِيرَةً.","ro":"Taʿallamtu minhu ashyāʾa kathīratan."},{"fr":"Nous nous parlerons chaque semaine en vidéo.","tgt":"سَنَتَحَادَثُ كُلَّ أُسْبُوعٍ بِالْفِيدْيُو.","ro":"Sanataḥādathu kulla usbūʿin bi-l-fīdyū."},{"fr":"On dit que les voyages enseignent beaucoup.","tgt":"يُقَالُ إِنَّ السَّفَرَ يُعَلِّمُ الْكَثِيرَ.","ro":"Yuqālu inna as-safara yuʿallimu al-kathīra."}],"tip":{"title":"Les formes dérivées du verbe : « allama », enseigner ; « saafara », voyager","example":"Il a enseigné dix ans à Tripoli. — <b>عَلَّمَ</b> عَشْرَ سَنَوَاتٍ فِي طَرَابُلُسَ.","body":"En arabe, presque chaque mot repose sur une racine de trois consonnes, et on fabrique de nouveaux verbes en modifiant le moule. Avec la racine du savoir, « alima », il a su, on double la lettre du milieu et on obtient « allama », il a fait savoir, donc il a enseigné. On ajoute encore « ta » devant et cela donne « taallama », il a appris. Avec le nom « safar », le voyage, on allonge la voyelle après la première lettre et on obtient « saafara », il a voyagé, d'où « musafir », le voyageur. Notre exemple dit simplement : il a enseigné, dix années, à Tripoli. Astuce : un son doublé fait souvent agir sur quelqu'un d'autre, un a allongé ajoute souvent l'idée d'un mouvement ou d'un échange.","exampleRo":"ʿAllama ʿashra sanawātin fī ṭarābulusa.","lit":"il-a-enseigné · dix · années · à · Tripoli","say":{"alima":"عَلِمَ","allama":"عَلَّمَ","taallama":"تَعَلَّمَ","safar":"سَفَر","saafara":"سَافَرَ","musafir":"مُسَافِر"}}},{"title":"Des amis partis à l'étranger","phrases":[{"fr":"Depuis que Nada est partie en France, elle me manque.","tgt":"مُنْذُ أَنْ سَافَرَتْ نَدَى إِلَى فَرَنْسَا أَشْتَاقُ إِلَيْهَا.","ro":"Mundhu an sāfarat nadā ilā faransā ashtāqu ilayhā."},{"fr":"Elle fait des études de médecine à Paris.","tgt":"تَدْرُسُ الطِّبَّ فِي بَارِيسَ.","ro":"Tadrusu aṭ-ṭibba fī bārīsa."},{"fr":"On s'écrit presque tous les jours.","tgt":"نَتَرَاسَلُ كُلَّ يَوْمٍ تَقْرِيبًا.","ro":"Natarāsalu kulla yawmin taqrīban."},{"fr":"Elle m'envoie des photos de la neige.","tgt":"تُرْسِلُ لِي صُوَرَ الثَّلْجِ.","ro":"Tursilu lī ṣuwara ath-thalji."},{"fr":"Et moi, je lui envoie des photos de la mer.","tgt":"وَأَنَا أُرْسِلُ لَهَا صُوَرَ الْبَحْرِ.","ro":"Wa-anā ursilu lahā ṣuwara al-baḥri."},{"fr":"Beaucoup de jeunes Libanais vivent à l'étranger.","tgt":"يَعِيشُ كَثِيرٌ مِنَ الشَّبَابِ اللُّبْنَانِيِّينَ فِي الْخَارِجِ.","ro":"Yaʿīshu kathīrun mina ash-shabābi al-lubnāniyyīna fī al-khāriji."},{"fr":"Mais ils reviennent souvent pour l'été.","tgt":"لَكِنَّهُمْ يَعُودُونَ غَالِبًا فِي الصَّيْفِ.","ro":"Lākinnahum yaʿūdūna ghāliban fī aṣ-ṣayfi."},{"fr":"Elle me demande toujours des nouvelles du quartier.","tgt":"تَسْأَلُنِي دَائِمًا عَنْ أَخْبَارِ الْحَيِّ.","ro":"Tasʾalunī dāʾiman ʿan akhbāri al-ḥayyi."},{"fr":"Je vais lui envoyer du zaatar et des olives.","tgt":"سَأُرْسِلُ لَهَا زَعْتَرًا وَزَيْتُونًا.","ro":"Saʾursilu lahā zaʿtaran wa-zaytūnan."},{"fr":"La distance ne change rien à notre amitié.","tgt":"الْمَسَافَةُ لَا تُغَيِّرُ شَيْئًا فِي صَدَاقَتِنَا.","ro":"Al-masāfatu lā tughayyiru shayʾan fī ṣadāqatinā."}]},{"title":"Donner son avis","phrases":[{"fr":"À mon avis, la musique d'aujourd'hui est trop bruyante.","tgt":"فِي رَأْيِي، مُوسِيقَى الْيَوْمِ صَاخِبَةٌ جِدًّا.","ro":"Fī raʾyī, mūsīqā al-yawmi ṣākhibatun jiddan."},{"fr":"Je ne suis pas du tout d'accord avec toi sur ce point.","tgt":"لَا أُوَافِقُكَ أَبَدًا فِي هَذِهِ النُّقْطَةِ.","ro":"Lā uwāfiquka abadan fī hādhihi an-nuqṭati."},{"fr":"Les jeunes chanteurs ont beaucoup de talent.","tgt":"لِلْمُغَنِّينَ الشَّبَابِ مَوْهِبَةٌ كَبِيرَةٌ.","ro":"Li-l-mughannīna ash-shabābi mawhibatun kabīratun."},{"fr":"C'est une question de goût, finalement.","tgt":"إِنَّهَا مَسْأَلَةُ ذَوْقٍ فِي النِّهَايَةِ.","ro":"Innahā masʾalatu dhawqin fī an-nihāyati."},{"fr":"Pour moi, Fairouz reste la plus grande voix.","tgt":"بِالنِّسْبَةِ إِلَيَّ، تَبْقَى فَيْرُوزُ أَعْظَمَ صَوْتٍ.","ro":"Bi-n-nisbati ilayya, tabqā fayrūzu aʿẓama ṣawtin."},{"fr":"Là, je suis complètement d'accord avec toi !","tgt":"هُنَا أُوَافِقُكَ تَمَامًا!","ro":"Hunā uwāfiquka tamāman!"},{"fr":"Et que penses-tu des réseaux sociaux ?","tgt":"وَمَا رَأْيُكَ فِي وَسَائِلِ التَّوَاصُلِ الِاجْتِمَاعِيِّ؟","ro":"Wa-mā raʾyuka fī wasāʾili at-tawāṣuli al-ijtimāʿiyyi?"},{"fr":"Ils sont utiles, mais on y passe trop de temps.","tgt":"هِيَ مُفِيدَةٌ، لَكِنَّنَا نَقْضِي فِيهَا وَقْتًا طَوِيلًا.","ro":"Hiya mufīdatun, lākinnanā naqḍī fīhā waqtan ṭawīlan."},{"fr":"Tu as raison, il faut savoir s'arrêter.","tgt":"مَعَكَ حَقٌّ، يَجِبُ أَنْ نَعْرِفَ مَتَى نَتَوَقَّفُ.","ro":"Maʿaka ḥaqqun, yajibu an naʿrifa matā natawaqqafu."},{"fr":"J'aime discuter avec toi, même quand on n'est pas d'accord.","tgt":"أُحِبُّ النِّقَاشَ مَعَكَ حَتَّى عِنْدَمَا نَخْتَلِفُ.","ro":"Uḥibbu an-niqāsha maʿaka ḥattā ʿindamā nakhtalifu."}]},{"title":"Une fête d'anniversaire","phrases":[{"fr":"Samedi, c'est l'anniversaire de Maya.","tgt":"يَوْمُ السَّبْتِ هُوَ عِيدُ مِيلَادِ مَايَا.","ro":"Yawmu as-sabti huwa ʿīdu mīlādi māyā."},{"fr":"Nous lui préparons une fête surprise.","tgt":"نُحَضِّرُ لَهَا حَفْلَةً مُفَاجِئَةً.","ro":"Nuḥaḍḍiru lahā ḥaflatan mufājiʾatan."},{"fr":"Surtout, ne lui dis rien !","tgt":"لَا تَقُلْ لَهَا شَيْئًا أَبَدًا!","ro":"Lā taqul lahā shayʾan abadan!"},{"fr":"Son frère l'emmènera dîner à Byblos.","tgt":"سَيَأْخُذُهَا أَخُوهَا إِلَى الْعَشَاءِ فِي جُبَيْلَ.","ro":"Sayaʾkhudhuhā akhūhā ilā al-ʿashāʾi fī jubayla."},{"fr":"Pendant ce temps, nous décorerons l'appartement.","tgt":"فِي هَذِهِ الْأَثْنَاءِ سَنُزَيِّنُ الشَّقَّةَ.","ro":"Fī hādhihi al-athnāʾi sanuzayyinu ash-shaqqata."},{"fr":"J'ai commandé un gâteau au chocolat et à la pistache.","tgt":"طَلَبْتُ كَعْكَةً بِالشُّوكُولَاتَةِ وَالْفُسْتُقِ.","ro":"Ṭalabtu kaʿkatan bi-sh-shūkūlātati wa-l-fustuqi."},{"fr":"Combien d'invités avez-vous appelés ?","tgt":"كَمْ ضَيْفًا دَعَوْتُمْ؟","ro":"Kam ḍayfan daʿawtum?"},{"fr":"Une vingtaine, surtout des amis de l'université.","tgt":"نَحْوَ عِشْرِينَ، مُعْظَمُهُمْ مِنْ أَصْدِقَاءِ الْجَامِعَةِ.","ro":"Naḥwa ʿishrīna, muʿẓamuhum min aṣdiqāʾi al-jāmiʿati."},{"fr":"Quand elle ouvrira la porte, criez « surprise » !","tgt":"عِنْدَمَا تَفْتَحُ الْبَابَ، اُصْرُخُوا: «مُفَاجَأَةٌ»!","ro":"ʿIndamā taftaḥu al-bāba, uṣrukhū: «mufājaʾatun»!"},{"fr":"Elle était si contente qu'elle a pleuré.","tgt":"كَانَتْ سَعِيدَةً جِدًّا حَتَّى إِنَّهَا بَكَتْ.","ro":"Kānat saʿīdatan jiddan ḥattā innahā bakat."}]},{"title":"Les gens du quartier","phrases":[{"fr":"Notre voisin est un écrivain connu.","tgt":"جَارُنَا كَاتِبٌ مَعْرُوفٌ.","ro":"Jārunā kātibun maʿrūfun."},{"fr":"Le gardien de l'immeuble connaît tout le monde.","tgt":"حَارِسُ الْعِمَارَةِ يَعْرِفُ الْجَمِيعَ.","ro":"Ḥārisu al-ʿimārati yaʿrifu al-jamīʿa."},{"fr":"Les habitants de la rue se connaissent depuis des années.","tgt":"سُكَّانُ الشَّارِعِ يَعْرِفُ بَعْضُهُمْ بَعْضًا مُنْذُ سَنَوَاتٍ.","ro":"Sukkānu ash-shāriʿi yaʿrifu baʿḍuhum baʿḍan mundhu sanawātin."},{"fr":"Le fils du coiffeur est joueur de football.","tgt":"اِبْنُ الْحَلَّاقِ لَاعِبُ كُرَةِ قَدَمٍ.","ro":"Ibnu al-ḥallāqi lāʿibu kurati qadamin."},{"fr":"Il y a toujours des visiteurs chez Oum Sami.","tgt":"هُنَاكَ دَائِمًا زَائِرُونَ عِنْدَ أُمِّ سَامِي.","ro":"Hunāka dāʾiman zāʾirūna ʿinda ummi sāmī."},{"fr":"Le chauffeur de taxi nous raconte les nouvelles du jour.","tgt":"سَائِقُ التَّاكْسِي يَحْكِي لَنَا أَخْبَارَ الْيَوْمِ.","ro":"Sāʾiqu at-tāksī yaḥkī lanā akhbāra al-yawmi."},{"fr":"Ma voisine est une excellente joueuse de oud.","tgt":"جَارَتِي عَازِفَةُ عُودٍ مُمْتَازَةٌ.","ro":"Jāratī ʿāzifatu ʿūdin mumtāzatun."},{"fr":"Le soir, elle est souvent assise sur son balcon.","tgt":"فِي الْمَسَاءِ تَكُونُ غَالِبًا جَالِسَةً عَلَى شُرْفَتِهَا.","ro":"Fī al-masāʾi takūnu ghāliban jālisatan ʿalā shurfatihā."},{"fr":"Le marchand de légumes est la personne la plus gentille du quartier.","tgt":"بَائِعُ الْخُضَارِ أَلْطَفُ شَخْصٍ فِي الْحَيِّ.","ro":"Bāʾiʿu al-khuḍāri alṭafu shakhṣin fī al-ḥayyi."},{"fr":"Je suis sûr que tu vas aimer l'endroit.","tgt":"أَنَا وَاثِقٌ مِنْ أَنَّكَ سَتُحِبُّ الْمَكَانَ.","ro":"Anā wāthiqun min annaka satuḥibbu al-makāna."}],"tip":{"title":"Le participe actif : « katib », celui qui écrit","example":"Notre voisin est un écrivain connu. — جَارُنَا <b>كَاتِبٌ</b> مَعْرُوفٌ.","body":"À partir d'un verbe simple, l'arabe fabrique très facilement le nom de celui qui fait l'action : on met un a long après la première lettre et un i après la deuxième. Ainsi « kataba », il a écrit, donne « katib », celui qui écrit, c'est-à-dire l'écrivain. Notre exemple se lit mot à mot : notre voisin, écrivain, connu, toujours sans verbe être. Sur le même modèle, « laiba », il a joué, donne « laib », le joueur, « sakana », il a habité, donne « sakin », l'habitant, et « haris » est celui qui garde. Au féminin, on ajoute simplement a : « katiba », l'écrivaine. Astuce : dès que tu entends ce rythme long-court, « faa-il », pense à celui qui fait.","exampleRo":"Jārunā kātibun maʿrūfun.","lit":"voisin-de-nous · écrivain · connu","say":{"kataba":"كَتَبَ","katib":"كَاتِب","laiba":"لَعِبَ","laib":"لَاعِب","sakana":"سَكَنَ","sakin":"سَاكِن","haris":"حَارِس","katiba":"كَاتِبَة"}}},{"title":"Retrouvailles à Beyrouth","phrases":[{"fr":"Nada est rentrée de France pour les vacances !","tgt":"عَادَتْ نَدَى مِنْ فَرَنْسَا لِقَضَاءِ الْعُطْلَةِ!","ro":"ʿĀdat nadā min faransā li-qaḍāʾi al-ʿuṭlati!"},{"fr":"Tous les amis se sont réunis sur la corniche.","tgt":"اِجْتَمَعَ الْأَصْدِقَاءُ كُلُّهُمْ عَلَى الْكُورْنِيشِ.","ro":"Ijtamaʿa al-aṣdiqāʾu kulluhum ʿalā al-kūrnīshi."},{"fr":"Nada, tu n'as pas changé du tout !","tgt":"يَا نَدَى، لَمْ تَتَغَيَّرِي أَبَدًا!","ro":"Yā nadā, lam tataghayyarī abadan!"},{"fr":"Toi non plus, mais tes cheveux sont plus courts.","tgt":"وَأَنْتَ أَيْضًا، لَكِنَّ شَعْرَكَ أَقْصَرُ.","ro":"Wa-anta ayḍan, lākinna shaʿraka aqṣaru."},{"fr":"Raconte-nous ta vie là-bas, Nada.","tgt":"اِحْكِي لَنَا عَنْ حَيَاتِكِ هُنَاكَ يَا نَدَى.","ro":"Iḥkī lanā ʿan ḥayātiki hunāka yā nadā."},{"fr":"Le travail est dur, mais j'aime beaucoup la ville.","tgt":"الْعَمَلُ صَعْبٌ، لَكِنَّنِي أُحِبُّ الْمَدِينَةَ كَثِيرًا.","ro":"Al-ʿamalu ṣaʿbun, lākinnanī uḥibbu al-madīnata kathīran."},{"fr":"Le soleil et la mer de Beyrouth me manquaient.","tgt":"كُنْتُ أَشْتَاقُ إِلَى شَمْسِ بَيْرُوتَ وَبَحْرِهَا.","ro":"Kuntu ashtāqu ilā shamsi bayrūta wa-baḥrihā."},{"fr":"Et surtout, la manouché du matin m'a manqué !","tgt":"وَاشْتَقْتُ خُصُوصًا إِلَى مَنَاقِيشِ الصَّبَاحِ!","ro":"Wa-shtaqtu khuṣūṣan ilā manāqīshi aṣ-ṣabāḥi!"},{"fr":"Restons ensemble jusqu'au coucher du soleil.","tgt":"هَيَّا نَبْقَى مَعًا حَتَّى غُرُوبِ الشَّمْسِ.","ro":"Hayyā nabqā maʿan ḥattā ghurūbi ash-shamsi."},{"fr":"Ces moments sont plus précieux que tout l'or du monde.","tgt":"هَذِهِ اللَّحَظَاتُ أَغْلَى مِنْ ذَهَبِ الْعَالَمِ.","ro":"Hādhihi al-laḥaẓātu aghlā min dhahabi al-ʿālami."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a appris à parler de nos amis et de nos fêtes.","tgt":"عَلَّمَتْنَا هَذِهِ الْوَحْدَةُ أَنْ نَتَحَدَّثَ عَنْ أَصْدِقَائِنَا وَحَفَلَاتِنَا.","ro":"ʿAllamatnā hādhihi al-waḥdatu an nataḥaddatha ʿan aṣdiqāʾinā wa-ḥafalātinā."},{"fr":"Maintenant, tu sais exprimer ton avis en arabe.","tgt":"الْآنَ تَسْتَطِيعُ أَنْ تُعَبِّرَ عَنْ رَأْيِكَ بِالْعَرَبِيَّةِ.","ro":"Al-āna tastaṭīʿu an tuʿabbira ʿan raʾyika bi-l-ʿarabiyyati."},{"fr":"Tu peux raconter tes souvenirs au passé.","tgt":"تَسْتَطِيعُ أَنْ تَحْكِيَ ذِكْرَيَاتِكَ بِصِيغَةِ الْمَاضِي.","ro":"Tastaṭīʿu an taḥkiya dhikrayātika bi-ṣīghati al-māḍī."},{"fr":"Tu sais aussi dire ce que tu ne feras jamais.","tgt":"وَتَعْرِفُ أَيْضًا كَيْفَ تَقُولُ مَا لَنْ تَفْعَلَهُ أَبَدًا.","ro":"Wa-taʿrifu ayḍan kayfa taqūlu mā lan tafʿalahu abadan."},{"fr":"Les verbes dérivés ne sont plus un mystère pour toi.","tgt":"لَمْ تَعُدِ الْأَفْعَالُ الْمَزِيدَةُ سِرًّا عَلَيْكَ.","ro":"Lam taʿudi al-afʿālu al-mazīdatu sirran ʿalayka."},{"fr":"Ce deuxième niveau se termine ici.","tgt":"يَنْتَهِي هُنَا الْمُسْتَوَى الثَّانِي.","ro":"Yantahī hunā al-mustawā ath-thānī."},{"fr":"L'arabe est devenu peu à peu plus facile pour toi.","tgt":"أَصْبَحَتِ الْعَرَبِيَّةُ أَسْهَلَ عَلَيْكَ شَيْئًا فَشَيْئًا.","ro":"Aṣbaḥati al-ʿarabiyyatu ashala ʿalayka shayʾan fa-shayʾan."},{"fr":"Le niveau suivant t'attend avec de nouveaux défis.","tgt":"يَنْتَظِرُكَ الْمُسْتَوَى التَّالِي بِتَحَدِّيَاتٍ جَدِيدَةٍ.","ro":"Yantaẓiruka al-mustawā at-tālī bi-taḥaddiyātin jadīdatin."},{"fr":"Bravo pour tous tes efforts !","tgt":"أَحْسَنْتَ عَلَى كُلِّ جُهُودِكَ!","ro":"Aḥsanta ʿalā kulli juhūdika!"},{"fr":"À bientôt, et bonne continuation en arabe !","tgt":"إِلَى اللِّقَاءِ قَرِيبًا، وَبِالتَّوْفِيقِ فِي الْعَرَبِيَّةِ!","ro":"Ilā al-liqāʾi qarīban, wa-bi-t-tawfīqi fī al-ʿarabiyyati!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée dans le monde arabe, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un nouveau contrat de travail","phrases":[{"fr":"Le contrat a été signé hier matin.","tgt":"وُقِّعَ الْعَقْدُ صَبَاحَ أَمْسِ.","ro":"Wuqqiʿa al-ʿaqdu ṣabāḥa amsi."},{"fr":"Mon salaire sera versé à la fin de chaque mois.","tgt":"سَيُدْفَعُ رَاتِبِي فِي نِهَايَةِ كُلِّ شَهْرٍ.","ro":"Sa-yudfaʿu rātibī fī nihāyati kulli shahrin."},{"fr":"Le contrat a été écrit en arabe et en français.","tgt":"كُتِبَ الْعَقْدُ بِالْعَرَبِيَّةِ وَالْفَرَنْسِيَّةِ.","ro":"Kutiba al-ʿaqdu bil-ʿarabiyyati wal-faransiyyati."},{"fr":"On m'a donné un badge pour entrer dans l'immeuble.","tgt":"أُعْطِيتُ بِطَاقَةً لِدُخُولِ الْمَبْنَى.","ro":"Uʿṭītu biṭāqatan li-dukhūli al-mabnā."},{"fr":"La date de début a été reportée d'une semaine.","tgt":"أُجِّلَ تَارِيخُ الْبَدْءِ أُسْبُوعًا.","ro":"Ujjila tārīkhu al-badʾi usbūʿan."},{"fr":"Une copie de mon passeport a été demandée.","tgt":"طُلِبَتْ نُسْخَةٌ مِنْ جَوَازِ سَفَرِي.","ro":"Ṭulibat nuskhatun min jawāzi safarī."},{"fr":"Les horaires de travail ont été précisés à l'article cinq.","tgt":"حُدِّدَتْ سَاعَاتُ الْعَمَلِ فِي الْمَادَّةِ الْخَامِسَةِ.","ro":"Ḥuddidat sāʿātu al-ʿamali fī al-māddati al-khāmisati."},{"fr":"Mon bureau a été préparé avant mon arrivée.","tgt":"جُهِّزَ مَكْتَبِي قَبْلَ وُصُولِي.","ro":"Juhhiza maktabī qabla wuṣūlī."},{"fr":"J'ai été accueilli chaleureusement par toute l'équipe.","tgt":"اسْتُقْبِلْتُ بِحَرَارَةٍ مِنْ قِبَلِ الْفَرِيقِ كُلِّهِ.","ro":"Ustuqbiltu bi-ḥarāratin min qibali al-farīqi kullihi."},{"fr":"On dit que cette entreprise est l'une des meilleures de Dubaï.","tgt":"يُقَالُ إِنَّ هَذِهِ الشَّرِكَةَ مِنْ أَفْضَلِ الشَّرِكَاتِ فِي دُبَيّ.","ro":"Yuqālu inna hādhihi ash-sharikata min afḍali ash-sharikāti fī Dubayy."}],"tip":{"title":"Le passif : « kutiba », il a été écrit","example":"Le contrat a été écrit en arabe et en français. — <b>كُتِبَ</b> الْعَقْدُ بِالْعَرَبِيَّةِ وَالْفَرَنْسِيَّةِ.","body":"Pour dire qu'une chose a été faite sans dire par qui, l'arabe n'a pas besoin d'auxiliaire comme le français : il change simplement les voyelles du verbe. « Kataba », il a écrit, devient « kutiba », il a été écrit : on met un son « ou » sur la première lettre et un son « i » sur l'avant-dernière. « Kutiba al-aqdu » se dit donc littéralement : a-été-écrit, le contrat. Au présent, la musique devient « you… a… » : « yuktabu », il est écrit, ou « yudfau », il est versé. Retenez ce petit air « ou-i » du passif, comme dans « tulibat », elle a été demandée, et « juhhiza », il a été préparé.","exampleRo":"Kutiba al-ʿaqdu bil-ʿarabiyyati wal-faransiyyati.","lit":"a-été-écrit · le-contrat · en-l'arabe · et-le-français","say":{"Kataba":"كَتَبَ","kutiba":"كُتِبَ","yuktabu":"يُكْتَبُ","yudfau":"يُدْفَعُ","tulibat":"طُلِبَتْ","juhhiza":"جُهِّزَ","Kutiba al-aqdu":"كُتِبَ الْعَقْدُ"}}},{"title":"La première réunion d'équipe","phrases":[{"fr":"La réunion commence à neuf heures précises.","tgt":"يَبْدَأُ الِاجْتِمَاعُ فِي السَّاعَةِ التَّاسِعَةِ تَمَامًا.","ro":"Yabdaʾu al-ijtimāʿu fī as-sāʿati at-tāsiʿati tamāman."},{"fr":"Le directeur a présenté les objectifs de cette année.","tgt":"عَرَضَ الْمُدِيرُ أَهْدَافَ هَذِهِ السَّنَةِ.","ro":"ʿAraḍa al-mudīru ahdāfa hādhihi as-sanati."},{"fr":"Chacun a parlé de son projet pendant cinq minutes.","tgt":"تَحَدَّثَ كُلُّ وَاحِدٍ عَنْ مَشْرُوعِهِ خَمْسَ دَقَائِقَ.","ro":"Taḥaddatha kullu wāḥidin ʿan mashrūʿihi khamsa daqāʾiqa."},{"fr":"Ma collègue Fatima a pris des notes.","tgt":"دَوَّنَتْ زَمِيلَتِي فَاطِمَةُ الْمُلَاحَظَاتِ.","ro":"Dawwanat zamīlatī Fāṭimatu al-mulāḥaẓāti."},{"fr":"Je n'ai pas compris tous les termes techniques.","tgt":"لَمْ أَفْهَمْ كُلَّ الْمُصْطَلَحَاتِ التِّقْنِيَّةِ.","ro":"Lam afham kulla al-muṣṭalaḥāti at-tiqniyyati."},{"fr":"Pourriez-vous répéter la dernière idée, s'il vous plaît ?","tgt":"هَلْ يُمْكِنُكَ أَنْ تُعِيدَ الْفِكْرَةَ الْأَخِيرَةَ مِنْ فَضْلِكَ؟","ro":"Hal yumkinuka an tuʿīda al-fikrata al-akhīrata min faḍlika?"},{"fr":"La prochaine réunion se tiendra à distance.","tgt":"سَيُعْقَدُ الِاجْتِمَاعُ الْقَادِمُ عَنْ بُعْدٍ.","ro":"Sa-yuʿqadu al-ijtimāʿu al-qādimu ʿan buʿdin."},{"fr":"Il y avait du café et des dattes dans la salle.","tgt":"كَانَتِ الْقَهْوَةُ وَالتَّمْرُ فِي الْقَاعَةِ.","ro":"Kānati al-qahwatu wat-tamru fī al-qāʿati."},{"fr":"Mon responsable m'a demandé un rapport avant jeudi.","tgt":"طَلَبَ مِنِّي مَسْؤُولِي تَقْرِيرًا قَبْلَ يَوْمِ الْخَمِيسِ.","ro":"Ṭalaba minnī masʾūlī taqrīran qabla yawmi al-khamīsi."},{"fr":"La réunion s'est terminée plus tôt que prévu.","tgt":"انْتَهَى الِاجْتِمَاعُ قَبْلَ الْمَوْعِدِ الْمُتَوَقَّعِ.","ro":"Intahā al-ijtimāʿu qabla al-mawʿidi al-mutawaqqaʿi."}]},{"title":"Les codes de l'entreprise","phrases":[{"fr":"J'ai appris beaucoup de choses durant ma première semaine.","tgt":"تَعَلَّمْتُ أَشْيَاءَ كَثِيرَةً فِي أُسْبُوعِي الْأَوَّلِ.","ro":"Taʿallamtu ashyāʾa kathīratan fī usbūʿī al-awwali."},{"fr":"J'ai fait la connaissance de mes collègues autour d'un café.","tgt":"تَعَرَّفْتُ عَلَى زُمَلَائِي حَوْلَ فِنْجَانِ قَهْوَةٍ.","ro":"Taʿarraftu ʿalā zumalāʾī ḥawla finjāni qahwatin."},{"fr":"La réceptionniste accueille les clients avec le sourire.","tgt":"تَسْتَقْبِلُ مُوَظَّفَةُ الِاسْتِقْبَالِ الْعُمَلَاءَ بِابْتِسَامَةٍ.","ro":"Tastaqbilu muwaẓẓafatu al-istiqbāli al-ʿumalāʾa bi-btisāmatin."},{"fr":"Nous utilisons une application pour réserver les salles.","tgt":"نَسْتَخْدِمُ تَطْبِيقًا لِحَجْزِ الْقَاعَاتِ.","ro":"Nastakhdimu taṭbīqan li-ḥajzi al-qāʿāti."},{"fr":"Les employés échangent les informations par courriel.","tgt":"يَتَبَادَلُ الْمُوَظَّفُونَ الْمَعْلُومَاتِ بِالْبَرِيدِ الْإِلِكْتُرُونِيِّ.","ro":"Yatabādalu al-muwaẓẓafūna al-maʿlūmāti bil-barīdi al-iliktrūniyyi."},{"fr":"Je me suis habitué aux longues journées de travail.","tgt":"تَعَوَّدْتُ عَلَى أَيَّامِ الْعَمَلِ الطَّوِيلَةِ.","ro":"Taʿawwadtu ʿalā ayyāmi al-ʿamali aṭ-ṭawīlati."},{"fr":"J'ai demandé l'avis de mon chef avant de répondre au client.","tgt":"اسْتَشَرْتُ مُدِيرِي قَبْلَ أَنْ أُجِيبَ الْعَمِيلَ.","ro":"Istashartu mudīrī qabla an ujība al-ʿamīla."},{"fr":"Je profite beaucoup de l'expérience de mes collègues.","tgt":"أَسْتَفِيدُ كَثِيرًا مِنْ خِبْرَةِ زُمَلَائِي.","ro":"Astafīdu kathīran min khibrati zumalāʾī."},{"fr":"Nous coopérons quand le travail s'accumule.","tgt":"نَتَعَاوَنُ عِنْدَمَا يَتَرَاكَمُ الْعَمَلُ.","ro":"Nataʿāwanu ʿindamā yatarākamu al-ʿamalu."},{"fr":"Il faut toujours se préparer avant chaque présentation.","tgt":"يَجِبُ أَنْ نَسْتَعِدَّ دَائِمًا قَبْلَ أَيِّ عَرْضٍ.","ro":"Yajibu an nastaʿidda dāʾiman qabla ayyi ʿarḍin."}],"tip":{"title":"Les formes dérivées avec « ta- » et « ista- » : « taallama, istaqbala »","example":"La réceptionniste accueille les clients avec le sourire. — <b>تَسْتَقْبِلُ</b> مُوَظَّفَةُ الِاسْتِقْبَالِ الْعُمَلَاءَ بِابْتِسَامَةٍ.","body":"Beaucoup de verbes arabes se fabriquent en ajoutant un petit préfixe à une racine. Avec « ta- », l'action revient sur soi ou devient réciproque : « allama », enseigner, donne « taallama », apprendre, c'est-à-dire s'enseigner à soi-même, et « taawana » veut dire coopérer, s'aider les uns les autres. Avec « ista- », on demande ou on va chercher quelque chose : « istashara », demander conseil, ou « istafada », tirer profit. « Tastaqbilu al-umala » se dit littéralement : elle accueille, les clients ; et le mot « istiqbal », l'accueil, vient de la même famille. Retenez l'image : « ta- » renvoie l'action vers soi, « ista- » part la chercher.","exampleRo":"Tastaqbilu muwaẓẓafatu al-istiqbāli al-ʿumalāʾa bi-btisāmatin.","lit":"accueille · employée · l'accueil · les-clients · avec-un-sourire","say":{"allama":"عَلَّمَ","taallama":"تَعَلَّمَ","taawana":"تَعَاوَنَ","istashara":"اِسْتَشَارَ","istafada":"اِسْتَفَادَ","istiqbal":"اِسْتِقْبَال","taallama, istaqbala":"تَعَلَّمَ، اِسْتَقْبَلَ","Tastaqbilu al-umala":"تَسْتَقْبِلُ الْعُمَلَاءَ"}}},{"title":"Chercher un appartement à Dubaï","phrases":[{"fr":"Je cherche un appartement de deux chambres près du métro.","tgt":"أَبْحَثُ عَنْ شَقَّةٍ بِغُرْفَتَيْ نَوْمٍ قُرْبَ الْمِتْرُو.","ro":"Abḥathu ʿan shaqqatin bi-ghurfatay nawmin qurba al-mitrū."},{"fr":"Le loyer se paie souvent en un ou deux chèques par an.","tgt":"يُدْفَعُ الْإِيجَارُ غَالِبًا بِشِيكٍ أَوْ شِيكَيْنِ فِي السَّنَةِ.","ro":"Yudfaʿu al-ījāru ghāliban bi-shīkin aw shīkayni fī as-sanati."},{"fr":"Les loyers à Dubaï Marina sont très élevés.","tgt":"الْإِيجَارَاتُ فِي دُبَيّ مَارِينَا مُرْتَفِعَةٌ جِدًّا.","ro":"Al-ījārātu fī Dubayy Mārīnā murtafiʿatun jiddan."},{"fr":"Un agent immobilier m'a montré trois appartements.","tgt":"أَرَانِي وَكِيلٌ عَقَارِيٌّ ثَلَاثَ شُقَقٍ.","ro":"Arānī wakīlun ʿaqāriyyun thalātha shuqaqin."},{"fr":"Le deuxième était ensoleillé mais un peu bruyant.","tgt":"كَانَتِ الثَّانِيَةُ مُشْمِسَةً لَكِنَّهَا صَاخِبَةٌ قَلِيلًا.","ro":"Kānati ath-thāniyatu mushmisatan lākinnahā ṣākhibatun qalīlan."},{"fr":"Est-ce que la place de parking est comprise dans le prix ?","tgt":"هَلْ مَوْقِفُ السَّيَّارَةِ مَشْمُولٌ فِي السِّعْرِ؟","ro":"Hal mawqifu as-sayyārati mashmūlun fī as-siʿri?"},{"fr":"Le propriétaire demande un dépôt de garantie de cinq pour cent.","tgt":"يَطْلُبُ الْمَالِكُ تَأْمِينًا بِنِسْبَةِ خَمْسَةٍ فِي الْمِئَةِ.","ro":"Yaṭlubu al-māliku taʾmīnan bi-nisbati khamsatin fī al-miʾati."},{"fr":"Je préfère habiter près de mon bureau pour éviter les embouteillages.","tgt":"أُفَضِّلُ السَّكَنَ قُرْبَ مَكْتَبِي لِأَتَجَنَّبَ الزَّحْمَةَ.","ro":"Ufaḍḍilu as-sakana qurba maktabī li-atajannaba az-zaḥmata."},{"fr":"Le bail doit être enregistré dans le système Ejari.","tgt":"يَجِبُ تَسْجِيلُ عَقْدِ الْإِيجَارِ فِي نِظَامِ إِيجَارِي.","ro":"Yajibu tasjīlu ʿaqdi al-ījāri fī niẓāmi Ījārī."},{"fr":"Finalement, nous avons choisi un appartement à Al Barsha.","tgt":"فِي النِّهَايَةِ، اخْتَرْنَا شَقَّةً فِي الْبَرْشَاءِ.","ro":"Fī an-nihāyati, ikhtarnā shaqqatan fī al-Barshāʾi."}]},{"title":"Coincé dans les embouteillages","phrases":[{"fr":"Si j'habitais plus près, je viendrais à pied.","tgt":"لَوْ كُنْتُ أَسْكُنُ قَرِيبًا لَجِئْتُ مَشْيًا.","ro":"Law kuntu askunu qarīban la-jiʾtu mashyan."},{"fr":"Si j'étais parti plus tôt, je n'aurais pas été en retard.","tgt":"لَوْ خَرَجْتُ مُبَكِّرًا لَمَا تَأَخَّرْتُ.","ro":"Law kharajtu mubakkiran lamā taʾakhkhartu."},{"fr":"La route Sheikh Zayed est saturée tous les matins.","tgt":"شَارِعُ الشَّيْخِ زَايِدٍ مُزْدَحِمٌ كُلَّ صَبَاحٍ.","ro":"Shāriʿu ash-shaykhi Zāyidin muzdaḥimun kulla ṣabāḥin."},{"fr":"Si je prenais le métro, je gagnerais une heure par jour.","tgt":"لَوْ رَكِبْتُ الْمِتْرُو لَوَفَّرْتُ سَاعَةً كُلَّ يَوْمٍ.","ro":"Law rakibtu al-mitrū la-waffartu sāʿatan kulla yawmin."},{"fr":"Si tu avais écouté les informations, tu aurais su qu'il y avait un accident.","tgt":"لَوْ سَمِعْتَ الْأَخْبَارَ لَعَرَفْتَ أَنَّ هُنَاكَ حَادِثًا.","ro":"Law samiʿta al-akhbāra la-ʿarafta anna hunāka ḥādithan."},{"fr":"Le trajet entre Dubaï et Abou Dhabi prend parfois deux heures.","tgt":"يَسْتَغْرِقُ الطَّرِيقُ بَيْنَ دُبَيّ وَأَبُوظَبْي سَاعَتَيْنِ أَحْيَانًا.","ro":"Yastaghriqu aṭ-ṭarīqu bayna Dubayy wa-Abū Ẓabī sāʿatayni aḥyānan."},{"fr":"Si la route était dégagée, nous arriverions en une demi-heure.","tgt":"لَوْ كَانَ الطَّرِيقُ فَارِغًا لَوَصَلْنَا فِي نِصْفِ سَاعَةٍ.","ro":"Law kāna aṭ-ṭarīqu fārighan la-waṣalnā fī niṣfi sāʿatin."},{"fr":"J'écoute des leçons d'arabe dans la voiture.","tgt":"أَسْتَمِعُ إِلَى دُرُوسٍ فِي الْعَرَبِيَّةِ فِي السَّيَّارَةِ.","ro":"Astamiʿu ilā durūsin fī al-ʿarabiyyati fī as-sayyārati."},{"fr":"Si c'était possible, je travaillerais de la maison tous les jours.","tgt":"لَوْ كَانَ ذَلِكَ مُمْكِنًا لَعَمِلْتُ مِنَ الْبَيْتِ كُلَّ يَوْمٍ.","ro":"Law kāna dhālika mumkinan la-ʿamiltu mina al-bayti kulla yawmin."},{"fr":"S'il y avait moins de voitures, la route serait plus rapide.","tgt":"لَوْ كَانَتِ السَّيَّارَاتُ أَقَلَّ لَكَانَ الطَّرِيقُ أَسْرَعَ.","ro":"Law kānati as-sayyārātu aqalla la-kāna aṭ-ṭarīqu asraʿa."}],"tip":{"title":"« Law » : si, pour l'irréel","example":"Si j'étais parti plus tôt, je n'aurais pas été en retard. — <b>لَوْ</b> خَرَجْتُ مُبَكِّرًا <b>لَمَا</b> تَأَخَّرْتُ.","body":"Pour une hypothèse irréelle, qui ne s'est pas réalisée ou qui reste un rêve, l'arabe utilise « law », si, suivi d'un verbe au passé ; la conséquence commence par « la- », collé au verbe suivant. « Law kharajtu mubakkiran lama taakhkhartu » se dit littéralement : si je suis sorti tôt, alors ne pas je me suis retardé. À la forme négative, « la- » devient « lama ». Le même passé sert pour le présent et pour le passé : « law rakibtu al-mitro la-waffartu saatan » veut dire si je prenais le métro, je gagnerais une heure, ou si je l'avais pris, j'aurais gagné une heure. Pensez à « law » comme au rêve et à « la- » comme à sa conséquence.","exampleRo":"Law kharajtu mubakkiran lamā taʾakhkhartu.","lit":"si · je-suis-sorti · tôt · [alors] ne… pas · je-me-suis-retardé","say":{"Law":"لَوْ","law":"لَوْ","lama":"لَمَا","law rakibtu al-mitro la-waffartu saatan":"لَوْ رَكِبْتُ الْمِتْرُو لَوَفَّرْتُ سَاعَةً","Law kharajtu mubakkiran lama taakhkhartu":"لَوْ خَرَجْتُ مُبَكِّرًا لَمَا تَأَخَّرْتُ"}}},{"title":"Le métro de Dubaï","phrases":[{"fr":"Le métro de Dubaï fonctionne sans conducteur.","tgt":"يَعْمَلُ مِتْرُو دُبَيّ بِلَا سَائِقٍ.","ro":"Yaʿmalu mitrū Dubayy bi-lā sāʾiqin."},{"fr":"Je recharge ma carte Nol chaque semaine.","tgt":"أُعَبِّئُ رَصِيدَ بِطَاقَةِ نُولْ كُلَّ أُسْبُوعٍ.","ro":"Uʿabbiʾu raṣīda biṭāqati Nūl kulla usbūʿin."},{"fr":"Il y a une voiture réservée aux femmes et aux enfants.","tgt":"هُنَاكَ عَرَبَةٌ مُخَصَّصَةٌ لِلنِّسَاءِ وَالْأَطْفَالِ.","ro":"Hunāka ʿarabatun mukhaṣṣaṣatun lin-nisāʾi wal-aṭfāli."},{"fr":"Il est interdit de manger et de boire dans le métro.","tgt":"يُمْنَعُ الْأَكْلُ وَالشُّرْبُ فِي الْمِتْرُو.","ro":"Yumnaʿu al-aklu wash-shurbu fī al-mitrū."},{"fr":"La ligne rouge relie l'aéroport au centre-ville.","tgt":"يَرْبِطُ الْخَطُّ الْأَحْمَرُ الْمَطَارَ بِوَسَطِ الْمَدِينَةِ.","ro":"Yarbiṭu al-khaṭṭu al-aḥmaru al-maṭāra bi-wasaṭi al-madīnati."},{"fr":"À quelle station faut-il changer pour la ligne verte ?","tgt":"فِي أَيِّ مَحَطَّةٍ يَجِبُ أَنْ أُغَيِّرَ إِلَى الْخَطِّ الْأَخْضَرِ؟","ro":"Fī ayyi maḥaṭṭatin yajibu an ughayyira ilā al-khaṭṭi al-akhḍari?"},{"fr":"Les stations sont climatisées, heureusement.","tgt":"الْمَحَطَّاتُ مُكَيَّفَةٌ لِحُسْنِ الْحَظِّ.","ro":"Al-maḥaṭṭātu mukayyafatun li-ḥusni al-ḥaẓẓi."},{"fr":"Aux heures de pointe, les rames sont bondées.","tgt":"فِي سَاعَاتِ الذُّرْوَةِ تَكُونُ الْقِطَارَاتُ مُزْدَحِمَةً.","ro":"Fī sāʿāti adh-dhurwati takūnu al-qiṭārātu muzdaḥimatan."},{"fr":"Je descends à la station Burj Khalifa.","tgt":"أَنْزِلُ فِي مَحَطَّةِ بُرْجِ خَلِيفَةَ.","ro":"Anzilu fī maḥaṭṭati Burji Khalīfata."},{"fr":"Le tramway dessert le quartier de la Marina.","tgt":"يَخْدُمُ التِّرَامُ مِنْطَقَةَ الْمَارِينَا.","ro":"Yakhdumu at-tirāmu minṭaqata al-Mārīnā."}]},{"title":"Ouvrir un compte en banque","phrases":[{"fr":"Je voudrais ouvrir un compte courant.","tgt":"أُرِيدُ أَنْ أَفْتَحَ حِسَابًا جَارِيًا.","ro":"Urīdu an aftaḥa ḥisāban jāriyan."},{"fr":"La banque exige une lettre de mon employeur.","tgt":"يَطْلُبُ الْمَصْرِفُ رِسَالَةً مِنْ صَاحِبِ الْعَمَلِ.","ro":"Yaṭlubu al-maṣrifu risālatan min ṣāḥibi al-ʿamali."},{"fr":"Mon salaire doit être viré sur ce compte.","tgt":"يَجِبُ أَنْ يُحَوَّلَ رَاتِبِي إِلَى هَذَا الْحِسَابِ.","ro":"Yajibu an yuḥawwala rātibī ilā hādhā al-ḥisābi."},{"fr":"Quels sont les frais mensuels de ce compte ?","tgt":"مَا الرُّسُومُ الشَّهْرِيَّةُ لِهَذَا الْحِسَابِ؟","ro":"Mā ar-rusūmu ash-shahriyyatu li-hādhā al-ḥisābi?"},{"fr":"Le solde minimum est de trois mille dirhams.","tgt":"الْحَدُّ الْأَدْنَى لِلرَّصِيدِ ثَلَاثَةُ آلَافِ دِرْهَمٍ.","ro":"Al-ḥaddu al-adnā lir-raṣīdi thalāthatu ālāfi dirhamin."},{"fr":"J'ai reçu ma carte bancaire au bout d'une semaine.","tgt":"وَصَلَتْنِي بِطَاقَتِي الْمَصْرِفِيَّةُ بَعْدَ أُسْبُوعٍ.","ro":"Waṣalatnī biṭāqatī al-maṣrifiyyatu baʿda usbūʿin."},{"fr":"J'envoie de l'argent à ma famille en France chaque mois.","tgt":"أُرْسِلُ مَالًا إِلَى عَائِلَتِي فِي فَرَنْسَا كُلَّ شَهْرٍ.","ro":"Ursilu mālan ilā ʿāʾilatī fī Faransā kulla shahrin."},{"fr":"L'application de la banque est très pratique.","tgt":"تَطْبِيقُ الْمَصْرِفِ عَمَلِيٌّ جِدًّا.","ro":"Taṭbīqu al-maṣrifi ʿamaliyyun jiddan."},{"fr":"J'ai oublié mon code secret, que dois-je faire ?","tgt":"نَسِيتُ رَقْمِي السِّرِّيَّ، فَمَاذَا أَفْعَلُ؟","ro":"Nasītu raqmī as-sirriyya, fa-mādhā afʿalu?"},{"fr":"Le conseiller m'a proposé une carte de crédit.","tgt":"عَرَضَ عَلَيَّ الْمُوَظَّفُ بِطَاقَةَ ائْتِمَانٍ.","ro":"ʿAraḍa ʿalayya al-muwaẓẓafu biṭāqata iʾtimānin."}]},{"title":"L'assurance santé","phrases":[{"fr":"L'assurance santé est obligatoire à Dubaï.","tgt":"التَّأْمِينُ الصِّحِّيُّ إِلْزَامِيٌّ فِي دُبَيّ.","ro":"At-taʾmīnu aṣ-ṣiḥḥiyyu ilzāmiyyun fī Dubayy."},{"fr":"Remplir le formulaire prend dix minutes.","tgt":"مَلْءُ الِاسْتِمَارَةِ يَسْتَغْرِقُ عَشْرَ دَقَائِقَ.","ro":"Malʾu al-istimārati yastaghriqu ʿashra daqāʾiqa."},{"fr":"Le remboursement des frais prend environ deux semaines.","tgt":"يَسْتَغْرِقُ اسْتِرْدَادُ التَّكَالِيفِ نَحْوَ أُسْبُوعَيْنِ.","ro":"Yastaghriqu istirdādu at-takālīfi naḥwa usbūʿayni."},{"fr":"Mon employeur paie l'assurance de toute la famille.","tgt":"يَدْفَعُ صَاحِبُ الْعَمَلِ تَأْمِينَ الْعَائِلَةِ كُلِّهَا.","ro":"Yadfaʿu ṣāḥibu al-ʿamali taʾmīna al-ʿāʾilati kullihā."},{"fr":"La prise de rendez-vous se fait en ligne.","tgt":"يَتِمُّ حَجْزُ الْمَوَاعِيدِ عَبْرَ الْإِنْتَرْنِتْ.","ro":"Yatimmu ḥajzu al-mawāʿīdi ʿabra al-intarnit."},{"fr":"J'ai besoin de renouveler ma carte d'assurance.","tgt":"أَحْتَاجُ إِلَى تَجْدِيدِ بِطَاقَةِ التَّأْمِينِ.","ro":"Aḥtāju ilā tajdīdi biṭāqati at-taʾmīni."},{"fr":"Les soins dentaires ne sont pas toujours couverts.","tgt":"عِلَاجُ الْأَسْنَانِ لَا يُغَطَّى دَائِمًا.","ro":"ʿIlāju al-asnāni lā yughaṭṭā dāʾiman."},{"fr":"Lire attentivement le contrat est indispensable.","tgt":"قِرَاءَةُ الْعَقْدِ بِعِنَايَةٍ ضَرُورِيَّةٌ.","ro":"Qirāʾatu al-ʿaqdi bi-ʿināyatin ḍarūriyyatun."},{"fr":"Je n'aime pas l'attente aux urgences.","tgt":"لَا أُحِبُّ الِانْتِظَارَ فِي قِسْمِ الطَّوَارِئِ.","ro":"Lā uḥibbu al-intiẓāra fī qismi aṭ-ṭawāriʾi."},{"fr":"Une consultation chez le généraliste coûte cinquante dirhams avec l'assurance.","tgt":"تُكَلِّفُ زِيَارَةُ الطَّبِيبِ الْعَامِّ خَمْسِينَ دِرْهَمًا مَعَ التَّأْمِينِ.","ro":"Tukallifu ziyāratu aṭ-ṭabībi al-ʿāmmi khamsīna dirhaman maʿa at-taʾmīni."}],"tip":{"title":"Le nom verbal (masdar) : « al-kitaba », l'écriture","example":"J'ai besoin de renouveler ma carte d'assurance. — أَحْتَاجُ إِلَى <b>تَجْدِيدِ</b> بِطَاقَةِ التَّأْمِينِ.","body":"En arabe, l'infinitif français se traduit très souvent par un nom, le « masdar », qui désigne l'action elle-même. Au lieu de dire j'ai besoin de renouveler, on dit : j'ai besoin du renouvellement. « Ahtaju ila tajdidi bitaqati at-tamin » se dit littéralement : j'ai besoin de, renouvellement, carte, l'assurance. Chaque forme verbale a son modèle : « kataba », écrire, donne « kitaba », l'écriture ; « jaddada », renouveler, donne « tajdid » ; « intazara », attendre, donne « intizar », l'attente. Retenez cette habitude : là où le français met un verbe à l'infinitif, l'arabe aime mettre un nom.","exampleRo":"Aḥtāju ilā tajdīdi biṭāqati at-taʾmīni.","lit":"j'ai-besoin · [à] · renouvellement · carte · l'assurance","say":{"masdar":"مَصْدَر","kataba":"كَتَبَ","kitaba":"كِتَابَة","jaddada":"جَدَّدَ","tajdid":"تَجْدِيد","intazara":"اِنْتَظَرَ","intizar":"اِنْتِظَار","al-kitaba":"الْكِتَابَة","Ahtaju ila tajdidi bitaqati at-tamin":"أَحْتَاجُ إِلَى تَجْدِيدِ بِطَاقَةِ التَّأْمِينِ"}}},{"title":"Le déménagement","phrases":[{"fr":"Nous déménageons à Abou Dhabi le mois prochain.","tgt":"سَنَنْتَقِلُ إِلَى أَبُوظَبْي الشَّهْرَ الْقَادِمَ.","ro":"Sa-nantaqilu ilā Abū Ẓabī ash-shahra al-qādima."},{"fr":"Mon entreprise a ouvert un nouveau bureau là-bas.","tgt":"فَتَحَتْ شَرِكَتِي مَكْتَبًا جَدِيدًا هُنَاكَ.","ro":"Fataḥat sharikatī maktaban jadīdan hunāka."},{"fr":"Nous avons fait appel à une société de déménagement.","tgt":"اسْتَعَنَّا بِشَرِكَةِ نَقْلٍ.","ro":"Istaʿannā bi-sharikati naqlin."},{"fr":"Les cartons ont été emballés en une seule journée.","tgt":"حُزِمَتِ الصَّنَادِيقُ فِي يَوْمٍ وَاحِدٍ.","ro":"Ḥuzimati aṣ-ṣanādīqu fī yawmin wāḥidin."},{"fr":"Il faut résilier l'abonnement à l'électricité et à l'eau.","tgt":"يَجِبُ إِلْغَاءُ اشْتِرَاكِ الْكَهْرَبَاءِ وَالْمَاءِ.","ro":"Yajibu ilghāʾu ishtirāki al-kahrabāʾi wal-māʾi."},{"fr":"Les enfants sont tristes parce qu'ils vont quitter leurs amis.","tgt":"الْأَطْفَالُ حَزِينُونَ لِأَنَّهُمْ سَيَتْرُكُونَ أَصْدِقَاءَهُمْ.","ro":"Al-aṭfālu ḥazīnūna li-annahum sa-yatrukūna aṣdiqāʾahum."},{"fr":"Le canapé n'est pas passé par la porte !","tgt":"لَمْ تَدْخُلِ الْأَرِيكَةُ مِنَ الْبَابِ!","ro":"Lam tadkhuli al-arīkatu mina al-bābi!"},{"fr":"Nous avons rendu les clés au propriétaire.","tgt":"أَعَدْنَا الْمَفَاتِيحَ إِلَى الْمَالِكِ.","ro":"Aʿadnā al-mafātīḥa ilā al-māliki."},{"fr":"Le nouvel appartement est plus grand et moins cher.","tgt":"الشَّقَّةُ الْجَدِيدَةُ أَكْبَرُ وَأَرْخَصُ.","ro":"Ash-shaqqatu al-jadīdatu akbaru wa-arkhaṣu."},{"fr":"Il nous faudra quelques semaines pour nous installer.","tgt":"سَنَحْتَاجُ إِلَى بِضْعَةِ أَسَابِيعَ لِنَسْتَقِرَّ.","ro":"Sa-naḥtāju ilā biḍʿati asābīʿa li-nastaqirra."}]},{"title":"La chaleur de l'été","phrases":[{"fr":"En août, la température dépasse quarante-cinq degrés.","tgt":"فِي أَغُسْطُسَ تَتَجَاوَزُ الْحَرَارَةُ خَمْسًا وَأَرْبَعِينَ دَرَجَةً.","ro":"Fī Aghusṭusa tatajāwazu al-ḥarāratu khamsan wa-arbaʿīna darajatan."},{"fr":"L'humidité rend la respiration difficile.","tgt":"الرُّطُوبَةُ تَجْعَلُ التَّنَفُّسَ صَعْبًا.","ro":"Ar-ruṭūbatu tajʿalu at-tanaffusa ṣaʿban."},{"fr":"Personne ne marche dehors à midi.","tgt":"لَا أَحَدَ يَمْشِي فِي الْخَارِجِ عِنْدَ الظُّهْرِ.","ro":"Lā aḥada yamshī fī al-khāriji ʿinda aẓ-ẓuhri."},{"fr":"La climatisation fonctionne jour et nuit.","tgt":"يَعْمَلُ الْمُكَيِّفُ لَيْلَ نَهَارَ.","ro":"Yaʿmalu al-mukayyifu layla nahāra."},{"fr":"La facture d'électricité est très élevée en été.","tgt":"فَاتُورَةُ الْكَهْرَبَاءِ مُرْتَفِعَةٌ جِدًّا فِي الصَّيْفِ.","ro":"Fātūratu al-kahrabāʾi murtafiʿatun jiddan fī aṣ-ṣayfi."},{"fr":"Le travail en plein air s'arrête à midi pendant l'été.","tgt":"يَتَوَقَّفُ الْعَمَلُ فِي الْهَوَاءِ الطَّلْقِ وَقْتَ الظُّهْرِ صَيْفًا.","ro":"Yatawaqqafu al-ʿamalu fī al-hawāʾi aṭ-ṭalqi waqta aẓ-ẓuhri ṣayfan."},{"fr":"Nous allons au centre commercial pour profiter de la fraîcheur.","tgt":"نَذْهَبُ إِلَى الْمَرْكَزِ التِّجَارِيِّ لِنَسْتَمْتِعَ بِالْبُرُودَةِ.","ro":"Nadhhabu ilā al-markazi at-tijāriyyi li-nastamtiʿa bil-burūdati."},{"fr":"Il faut boire beaucoup d'eau pour éviter la déshydratation.","tgt":"يَجِبُ شُرْبُ الْكَثِيرِ مِنَ الْمَاءِ لِتَجَنُّبِ الْجَفَافِ.","ro":"Yajibu shurbu al-kathīri mina al-māʾi li-tajannubi al-jafāfi."},{"fr":"Beaucoup de familles voyagent pendant les mois chauds.","tgt":"تُسَافِرُ عَائِلَاتٌ كَثِيرَةٌ خِلَالَ الْأَشْهُرِ الْحَارَّةِ.","ro":"Tusāfiru ʿāʾilātun kathīratun khilāla al-ashhuri al-ḥārrati."},{"fr":"En hiver, en revanche, le climat est vraiment agréable.","tgt":"أَمَّا فِي الشِّتَاءِ فَالْجَوُّ لَطِيفٌ حَقًّا.","ro":"Ammā fī ash-shitāʾi fal-jawwu laṭīfun ḥaqqan."}]},{"title":"Le télétravail","phrases":[{"fr":"Je travaille à distance le mardi et le jeudi.","tgt":"أَعْمَلُ عَنْ بُعْدٍ يَوْمَيِ الثُّلَاثَاءِ وَالْخَمِيسِ.","ro":"Aʿmalu ʿan buʿdin yawmayi ath-thulāthāʾi wal-khamīsi."},{"fr":"J'ai installé un petit bureau dans la chambre d'amis.","tgt":"جَهَّزْتُ مَكْتَبًا صَغِيرًا فِي غُرْفَةِ الضُّيُوفِ.","ro":"Jahhaztu maktaban ṣaghīran fī ghurfati aḍ-ḍuyūfi."},{"fr":"La connexion coupe parfois pendant les appels vidéo.","tgt":"يَنْقَطِعُ الِاتِّصَالُ بِالْإِنْتَرْنِتْ أَحْيَانًا أَثْنَاءَ مُكَالَمَاتِ الْفِيدْيُو.","ro":"Yanqaṭiʿu al-ittiṣālu bil-intarnit aḥyānan athnāʾa mukālamāti al-fīdyū."},{"fr":"J'économise une heure et demie de trajet.","tgt":"أُوَفِّرُ سَاعَةً وَنِصْفًا مِنَ الطَّرِيقِ.","ro":"Uwaffiru sāʿatan wa-niṣfan mina aṭ-ṭarīqi."},{"fr":"Mes collègues me manquent un peu.","tgt":"أَشْتَاقُ إِلَى زُمَلَائِي قَلِيلًا.","ro":"Ashtāqu ilā zumalāʾī qalīlan."},{"fr":"Il est difficile de séparer la vie privée et le travail.","tgt":"مِنَ الصَّعْبِ الْفَصْلُ بَيْنَ الْحَيَاةِ الْخَاصَّةِ وَالْعَمَلِ.","ro":"Mina aṣ-ṣaʿbi al-faṣlu bayna al-ḥayāti al-khāṣṣati wal-ʿamali."},{"fr":"Je commence ma journée par une liste de tâches.","tgt":"أَبْدَأُ يَوْمِي بِقَائِمَةِ مَهَامَّ.","ro":"Abdaʾu yawmī bi-qāʾimati mahāmma."},{"fr":"Notre directeur nous appelle chaque matin à huit heures et demie.","tgt":"يَتَّصِلُ بِنَا مُدِيرُنَا كُلَّ صَبَاحٍ فِي الثَّامِنَةِ وَالنِّصْفِ.","ro":"Yattaṣilu binā mudīrunā kulla ṣabāḥin fī ath-thāminati wan-niṣfi."},{"fr":"À midi, je prends une vraie pause loin de l'écran.","tgt":"عِنْدَ الظُّهْرِ آخُذُ اسْتِرَاحَةً حَقِيقِيَّةً بَعِيدًا عَنِ الشَّاشَةِ.","ro":"ʿInda aẓ-ẓuhri ākhudhu istirāḥatan ḥaqīqiyyatan baʿīdan ʿani ash-shāshati."},{"fr":"Le télétravail me convient parfaitement.","tgt":"الْعَمَلُ عَنْ بُعْدٍ يُنَاسِبُنِي تَمَامًا.","ro":"Al-ʿamalu ʿan buʿdin yunāsibunī tamāman."}]},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Nos voisins sont vraiment gentils.","tgt":"إِنَّ جِيرَانَنَا لُطَفَاءُ حَقًّا.","ro":"Inna jīrānanā luṭafāʾu ḥaqqan."},{"fr":"Je sais que notre voisine du dessus est médecin.","tgt":"أَعْرِفُ أَنَّ جَارَتَنَا فِي الطَّابِقِ الْعُلْوِيِّ طَبِيبَةٌ.","ro":"Aʿrifu anna jāratanā fī aṭ-ṭābiqi al-ʿulwiyyi ṭabībatun."},{"fr":"On dirait que le gardien connaît tout le monde.","tgt":"كَأَنَّ الْحَارِسَ يَعْرِفُ الْجَمِيعَ.","ro":"Ka-anna al-ḥārisa yaʿrifu al-jamīʿa."},{"fr":"L'immeuble est calme, mais les murs sont fins.","tgt":"الْمَبْنَى هَادِئٌ، لَكِنَّ الْجُدْرَانَ رَقِيقَةٌ.","ro":"Al-mabnā hādiʾun, lākinna al-judrāna raqīqatun."},{"fr":"Notre voisin rénove peut-être son appartement.","tgt":"لَعَلَّ جَارَنَا يُرَمِّمُ شَقَّتَهُ.","ro":"Laʿalla jāranā yurammimu shaqqatahu."},{"fr":"Si seulement l'ascenseur était plus rapide !","tgt":"لَيْتَ الْمِصْعَدَ أَسْرَعُ!","ro":"Layta al-miṣʿada asraʿu!"},{"fr":"La famille d'à côté nous a apporté des luqaimat.","tgt":"أَحْضَرَتْ لَنَا الْعَائِلَةُ الْمُجَاوِرَةُ لُقَيْمَاتٍ.","ro":"Aḥḍarat lanā al-ʿāʾilatu al-mujāwiratu luqaymātin."},{"fr":"En fait, nous ne nous croisons que dans l'ascenseur.","tgt":"إِنَّنَا لَا نَلْتَقِي إِلَّا فِي الْمِصْعَدِ.","ro":"Innanā lā naltaqī illā fī al-miṣʿadi."},{"fr":"La gestion de l'immeuble a annoncé que la piscine fermera lundi.","tgt":"أَعْلَنَتِ الْإِدَارَةُ أَنَّ الْمَسْبَحَ سَيُغْلَقُ يَوْمَ الِاثْنَيْنِ.","ro":"Aʿlanati al-idāratu anna al-masbaḥa sa-yughlaqu yawma al-ithnayni."},{"fr":"Nous sommes heureux ici, sans aucun doute.","tgt":"إِنَّنَا سُعَدَاءُ هُنَا بِلَا شَكٍّ.","ro":"Innanā suʿadāʾu hunā bi-lā shakkin."}],"tip":{"title":"« Inna » et ses sœurs","example":"Nos voisins sont vraiment gentils. — <b>إِنَّ</b> جِيرَانَنَا لُطَفَاءُ حَقًّا.","body":"« Inna » se place en tête de phrase pour insister, un peu comme en vérité ou bien sûr en français. Sa particularité : le sujet qui le suit change de terminaison, le son « ou » devient « a ». On dit « jiranuna lutafau », nos voisins sont gentils, mais « inna jiranana lutafau ». Mot à mot : certes, nos voisins, gentils. Ses sœurs fonctionnent exactement pareil : « anna », que ; « lakinna », mais ; « kaanna », comme si ; « laalla », peut-être ; « layta », si seulement. Astuce pour retenir : après « inna » et toute sa famille, le sujet prend le son « a ».","exampleRo":"Inna jīrānanā luṭafāʾu ḥaqqan.","lit":"[certes] · voisins-de-nous · gentils · vraiment","say":{"Inna":"إِنَّ","jiranuna lutafau":"جِيرَانُنَا لُطَفَاءُ","inna jiranana lutafau":"إِنَّ جِيرَانَنَا لُطَفَاءُ","anna":"أَنَّ","lakinna":"لَكِنَّ","kaanna":"كَأَنَّ","laalla":"لَعَلَّ","layta":"لَيْتَ","inna":"إِنَّ"}}},{"title":"Les démarches administratives","phrases":[{"fr":"Mon visa de résidence expire dans deux mois.","tgt":"تَنْتَهِي تَأْشِيرَةُ إِقَامَتِي بَعْدَ شَهْرَيْنِ.","ro":"Tantahī taʾshīratu iqāmatī baʿda shahrayni."},{"fr":"J'ai pris rendez-vous pour les empreintes digitales.","tgt":"حَجَزْتُ مَوْعِدًا لِأَخْذِ الْبَصَمَاتِ.","ro":"Ḥajaztu mawʿidan li-akhdhi al-baṣamāti."},{"fr":"La carte d'identité émiratie est indispensable pour tout.","tgt":"بِطَاقَةُ الْهُوِيَّةِ الْإِمَارَاتِيَّةُ ضَرُورِيَّةٌ لِكُلِّ شَيْءٍ.","ro":"Biṭāqatu al-huwiyyati al-imārātiyyatu ḍarūriyyatun li-kulli shayʾin."},{"fr":"L'examen médical se fait dans un centre agréé.","tgt":"يُجْرَى الْفَحْصُ الطِّبِّيُّ فِي مَرْكَزٍ مُعْتَمَدٍ.","ro":"Yujrā al-faḥṣu aṭ-ṭibbiyyu fī markazin muʿtamadin."},{"fr":"Je dois faire traduire mon permis de conduire.","tgt":"يَجِبُ أَنْ أُتَرْجِمَ رُخْصَةَ قِيَادَتِي.","ro":"Yajibu an utarjima rukhṣata qiyādatī."},{"fr":"Le formulaire est disponible sur le site officiel.","tgt":"الِاسْتِمَارَةُ مُتَوَفِّرَةٌ عَلَى الْمَوْقِعِ الرَّسْمِيِّ.","ro":"Al-istimāratu mutawaffiratun ʿalā al-mawqiʿi ar-rasmiyyi."},{"fr":"Les frais de dossier s'élèvent à cinq cents dirhams.","tgt":"تَبْلُغُ رُسُومُ الْمُعَامَلَةِ خَمْسَمِئَةِ دِرْهَمٍ.","ro":"Tablughu rusūmu al-muʿāmalati khamsamiʾati dirhamin."},{"fr":"Il me manquait une photo, j'ai dû revenir le lendemain.","tgt":"نَقَصَتْنِي صُورَةٌ فَاضْطُرِرْتُ إِلَى الْعَوْدَةِ فِي الْيَوْمِ التَّالِي.","ro":"Naqaṣatnī ṣūratun fa-ḍṭurirtu ilā al-ʿawdati fī al-yawmi at-tālī."},{"fr":"L'employé m'a expliqué toutes les étapes patiemment.","tgt":"شَرَحَ لِي الْمُوَظَّفُ كُلَّ الْخُطُوَاتِ بِصَبْرٍ.","ro":"Sharaḥa lī al-muwaẓẓafu kulla al-khuṭuwāti bi-ṣabrin."},{"fr":"Tout a été réglé en moins d'une semaine.","tgt":"أُنْجِزَ كُلُّ شَيْءٍ فِي أَقَلَّ مِنْ أُسْبُوعٍ.","ro":"Unjiza kullu shayʾin fī aqalla min usbūʿin."}]},{"title":"Un week-end à Abou Dhabi","phrases":[{"fr":"Samedi matin, nous sommes partis à Abou Dhabi en famille.","tgt":"صَبَاحَ السَّبْتِ ذَهَبْنَا إِلَى أَبُوظَبْي مَعَ الْعَائِلَةِ.","ro":"Ṣabāḥa as-sabti dhahabnā ilā Abū Ẓabī maʿa al-ʿāʾilati."},{"fr":"Nous avons visité le Louvre Abou Dhabi sur l'île de Saadiyat.","tgt":"زُرْنَا مَتْحَفَ اللُّوفْرِ أَبُوظَبْي فِي جَزِيرَةِ السَّعْدِيَّاتِ.","ro":"Zurnā matḥafa al-Lūfri Abū Ẓabī fī jazīrati as-Saʿdiyyāti."},{"fr":"La corniche est idéale pour une promenade au coucher du soleil.","tgt":"الْكُورْنِيشُ مِثَالِيٌّ لِلتَّنَزُّهِ عِنْدَ الْغُرُوبِ.","ro":"Al-kūrnīshu mithāliyyun lit-tanazzuhi ʿinda al-ghurūbi."},{"fr":"Les enfants ont adoré le parc d'attractions de l'île de Yas.","tgt":"أَحَبَّ الْأَطْفَالُ مَدِينَةَ الْأَلْعَابِ فِي جَزِيرَةِ يَاسْ.","ro":"Aḥabba al-aṭfālu madīnata al-alʿābi fī jazīrati Yās."},{"fr":"Nous avons déjeuné de poisson grillé près du marché aux poissons.","tgt":"تَغَدَّيْنَا سَمَكًا مَشْوِيًّا قُرْبَ سُوقِ السَّمَكِ.","ro":"Taghaddaynā samakan mashwiyyan qurba sūqi as-samaki."},{"fr":"L'hôtel avait une belle vue sur la mer.","tgt":"كَانَ لِلْفُنْدُقِ إِطْلَالَةٌ جَمِيلَةٌ عَلَى الْبَحْرِ.","ro":"Kāna lil-funduqi iṭlālatun jamīlatun ʿalā al-baḥri."},{"fr":"Abou Dhabi est plus calme que Dubaï, à mon avis.","tgt":"أَبُوظَبْي أَهْدَأُ مِنْ دُبَيّ فِي رَأْيِي.","ro":"Abū Ẓabī ahdaʾu min Dubayy fī raʾyī."},{"fr":"Ma femme a acheté des dattes au marché pour ses parents.","tgt":"اشْتَرَتْ زَوْجَتِي تَمْرًا مِنَ السُّوقِ لِوَالِدَيْهَا.","ro":"Ishtarat zawjatī tamran mina as-sūqi li-wālidayhā."},{"fr":"Sur la route du retour, tout le monde dormait dans la voiture.","tgt":"فِي طَرِيقِ الْعَوْدَةِ كَانَ الْجَمِيعُ نَائِمِينَ فِي السَّيَّارَةِ.","ro":"Fī ṭarīqi al-ʿawdati kāna al-jamīʿu nāʾimīna fī as-sayyārati."},{"fr":"Nous y retournerons sûrement cet hiver.","tgt":"سَنَعُودُ إِلَيْهَا بِالتَّأْكِيدِ هَذَا الشِّتَاءَ.","ro":"Sa-naʿūdu ilayhā bit-taʾkīdi hādhā ash-shitāʾa."}]},{"title":"Les enfants et l'école","phrases":[{"fr":"Notre fils va dans une école bilingue près de chez nous.","tgt":"يَذْهَبُ ابْنُنَا إِلَى مَدْرَسَةٍ ثُنَائِيَّةِ اللُّغَةِ قُرْبَ بَيْتِنَا.","ro":"Yadhhabu ibnunā ilā madrasatin thunāʾiyyati al-lughati qurba baytinā."},{"fr":"Les inscriptions commencent dès le mois de janvier.","tgt":"يَبْدَأُ التَّسْجِيلُ مُنْذُ شَهْرِ يَنَايِرَ.","ro":"Yabdaʾu at-tasjīlu mundhu shahri Yanāyira."},{"fr":"Les frais de scolarité pèsent lourd sur les familles.","tgt":"الرُّسُومُ الدِّرَاسِيَّةُ عِبْءٌ كَبِيرٌ عَلَى الْعَائِلَاتِ.","ro":"Ar-rusūmu ad-dirāsiyyatu ʿibʾun kabīrun ʿalā al-ʿāʾilāti."},{"fr":"Ma fille apprend l'arabe depuis la maternelle.","tgt":"تَتَعَلَّمُ ابْنَتِي الْعَرَبِيَّةَ مُنْذُ الرَّوْضَةِ.","ro":"Tataʿallamu ibnatī al-ʿarabiyyata mundhu ar-rawḍati."},{"fr":"Le bus scolaire passe à six heures et demie.","tgt":"تَمُرُّ الْحَافِلَةُ الْمَدْرَسِيَّةُ فِي السَّادِسَةِ وَالنِّصْفِ.","ro":"Tamurru al-ḥāfilatu al-madrasiyyatu fī as-sādisati wan-niṣfi."},{"fr":"Les cours se terminent vers deux heures de l'après-midi.","tgt":"تَنْتَهِي الدُّرُوسُ نَحْوَ السَّاعَةِ الثَّانِيَةِ بَعْدَ الظُّهْرِ.","ro":"Tantahī ad-durūsu naḥwa as-sāʿati ath-thāniyati baʿda aẓ-ẓuhri."},{"fr":"Dans sa classe, il y a des élèves de vingt nationalités.","tgt":"فِي صَفِّهِ تَلَامِيذُ مِنْ عِشْرِينَ جِنْسِيَّةً.","ro":"Fī ṣaffihi talāmīdhu min ʿishrīna jinsiyyatan."},{"fr":"La réunion parents-professeurs a lieu jeudi soir.","tgt":"يُعْقَدُ لِقَاءُ الْأَهْلِ وَالْمُعَلِّمِينَ مَسَاءَ الْخَمِيسِ.","ro":"Yuʿqadu liqāʾu al-ahli wal-muʿallimīna masāʾa al-khamīsi."},{"fr":"Le professeur dit que notre fils a fait de grands progrès.","tgt":"يَقُولُ الْمُعَلِّمُ إِنَّ ابْنَنَا تَقَدَّمَ كَثِيرًا.","ro":"Yaqūlu al-muʿallimu inna ibnanā taqaddama kathīran."},{"fr":"Le week-end, les enfants font de la natation.","tgt":"فِي عُطْلَةِ نِهَايَةِ الْأُسْبُوعِ يُمَارِسُ الْأَطْفَالُ السِّبَاحَةَ.","ro":"Fī ʿuṭlati nihāyati al-usbūʿi yumārisu al-aṭfālu as-sibāḥata."}]},{"title":"Faire les courses","phrases":[{"fr":"Nous faisons les courses pour la maison chaque samedi matin.","tgt":"نَتَسَوَّقُ لِلْبَيْتِ صَبَاحَ كُلِّ سَبْتٍ.","ro":"Natasawwaqu lil-bayti ṣabāḥa kulli sabtin."},{"fr":"L'hypermarché est ouvert jour et nuit.","tgt":"الْمَتْجَرُ الْكَبِيرُ مَفْتُوحٌ عَلَى مَدَارِ السَّاعَةِ.","ro":"Al-matjaru al-kabīru maftūḥun ʿalā madāri as-sāʿati."},{"fr":"Les fruits sont importés de nombreux pays.","tgt":"تُسْتَوْرَدُ الْفَوَاكِهُ مِنْ بُلْدَانٍ كَثِيرَةٍ.","ro":"Tustawradu al-fawākihu min buldānin kathīratin."},{"fr":"Je compare toujours les prix avant d'acheter.","tgt":"أُقَارِنُ الْأَسْعَارَ دَائِمًا قَبْلَ الشِّرَاءِ.","ro":"Uqārinu al-asʿāra dāʾiman qabla ash-shirāʾi."},{"fr":"Les sacs en plastique sont désormais payants.","tgt":"أَصْبَحَتِ الْأَكْيَاسُ الْبِلَاسْتِيكِيَّةُ مَدْفُوعَةً.","ro":"Aṣbaḥati al-akyāsu al-bilāstīkiyyatu madfūʿatan."},{"fr":"Je commande souvent les courses en ligne.","tgt":"كَثِيرًا مَا أَطْلُبُ الْمُشْتَرَيَاتِ عَبْرَ الْإِنْتَرْنِتْ.","ro":"Kathīran mā aṭlubu al-mushtarayāti ʿabra al-intarnit."},{"fr":"La commande arrive en moins d'une heure.","tgt":"تَصِلُ الطَّلَبِيَّةُ فِي أَقَلَّ مِنْ سَاعَةٍ.","ro":"Taṣilu aṭ-ṭalabiyyatu fī aqalla min sāʿatin."},{"fr":"Au souk de Deira, on peut marchander les prix.","tgt":"فِي سُوقِ دِيرَةَ يُمْكِنُ الْمُسَاوَمَةُ عَلَى الْأَسْعَارِ.","ro":"Fī sūqi Dīrata yumkinu al-musāwamatu ʿalā al-asʿāri."},{"fr":"Les épices sont vendues au poids.","tgt":"تُبَاعُ التَّوَابِلُ بِالْوَزْنِ.","ro":"Tubāʿu at-tawābilu bil-wazni."},{"fr":"J'ai oublié d'acheter du lait, encore une fois !","tgt":"نَسِيتُ أَنْ أَشْتَرِيَ الْحَلِيبَ مَرَّةً أُخْرَى!","ro":"Nasītu an ashtariya al-ḥalība marratan ukhrā!"}]},{"title":"Une visite chez le médecin","phrases":[{"fr":"Mon fils a de la fièvre depuis hier soir.","tgt":"ابْنِي مَحْمُومٌ مُنْذُ مَسَاءِ أَمْسِ.","ro":"Ibnī maḥmūmun mundhu masāʾi amsi."},{"fr":"J'ai pris rendez-vous dans une clinique près de chez nous.","tgt":"حَجَزْتُ مَوْعِدًا فِي عِيَادَةٍ قَرِيبَةٍ مِنْ بَيْتِنَا.","ro":"Ḥajaztu mawʿidan fī ʿiyādatin qarībatin min baytinā."},{"fr":"La secrétaire a demandé ma carte d'assurance.","tgt":"طَلَبَتِ السِّكْرِتِيرَةُ بِطَاقَةَ التَّأْمِينِ.","ro":"Ṭalabati as-sikritīratu biṭāqata at-taʾmīni."},{"fr":"Le médecin l'a examiné attentivement.","tgt":"فَحَصَهُ الطَّبِيبُ بِعِنَايَةٍ.","ro":"Faḥaṣahu aṭ-ṭabību bi-ʿināyatin."},{"fr":"Ce n'est qu'un virus saisonnier, rien de grave.","tgt":"إِنَّهُ مُجَرَّدُ فَيْرُوسٍ مَوْسِمِيٍّ وَلَيْسَ خَطِيرًا.","ro":"Innahu mujarradu fayrūsin mawsimiyyin wa-laysa khaṭīran."},{"fr":"Il doit se reposer et boire beaucoup.","tgt":"عَلَيْهِ أَنْ يَرْتَاحَ وَيَشْرَبَ كَثِيرًا.","ro":"ʿAlayhi an yartāḥa wa-yashraba kathīran."},{"fr":"Le médecin a prescrit un sirop contre la toux.","tgt":"وَصَفَ الطَّبِيبُ شَرَابًا لِلسُّعَالِ.","ro":"Waṣafa aṭ-ṭabību sharāban lis-suʿāli."},{"fr":"La pharmacie est au rez-de-chaussée de la clinique.","tgt":"الصَّيْدَلِيَّةُ فِي الطَّابِقِ الْأَرْضِيِّ مِنَ الْعِيَادَةِ.","ro":"Aṣ-ṣaydaliyyatu fī aṭ-ṭābiqi al-arḍiyyi mina al-ʿiyādati."},{"fr":"L'assurance a couvert la consultation et les médicaments.","tgt":"غَطَّى التَّأْمِينُ الِاسْتِشَارَةَ وَالْأَدْوِيَةَ.","ro":"Ghaṭṭā at-taʾmīnu al-istishārata wal-adwiyata."},{"fr":"Trois jours plus tard, il était de retour à l'école.","tgt":"بَعْدَ ثَلَاثَةِ أَيَّامٍ عَادَ إِلَى الْمَدْرَسَةِ.","ro":"Baʿda thalāthati ayyāmin ʿāda ilā al-madrasati."}]},{"title":"Le sport et le bien-être","phrases":[{"fr":"Je cours sur la plage de Jumeirah tôt le matin.","tgt":"أَجْرِي عَلَى شَاطِئِ جُمَيْرَا فِي الصَّبَاحِ الْبَاكِرِ.","ro":"Ajrī ʿalā shāṭiʾi Jumayrā fī aṣ-ṣabāḥi al-bākiri."},{"fr":"Je me suis inscrit dans une salle de sport près du bureau.","tgt":"اشْتَرَكْتُ فِي نَادٍ رِيَاضِيٍّ قُرْبَ الْمَكْتَبِ.","ro":"Ishtaraktu fī nādin riyāḍiyyin qurba al-maktabi."},{"fr":"Le vendredi soir, je joue au padel avec des collègues.","tgt":"مَسَاءَ الْجُمُعَةِ أَلْعَبُ الْبَادِلَ مَعَ زُمَلَاءَ مِنَ الْعَمَلِ.","ro":"Masāʾa al-jumuʿati alʿabu al-bādila maʿa zumalāʾa mina al-ʿamali."},{"fr":"Faire du sport en été demande de l'organisation.","tgt":"مُمَارَسَةُ الرِّيَاضَةِ فِي الصَّيْفِ تَحْتَاجُ إِلَى تَنْظِيمٍ.","ro":"Mumārasatu ar-riyāḍati fī aṣ-ṣayfi taḥtāju ilā tanẓīmin."},{"fr":"Le parc de Zabeel s'anime après le coucher du soleil.","tgt":"تَدِبُّ الْحَيَاةُ فِي حَدِيقَةِ زَعَبِيلَ بَعْدَ الْغُرُوبِ.","ro":"Tadibbu al-ḥayātu fī ḥadīqati Zaʿabīla baʿda al-ghurūbi."},{"fr":"Le yoga m'aide à gérer le stress du travail.","tgt":"تُسَاعِدُنِي الْيُوغَا عَلَى التَّحَكُّمِ فِي ضَغْطِ الْعَمَلِ.","ro":"Tusāʿidunī al-yūghā ʿalā at-taḥakkumi fī ḍaghṭi al-ʿamali."},{"fr":"Depuis quelques mois, je mange moins de sucre.","tgt":"مُنْذُ بِضْعَةِ أَشْهُرٍ أَتَنَاوَلُ سُكَّرًا أَقَلَّ.","ro":"Mundhu biḍʿati ashhurin atanāwalu sukkaran aqalla."},{"fr":"Mon voisin m'a proposé de faire du vélo ensemble.","tgt":"اقْتَرَحَ عَلَيَّ جَارِي أَنْ نَرْكَبَ الدَّرَّاجَةَ مَعًا.","ro":"Iqtaraḥa ʿalayya jārī an narkaba ad-darrājata maʿan."},{"fr":"Il y a une piste cyclable dans le désert d'Al Qudra.","tgt":"هُنَاكَ مَسَارٌ لِلدَّرَّاجَاتِ فِي صَحْرَاءِ الْقُدْرَةِ.","ro":"Hunāka masārun lid-darrājāti fī ṣaḥrāʾi al-Qudrati."},{"fr":"Je me sens beaucoup mieux depuis que je fais du sport.","tgt":"أَشْعُرُ بِتَحَسُّنٍ كَبِيرٍ مُنْذُ أَنْ بَدَأْتُ أُمَارِسُ الرِّيَاضَةَ.","ro":"Ashʿuru bi-taḥassunin kabīrin mundhu an badaʾtu umārisu ar-riyāḍata."}]},{"title":"La famille vient de France","phrases":[{"fr":"Mes parents arrivent de Paris la semaine prochaine.","tgt":"يَصِلُ وَالِدَايَ مِنْ بَارِيسَ الْأُسْبُوعَ الْقَادِمَ.","ro":"Yaṣilu wālidāya min Bārīsa al-usbūʿa al-qādima."},{"fr":"Ils viennent aux Émirats pour la première fois.","tgt":"يَأْتِيَانِ إِلَى الْإِمَارَاتِ لِأَوَّلِ مَرَّةٍ.","ro":"Yaʾtiyāni ilā al-imārāti li-awwali marratin."},{"fr":"Nous leur avons préparé la chambre d'amis.","tgt":"جَهَّزْنَا لَهُمَا غُرْفَةَ الضُّيُوفِ.","ro":"Jahhaznā lahumā ghurfata aḍ-ḍuyūfi."},{"fr":"Ma mère tient beaucoup à voir le désert.","tgt":"تُرِيدُ أُمِّي بِشِدَّةٍ أَنْ تَرَى الصَّحْرَاءَ.","ro":"Turīdu ummī bi-shiddatin an tarā aṣ-ṣaḥrāʾa."},{"fr":"Nous avons réservé une soirée dans un camp au milieu des dunes.","tgt":"حَجَزْنَا سَهْرَةً فِي مُخَيَّمٍ وَسَطَ الْكُثْبَانِ.","ro":"Ḥajaznā saharatan fī mukhayyamin wasaṭa al-kuthbāni."},{"fr":"Mon père a été surpris par la propreté de la ville.","tgt":"فُوجِئَ أَبِي بِنَظَافَةِ الْمَدِينَةِ.","ro":"Fūjiʾa abī bi-naẓāfati al-madīnati."},{"fr":"Les enfants sont ravis de retrouver leurs grands-parents.","tgt":"الْأَطْفَالُ فَرِحُونَ بِلِقَاءِ جَدِّهِمْ وَجَدَّتِهِمْ.","ro":"Al-aṭfālu fariḥūna bi-liqāʾi jaddihim wa-jaddatihim."},{"fr":"Nous avons dîné dans un restaurant émirati traditionnel.","tgt":"تَعَشَّيْنَا فِي مَطْعَمٍ إِمَارَاتِيٍّ تَقْلِيدِيٍّ.","ro":"Taʿashshaynā fī maṭʿamin imārātiyyin taqlīdiyyin."},{"fr":"J'ai traduit le menu pour mes parents.","tgt":"تَرْجَمْتُ قَائِمَةَ الطَّعَامِ لِوَالِدَيَّ.","ro":"Tarjamtu qāʾimata aṭ-ṭaʿāmi li-wālidayya."},{"fr":"Leur séjour est passé beaucoup trop vite.","tgt":"مَرَّتْ زِيَارَتُهُمَا بِسُرْعَةٍ كَبِيرَةٍ.","ro":"Marrat ziyāratuhumā bi-surʿatin kabīratin."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait découvrir la vie quotidienne aux Émirats.","tgt":"عَرَّفَتْنَا هَذِهِ الْوَحْدَةُ عَلَى الْحَيَاةِ الْيَوْمِيَّةِ فِي الْإِمَارَاتِ.","ro":"ʿArrafatnā hādhihi al-waḥdatu ʿalā al-ḥayāti al-yawmiyyati fī al-imārāti."},{"fr":"Nous avons parlé de travail, de logement et de santé.","tgt":"تَحَدَّثْنَا عَنِ الْعَمَلِ وَالسَّكَنِ وَالصِّحَّةِ.","ro":"Taḥaddathnā ʿani al-ʿamali was-sakani waṣ-ṣiḥḥati."},{"fr":"Le passif permet de parler des démarches sans nommer personne.","tgt":"يَسْمَحُ الْمَبْنِيُّ لِلْمَجْهُولِ بِالْحَدِيثِ عَنِ الْمُعَامَلَاتِ دُونَ ذِكْرِ أَحَدٍ.","ro":"Yasmaḥu al-mabniyyu lil-majhūli bil-ḥadīthi ʿani al-muʿāmalāti dūna dhikri aḥadin."},{"fr":"Nous savons maintenant imaginer ce qui n'est pas arrivé.","tgt":"صَارَ بِإِمْكَانِنَا أَنْ نَتَخَيَّلَ مَا لَمْ يَحْدُثْ.","ro":"Ṣāra bi-imkāninā an natakhayyala mā lam yaḥduth."},{"fr":"L'arabe devient de plus en plus naturel pour nous.","tgt":"أَصْبَحَتِ الْعَرَبِيَّةُ طَبِيعِيَّةً أَكْثَرَ فَأَكْثَرَ بِالنِّسْبَةِ إِلَيْنَا.","ro":"Aṣbaḥati al-ʿarabiyyatu ṭabīʿiyyatan akthara fa-akthara bin-nisbati ilaynā."},{"fr":"Les formes dérivées ne nous font plus peur.","tgt":"لَمْ تَعُدِ الْأَوْزَانُ الْمَزِيدَةُ تُخِيفُنَا.","ro":"Lam taʿudi al-awzānu al-mazīdatu tukhīfunā."},{"fr":"Le prochain module nous emmènera en voyage à travers le monde arabe.","tgt":"سَتَأْخُذُنَا الْوَحْدَةُ الْقَادِمَةُ فِي رِحْلَةٍ عَبْرَ الْعَالَمِ الْعَرَبِيِّ.","ro":"Sa-taʾkhudhunā al-waḥdatu al-qādimatu fī riḥlatin ʿabra al-ʿālami al-ʿarabiyyi."},{"fr":"Chaque leçon nous rapproche d'un arabe fluide.","tgt":"كُلُّ دَرْسٍ يُقَرِّبُنَا مِنْ عَرَبِيَّةٍ سَلِسَةٍ.","ro":"Kullu darsin yuqarribunā min ʿarabiyyatin salisatin."},{"fr":"Bravo pour ta persévérance tout au long de ce module.","tgt":"أَحْسَنْتَ عَلَى مُثَابَرَتِكَ طَوَالَ هَذِهِ الْوَحْدَةِ.","ro":"Aḥsanta ʿalā muthābaratika ṭawāla hādhihi al-waḥdati."},{"fr":"Repose-toi bien, et à très bientôt !","tgt":"اسْتَرِحْ جَيِّدًا، وَإِلَى اللِّقَاءِ قَرِيبًا!","ro":"Istariḥ jayyidan, wa-ilā al-liqāʾi qarīban!"}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Mascate","phrases":[{"fr":"Notre avion a atterri à Mascate en fin d'après-midi.","tgt":"هَبَطَتْ طَائِرَتُنَا فِي مَسْقَطَ فِي آخِرِ الْعَصْرِ.","ro":"Habaṭat ṭāʾiratunā fī Masqaṭa fī ākhiri l-ʿaṣri."},{"fr":"Dès la sortie de l'aéroport, la chaleur humide nous a surpris.","tgt":"فَاجَأَتْنَا الْحَرَارَةُ الرَّطْبَةُ فَوْرَ خُرُوجِنَا مِنَ الْمَطَارِ.","ro":"Fājaʾatnā l-ḥarāratu r-raṭbatu fawra khurūjinā mina l-maṭāri."},{"fr":"Le chauffeur de taxi nous a accueillis avec beaucoup de gentillesse.","tgt":"اسْتَقْبَلَنَا سَائِقُ سَيَّارَةِ الْأُجْرَةِ بِلُطْفٍ كَبِيرٍ.","ro":"Istaqbalanā sāʾiqu sayyārati l-ujrati bi-luṭfin kabīrin."},{"fr":"La capitale s'étend entre les montagnes et la mer.","tgt":"تَمْتَدُّ الْعَاصِمَةُ بَيْنَ الْجِبَالِ وَالْبَحْرِ.","ro":"Tamtaddu l-ʿāṣimatu bayna l-jibāli wa-l-baḥri."},{"fr":"Les maisons y sont blanches et basses, et elles se ressemblent beaucoup.","tgt":"الْبُيُوتُ هُنَا بَيْضَاءُ وَمُنْخَفِضَةٌ، وَتَتَشَابَهُ كَثِيرًا.","ro":"Al-buyūtu hunā bayḍāʾu wa-munkhafiḍatun, wa-tatashābahu kathīran."},{"fr":"Nous avons déposé nos bagages dans un petit hôtel près de la corniche.","tgt":"وَضَعْنَا أَمْتِعَتَنَا فِي فُنْدُقٍ صَغِيرٍ قُرْبَ الْكُورْنِيشِ.","ro":"Waḍaʿnā amtiʿatanā fī funduqin ṣaghīrin qurba l-kūrnīshi."},{"fr":"Le soir, nous nous sommes promenés le long du port de Mutrah.","tgt":"فِي الْمَسَاءِ، تَمَشَّيْنَا عَلَى طُولِ مِينَاءِ مَطْرَحَ.","ro":"Fī l-masāʾi, tamashshaynā ʿalā ṭūli mīnāʾi Maṭraḥa."},{"fr":"Les gens d'ici sont connus pour leur sens de l'hospitalité.","tgt":"يُعْرَفُ النَّاسُ هُنَا بِكَرَمِ الضِّيَافَةِ.","ro":"Yuʿrafu n-nāsu hunā bi-karami ḍ-ḍiyāfati."},{"fr":"On nous a servi du café à la cardamome avec des dattes.","tgt":"قُدِّمَتْ لَنَا قَهْوَةٌ بِالْهَيْلِ مَعَ التَّمْرِ.","ro":"Quddimat lanā qahwatun bi-l-hayli maʿa t-tamri."},{"fr":"Cette première nuit à Oman nous a déjà charmés.","tgt":"لَقَدْ سَحَرَتْنَا هَذِهِ اللَّيْلَةُ الْأُولَى فِي عُمَانَ.","ro":"Laqad saḥaratnā hādhihi l-laylatu l-ūlā fī ʿUmāna."}]},{"title":"Préparer un voyage responsable","phrases":[{"fr":"Nous voyageons lentement pour mieux connaître le pays.","tgt":"نُسَافِرُ بِبُطْءٍ لِنَعْرِفَ الْبَلَدَ بِشَكْلٍ أَفْضَلَ.","ro":"Nusāfiru bi-buṭʾin li-naʿrifa l-balada bi-shaklin afḍala."},{"fr":"Nous avons loué une seule voiture pour tout le groupe afin de moins polluer.","tgt":"اسْتَأْجَرْنَا سَيَّارَةً وَاحِدَةً لِلْمَجْمُوعَةِ كُلِّهَا كَيْ نُقَلِّلَ التَّلَوُّثَ.","ro":"Istaʾjarnā sayyāratan wāḥidatan li-l-majmūʿati kullihā kay nuqallila t-talawwutha."},{"fr":"On loge chez l'habitant pour que l'argent reste dans les villages.","tgt":"نَنْزِلُ عِنْدَ السُّكَّانِ كَيْ يَبْقَى الْمَالُ فِي الْقُرَى.","ro":"Nanzilu ʿinda s-sukkāni kay yabqā l-mālu fī l-qurā."},{"fr":"J'ai acheté une gourde en métal pour ne pas acheter de bouteilles en plastique.","tgt":"اشْتَرَيْتُ قِنِّينَةً مَعْدِنِيَّةً لِكَيْلَا أَشْتَرِيَ زُجَاجَاتٍ بِلَاسْتِيكِيَّةً.","ro":"Ishtaraytu qinnīnatan maʿdiniyyatan li-kaylā ashtariya zujājātin bilāstīkiyyatan."},{"fr":"Nous avons appris quelques mots d'arabe afin de parler avec les habitants.","tgt":"تَعَلَّمْنَا بَعْضَ الْكَلِمَاتِ الْعَرَبِيَّةِ لِنَتَحَدَّثَ مَعَ السُّكَّانِ.","ro":"Taʿallamnā baʿḍa l-kalimāti l-ʿarabiyyati li-nataḥaddatha maʿa s-sukkāni."},{"fr":"Le guide nous parle de l'histoire de la région pour que nous la comprenions mieux.","tgt":"يُحَدِّثُنَا الْمُرْشِدُ عَنْ تَارِيخِ الْمِنْطَقَةِ كَيْ نَفْهَمَهَا أَكْثَرَ.","ro":"Yuḥaddithunā l-murshidu ʿan tārīkhi l-minṭaqati kay nafhamahā akthara."},{"fr":"Je me lève tôt pour profiter de la fraîcheur du matin.","tgt":"أَسْتَيْقِظُ بَاكِرًا لِأَسْتَمْتِعَ بِبُرُودَةِ الصَّبَاحِ.","ro":"Astayqiẓu bākiran li-astamtiʿa bi-burūdati ṣ-ṣabāḥi."},{"fr":"Nous emportons un sac pour y ramasser nos déchets.","tgt":"نَحْمِلُ كِيسًا لِنَجْمَعَ فِيهِ نُفَايَاتِنَا.","ro":"Naḥmilu kīsan li-najmaʿa fīhi nufāyātinā."},{"fr":"On nous a conseillé de couvrir nos épaules afin de respecter les coutumes locales.","tgt":"نُصِحْنَا بِأَنْ نُغَطِّيَ أَكْتَافَنَا كَيْ نَحْتَرِمَ الْعَادَاتِ الْمَحَلِّيَّةَ.","ro":"Nuṣiḥnā bi-an nughaṭṭiya aktāfanā kay naḥtarima l-ʿādāti l-maḥalliyyata."},{"fr":"Nous voyageons pour découvrir, pas pour consommer.","tgt":"نُسَافِرُ لِنَكْتَشِفَ، لَا لِنَسْتَهْلِكَ.","ro":"Nusāfiru li-naktashifa, lā li-nastahlika."}],"tip":{"title":"« Kay » et « li » : pour que, afin de","example":"Nous voyageons pour découvrir, pas pour consommer. — نُسَافِرُ <b>لِنَكْتَشِفَ</b>، لَا <b>لِنَسْتَهْلِكَ</b>.","body":"Pour exprimer le but d'une action, l'arabe place devant le verbe la petite particule « li », collée au verbe, ou le mot « kay ». Les deux signifient pour ou afin de. Après elles, le verbe au présent change sa voyelle finale : « naktashifu », nous découvrons, devient « li-naktashifa », littéralement : pour que nous découvrions. C'est l'équivalent de notre subjonctif après pour que. On dira aussi « kay yabqa al-mal », pour que l'argent reste, et « li-kayla » pour dire afin de ne pas. Astuce : quand vous entendez « li » ou « kay » suivi d'un verbe en « a » final, pensez au but.","exampleRo":"Nusāfiru li-naktashifa, lā li-nastahlika.","lit":"nous voyageons · pour-que-nous-découvrions · [ne… pas] · pour-que-nous-consommions","say":{"Kay":"كَيْ","kay":"كَيْ","naktashifu":"نَكْتَشِفُ","li-naktashifa":"لِنَكْتَشِفَ","kay yabqa al-mal":"كَيْ يَبْقَى الْمَال","li-kayla":"لِكَيْلَا"}}},{"title":"Le souk de Mutrah","phrases":[{"fr":"Le souk de Mutrah est l'un des plus anciens marchés du pays.","tgt":"سُوقُ مَطْرَحَ مِنْ أَقْدَمِ الْأَسْوَاقِ فِي الْبَلَدِ.","ro":"Sūqu Maṭraḥa min aqdami l-aswāqi fī l-baladi."},{"fr":"Ses ruelles étroites sont couvertes d'un toit en bois.","tgt":"أَزِقَّتُهُ الضَّيِّقَةُ مُغَطَّاةٌ بِسَقْفٍ خَشَبِيٍّ.","ro":"Aziqqatuhu ḍ-ḍayyiqatu mughaṭṭātun bi-saqfin khashabiyyin."},{"fr":"Une odeur d'encens flotte dans toutes les allées.","tgt":"تَفُوحُ رَائِحَةُ اللُّبَانِ فِي كُلِّ الْمَمَرَّاتِ.","ro":"Tafūḥu rāʾiḥatu l-lubāni fī kulli l-mamarrāti."},{"fr":"Les marchands proposent des bijoux en argent et des poignards traditionnels.","tgt":"يَعْرِضُ التُّجَّارُ حُلِيًّا فِضِّيَّةً وَخَنَاجِرَ تَقْلِيدِيَّةً.","ro":"Yaʿriḍu t-tujjāru ḥuliyyan fiḍḍiyyatan wa-khanājira taqlīdiyyatan."},{"fr":"Le khanjar, un poignard recourbé, est un symbole national à Oman.","tgt":"الْخَنْجَرُ الْمَعْقُوفُ رَمْزٌ وَطَنِيٌّ فِي عُمَانَ.","ro":"Al-khanjaru l-maʿqūfu ramzun waṭaniyyun fī ʿUmāna."},{"fr":"Il faut marchander, mais toujours avec le sourire.","tgt":"يَجِبُ أَنْ تُسَاوِمَ، وَلَكِنْ دَائِمًا بِابْتِسَامَةٍ.","ro":"Yajibu an tusāwima, wa-lākin dāʾiman bi-btisāmatin."},{"fr":"Le vendeur m'a fait goûter plusieurs sortes de halwa omanaise.","tgt":"جَعَلَنِي الْبَائِعُ أَتَذَوَّقُ أَنْوَاعًا عَدِيدَةً مِنَ الْحَلْوَى الْعُمَانِيَّةِ.","ro":"Jaʿalanī l-bāʾiʿu atadhawwaqu anwāʿan ʿadīdatan mina l-ḥalwā l-ʿumāniyyati."},{"fr":"Cette douceur est parfumée à l'eau de rose et au safran.","tgt":"هَذِهِ الْحَلْوَى مُعَطَّرَةٌ بِمَاءِ الْوَرْدِ وَالزَّعْفَرَانِ.","ro":"Hādhihi l-ḥalwā muʿaṭṭaratun bi-māʾi l-wardi wa-z-zaʿfarāni."},{"fr":"J'ai finalement acheté un petit brûle-encens en terre cuite.","tgt":"اشْتَرَيْتُ فِي النِّهَايَةِ مِبْخَرَةً صَغِيرَةً مِنَ الْفَخَّارِ.","ro":"Ishtaraytu fī n-nihāyati mibkharatan ṣaghīratan mina l-fakhkhāri."},{"fr":"Le prix final était la moitié du prix de départ.","tgt":"كَانَ السِّعْرُ النِّهَائِيُّ نِصْفَ السِّعْرِ الْأَوَّلِ.","ro":"Kāna s-siʿru n-nihāʾiyyu niṣfa s-siʿri l-awwali."}]},{"title":"Le fort de Nizwa","phrases":[{"fr":"Nizwa était autrefois la capitale du pays.","tgt":"كَانَتْ نِزْوَى عَاصِمَةَ الْبِلَادِ فِي الْمَاضِي.","ro":"Kānat Nizwā ʿāṣimata l-bilādi fī l-māḍī."},{"fr":"Son fort circulaire domine encore la ville.","tgt":"مَا زَالَتْ قَلْعَتُهَا الدَّائِرِيَّةُ تُطِلُّ عَلَى الْمَدِينَةِ.","ro":"Mā zālat qalʿatuhā d-dāʾiriyyatu tuṭillu ʿalā l-madīnati."},{"fr":"La tour a été construite au dix-septième siècle.","tgt":"بُنِيَ الْبُرْجُ فِي الْقَرْنِ السَّابِعَ عَشَرَ.","ro":"Buniya l-burju fī l-qarni s-sābiʿa ʿashara."},{"fr":"Les murs sont toujours aussi solides qu'avant.","tgt":"مَا زَالَتِ الْجُدْرَانُ قَوِيَّةً كَمَا كَانَتْ.","ro":"Mā zālati l-judrānu qawiyyatan kamā kānat."},{"fr":"Est-ce que tu es encore fatigué après la montée ?","tgt":"هَلْ مَا زِلْتَ مُتْعَبًا بَعْدَ الصُّعُودِ؟","ro":"Hal mā zilta mutʿaban baʿda ṣ-ṣuʿūdi?"},{"fr":"Le marché aux chèvres se tient toujours chaque semaine au pied du fort.","tgt":"مَا زَالَ سُوقُ الْمَاعِزِ يُقَامُ كُلَّ أُسْبُوعٍ عِنْدَ سَفْحِ الْقَلْعَةِ.","ro":"Mā zāla sūqu l-māʿizi yuqāmu kulla usbūʿin ʿinda safḥi l-qalʿati."},{"fr":"Les artisans fabriquent encore des poteries comme leurs ancêtres.","tgt":"مَا زَالَ الْحِرَفِيُّونَ يَصْنَعُونَ الْفَخَّارَ مِثْلَ أَجْدَادِهِمْ.","ro":"Mā zāla l-ḥirafiyyūna yaṣnaʿūna l-fakhkhāra mithla ajdādihim."},{"fr":"Du haut de la tour, on voit une immense palmeraie.","tgt":"مِنْ أَعْلَى الْبُرْجِ، نَرَى وَاحَةَ نَخِيلٍ شَاسِعَةً.","ro":"Min aʿlā l-burji, narā wāḥata nakhīlin shāsiʿatan."},{"fr":"Les anciens canaux d'irrigation fonctionnent toujours.","tgt":"مَا زَالَتْ قَنَوَاتُ الرَّيِّ الْقَدِيمَةُ تَعْمَلُ.","ro":"Mā zālat qanawātu r-rayyi l-qadīmatu taʿmalu."},{"fr":"Le soir, nous parlions encore de cette visite.","tgt":"فِي الْمَسَاءِ، كُنَّا مَا نَزَالُ نَتَحَدَّثُ عَنْ هَذِهِ الزِّيَارَةِ.","ro":"Fī l-masāʾi, kunnā mā nazālu nataḥaddathu ʿan hādhihi z-ziyārati."}],"tip":{"title":"« Ma zala » : toujours, encore","example":"Son fort circulaire domine encore la ville. — <b>مَا زَالَتْ</b> قَلْعَتُهَا الدَّائِرِيَّةُ تُطِلُّ عَلَى الْمَدِينَةِ.","body":"Pour dire toujours ou encore, l'arabe utilise « ma zala », qui signifie littéralement : n'a pas cessé. « Ma zalat qalatuha tutillu » se décompose ainsi : n'a pas cessé, son fort, il domine. C'est un verbe qui se conjugue : « ma zilta », tu es toujours, « ma zilna », nous sommes toujours. Il est suivi soit d'un verbe au présent, comme « ma zala yasnau », il fabrique encore, soit d'un adjectif terminé en « an », comme « ma zalat qawiyyatan », ils sont toujours solides. Astuce : pensez à la tournure française il ne cesse de, c'est exactement la même logique.","exampleRo":"Mā zālat qalʿatuhā d-dāʾiriyyatu tuṭillu ʿalā l-madīnati.","lit":"[ne… pas] · elle a cessé · fort-de-elle · [le] circulaire · elle domine · sur · [la] ville","say":{"Ma zala":"مَا زَالَ","ma zala":"مَا زَالَ","Ma zalat qalatuha tutillu":"مَا زَالَتْ قَلْعَتُهَا تُطِلُّ","ma zilta":"مَا زِلْتَ","ma zilna":"مَا زِلْنَا","ma zala yasnau":"مَا زَالَ يَصْنَعُ","ma zalat qawiyyatan":"مَا زَالَتْ قَوِيَّةً"}}},{"title":"Les terrasses du Djebel Akhdar","phrases":[{"fr":"La route vers le Djebel Akhdar est très raide.","tgt":"الطَّرِيقُ إِلَى الْجَبَلِ الْأَخْضَرِ شَدِيدُ الِانْحِدَارِ.","ro":"Aṭ-ṭarīqu ilā l-jabali l-akhḍari shadīdu l-inḥidāri."},{"fr":"Seuls les véhicules à quatre roues motrices sont autorisés à monter.","tgt":"لَا يُسْمَحُ بِالصُّعُودِ إِلَّا لِسَيَّارَاتِ الدَّفْعِ الرُّبَاعِيِّ.","ro":"Lā yusmaḥu bi-ṣ-ṣuʿūdi illā li-sayyārāti d-dafʿi r-rubāʿiyyi."},{"fr":"À deux mille mètres, l'air devient beaucoup plus frais.","tgt":"عَلَى ارْتِفَاعِ أَلْفَيْ مِتْرٍ، يُصْبِحُ الْهَوَاءُ أَبْرَدَ بِكَثِيرٍ.","ro":"ʿAlā rtifāʿi alfay mitrin, yuṣbiḥu l-hawāʾu abrada bi-kathīrin."},{"fr":"Les villages sont accrochés au bord des falaises.","tgt":"الْقُرَى مُعَلَّقَةٌ عَلَى حَوَافِّ الْجُرُوفِ.","ro":"Al-qurā muʿallaqatun ʿalā ḥawāffi l-jurūfi."},{"fr":"Les paysans cultivent des grenades, des noix et des abricots en terrasses.","tgt":"يَزْرَعُ الْفَلَّاحُونَ الرُّمَّانَ وَالْجَوْزَ وَالْمِشْمِشَ فِي مُدَرَّجَاتٍ.","ro":"Yazraʿu l-fallāḥūna r-rummāna wa-l-jawza wa-l-mishmisha fī mudarrajātin."},{"fr":"Au printemps, on cueille les roses pour fabriquer de l'eau de rose.","tgt":"فِي الرَّبِيعِ، تُقْطَفُ الْوُرُودُ لِصِنَاعَةِ مَاءِ الْوَرْدِ.","ro":"Fī r-rabīʿi, tuqṭafu l-wurūdu li-ṣināʿati māʾi l-wardi."},{"fr":"Un vieil homme nous a montré l'alambic de sa famille.","tgt":"أَرَانَا رَجُلٌ مُسِنٌّ جِهَازَ التَّقْطِيرِ الْخَاصَّ بِعَائِلَتِهِ.","ro":"Arānā rajulun musinnun jihāza t-taqṭīri l-khāṣṣa bi-ʿāʾilatihi."},{"fr":"Un sentier de montagne relie plusieurs villages abandonnés.","tgt":"يَرْبِطُ مَمَرٌّ جَبَلِيٌّ بَيْنَ عِدَّةِ قُرًى مَهْجُورَةٍ.","ro":"Yarbiṭu mamarrun jabaliyyun bayna ʿiddati quran mahjūratin."},{"fr":"La vue sur les gorges donne vraiment le vertige.","tgt":"الْمَنْظَرُ الْمُطِلُّ عَلَى الْوِدْيَانِ يُثِيرُ الدُّوَارَ حَقًّا.","ro":"Al-manẓaru l-muṭillu ʿalā l-widyāni yuthīru d-duwāra ḥaqqan."},{"fr":"Nous avons dormi dans une maison d'hôtes au milieu des rosiers.","tgt":"نِمْنَا فِي بَيْتِ ضِيَافَةٍ بَيْنَ شُجَيْرَاتِ الْوَرْدِ.","ro":"Nimnā fī bayti ḍiyāfatin bayna shujayrāti l-wardi."}]},{"title":"Une nuit dans les sables de Wahiba","phrases":[{"fr":"Les sables de Wahiba se trouvent à trois heures de Mascate.","tgt":"تَقَعُ رِمَالُ وَهِيبَةَ عَلَى بُعْدِ ثَلَاثِ سَاعَاتٍ مِنْ مَسْقَطَ.","ro":"Taqaʿu rimālu Wahībata ʿalā buʿdi thalāthi sāʿātin min Masqaṭa."},{"fr":"Les dunes orange peuvent atteindre cent mètres de haut.","tgt":"قَدْ يَصِلُ ارْتِفَاعُ الْكُثْبَانِ الْبُرْتُقَالِيَّةِ إِلَى مِئَةِ مِتْرٍ.","ro":"Qad yaṣilu rtifāʿu l-kuthbāni l-burtuqāliyyati ilā miʾati mitrin."},{"fr":"Notre chauffeur a dégonflé un peu les pneus avant d'entrer dans le sable.","tgt":"أَفْرَغَ سَائِقُنَا الْإِطَارَاتِ مِنْ بَعْضِ الْهَوَاءِ قَبْلَ دُخُولِ الرِّمَالِ.","ro":"Afragha sāʾiqunā l-iṭārāti min baʿḍi l-hawāʾi qabla dukhūli r-rimāli."},{"fr":"Une famille bédouine nous a reçus sous sa tente.","tgt":"اسْتَضَافَتْنَا عَائِلَةٌ بَدَوِيَّةٌ فِي خَيْمَتِهَا.","ro":"Istaḍāfatnā ʿāʾilatun badawiyyatun fī khaymatihā."},{"fr":"Les enfants nous ont montré comment on trait les chamelles.","tgt":"أَرَانَا الْأَطْفَالُ كَيْفَ تُحْلَبُ النُّوقُ.","ro":"Arānā l-aṭfālu kayfa tuḥlabu n-nūqu."},{"fr":"Nous avons grimpé au sommet d'une dune pour regarder le coucher du soleil.","tgt":"صَعِدْنَا إِلَى قِمَّةِ كَثِيبٍ لِنُشَاهِدَ غُرُوبَ الشَّمْسِ.","ro":"Ṣaʿidnā ilā qimmati kathībin li-nushāhida ghurūba sh-shamsi."},{"fr":"Le sable change de couleur à chaque minute.","tgt":"يَتَغَيَّرُ لَوْنُ الرَّمْلِ كُلَّ دَقِيقَةٍ.","ro":"Yataghayyaru lawnu r-ramli kulla daqīqatin."},{"fr":"Le dîner a été cuit sous la braise, dans une fosse de sable.","tgt":"طُهِيَ الْعَشَاءُ تَحْتَ الْجَمْرِ فِي حُفْرَةٍ رَمْلِيَّةٍ.","ro":"Ṭuhiya l-ʿashāʾu taḥta l-jamri fī ḥufratin ramliyyatin."},{"fr":"La nuit, le ciel était rempli d'étoiles.","tgt":"فِي اللَّيْلِ، كَانَتِ السَّمَاءُ مَلِيئَةً بِالنُّجُومِ.","ro":"Fī l-layli, kānati s-samāʾu malīʾatan bi-n-nujūmi."},{"fr":"Je n'avais jamais connu un silence aussi profond.","tgt":"لَمْ أَعْرِفْ مِنْ قَبْلُ صَمْتًا عَمِيقًا كَهَذَا.","ro":"Lam aʿrif min qablu ṣamtan ʿamīqan ka-hādhā."}]},{"title":"Randonnée dans le Wadi Shab","phrases":[{"fr":"Nous sommes arrivés au wadi tôt le matin, pleins d'enthousiasme.","tgt":"وَصَلْنَا إِلَى الْوَادِي فِي الصَّبَاحِ الْبَاكِرِ مُتَحَمِّسِينَ.","ro":"Waṣalnā ilā l-wādī fī ṣ-ṣabāḥi l-bākiri mutaḥammisīna."},{"fr":"Une petite barque nous a emmenés sur l'autre rive.","tgt":"نَقَلَنَا قَارِبٌ صَغِيرٌ إِلَى الضِّفَّةِ الْأُخْرَى.","ro":"Naqalanā qāribun ṣaghīrun ilā ḍ-ḍiffati l-ukhrā."},{"fr":"Le guide marchait devant nous en chantant.","tgt":"كَانَ الْمُرْشِدُ يَمْشِي أَمَامَنَا مُغَنِّيًا.","ro":"Kāna l-murshidu yamshī amāmanā mughanniyan."},{"fr":"Nous avons marché une heure entre les palmiers et les rochers.","tgt":"مَشَيْنَا سَاعَةً بَيْنَ النَّخِيلِ وَالصُّخُورِ.","ro":"Mashaynā sāʿatan bayna n-nakhīli wa-ṣ-ṣukhūri."},{"fr":"Un enfant du village est venu vers nous en souriant.","tgt":"جَاءَ إِلَيْنَا طِفْلٌ مِنَ الْقَرْيَةِ مُبْتَسِمًا.","ro":"Jāʾa ilaynā ṭiflun mina l-qaryati mubtasiman."},{"fr":"Nous avons nagé jusqu'à la grotte, émerveillés par la couleur de l'eau.","tgt":"سَبَحْنَا حَتَّى الْكَهْفِ مُنْبَهِرِينَ بِلَوْنِ الْمَاءِ.","ro":"Sabaḥnā ḥattā l-kahfi munbahirīna bi-lawni l-māʾi."},{"fr":"Il faut passer par une fente étroite pour voir la cascade.","tgt":"يَجِبُ أَنْ تَمُرَّ عَبْرَ شَقٍّ ضَيِّقٍ لِتَرَى الشَّلَّالَ.","ro":"Yajibu an tamurra ʿabra shaqqin ḍayyiqin li-tarā sh-shallāla."},{"fr":"Ma sœur est sortie de l'eau en riant.","tgt":"خَرَجَتْ أُخْتِي مِنَ الْمَاءِ ضَاحِكَةً.","ro":"Kharajat ukhtī mina l-māʾi ḍāḥikatan."},{"fr":"Nous sommes rentrés à pied, épuisés mais heureux.","tgt":"عُدْنَا مَشْيًا مُتْعَبِينَ وَلَكِنْ سُعَدَاءَ.","ro":"ʿUdnā mashyan mutʿabīna wa-lākin suʿadāʾa."},{"fr":"Le guide nous a quittés en nous souhaitant un bon voyage.","tgt":"وَدَّعَنَا الْمُرْشِدُ مُتَمَنِّيًا لَنَا رِحْلَةً سَعِيدَةً.","ro":"Waddaʿanā l-murshidu mutamanniyan lanā riḥlatan saʿīdatan."}],"tip":{"title":"Le complément d'état : il est venu en souriant","example":"Un enfant du village est venu vers nous en souriant. — جَاءَ إِلَيْنَا طِفْلٌ مِنَ الْقَرْيَةِ <b>مُبْتَسِمًا</b>.","body":"Pour dire dans quel état on fait quelque chose, le français utilise souvent le gérondif : en souriant, en riant. L'arabe, lui, ajoute simplement un adjectif ou un participe terminé par le son « an » : c'est le « hal », le complément d'état. « Jaa mubtasiman » se dit littéralement : il est venu, souriant. Ce mot s'accorde avec la personne : « dahikatan » pour une femme qui rit, « mutabina » pour un groupe fatigué, « samitina », nous, silencieux. Astuce : dès que vous entendez un adjectif en « an » ou en « ina » après un verbe, demandez-vous : dans quel état ?","exampleRo":"Jāʾa ilaynā ṭiflun mina l-qaryati mubtasiman.","lit":"est venu · vers-nous · enfant · de · [le] village · souriant","say":{"hal":"حَال","Jaa mubtasiman":"جَاءَ مُبْتَسِمًا","dahikatan":"ضَاحِكَةً","mutabina":"مُتْعَبِينَ","samitina":"صَامِتِينَ"}}},{"title":"Plongée aux îles Daymaniyat","phrases":[{"fr":"Les îles Daymaniyat forment une réserve naturelle protégée.","tgt":"جُزُرُ الدِّيمَانِيَّاتِ مَحْمِيَّةٌ طَبِيعِيَّةٌ.","ro":"Juzuru d-Dīmāniyyāti maḥmiyyatun ṭabīʿiyyatun."},{"fr":"Le bateau a quitté le port à sept heures du matin.","tgt":"انْطَلَقَ الْقَارِبُ مِنَ الْمِينَاءِ فِي السَّاعَةِ السَّابِعَةِ صَبَاحًا.","ro":"Inṭalaqa l-qāribu mina l-mīnāʾi fī s-sāʿati s-sābiʿati ṣabāḥan."},{"fr":"L'instructeur a vérifié notre équipement avant la plongée.","tgt":"فَحَصَ الْمُدَرِّبُ مُعَدَّاتِنَا قَبْلَ الْغَوْصِ.","ro":"Faḥaṣa l-mudarribu muʿaddātinā qabla l-ghawṣi."},{"fr":"C'était ma première plongée en pleine mer.","tgt":"كَانَ هَذَا أَوَّلَ غَوْصٍ لِي فِي عُرْضِ الْبَحْرِ.","ro":"Kāna hādhā awwala ghawṣin lī fī ʿurḍi l-baḥri."},{"fr":"Sous l'eau, nous avons vu des tortues et des poissons multicolores.","tgt":"تَحْتَ الْمَاءِ، رَأَيْنَا سَلَاحِفَ وَأَسْمَاكًا مُلَوَّنَةً.","ro":"Taḥta l-māʾi, raʾaynā salāḥifa wa-asmākan mulawwanatan."},{"fr":"Les récifs de corail semblent ici en bonne santé.","tgt":"تَبْدُو الشُّعَبُ الْمَرْجَانِيَّةُ هُنَا فِي حَالَةٍ جَيِّدَةٍ.","ro":"Tabdū sh-shuʿabu l-marjāniyyatu hunā fī ḥālatin jayyidatin."},{"fr":"Il est interdit de toucher le corail ou de nourrir les poissons.","tgt":"يُمْنَعُ لَمْسُ الْمَرْجَانِ أَوْ إِطْعَامُ الْأَسْمَاكِ.","ro":"Yumnaʿu lamsu l-marjāni aw iṭʿāmu l-asmāki."},{"fr":"Un requin-baleine est passé lentement près de nous.","tgt":"مَرَّ قِرْشٌ حُوتِيٌّ بِبُطْءٍ بِالْقُرْبِ مِنَّا.","ro":"Marra qirshun ḥūtiyyun bi-buṭʾin bi-l-qurbi minnā."},{"fr":"Nous sommes remontés tranquillement à la surface.","tgt":"صَعِدْنَا إِلَى السَّطْحِ بِهُدُوءٍ.","ro":"Ṣaʿidnā ilā s-saṭḥi bi-hudūʾin."},{"fr":"Cette plongée m'a donné envie d'apprendre sérieusement à plonger.","tgt":"جَعَلَنِي هَذَا الْغَوْصُ أَرْغَبُ فِي تَعَلُّمِ الْغَوْصِ بِجِدِّيَّةٍ.","ro":"Jaʿalanī hādhā l-ghawṣu arghabu fī taʿallumi l-ghawṣi bi-jiddiyyatin."}]},{"title":"En boutre dans les fjords de Musandam","phrases":[{"fr":"Musandam est une péninsule séparée du reste d'Oman.","tgt":"مُسَنْدَمُ شِبْهُ جَزِيرَةٍ مُنْفَصِلَةٍ عَنْ بَاقِي عُمَانَ.","ro":"Musandamu shibhu jazīratin munfaṣilatin ʿan bāqī ʿUmāna."},{"fr":"Ses fjords étroits sont entourés de montagnes nues.","tgt":"خُلْجَانُهَا الضَّيِّقَةُ مُحَاطَةٌ بِجِبَالٍ جَرْدَاءَ.","ro":"Khuljānuhā ḍ-ḍayyiqatu muḥāṭatun bi-jibālin jardāʾa."},{"fr":"Nous avons embarqué pour la journée sur un boutre traditionnel en bois.","tgt":"رَكِبْنَا مَرْكَبًا خَشَبِيًّا تَقْلِيدِيًّا لِيَوْمٍ كَامِلٍ.","ro":"Rakibnā markaban khashabiyyan taqlīdiyyan li-yawmin kāmilin."},{"fr":"Ces bateaux servaient autrefois au commerce.","tgt":"كَانَتْ هَذِهِ الْمَرَاكِبُ تُسْتَخْدَمُ قَدِيمًا لِلتِّجَارَةِ.","ro":"Kānat hādhihi l-marākibu tustakhdamu qadīman li-t-tijārati."},{"fr":"Des dauphins ont nagé à côté du boutre pendant plusieurs minutes.","tgt":"سَبَحَتِ الدَّلَافِينُ بِجَانِبِ الْمَرْكَبِ عِدَّةَ دَقَائِقَ.","ro":"Sabaḥati d-dalāfīnu bi-jānibi l-markabi ʿiddata daqāʾiqa."},{"fr":"Le capitaine a jeté l'ancre près d'un village de pêcheurs.","tgt":"أَلْقَى الْقُبْطَانُ الْمِرْسَاةَ قُرْبَ قَرْيَةِ صَيَّادِينَ.","ro":"Alqā l-qubṭānu l-mirsāta qurba qaryati ṣayyādīna."},{"fr":"On ne peut atteindre ce village que par la mer.","tgt":"لَا يُمْكِنُ الْوُصُولُ إِلَى هَذِهِ الْقَرْيَةِ إِلَّا عَنْ طَرِيقِ الْبَحْرِ.","ro":"Lā yumkinu l-wuṣūlu ilā hādhihi l-qaryati illā ʿan ṭarīqi l-baḥri."},{"fr":"Nous avons nagé avec masque et tuba dans une eau turquoise.","tgt":"سَبَحْنَا بِالْقِنَاعِ وَالْأُنْبُوبِ فِي مِيَاهٍ فَيْرُوزِيَّةٍ.","ro":"Sabaḥnā bi-l-qināʿi wa-l-unbūbi fī miyāhin fayrūziyyatin."},{"fr":"Le déjeuner de poisson grillé a été servi sur le pont.","tgt":"قُدِّمَ الْغَدَاءُ مِنَ السَّمَكِ الْمَشْوِيِّ عَلَى سَطْحِ الْمَرْكَبِ.","ro":"Quddima l-ghadāʾu mina s-samaki l-mashwiyyi ʿalā saṭḥi l-markabi."},{"fr":"Au retour, tout le monde s'est endormi sur les coussins.","tgt":"فِي طَرِيقِ الْعَوْدَةِ، نَامَ الْجَمِيعُ عَلَى الْوَسَائِدِ.","ro":"Fī ṭarīqi l-ʿawdati, nāma l-jamīʿu ʿalā l-wasāʾidi."}]},{"title":"Une tempête de sable sur la route","phrases":[{"fr":"Le ciel est soudain devenu jaune.","tgt":"أَصْبَحَتِ السَّمَاءُ فَجْأَةً صَفْرَاءَ.","ro":"Aṣbaḥati s-samāʾu fajʾatan ṣafrāʾa."},{"fr":"Le vent s'est levé et a soulevé des nuages de poussière.","tgt":"هَبَّتِ الرِّيحُ وَأَثَارَتْ سُحُبًا مِنَ الْغُبَارِ.","ro":"Habbati r-rīḥu wa-athārat suḥuban mina l-ghubāri."},{"fr":"Le chauffeur a arrêté la voiture au bord de la route.","tgt":"أَوْقَفَ السَّائِقُ السَّيَّارَةَ عَلَى جَانِبِ الطَّرِيقِ.","ro":"Awqafa s-sāʾiqu s-sayyārata ʿalā jānibi ṭ-ṭarīqi."},{"fr":"On ne voyait plus rien à dix mètres.","tgt":"لَمْ نَعُدْ نَرَى شَيْئًا عَلَى بُعْدِ عَشَرَةِ أَمْتَارٍ.","ro":"Lam naʿud narā shayʾan ʿalā buʿdi ʿasharati amtārin."},{"fr":"Nous avons fermé les fenêtres et couvert nos visages avec des foulards.","tgt":"أَغْلَقْنَا النَّوَافِذَ وَغَطَّيْنَا وُجُوهَنَا بِالْأَوْشِحَةِ.","ro":"Aghlaqnā n-nawāfidha wa-ghaṭṭaynā wujūhanā bi-l-awshiḥati."},{"fr":"Le sable s'infiltrait partout, même dans nos sacs.","tgt":"كَانَ الرَّمْلُ يَتَسَرَّبُ إِلَى كُلِّ مَكَانٍ، حَتَّى إِلَى حَقَائِبِنَا.","ro":"Kāna r-ramlu yatasarrabu ilā kulli makānin, ḥattā ilā ḥaqāʾibinā."},{"fr":"Le chauffeur est resté calme, car il en avait l'habitude.","tgt":"بَقِيَ السَّائِقُ هَادِئًا لِأَنَّهُ مُعْتَادٌ عَلَى ذَلِكَ.","ro":"Baqiya s-sāʾiqu hādiʾan li-annahu muʿtādun ʿalā dhālika."},{"fr":"La tempête a duré près d'une heure.","tgt":"اسْتَمَرَّتِ الْعَاصِفَةُ نَحْوَ سَاعَةٍ.","ro":"Istamarrati l-ʿāṣifatu naḥwa sāʿatin."},{"fr":"Ensuite, le ciel est redevenu parfaitement bleu.","tgt":"بَعْدَ ذَلِكَ، عَادَتِ السَّمَاءُ زَرْقَاءَ صَافِيَةً.","ro":"Baʿda dhālika, ʿādati s-samāʾu zarqāʾa ṣāfiyatan."},{"fr":"Il nous a fallu une heure pour nettoyer la voiture.","tgt":"احْتَجْنَا إِلَى سَاعَةٍ لِتَنْظِيفِ السَّيَّارَةِ.","ro":"Iḥtajnā ilā sāʿatin li-tanẓīfi s-sayyārati."}]},{"title":"Salalah sous la mousson","phrases":[{"fr":"Salalah se trouve dans le sud d'Oman, dans la région du Dhofar.","tgt":"تَقَعُ صَلَالَةُ فِي جَنُوبِ عُمَانَ، فِي مِنْطَقَةِ ظُفَارَ.","ro":"Taqaʿu Ṣalālatu fī janūbi ʿUmāna, fī minṭaqati Ẓufāra."},{"fr":"En été, la saison du khareef apporte de la bruine et du brouillard.","tgt":"فِي الصَّيْفِ، يَجْلِبُ مَوْسِمُ الْخَرِيفِ رَذَاذًا وَضَبَابًا.","ro":"Fī ṣ-ṣayfi, yajlibu mawsimu l-kharīfi radhādhan wa-ḍabāban."},{"fr":"Les collines deviennent alors entièrement vertes.","tgt":"فَتُصْبِحُ التِّلَالُ خَضْرَاءَ تَمَامًا.","ro":"Fa-tuṣbiḥu t-tilālu khaḍrāʾa tamāman."},{"fr":"Des familles de tout le Golfe viennent ici pour fuir la chaleur.","tgt":"تَأْتِي إِلَى هُنَا عَائِلَاتٌ مِنْ كُلِّ دُوَلِ الْخَلِيجِ لِتَهْرُبَ مِنَ الْحَرِّ.","ro":"Taʾtī ilā hunā ʿāʾilātun min kulli duwali l-khalīji li-tahruba mina l-ḥarri."},{"fr":"Il fait vingt-cinq degrés ici, alors qu'il en fait quarante-cinq à Mascate.","tgt":"دَرَجَةُ الْحَرَارَةِ هُنَا خَمْسٌ وَعِشْرُونَ، بَيْنَمَا تَبْلُغُ خَمْسًا وَأَرْبَعِينَ فِي مَسْقَطَ.","ro":"Darajatu l-ḥarārati hunā khamsun wa-ʿishrūna, baynamā tablughu khamsan wa-arbaʿīna fī Masqaṭa."},{"fr":"Les cascades du Wadi Darbat ne coulent que pendant cette saison.","tgt":"لَا تَتَدَفَّقُ شَلَّالَاتُ وَادِي دَرْبَاتَ إِلَّا فِي هَذَا الْمَوْسِمِ.","ro":"Lā tatadaffaqu shallālātu Wādī Darbāta illā fī hādhā l-mawsimi."},{"fr":"Les dromadaires se promènent librement au bord de la route.","tgt":"تَتَجَوَّلُ الْجِمَالُ بِحُرِّيَّةٍ عَلَى جَانِبِ الطَّرِيقِ.","ro":"Tatajawwalu l-jimālu bi-ḥurriyyatin ʿalā jānibi ṭ-ṭarīqi."},{"fr":"Nous avons bu de l'eau de coco fraîche au bord de la route.","tgt":"شَرِبْنَا مَاءَ النَّارَجِيلِ الطَّازَجَ عَلَى قَارِعَةِ الطَّرِيقِ.","ro":"Sharibnā māʾa n-nārajīli ṭ-ṭāzaja ʿalā qāriʿati ṭ-ṭarīqi."},{"fr":"Le Dhofar est aussi la terre de l'encens.","tgt":"ظُفَارُ أَيْضًا مَوْطِنُ اللُّبَانِ.","ro":"Ẓufāru ayḍan mawṭinu l-lubāni."},{"fr":"Les arbres à encens poussent sur des terres très sèches.","tgt":"تَنْمُو أَشْجَارُ اللُّبَانِ فِي أَرَاضٍ جَافَّةٍ جِدًّا.","ro":"Tanmū ashjāru l-lubāni fī arāḍin jāffatin jiddan."}]},{"title":"Grottes et gouffres : un autre monde","phrases":[{"fr":"La grotte d'Al Hoota s'étend sur plusieurs kilomètres sous la montagne.","tgt":"يَمْتَدُّ كَهْفُ الْهُوتَةِ عِدَّةَ كِيلُومِتْرَاتٍ تَحْتَ الْجَبَلِ.","ro":"Yamtaddu kahfu l-Hūtati ʿiddata kīlūmitrātin taḥta l-jabali."},{"fr":"Un petit train électrique nous a conduits jusqu'à l'entrée.","tgt":"أَوْصَلَنَا قِطَارٌ كَهْرَبَائِيٌّ صَغِيرٌ إِلَى الْمَدْخَلِ.","ro":"Awṣalanā qiṭārun kahrabāʾiyyun ṣaghīrun ilā l-madkhali."},{"fr":"À l'intérieur, nous avions l'impression d'être sur une autre planète.","tgt":"فِي الدَّاخِلِ، شَعَرْنَا كَأَنَّنَا عَلَى كَوْكَبٍ آخَرَ.","ro":"Fī d-dākhili, shaʿarnā ka-annanā ʿalā kawkabin ākhara."},{"fr":"Les stalactites ont l'air de statues géantes.","tgt":"تَبْدُو الْهَوَابِطُ كَأَنَّهَا تَمَاثِيلُ عِمْلَاقَةٌ.","ro":"Tabdū l-hawābiṭu ka-annahā tamāthīlu ʿimlāqatun."},{"fr":"Le lac souterrain abrite des poissons aveugles.","tgt":"تَعِيشُ فِي الْبُحَيْرَةِ الْجَوْفِيَّةِ أَسْمَاكٌ عَمْيَاءُ.","ro":"Taʿīshu fī l-buḥayrati l-jawfiyyati asmākun ʿamyāʾu."},{"fr":"Le guide parlait à voix basse, comme s'il ne voulait pas réveiller la grotte.","tgt":"كَانَ الْمُرْشِدُ يَتَكَلَّمُ بِصَوْتٍ خَافِتٍ كَأَنَّهُ لَا يُرِيدُ أَنْ يُوقِظَ الْكَهْفَ.","ro":"Kāna l-murshidu yatakallamu bi-ṣawtin khāfitin ka-annahu lā yurīdu an yūqiẓa l-kahfa."},{"fr":"Ensuite, nous sommes allés au gouffre de Bimmah, près de la côte.","tgt":"بَعْدَ ذَلِكَ، ذَهَبْنَا إِلَى حُفْرَةِ بِمَّةَ قُرْبَ السَّاحِلِ.","ro":"Baʿda dhālika, dhahabnā ilā ḥufrati Bimmata qurba s-sāḥili."},{"fr":"L'eau y est si limpide qu'on dirait du verre.","tgt":"الْمَاءُ هُنَاكَ صَافٍ جِدًّا كَأَنَّهُ زُجَاجٌ.","ro":"Al-māʾu hunāka ṣāfin jiddan ka-annahu zujājun."},{"fr":"De petits poissons nous chatouillaient les pieds comme s'ils nous connaissaient.","tgt":"كَانَتْ أَسْمَاكٌ صَغِيرَةٌ تُدَغْدِغُ أَقْدَامَنَا كَأَنَّهَا تَعْرِفُنَا.","ro":"Kānat asmākun ṣaghīratun tudaghdighu aqdāmanā ka-annahā taʿrifunā."},{"fr":"Nous sommes ressortis éblouis, comme si nous nous réveillions d'un rêve.","tgt":"خَرَجْنَا مُنْبَهِرِينَ كَأَنَّنَا اسْتَيْقَظْنَا مِنْ حُلْمٍ.","ro":"Kharajnā munbahirīna ka-annanā stayqaẓnā min ḥulmin."}],"tip":{"title":"« Kaanna » : comme si","example":"À l'intérieur, nous avions l'impression d'être sur une autre planète. — فِي الدَّاخِلِ، شَعَرْنَا <b>كَأَنَّنَا</b> عَلَى كَوْكَبٍ آخَرَ.","body":"« Kaanna » veut dire comme si, ou on dirait que. Il est formé de « ka », comme, et de « anna », que : c'est donc un membre de la famille de « inna ». Comme ses sœurs, il est suivi d'un nom à l'accusatif ou d'un pronom collé : « kaannana », comme si nous, « kaannahu », comme si lui, « kaannaha », comme si elle. Pas besoin du verbe être : « kaannahu zujajun » se dit littéralement : comme si lui, du verre, c'est-à-dire on dirait du verre. Astuce : retenez « kaanna » comme le petit mot des comparaisons rêveuses, celles qu'on fait devant un paysage incroyable.","exampleRo":"Fī d-dākhili, shaʿarnā ka-annanā ʿalā kawkabin ākhara.","lit":"dans · [l']intérieur · nous avons senti · comme-si-nous · sur · planète · autre","say":{"Kaanna":"كَأَنَّ","anna":"أَنَّ","inna":"إِنَّ","kaannana":"كَأَنَّنَا","kaannahu":"كَأَنَّهُ","kaannaha":"كَأَنَّهَا","kaannahu zujajun":"كَأَنَّهُ زُجَاجٌ","kaanna":"كَأَنَّ"}}},{"title":"Doha et le souk Waqif","phrases":[{"fr":"Nous avons pris l'avion de Mascate à Doha, un vol très court.","tgt":"سَافَرْنَا بِالطَّائِرَةِ مِنْ مَسْقَطَ إِلَى الدَّوْحَةِ فِي رِحْلَةٍ قَصِيرَةٍ.","ro":"Sāfarnā bi-ṭ-ṭāʾirati min Masqaṭa ilā d-Dawḥati fī riḥlatin qaṣīratin."},{"fr":"Le souk Waqif a été restauré dans le style d'autrefois.","tgt":"رُمِّمَ سُوقُ وَاقِفٍ عَلَى الطِّرَازِ الْقَدِيمِ.","ro":"Rummima sūqu Wāqifin ʿalā ṭ-ṭirāzi l-qadīmi."},{"fr":"Ses murs en terre et ses poutres en bois rappellent le vieux Doha.","tgt":"جُدْرَانُهُ الطِّينِيَّةُ وَعَوَارِضُهُ الْخَشَبِيَّةُ تُذَكِّرُ بِالدَّوْحَةِ الْقَدِيمَةِ.","ro":"Judrānuhu ṭ-ṭīniyyatu wa-ʿawāriḍuhu l-khashabiyyatu tudhakkiru bi-d-Dawḥati l-qadīmati."},{"fr":"On y trouve des épices, des tissus et des oiseaux.","tgt":"نَجِدُ فِيهِ التَّوَابِلَ وَالْأَقْمِشَةَ وَالطُّيُورَ.","ro":"Najidu fīhi t-tawābila wa-l-aqmishata wa-ṭ-ṭuyūra."},{"fr":"Il y a même un marché aux faucons et un hôpital qui leur est réservé.","tgt":"هُنَاكَ أَيْضًا سُوقٌ لِلصُّقُورِ وَمُسْتَشْفًى خَاصٌّ بِهَا.","ro":"Hunāka ayḍan sūqun li-ṣ-ṣuqūri wa-mustashfan khāṣṣun bihā."},{"fr":"La chasse au faucon est une tradition très ancienne dans le Golfe.","tgt":"الصَّيْدُ بِالصُّقُورِ تَقْلِيدٌ عَرِيقٌ فِي الْخَلِيجِ.","ro":"Aṣ-ṣaydu bi-ṣ-ṣuqūri taqlīdun ʿarīqun fī l-khalīji."},{"fr":"Le soir, les terrasses des cafés se remplissent de monde.","tgt":"فِي الْمَسَاءِ، تَمْتَلِئُ شُرُفَاتُ الْمَقَاهِي بِالنَّاسِ.","ro":"Fī l-masāʾi, tamtaliʾu shurufātu l-maqāhī bi-n-nāsi."},{"fr":"Nous avons dîné d'un riz aux épices avec de l'agneau.","tgt":"تَعَشَّيْنَا أَرُزًّا بِالتَّوَابِلِ مَعَ لَحْمِ الضَّأْنِ.","ro":"Taʿashshaynā aruzzan bi-t-tawābili maʿa laḥmi ḍ-ḍaʾni."},{"fr":"Un vendeur nous a proposé de goûter le thé karak.","tgt":"عَرَضَ عَلَيْنَا بَائِعٌ أَنْ نَتَذَوَّقَ شَايَ الْكَرَكِ.","ro":"ʿAraḍa ʿalaynā bāʾiʿun an natadhawwaqa shāya l-karaki."},{"fr":"Le contraste avec les gratte-ciel voisins est saisissant.","tgt":"التَّنَاقُضُ مَعَ نَاطِحَاتِ السَّحَابِ الْمُجَاوِرَةِ مُدْهِشٌ.","ro":"At-tanāquḍu maʿa nāṭiḥāti s-saḥābi l-mujāwirati mudhishun."}]},{"title":"Le Musée national du Qatar","phrases":[{"fr":"Le Musée national du Qatar a la forme d'une rose des sables.","tgt":"يَتَّخِذُ مَتْحَفُ قَطَرَ الْوَطَنِيُّ شَكْلَ وَرْدَةِ الصَّحْرَاءِ.","ro":"Yattakhidhu matḥafu Qaṭara l-waṭaniyyu shakla wardati ṣ-ṣaḥrāʾi."},{"fr":"Cette fleur de pierre se forme naturellement dans le désert.","tgt":"تَتَكَوَّنُ هَذِهِ الْوَرْدَةُ الْحَجَرِيَّةُ طَبِيعِيًّا فِي الصَّحْرَاءِ.","ro":"Tatakawwanu hādhihi l-wardatu l-ḥajariyyatu ṭabīʿiyyan fī ṣ-ṣaḥrāʾi."},{"fr":"L'architecte s'en est inspiré pour dessiner le bâtiment.","tgt":"اسْتَوْحَى الْمِعْمَارِيُّ مِنْهَا تَصْمِيمَ الْمَبْنَى.","ro":"Istawḥā l-miʿmāriyyu minhā taṣmīma l-mabnā."},{"fr":"Le parcours raconte l'histoire de la péninsule, de la préhistoire à nos jours.","tgt":"يَرْوِي الْمَسَارُ تَارِيخَ شِبْهِ الْجَزِيرَةِ مِنْ عُصُورِ مَا قَبْلَ التَّارِيخِ حَتَّى الْيَوْمِ.","ro":"Yarwī l-masāru tārīkha shibhi l-jazīrati min ʿuṣūri mā qabla t-tārīkhi ḥattā l-yawmi."},{"fr":"Une salle entière est consacrée à la pêche aux perles.","tgt":"خُصِّصَتْ قَاعَةٌ كَامِلَةٌ لِصَيْدِ اللُّؤْلُؤِ.","ro":"Khuṣṣiṣat qāʿatun kāmilatun li-ṣaydi l-luʾluʾi."},{"fr":"Les plongeurs restaient sous l'eau sans aucun équipement.","tgt":"كَانَ الْغَوَّاصُونَ يَبْقَوْنَ تَحْتَ الْمَاءِ بِلَا أَيِّ مُعَدَّاتٍ.","ro":"Kāna l-ghawwāṣūna yabqawna taḥta l-māʾi bi-lā ayyi muʿaddātin."},{"fr":"Leur vie était dure et dangereuse.","tgt":"كَانَتْ حَيَاتُهُمْ قَاسِيَةً وَخَطِيرَةً.","ro":"Kānat ḥayātuhum qāsiyatan wa-khaṭīratan."},{"fr":"Des écrans géants projettent des images du désert sur les murs.","tgt":"تَعْرِضُ شَاشَاتٌ عِمْلَاقَةٌ صُوَرًا لِلصَّحْرَاءِ عَلَى الْجُدْرَانِ.","ro":"Taʿriḍu shāshātun ʿimlāqatun ṣuwaran li-ṣ-ṣaḥrāʾi ʿalā l-judrāni."},{"fr":"On peut facilement y passer une demi-journée.","tgt":"يُمْكِنُ أَنْ تَقْضِيَ فِيهِ نِصْفَ يَوْمٍ بِسُهُولَةٍ.","ro":"Yumkinu an taqḍiya fīhi niṣfa yawmin bi-suhūlatin."},{"fr":"En sortant, nous avons flâné sur la corniche de Doha.","tgt":"عِنْدَ خُرُوجِنَا، تَمَشَّيْنَا عَلَى كُورْنِيشِ الدَّوْحَةِ.","ro":"ʿInda khurūjinā, tamashshaynā ʿalā kūrnīshi d-Dawḥati."}]},{"title":"Les tortues de Ras al Jinz","phrases":[{"fr":"Chaque nuit, des tortues vertes viennent pondre sur cette plage.","tgt":"تَأْتِي السَّلَاحِفُ الْخَضْرَاءُ كُلَّ لَيْلَةٍ لِتَضَعَ بَيْضَهَا عَلَى هَذَا الشَّاطِئِ.","ro":"Taʾtī s-salāḥifu l-khaḍrāʾu kulla laylatin li-taḍaʿa bayḍahā ʿalā hādhā sh-shāṭiʾi."},{"fr":"La réserve de Ras al Jinz limite le nombre de visiteurs.","tgt":"تُحَدِّدُ مَحْمِيَّةُ رَأْسِ الْجِنْزِ عَدَدَ الزُّوَّارِ.","ro":"Tuḥaddidu maḥmiyyatu Raʾsi l-Jinzi ʿadada z-zuwwāri."},{"fr":"Il faut réserver la visite nocturne plusieurs jours à l'avance.","tgt":"يَجِبُ حَجْزُ الزِّيَارَةِ اللَّيْلِيَّةِ قَبْلَ عِدَّةِ أَيَّامٍ.","ro":"Yajibu ḥajzu z-ziyārati l-layliyyati qabla ʿiddati ayyāmin."},{"fr":"La lumière dérange les tortues, c'est pourquoi les lampes sont interdites.","tgt":"الضَّوْءُ يُزْعِجُ السَّلَاحِفَ، لِذَلِكَ تُمْنَعُ الْمَصَابِيحُ.","ro":"Aḍ-ḍawʾu yuzʿiju s-salāḥifa, li-dhālika tumnaʿu l-maṣābīḥu."},{"fr":"Nous avons attendu en silence dans l'obscurité.","tgt":"انْتَظَرْنَا صَامِتِينَ فِي الظَّلَامِ.","ro":"Intaẓarnā ṣāmitīna fī ẓ-ẓalāmi."},{"fr":"Une énorme tortue creusait lentement son nid.","tgt":"كَانَتْ سُلَحْفَاةٌ ضَخْمَةٌ تَحْفِرُ عُشَّهَا بِبُطْءٍ.","ro":"Kānat sulaḥfātun ḍakhmatun taḥfiru ʿushshahā bi-buṭʾin."},{"fr":"Elle peut pondre plus de cent œufs en une seule nuit.","tgt":"يُمْكِنُ أَنْ تَضَعَ أَكْثَرَ مِنْ مِئَةِ بَيْضَةٍ فِي لَيْلَةٍ وَاحِدَةٍ.","ro":"Yumkinu an taḍaʿa akthara min miʾati bayḍatin fī laylatin wāḥidatin."},{"fr":"À l'aube, nous avons vu des bébés tortues courir vers la mer.","tgt":"عِنْدَ الْفَجْرِ، رَأَيْنَا صِغَارَ السَّلَاحِفِ تَرْكُضُ نَحْوَ الْبَحْرِ.","ro":"ʿInda l-fajri, raʾaynā ṣighāra s-salāḥifi tarkuḍu naḥwa l-baḥri."},{"fr":"Très peu d'entre elles atteindront l'âge adulte.","tgt":"قَلِيلٌ مِنْهَا فَقَطْ سَيَبْلُغُ سِنَّ الرُّشْدِ.","ro":"Qalīlun minhā faqaṭ sa-yablughu sinna r-rushdi."},{"fr":"Ce spectacle nous a appris le respect de la nature.","tgt":"عَلَّمَنَا هَذَا الْمَشْهَدُ احْتِرَامَ الطَّبِيعَةِ.","ro":"ʿAllamanā hādhā l-mashhadu ḥtirāma ṭ-ṭabīʿati."}]},{"title":"Invités dans une famille omanaise","phrases":[{"fr":"Notre guide nous a invités à déjeuner chez ses parents.","tgt":"دَعَانَا مُرْشِدُنَا إِلَى الْغَدَاءِ فِي بَيْتِ وَالِدَيْهِ.","ro":"Daʿānā murshidunā ilā l-ghadāʾi fī bayti wālidayhi."},{"fr":"On enlève ses chaussures avant d'entrer dans le salon.","tgt":"نَخْلَعُ أَحْذِيَتَنَا قَبْلَ دُخُولِ الْمَجْلِسِ.","ro":"Nakhlaʿu aḥdhiyatanā qabla dukhūli l-majlisi."},{"fr":"Tout le monde s'assoit par terre, sur de beaux tapis.","tgt":"يَجْلِسُ الْجَمِيعُ عَلَى الْأَرْضِ فَوْقَ سَجَّادٍ جَمِيلٍ.","ro":"Yajlisu l-jamīʿu ʿalā l-arḍi fawqa sajjādin jamīlin."},{"fr":"Le père de notre guide nous a accueillis chaleureusement.","tgt":"رَحَّبَ بِنَا وَالِدُ مُرْشِدِنَا بِحَرَارَةٍ.","ro":"Raḥḥaba binā wālidu murshidinā bi-ḥarāratin."},{"fr":"Le café est servi avant le repas, dans de petites tasses.","tgt":"تُقَدَّمُ الْقَهْوَةُ قَبْلَ الطَّعَامِ فِي فَنَاجِينَ صَغِيرَةٍ.","ro":"Tuqaddamu l-qahwatu qabla ṭ-ṭaʿāmi fī fanājīna ṣaghīratin."},{"fr":"Pour dire qu'on n'en veut plus, on secoue doucement la tasse.","tgt":"لِكَيْ تَقُولَ إِنَّكَ اكْتَفَيْتَ، تَهُزُّ الْفِنْجَانَ بِلُطْفٍ.","ro":"Li-kay taqūla innaka ktafayta, tahuzzu l-finjāna bi-luṭfin."},{"fr":"Le plat principal était un riz au poulet délicieusement parfumé.","tgt":"كَانَ الطَّبَقُ الرَّئِيسِيُّ أَرُزًّا بِالدَّجَاجِ ذَا رَائِحَةٍ زَكِيَّةٍ.","ro":"Kāna ṭ-ṭabaqu r-raʾīsiyyu aruzzan bi-d-dajāji dhā rāʾiḥatin zakiyyatin."},{"fr":"La nourriture se mange avec la main droite.","tgt":"يُؤْكَلُ الطَّعَامُ بِالْيَدِ الْيُمْنَى.","ro":"Yuʾkalu ṭ-ṭaʿāmu bi-l-yadi l-yumnā."},{"fr":"La maîtresse de maison insistait pour que nous mangions davantage.","tgt":"كَانَتْ رَبَّةُ الْبَيْتِ تُلِحُّ عَلَيْنَا كَيْ نَأْكُلَ أَكْثَرَ.","ro":"Kānat rabbatu l-bayti tuliḥḥu ʿalaynā kay naʾkula akthara."},{"fr":"En partant, on nous a offert un sac de dattes.","tgt":"عِنْدَ رَحِيلِنَا، أُهْدِيَ إِلَيْنَا كِيسٌ مِنَ التَّمْرِ.","ro":"ʿInda raḥīlinā, uhdiya ilaynā kīsun mina t-tamri."}]},{"title":"Ensablés au milieu des dunes","phrases":[{"fr":"Notre voiture s'est enlisée dans le sable mou.","tgt":"عَلِقَتْ سَيَّارَتُنَا فِي الرَّمْلِ النَّاعِمِ.","ro":"ʿAliqat sayyāratunā fī r-ramli n-nāʿimi."},{"fr":"Plus le chauffeur accélérait, plus les roues s'enfonçaient.","tgt":"كُلَّمَا زَادَ السَّائِقُ السُّرْعَةَ، غَاصَتِ الْعَجَلَاتُ أَكْثَرَ.","ro":"Kullamā zāda s-sāʾiqu s-surʿata, ghāṣati l-ʿajalātu akthara."},{"fr":"Nous sommes tous descendus pour pousser la voiture.","tgt":"نَزَلْنَا جَمِيعًا لِنَدْفَعَ السَّيَّارَةَ.","ro":"Nazalnā jamīʿan li-nadfaʿa s-sayyārata."},{"fr":"Nous avons creusé le sable devant les roues avec nos mains.","tgt":"حَفَرْنَا الرَّمْلَ أَمَامَ الْعَجَلَاتِ بِأَيْدِينَا.","ro":"Ḥafarnā r-ramla amāma l-ʿajalāti bi-aydīnā."},{"fr":"Le soleil tapait fort et il ne nous restait plus beaucoup d'eau.","tgt":"كَانَتِ الشَّمْسُ حَارِقَةً، وَلَمْ يَبْقَ مَعَنَا مَاءٌ كَثِيرٌ.","ro":"Kānati sh-shamsu ḥāriqatan, wa-lam yabqa maʿanā māʾun kathīrun."},{"fr":"Au bout d'une heure, un berger est apparu avec son pick-up.","tgt":"بَعْدَ سَاعَةٍ، ظَهَرَ رَاعٍ بِشَاحِنَتِهِ الصَّغِيرَةِ.","ro":"Baʿda sāʿatin, ẓahara rāʿin bi-shāḥinatihi ṣ-ṣaghīrati."},{"fr":"Il a sorti notre voiture du sable avec une corde.","tgt":"أَخْرَجَ سَيَّارَتَنَا مِنَ الرَّمْلِ بِحَبْلٍ.","ro":"Akhraja sayyāratanā mina r-ramli bi-ḥablin."},{"fr":"Il a refusé l'argent que nous lui proposions.","tgt":"رَفَضَ الْمَالَ الَّذِي عَرَضْنَاهُ عَلَيْهِ.","ro":"Rafaḍa l-māla lladhī ʿaraḍnāhu ʿalayhi."},{"fr":"Il nous a seulement demandé de boire un café avec lui.","tgt":"طَلَبَ مِنَّا فَقَطْ أَنْ نَشْرَبَ مَعَهُ فِنْجَانَ قَهْوَةٍ.","ro":"Ṭalaba minnā faqaṭ an nashraba maʿahu finjāna qahwatin."},{"fr":"Depuis ce jour, nous ne partons jamais sans pelle.","tgt":"مُنْذُ ذَلِكَ الْيَوْمِ، لَا نُسَافِرُ أَبَدًا بِدُونِ مِجْرَفَةٍ.","ro":"Mundhu dhālika l-yawmi, lā nusāfiru abadan bi-dūni mijrafatin."}]},{"title":"Les récits de notre guide","phrases":[{"fr":"Le guide nous a dit que la mer était calme aujourd'hui.","tgt":"قَالَ لَنَا الْمُرْشِدُ إِنَّ الْبَحْرَ الْيَوْمَ هَادِئٌ.","ro":"Qāla lanā l-murshidu inna l-baḥra l-yawma hādiʾun."},{"fr":"Il a expliqué que les pêcheurs partent avant l'aube.","tgt":"أَوْضَحَ أَنَّ الصَّيَّادِينَ يَخْرُجُونَ قَبْلَ الْفَجْرِ.","ro":"Awḍaḥa anna ṣ-ṣayyādīna yakhrujūna qabla l-fajri."},{"fr":"Sa grand-mère lui disait que le désert parle à ceux qui l'écoutent.","tgt":"كَانَتْ جَدَّتُهُ تَقُولُ لَهُ إِنَّ الصَّحْرَاءَ تُكَلِّمُ مَنْ يُصْغِي إِلَيْهَا.","ro":"Kānat jaddatuhu taqūlu lahu inna ṣ-ṣaḥrāʾa tukallimu man yuṣghī ilayhā."},{"fr":"Il a dit que l'électricité n'était arrivée dans son village qu'il y a trente ans.","tgt":"قَالَ إِنَّ الْكَهْرَبَاءَ لَمْ تَصِلْ إِلَى قَرْيَتِهِ إِلَّا قَبْلَ ثَلَاثِينَ سَنَةً.","ro":"Qāla inna l-kahrabāʾa lam taṣil ilā qaryatihi illā qabla thalāthīna sanatan."},{"fr":"Il dit que la meilleure saison pour venir, c'est l'hiver.","tgt":"يَقُولُ إِنَّ أَفْضَلَ مَوْسِمٍ لِلزِّيَارَةِ هُوَ الشِّتَاءُ.","ro":"Yaqūlu inna afḍala mawsimin li-z-ziyārati huwa sh-shitāʾu."},{"fr":"Une touriste lui a demandé s'il avait déjà vu un léopard.","tgt":"سَأَلَتْهُ سَائِحَةٌ هَلْ رَأَى نَمِرًا مِنْ قَبْلُ.","ro":"Saʾalathu sāʾiḥatun hal raʾā namiran min qablu."},{"fr":"Il a répondu qu'il n'en avait vu qu'un seul, il y a très longtemps.","tgt":"أَجَابَ بِأَنَّهُ رَأَى نَمِرًا وَاحِدًا فَقَطْ مُنْذُ زَمَنٍ بَعِيدٍ.","ro":"Ajāba bi-annahu raʾā namiran wāḥidan faqaṭ mundhu zamanin baʿīdin."},{"fr":"Il nous a dit que le soleil était ici plus dangereux que nous le pensions.","tgt":"قَالَ لَنَا إِنَّ الشَّمْسَ هُنَا أَخْطَرُ مِمَّا نَظُنُّ.","ro":"Qāla lanā inna sh-shamsa hunā akhṭaru mimmā naẓunnu."},{"fr":"Les anciens disent que le khareef était plus fort autrefois.","tgt":"يَقُولُ الْكِبَارُ إِنَّ الْخَرِيفَ كَانَ أَقْوَى فِي الْمَاضِي.","ro":"Yaqūlu l-kibāru inna l-kharīfa kāna aqwā fī l-māḍī."},{"fr":"Je lui ai dit que nous reviendrions avec nos enfants.","tgt":"قُلْتُ لَهُ إِنَّنَا سَنَعُودُ مَعَ أَوْلَادِنَا.","ro":"Qultu lahu innanā sa-naʿūdu maʿa awlādinā."}],"tip":{"title":"Rapporter des paroles : « qala inna »","example":"Le guide nous a dit que la mer était calme aujourd'hui. — <b>قَالَ</b> لَنَا الْمُرْشِدُ <b>إِنَّ</b> الْبَحْرَ الْيَوْمَ هَادِئٌ.","body":"Pour rapporter les paroles de quelqu'un, l'arabe utilise le verbe « qala », il a dit, suivi de « inna », avec un i, qui joue le rôle de notre que. Après « inna », le nom se met à l'accusatif : « inna al-bahra », que la mer. Attention, avec les autres verbes comme « awdaha », il a expliqué, on emploie « anna », avec un a. Autre différence avec le français : pas de concordance des temps. On garde le temps des paroles d'origine, donc « hadiun », calme, au présent, là où le français dit était. Exemple : « qultu lahu innana sa-naudu », je lui ai dit que nous reviendrions. Astuce : « qala » appelle « inna », les deux commencent par le même souffle de parole.","exampleRo":"Qāla lanā l-murshidu inna l-baḥra l-yawma hādiʾun.","lit":"a dit · à-nous · [le] guide · [que] · [la] mer · [le] jour · calme","say":{"qala inna":"قَالَ إِنَّ","qala":"قَالَ","inna":"إِنَّ","inna al-bahra":"إِنَّ الْبَحْرَ","awdaha":"أَوْضَحَ","anna":"أَنَّ","hadiun":"هَادِئٌ","qultu lahu innana sa-naudu":"قُلْتُ لَهُ إِنَّنَا سَنَعُودُ"}}},{"title":"Voyager sans abîmer","phrases":[{"fr":"L'eau est rare ici, il faut donc l'économiser.","tgt":"الْمَاءُ نَادِرٌ هُنَا، لِذَلِكَ يَجِبُ أَنْ نَقْتَصِدَ فِيهِ.","ro":"Al-māʾu nādirun hunā, li-dhālika yajibu an naqtaṣida fīhi."},{"fr":"Nous nous douchons rapidement, même à l'hôtel.","tgt":"نَسْتَحِمُّ بِسُرْعَةٍ حَتَّى فِي الْفُنْدُقِ.","ro":"Nastaḥimmu bi-surʿatin ḥattā fī l-funduqi."},{"fr":"Les voitures ne doivent pas sortir des pistes.","tgt":"يَجِبُ أَلَّا تَخْرُجَ السَّيَّارَاتُ عَنِ الْمَسَارَاتِ.","ro":"Yajibu allā takhruja s-sayyārātu ʿani l-masārāti."},{"fr":"Les traces de pneus abîment le désert pendant des années.","tgt":"تُفْسِدُ آثَارُ الْعَجَلَاتِ الصَّحْرَاءَ لِسَنَوَاتٍ.","ro":"Tufsidu āthāru l-ʿajalāti ṣ-ṣaḥrāʾa li-sanawātin."},{"fr":"Il vaut mieux demander la permission avant de photographier quelqu'un.","tgt":"مِنَ الْأَفْضَلِ أَنْ تَسْتَأْذِنَ قَبْلَ تَصْوِيرِ أَيِّ شَخْصٍ.","ro":"Mina l-afḍali an tastaʾdhina qabla taṣwīri ayyi shakhṣin."},{"fr":"Nous achetons l'artisanat directement aux artisans.","tgt":"نَشْتَرِي الْمَصْنُوعَاتِ الْيَدَوِيَّةَ مِنَ الْحِرَفِيِّينَ مُبَاشَرَةً.","ro":"Nashtarī l-maṣnūʿāti l-yadawiyyata mina l-ḥirafiyyīna mubāsharatan."},{"fr":"Il est interdit de ramasser des coquillages sur les plages protégées.","tgt":"يُمْنَعُ جَمْعُ الْأَصْدَافِ مِنَ الشَّوَاطِئِ الْمَحْمِيَّةِ.","ro":"Yumnaʿu jamʿu l-aṣdāfi mina sh-shawāṭiʾi l-maḥmiyyati."},{"fr":"Choisir un guide local, c'est aussi soutenir l'économie de la région.","tgt":"اخْتِيَارُ مُرْشِدٍ مَحَلِّيٍّ هُوَ أَيْضًا دَعْمٌ لِاقْتِصَادِ الْمِنْطَقَةِ.","ro":"Ikhtiyāru murshidin maḥalliyyin huwa ayḍan daʿmun li-qtiṣādi l-minṭaqati."},{"fr":"Les gens apprécient beaucoup qu'on essaie de parler arabe.","tgt":"يُقَدِّرُ النَّاسُ كَثِيرًا أَنْ نُحَاوِلَ التَّحَدُّثَ بِالْعَرَبِيَّةِ.","ro":"Yuqaddiru n-nāsu kathīran an nuḥāwila t-taḥaddutha bi-l-ʿarabiyyati."},{"fr":"Nous voulons laisser les lieux comme nous les avons trouvés.","tgt":"نُرِيدُ أَنْ نَتْرُكَ الْأَمَاكِنَ كَمَا وَجَدْنَاهَا.","ro":"Nurīdu an natruka l-amākina kamā wajadnāhā."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Ce module nous a emmenés d'Oman jusqu'au Qatar.","tgt":"أَخَذَتْنَا هَذِهِ الْوَحْدَةُ مِنْ عُمَانَ إِلَى قَطَرَ.","ro":"Akhadhatnā hādhihi l-waḥdatu min ʿUmāna ilā Qaṭara."},{"fr":"Nous avons traversé des déserts, des montagnes et des wadis.","tgt":"عَبَرْنَا صَحَارِيَ وَجِبَالًا وَوِدْيَانًا.","ro":"ʿAbarnā ṣaḥāriya wa-jibālan wa-widyānan."},{"fr":"Nous avons plongé, navigué et dormi sous les étoiles.","tgt":"غُصْنَا وَأَبْحَرْنَا وَنِمْنَا تَحْتَ النُّجُومِ.","ro":"Ghuṣnā wa-abḥarnā wa-nimnā taḥta n-nujūmi."},{"fr":"Nous savons maintenant exprimer un but en arabe.","tgt":"صِرْنَا نَعْرِفُ كَيْفَ نُعَبِّرُ عَنِ الْهَدَفِ بِالْعَرَبِيَّةِ.","ro":"Ṣirnā naʿrifu kayfa nuʿabbiru ʿani l-hadafi bi-l-ʿarabiyyati."},{"fr":"Nous savons décrire l'état d'une personne pendant qu'elle agit.","tgt":"نَسْتَطِيعُ أَنْ نَصِفَ حَالَ الشَّخْصِ وَهُوَ يَفْعَلُ شَيْئًا.","ro":"Nastaṭīʿu an naṣifa ḥāla sh-shakhṣi wa-huwa yafʿalu shayʾan."},{"fr":"Nous pouvons rapporter ce que les autres nous ont dit.","tgt":"نَسْتَطِيعُ أَنْ نَنْقُلَ مَا قَالَهُ لَنَا الْآخَرُونَ.","ro":"Nastaṭīʿu an nanqula mā qālahu lanā l-ākharūna."},{"fr":"Certains souvenirs sont si proches, comme s'ils dataient d'hier.","tgt":"بَعْضُ الذِّكْرَيَاتِ قَرِيبَةٌ جِدًّا، كَأَنَّهَا حَدَثَتْ أَمْسِ.","ro":"Baʿḍu dh-dhikrayāti qarībatun jiddan, ka-annahā ḥadathat amsi."},{"fr":"Nous pensons encore à la gentillesse des gens rencontrés.","tgt":"مَا زِلْنَا نُفَكِّرُ فِي لُطْفِ النَّاسِ الَّذِينَ قَابَلْنَاهُمْ.","ro":"Mā zilnā nufakkiru fī luṭfi n-nāsi lladhīna qābalnāhum."},{"fr":"Notre arabe a beaucoup progressé pendant ce voyage.","tgt":"تَحَسَّنَتْ لُغَتُنَا الْعَرَبِيَّةُ كَثِيرًا خِلَالَ هَذِهِ الرِّحْلَةِ.","ro":"Taḥassanat lughatunā l-ʿarabiyyatu kathīran khilāla hādhihi r-riḥlati."},{"fr":"Nous sommes prêts pour de nouvelles conversations en arabe.","tgt":"نَحْنُ مُسْتَعِدُّونَ الْآنَ لِمُحَادَثَاتٍ جَدِيدَةٍ بِالْعَرَبِيَّةِ.","ro":"Naḥnu mustaʿiddūna l-āna li-muḥādathātin jadīdatin bi-l-ʿarabiyyati."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Les images cachées dans les mots","phrases":[{"fr":"Les expressions idiomatiques donnent à l'arabe sa saveur particulière.","tgt":"تُعْطِي التَّعَابِيرُ الِاصْطِلَاحِيَّةُ اللُّغَةَ الْعَرَبِيَّةَ نَكْهَتَهَا الْخَاصَّةَ.","ro":"Tuʿṭī at-taʿābīru al-iṣṭilāḥiyyatu al-lughata al-ʿarabiyyata nakhatahā al-khāṣṣata."},{"fr":"Quand on demande un service, les gens répondent souvent « sur ma tête ».","tgt":"عِنْدَمَا نَطْلُبُ خِدْمَةً، يُجِيبُ النَّاسُ غَالِبًا: «عَلَى رَأْسِي».","ro":"ʿIndamā naṭlubu khidmatan, yujību an-nāsu ghāliban: «ʿalā raʾsī»."},{"fr":"Cela veut dire : avec grand plaisir, je m'en occupe.","tgt":"وَهَذَا يَعْنِي: بِكُلِّ سُرُورٍ، سَأَهْتَمُّ بِالْأَمْرِ.","ro":"Wa-hādhā yaʿnī: bi-kulli surūrin, saʾahtammu bi-l-amri."},{"fr":"Mon voisin est « léger d'ombre » : il a beaucoup d'humour.","tgt":"جَارِي «خَفِيفُ الظِّلِّ»: لَدَيْهِ رُوحُ دُعَابَةٍ كَبِيرَةٌ.","ro":"Jārī «khafīfu aẓ-ẓilli»: ladayhi rūḥu duʿābatin kabīratun."},{"fr":"J'attends ta visite avec impatience.","tgt":"أَنْتَظِرُ زِيَارَتَكَ بِفَارِغِ الصَّبْرِ.","ro":"Antaẓiru ziyārataka bi-fārighi aṣ-ṣabri."},{"fr":"Tout a changé du jour au lendemain.","tgt":"تَغَيَّرَ كُلُّ شَيْءٍ بَيْنَ لَيْلَةٍ وَضُحَاهَا.","ro":"Taghayyara kullu shayʾin bayna laylatin wa-ḍuḥāhā."},{"fr":"Les préparatifs du festival battent leur plein.","tgt":"تَجْرِي اسْتِعْدَادَاتُ الْمِهْرَجَانِ عَلَى قَدَمٍ وَسَاقٍ.","ro":"Tajrī istiʿdādātu al-mihrajāni ʿalā qadamin wa-sāqin."},{"fr":"Avec une seule visite, j'ai fait d'une pierre deux coups.","tgt":"بِزِيَارَةٍ وَاحِدَةٍ، ضَرَبْتُ عُصْفُورَيْنِ بِحَجَرٍ وَاحِدٍ.","ro":"Bi-ziyāratin wāḥidatin, ḍarabtu ʿuṣfūrayni bi-ḥajarin wāḥidin."},{"fr":"Elle était sur des charbons ardents avant ses résultats.","tgt":"كَانَتْ عَلَى أَحَرَّ مِنَ الْجَمْرِ قَبْلَ نَتَائِجِهَا.","ro":"Kānat ʿalā aḥarra mina al-jamri qabla natāʾijihā."},{"fr":"Ces expressions ne se traduisent jamais mot à mot.","tgt":"لَا تُتَرْجَمُ هَذِهِ التَّعَابِيرُ حَرْفِيًّا أَبَدًا.","ro":"Lā tutarjamu hādhihi at-taʿābīru ḥarfiyyan abadan."}],"tip":{"title":"Les expressions idiomatiques de l'arabe","example":"Tout a changé du jour au lendemain. — تَغَيَّرَ كُلُّ شَيْءٍ <b>بَيْنَ لَيْلَةٍ وَضُحَاهَا</b>.","body":"Comme le français, l'arabe adore parler en images. « Bayna laylatin wa duhaha » se dit littéralement : entre une nuit et sa matinée ; nous dirions du jour au lendemain. Pour accepter un service avec plaisir, on répond « ala rassi », sur ma tête, et une personne drôle est « khafifu z-zilli », légère d'ombre. Quand des préparatifs battent leur plein, ils avancent « ala qadamin wa saq », sur pied et sur jambe. Ces expressions ne se traduisent jamais mot à mot : apprenez-les comme des blocs, avec leur petite image, et elles resteront gravées.","exampleRo":"Taghayyara kullu shayʾin bayna laylatin wa-ḍuḥāhā.","lit":"a-changé · tout · chose · entre · nuit · et-sa-matinée","say":{"Bayna laylatin wa duhaha":"بَيْنَ لَيْلَةٍ وَضُحَاهَا","ala rassi":"عَلَى رَأْسِي","khafifu z-zilli":"خَفِيفُ الظِّلِّ","ala qadamin wa saq":"عَلَى قَدَمٍ وَسَاق"}}},{"title":"L'arabe et ses dialectes","phrases":[{"fr":"Chaque pays arabe possède son propre dialecte.","tgt":"لِكُلِّ بَلَدٍ عَرَبِيٍّ لَهْجَتُهُ الْخَاصَّةُ.","ro":"Li-kulli baladin ʿarabiyyin lahjatuhu al-khāṣṣatu."},{"fr":"Un Marocain et un Irakien ne se comprennent pas toujours facilement.","tgt":"لَا يَتَفَاهَمُ الْمَغْرِبِيُّ وَالْعِرَاقِيُّ دَائِمًا بِسُهُولَةٍ.","ro":"Lā yatafāhamu al-maghribiyyu wa-l-ʿirāqiyyu dāʾiman bi-suhūlatin."},{"fr":"C'est pourquoi l'arabe standard reste la langue commune.","tgt":"لِذَلِكَ تَبْقَى الْفُصْحَى اللُّغَةَ الْمُشْتَرَكَةَ.","ro":"Li-dhālika tabqā al-fuṣḥā al-lughata al-mushtarakata."},{"fr":"On l'entend aux informations et on la lit dans les journaux.","tgt":"نَسْمَعُهَا فِي نَشَرَاتِ الْأَخْبَارِ وَنَقْرَؤُهَا فِي الصُّحُفِ.","ro":"Nasmaʿuhā fī nasharāti al-akhbāri wa-naqraʾuhā fī aṣ-ṣuḥufi."},{"fr":"À la maison, les familles parlent généralement en dialecte.","tgt":"فِي الْبَيْتِ، تَتَحَدَّثُ الْعَائِلَاتُ بِاللَّهْجَةِ عَادَةً.","ro":"Fī al-bayti, tataḥaddathu al-ʿāʾilātu bi-l-lahjati ʿādatan."},{"fr":"Le dialecte égyptien est compris presque partout grâce au cinéma.","tgt":"تُفْهَمُ اللَّهْجَةُ الْمِصْرِيَّةُ فِي كُلِّ مَكَانٍ تَقْرِيبًا بِفَضْلِ السِّينِمَا.","ro":"Tufhamu al-lahjatu al-miṣriyyatu fī kulli makānin taqrīban bi-faḍli as-sīnimā."},{"fr":"J'aimerais apprendre un dialecte après l'arabe standard.","tgt":"أَوَدُّ أَنْ أَتَعَلَّمَ لَهْجَةً بَعْدَ الْفُصْحَى.","ro":"Awaddu an ataʿallama lahjatan baʿda al-fuṣḥā."},{"fr":"Les dialectes du Maghreb contiennent beaucoup de mots berbères et français.","tgt":"تَحْتَوِي لَهَجَاتُ الْمَغْرِبِ الْعَرَبِيِّ عَلَى كَلِمَاتٍ أَمَازِيغِيَّةٍ وَفَرَنْسِيَّةٍ كَثِيرَةٍ.","ro":"Taḥtawī lahajātu al-maghribi al-ʿarabiyyi ʿalā kalimātin amāzīghiyyatin wa-faransiyyatin kathīratin."},{"fr":"L'arabe standard m'ouvre les portes de tout le monde arabe.","tgt":"تَفْتَحُ لِيَ الْفُصْحَى أَبْوَابَ الْعَالَمِ الْعَرَبِيِّ كُلِّهِ.","ro":"Taftaḥu liya al-fuṣḥā abwāba al-ʿālami al-ʿarabiyyi kullihi."},{"fr":"Les deux formes de la langue vivent côte à côte depuis des siècles.","tgt":"يَعِيشُ شَكْلَا اللُّغَةِ جَنْبًا إِلَى جَنْبٍ مُنْذُ قُرُونٍ.","ro":"Yaʿīshu shaklā al-lughati janban ilā janbin mundhu qurūnin."}]},{"title":"La poésie, mémoire des Arabes","phrases":[{"fr":"On dit que la poésie est le registre des Arabes.","tgt":"يُقَالُ إِنَّ الشِّعْرَ دِيوَانُ الْعَرَبِ.","ro":"Yuqālu inna ash-shiʿra dīwānu al-ʿarabi."},{"fr":"Autrefois, les poètes se réunissaient au marché d'Okaz.","tgt":"فِي الْمَاضِي، كَانَ الشُّعَرَاءُ يَجْتَمِعُونَ فِي سُوقِ عُكَاظَ.","ro":"Fī al-māḍī, kāna ash-shuʿarāʾu yajtamiʿūna fī sūqi ʿUkāẓa."},{"fr":"Le poète récitait son poème, puis le public réagissait.","tgt":"كَانَ الشَّاعِرُ يُلْقِي قَصِيدَتَهُ، ثُمَّ يَتَفَاعَلُ الْجُمْهُورُ.","ro":"Kāna ash-shāʿiru yulqī qaṣīdatahu, thumma yatafāʿalu al-jumhūru."},{"fr":"La poésie ancienne est difficile, mais elle est magnifique.","tgt":"الشِّعْرُ الْقَدِيمُ صَعْبٌ، لَكِنَّهُ رَائِعٌ.","ro":"Ash-shiʿru al-qadīmu ṣaʿbun, lākinnahu rāʾiʿun."},{"fr":"Ce poème n'est pas seulement beau, il est même très émouvant.","tgt":"لَيْسَتْ هَذِهِ الْقَصِيدَةُ جَمِيلَةً فَحَسْبُ، بَلْ هِيَ مُؤَثِّرَةٌ جِدًّا.","ro":"Laysat hādhihi al-qaṣīdatu jamīlatan fa-ḥasbu, bal hiya muʾaththiratun jiddan."},{"fr":"Quant à la poésie moderne, elle se libère des anciennes règles.","tgt":"أَمَّا الشِّعْرُ الْحَدِيثُ فَيَتَحَرَّرُ مِنَ الْقَوَاعِدِ الْقَدِيمَةِ.","ro":"Ammā ash-shiʿru al-ḥadīthu fa-yataḥarraru mina al-qawāʿidi al-qadīmati."},{"fr":"Al-Moutanabbi reste l'un des plus célèbres poètes arabes.","tgt":"يَبْقَى الْمُتَنَبِّي مِنْ أَشْهَرِ الشُّعَرَاءِ الْعَرَبِ.","ro":"Yabqā al-Mutanabbī min ashhari ash-shuʿarāʾi al-ʿarabi."},{"fr":"Mon grand-père connaissait des centaines de vers par cœur.","tgt":"كَانَ جَدِّي يَحْفَظُ مِئَاتِ الْأَبْيَاتِ عَنْ ظَهْرِ قَلْبٍ.","ro":"Kāna jaddī yaḥfaẓu miʾāti al-abyāti ʿan ẓahri qalbin."},{"fr":"J'ai d'abord lu le poème en silence, puis à voix haute.","tgt":"قَرَأْتُ الْقَصِيدَةَ أَوَّلًا بِصَمْتٍ، ثُمَّ بِصَوْتٍ عَالٍ.","ro":"Qaraʾtu al-qaṣīdata awwalan bi-ṣamtin, thumma bi-ṣawtin ʿālin."},{"fr":"La musique des mots touche le cœur avant l'esprit.","tgt":"تَمَسُّ مُوسِيقَى الْكَلِمَاتِ الْقَلْبَ قَبْلَ الْعَقْلِ.","ro":"Tamassu mūsīqā al-kalimāti al-qalba qabla al-ʿaqli."}],"tip":{"title":"Les mots de liaison : « thumma, lakin, bal, amma… fa »","example":"Quant à la poésie moderne, elle se libère des anciennes règles. — <b>أَمَّا</b> الشِّعْرُ الْحَدِيثُ <b>فَيَتَحَرَّرُ</b> مِنَ الْقَوَاعِدِ الْقَدِيمَةِ.","body":"Pour enchaîner vos idées, quatre petits mots suffisent. « Thumma » veut dire puis, pour une suite dans le temps. « Lakin » ou « lakinna » signifie mais : « sabun, lakinnahu raiun », difficile, mais magnifique. « Bal » corrige ou renchérit, comme bien plus, ou plutôt : pas seulement beau, « bal » très émouvant. Enfin, « amma… fa » correspond à quant à : on pose le sujet avec « amma », puis on colle « fa » au début de ce qu'on en dit, comme dans « amma sh-shiru l-hadith, fa-yataharraru », quant à la poésie moderne, alors elle se libère. Astuce : retenez que « amma » ne voyage jamais sans son « fa ».","exampleRo":"Ammā ash-shiʿru al-ḥadīthu fa-yataḥarraru mina al-qawāʿidi al-qadīmati.","lit":"quant-à · la-poésie · la-moderne · [alors]-elle-se-libère · de · les-règles · les-anciennes","say":{"Thumma":"ثُمَّ","Lakin":"لَكِنْ","lakinna":"لَكِنَّ","sabun, lakinnahu raiun":"صَعْبٌ، لَكِنَّهُ رَائِعٌ","Bal":"بَلْ","bal":"بَلْ","amma… fa":"أَمَّا… فَ","amma":"أَمَّا","amma sh-shiru l-hadith, fa-yataharraru":"أَمَّا الشِّعْرُ الْحَدِيث، فَيَتَحَرَّرُ","thumma, lakin, bal, amma… fa":"ثُمَّ، لَكِنْ، بَلْ، أَمَّا… فَ"}}},{"title":"L'art de la calligraphie","phrases":[{"fr":"La calligraphie arabe est un art à part entière.","tgt":"الْخَطُّ الْعَرَبِيُّ فَنٌّ قَائِمٌ بِذَاتِهِ.","ro":"Al-khaṭṭu al-ʿarabiyyu fannun qāʾimun bi-dhātihi."},{"fr":"Le calligraphe trace chaque lettre avec une grande patience.","tgt":"يَرْسُمُ الْخَطَّاطُ كُلَّ حَرْفٍ بِصَبْرٍ كَبِيرٍ.","ro":"Yarsumu al-khaṭṭāṭu kulla ḥarfin bi-ṣabrin kabīrin."},{"fr":"Il utilise un calame fabriqué en roseau.","tgt":"يَسْتَخْدِمُ قَلَمًا مَصْنُوعًا مِنَ الْقَصَبِ.","ro":"Yastakhdimu qalaman maṣnūʿan mina al-qaṣabi."},{"fr":"Le style coufique est anguleux, tandis que le naskh est arrondi.","tgt":"الْخَطُّ الْكُوفِيُّ ذُو زَوَايَا، بَيْنَمَا خَطُّ النَّسْخِ مُسْتَدِيرٌ.","ro":"Al-khaṭṭu al-kūfiyyu dhū zawāyā, baynamā khaṭṭu an-naskhi mustadīrun."},{"fr":"Le thuluth est considéré comme le plus difficile des styles.","tgt":"يُعْتَبَرُ خَطُّ الثُّلُثِ أَصْعَبَ الْخُطُوطِ.","ro":"Yuʿtabaru khaṭṭu ath-thuluthi aṣʿaba al-khuṭūṭi."},{"fr":"On l'apprend auprès d'un maître pendant de longues années.","tgt":"نَتَعَلَّمُهُ عَلَى يَدِ أُسْتَاذٍ سَنَوَاتٍ طَوِيلَةً.","ro":"Nataʿallamuhu ʿalā yadi ustādhin sanawātin ṭawīlatan."},{"fr":"J'ai assisté à un atelier de calligraphie à Tunis.","tgt":"حَضَرْتُ وَرْشَةً لِلْخَطِّ فِي تُونِسَ.","ro":"Ḥaḍartu warshatan li-l-khaṭṭi fī Tūnisa."},{"fr":"Mon nom, écrit en calligraphie arabe, ressemble à un tableau.","tgt":"يُشْبِهُ اسْمِي الْمَكْتُوبُ بِالْخَطِّ الْعَرَبِيِّ لَوْحَةً فَنِّيَّةً.","ro":"Yushbihu ismī al-maktūbu bi-l-khaṭṭi al-ʿarabiyyi lawḥatan fanniyyatan."},{"fr":"Les murs des vieux palais sont couverts de calligraphies.","tgt":"جُدْرَانُ الْقُصُورِ الْقَدِيمَةِ مُغَطَّاةٌ بِالْخُطُوطِ.","ro":"Judrānu al-quṣūri al-qadīmati mughaṭṭātun bi-l-khuṭūṭi."},{"fr":"Chaque œuvre unit la beauté de la forme et la profondeur du sens.","tgt":"يَجْمَعُ كُلُّ عَمَلٍ بَيْنَ جَمَالِ الشَّكْلِ وَعُمْقِ الْمَعْنَى.","ro":"Yajmaʿu kullu ʿamalin bayna jamāli ash-shakli wa-ʿumqi al-maʿnā."}]},{"title":"La cuisine, un patrimoine partagé","phrases":[{"fr":"La cuisine raconte l'histoire des peuples.","tgt":"يَحْكِي الْمَطْبَخُ تَارِيخَ الشُّعُوبِ.","ro":"Yaḥkī al-maṭbakhu tārīkha ash-shuʿūbi."},{"fr":"Le cuisinier a servi le couscous aux invités.","tgt":"قَدَّمَ الطَّبَّاخُ الْكُسْكُسَ لِلضُّيُوفِ.","ro":"Qaddama aṭ-ṭabbākhu al-kuskusa li-ḍ-ḍuyūfi."},{"fr":"Le couscous a été inscrit au patrimoine mondial.","tgt":"أُدْرِجَ الْكُسْكُسُ فِي التُّرَاثِ الْعَالَمِيِّ.","ro":"Udrija al-kuskusu fī at-turāthi al-ʿālamiyyi."},{"fr":"Chaque pays prépare le houmous à sa façon.","tgt":"يُحَضِّرُ كُلُّ بَلَدٍ الْحُمُّصَ عَلَى طَرِيقَتِهِ.","ro":"Yuḥaḍḍiru kullu baladin al-ḥummuṣa ʿalā ṭarīqatihi."},{"fr":"Ma mère m'a appris la recette de la maqlouba.","tgt":"عَلَّمَتْنِي أُمِّي وَصْفَةَ الْمَقْلُوبَةِ.","ro":"ʿAllamatnī ummī waṣfata al-maqlūbati."},{"fr":"Autrefois, les épices venaient de pays lointains.","tgt":"كَانَتِ التَّوَابِلُ تَأْتِي قَدِيمًا مِنْ بِلَادٍ بَعِيدَةٍ.","ro":"Kānati at-tawābilu taʾtī qadīman min bilādin baʿīdatin."},{"fr":"Le repas est avant tout un moment de partage.","tgt":"الطَّعَامُ لَحْظَةُ مُشَارَكَةٍ قَبْلَ كُلِّ شَيْءٍ.","ro":"Aṭ-ṭaʿāmu laḥẓatu mushārakatin qabla kulli shayʾin."},{"fr":"Les Libanais sont fiers de leurs mezzés variés.","tgt":"يَفْتَخِرُ اللُّبْنَانِيُّونَ بِمُقَبِّلَاتِهِمُ الْمُتَنَوِّعَةِ.","ro":"Yaftakhiru al-lubnāniyyūna bi-muqabbilātihimu al-mutanawwiʿati."},{"fr":"J'adore le thé à la menthe qu'on boit au Maroc.","tgt":"أَعْشَقُ الشَّايَ بِالنَّعْنَاعِ الَّذِي يُشْرَبُ فِي الْمَغْرِبِ.","ro":"Aʿshaqu ash-shāya bi-n-naʿnāʿi alladhī yushrabu fī al-maghribi."},{"fr":"Goûter un plat, c'est découvrir une culture.","tgt":"أَنْ تَتَذَوَّقَ طَبَقًا يَعْنِي أَنْ تَكْتَشِفَ ثَقَافَةً.","ro":"An tatadhawwaqa ṭabaqan yaʿnī an taktashifa thaqāfatan."}],"tip":{"title":"Les cas grammaticaux : les terminaisons -u, -a, -i","example":"Le cuisinier a servi le couscous aux invités. — قَدَّمَ <b>الطَّبَّاخُ</b> <b>الْكُسْكُسَ</b> <b>لِلضُّيُوفِ</b>.","body":"En arabe littéraire, la dernière voyelle d'un nom indique son rôle dans la phrase, un peu comme les cas en latin. La terminaison « u » marque le sujet, « a » le complément direct, et « i » le nom placé après une préposition ou un complément du nom. Écoutez notre exemple : « at-tabbakhu », le cuisinier, est le sujet ; « al-kuskusa », le couscous, est ce qu'on sert ; et « li-d-duyufi », aux invités, vient après la préposition « li ». Sans article, la voyelle se double d'un n : « kitabun », « kitaban », « kitabin ». Grâce à ces terminaisons, l'ordre des mots devient plus libre, car la voyelle finale dit déjà qui fait quoi.","exampleRo":"Qaddama aṭ-ṭabbākhu al-kuskusa li-ḍ-ḍuyūfi.","lit":"a-servi · le-cuisinier · le-couscous · pour-les-invités","say":{"at-tabbakhu":"الطَّبَّاخُ","al-kuskusa":"الْكُسْكُسَ","li-d-duyufi":"لِلضُّيُوفِ","kitabun":"كِتَابٌ","kitaban":"كِتَابًا","kitabin":"كِتَابٍ"}}},{"title":"L'hospitalité arabe","phrases":[{"fr":"L'hospitalité est une valeur essentielle dans le monde arabe.","tgt":"الضِّيَافَةُ قِيمَةٌ أَسَاسِيَّةٌ فِي الْعَالَمِ الْعَرَبِيِّ.","ro":"Aḍ-ḍiyāfatu qīmatun asāsiyyatun fī al-ʿālami al-ʿarabiyyi."},{"fr":"On ne laisse jamais un invité repartir affamé.","tgt":"لَا نَتْرُكُ الضَّيْفَ يُغَادِرُ جَائِعًا أَبَدًا.","ro":"Lā natruku aḍ-ḍayfa yughādiru jāʾiʿan abadan."},{"fr":"Dans le désert, on offre le café arabe à tout voyageur.","tgt":"فِي الصَّحْرَاءِ، تُقَدَّمُ الْقَهْوَةُ الْعَرَبِيَّةُ لِكُلِّ مُسَافِرٍ.","ro":"Fī aṣ-ṣaḥrāʾi, tuqaddamu al-qahwatu al-ʿarabiyyatu li-kulli musāfirin."},{"fr":"Ce café est servi dans de petites tasses avec des dattes.","tgt":"تُقَدَّمُ هَذِهِ الْقَهْوَةُ فِي فَنَاجِينَ صَغِيرَةٍ مَعَ التَّمْرِ.","ro":"Tuqaddamu hādhihi al-qahwatu fī fanājīna ṣaghīratin maʿa at-tamri."},{"fr":"On secoue la tasse pour dire qu'on en a assez bu.","tgt":"نَهُزُّ الْفِنْجَانَ لِنَقُولَ إِنَّنَا اكْتَفَيْنَا.","ro":"Nahuzzu al-finjāna li-naqūla innanā iktafaynā."},{"fr":"La famille m'a reçu comme si j'étais l'un des siens.","tgt":"اسْتَقْبَلَتْنِي الْعَائِلَةُ كَأَنَّنِي وَاحِدٌ مِنْهَا.","ro":"Istaqbalatnī al-ʿāʾilatu ka-annanī wāḥidun minhā."},{"fr":"Refuser une invitation peut parfois vexer.","tgt":"قَدْ يُزْعِجُ رَفْضُ الدَّعْوَةِ أَحْيَانًا.","ro":"Qad yuzʿiju rafḍu ad-daʿwati aḥyānan."},{"fr":"« Notre maison est ta maison », m'a dit mon hôte.","tgt":"قَالَ لِي مُضِيفِي: «بَيْتُنَا بَيْتُكَ».","ro":"Qāla lī muḍīfī: «baytunā baytuka»."},{"fr":"Le plus généreux des hommes est celui qui donne sans compter.","tgt":"أَكْرَمُ النَّاسِ مَنْ يُعْطِي بِلَا حِسَابٍ.","ro":"Akramu an-nāsi man yuʿṭī bi-lā ḥisābin."},{"fr":"Cette générosité m'a profondément touché.","tgt":"أَثَّرَ فِيَّ هَذَا الْكَرَمُ تَأْثِيرًا عَمِيقًا.","ro":"Aththara fiyya hādhā al-karamu taʾthīran ʿamīqan."}]},{"title":"Les médias et l'information","phrases":[{"fr":"Je lis les journaux électroniques chaque matin.","tgt":"أَقْرَأُ الصُّحُفَ الْإِلِكْتُرُونِيَّةَ كُلَّ صَبَاحٍ.","ro":"Aqraʾu aṣ-ṣuḥufa al-ilikturūniyyata kulla ṣabāḥin."},{"fr":"Des millions de personnes suivent les chaînes d'information arabes.","tgt":"يُتَابِعُ الْمَلَايِينُ الْقَنَوَاتِ الْإِخْبَارِيَّةَ الْعَرَبِيَّةَ.","ro":"Yutābiʿu al-malāyīnu al-qanawāti al-ikhbāriyyata al-ʿarabiyyata."},{"fr":"Les présentateurs parlent un arabe standard très soigné.","tgt":"يَتَحَدَّثُ الْمُذِيعُونَ بِعَرَبِيَّةٍ فَصِيحَةٍ وَمُتْقَنَةٍ.","ro":"Yataḥaddathu al-mudhīʿūna bi-ʿarabiyyatin faṣīḥatin wa-mutqanatin."},{"fr":"Il faut vérifier une information avant de la partager.","tgt":"يَجِبُ التَّحَقُّقُ مِنَ الْخَبَرِ قَبْلَ نَشْرِهِ.","ro":"Yajibu at-taḥaqququ mina al-khabari qabla nashrihi."},{"fr":"Les fausses nouvelles se propagent plus vite que la vérité.","tgt":"تَنْتَشِرُ الْأَخْبَارُ الْكَاذِبَةُ أَسْرَعَ مِنَ الْحَقِيقَةِ.","ro":"Tantashiru al-akhbāru al-kādhibatu asraʿa mina al-ḥaqīqati."},{"fr":"La radio reste très écoutée dans les voitures.","tgt":"مَا زَالَ الرَّادْيُو مَسْمُوعًا كَثِيرًا فِي السَّيَّارَاتِ.","ro":"Mā zāla ar-rādyū masmūʿan kathīran fī as-sayyārāti."},{"fr":"Ce documentaire sur le Nil a été diffusé hier soir.","tgt":"بُثَّ هَذَا الْفِيلْمُ الْوَثَائِقِيُّ عَنِ النِّيلِ مَسَاءَ أَمْسِ.","ro":"Buththa hādhā al-fīlmu al-wathāʾiqiyyu ʿani an-nīli masāʾa amsi."},{"fr":"Les journalistes jouent un rôle important dans la société.","tgt":"يَلْعَبُ الصَّحَفِيُّونَ دَوْرًا مُهِمًّا فِي الْمُجْتَمَعِ.","ro":"Yalʿabu aṣ-ṣaḥafiyyūna dawran muhimman fī al-mujtamaʿi."},{"fr":"J'écoute les nouvelles en arabe pour améliorer ma compréhension.","tgt":"أَسْتَمِعُ إِلَى الْأَخْبَارِ بِالْعَرَبِيَّةِ لِأُحَسِّنَ فَهْمِي.","ro":"Astamiʿu ilā al-akhbāri bi-l-ʿarabiyyati li-uḥassina fahmī."},{"fr":"Au début, je ne comprenais que quelques mots.","tgt":"فِي الْبِدَايَةِ، لَمْ أَكُنْ أَفْهَمُ إِلَّا بَعْضَ الْكَلِمَاتِ.","ro":"Fī al-bidāyati, lam akun afhamu illā baʿḍa al-kalimāti."}]},{"title":"Le cinéma arabe","phrases":[{"fr":"Le cinéma égyptien a connu un âge d'or.","tgt":"عَرَفَتِ السِّينِمَا الْمِصْرِيَّةُ عَصْرًا ذَهَبِيًّا.","ro":"ʿArafati as-sīnimā al-miṣriyyatu ʿaṣran dhahabiyyan."},{"fr":"Les deux jeunes réalisateurs écrivent ensemble un nouveau film.","tgt":"الْمُخْرِجَانِ الشَّابَّانِ يَكْتُبَانِ فِيلْمًا جَدِيدًا مَعًا.","ro":"Al-mukhrijāni ash-shābbāni yaktubāni fīlman jadīdan maʿan."},{"fr":"Ils travaillent sur le scénario depuis deux ans.","tgt":"يَعْمَلَانِ عَلَى السِّينَارْيُو مُنْذُ سَنَتَيْنِ.","ro":"Yaʿmalāni ʿalā as-sīnāryū mundhu sanatayni."},{"fr":"Les deux actrices principales viennent de Beyrouth.","tgt":"الْمُمَثِّلَتَانِ الرَّئِيسِيَّتَانِ مِنْ بَيْرُوتَ.","ro":"Al-mumaththilatāni ar-raʾīsiyyatāni min Bayrūta."},{"fr":"Elles jouent deux sœurs qui se retrouvent après des années.","tgt":"تُؤَدِّيَانِ دَوْرَ أُخْتَيْنِ تَلْتَقِيَانِ بَعْدَ سَنَوَاتٍ.","ro":"Tuʾaddiyāni dawra ukhtayni taltaqiyāni baʿda sanawātin."},{"fr":"Le film sera projeté au festival de Carthage.","tgt":"سَيُعْرَضُ الْفِيلْمُ فِي مِهْرَجَانِ قَرْطَاجَ.","ro":"Sa-yuʿraḍu al-fīlmu fī mihrajāni Qarṭāja."},{"fr":"Mes deux frères adorent les vieux films en noir et blanc.","tgt":"أَخَوَايَ يُحِبَّانِ الْأَفْلَامَ الْقَدِيمَةَ بِالْأَبْيَضِ وَالْأَسْوَدِ.","ro":"Akhawāya yuḥibbāni al-aflāma al-qadīmata bi-l-abyaḍi wa-l-aswadi."},{"fr":"Ils ne se lassent jamais des comédies égyptiennes.","tgt":"لَا يَمَلَّانِ أَبَدًا مِنَ الْأَفْلَامِ الْكُومِيدِيَّةِ الْمِصْرِيَّةِ.","ro":"Lā yamallāni abadan mina al-aflāmi al-kūmīdiyyati al-miṣriyyati."},{"fr":"Le cinéma arabe parle de plus en plus des jeunes.","tgt":"تَتَحَدَّثُ السِّينِمَا الْعَرَبِيَّةُ عَنِ الشَّبَابِ أَكْثَرَ فَأَكْثَرَ.","ro":"Tataḥaddathu as-sīnimā al-ʿarabiyyatu ʿani ash-shabābi akthara fa-akthara."},{"fr":"Ce film m'a fait rire et pleurer à la fois.","tgt":"أَضْحَكَنِي هَذَا الْفِيلْمُ وَأَبْكَانِي فِي الْوَقْتِ نَفْسِهِ.","ro":"Aḍḥakanī hādhā al-fīlmu wa-abkānī fī al-waqti nafsihi."}],"tip":{"title":"Le verbe au duel : « yaktubani »","example":"Les deux jeunes réalisateurs écrivent ensemble un nouveau film. — <b>الْمُخْرِجَانِ</b> <b>الشَّابَّانِ</b> <b>يَكْتُبَانِ</b> فِيلْمًا جَدِيدًا مَعًا.","body":"L'arabe possède un nombre que le français a perdu : le duel, pour parler de deux personnes ou de deux choses. Pour les noms, on ajoute « ani » : « mukhrij », un réalisateur, devient « mukhrijani », deux réalisateurs. Le verbe suit le même chemin : « yaktubu », il écrit, devient « yaktubani », ils écrivent à deux ; pour deux femmes, on dit « taktubani ». Notre exemple se lit donc : les deux réalisateurs, les deux jeunes, écrivent-à-deux un film nouveau. Attention, si le verbe vient avant le sujet, il reste au singulier. Astuce : pensez au son « ani » comme à une paire de chaussures, qui va toujours par deux.","exampleRo":"Al-mukhrijāni ash-shābbāni yaktubāni fīlman jadīdan maʿan.","lit":"les-deux-réalisateurs · les-deux-jeunes · ils-deux-écrivent · film · nouveau · ensemble","say":{"mukhrij":"مُخْرِج","mukhrijani":"مُخْرِجَانِ","yaktubu":"يَكْتُبُ","yaktubani":"يَكْتُبَانِ","taktubani":"تَكْتُبَانِ"}}},{"title":"L'Andalousie et son héritage","phrases":[{"fr":"L'Andalousie a été un grand foyer de la civilisation arabe.","tgt":"كَانَتِ الْأَنْدَلُسُ مَرْكَزًا كَبِيرًا لِلْحَضَارَةِ الْعَرَبِيَّةِ.","ro":"Kānati al-Andalusu markazan kabīran li-l-ḥaḍārati al-ʿarabiyyati."},{"fr":"Cordoue était l'une des plus grandes villes de son époque.","tgt":"كَانَتْ قُرْطُبَةُ مِنْ أَكْبَرِ مُدُنِ عَصْرِهَا.","ro":"Kānat Qurṭubatu min akbari muduni ʿaṣrihā."},{"fr":"Ses bibliothèques contenaient des milliers de livres.","tgt":"كَانَتْ مَكْتَبَاتُهَا تَضُمُّ آلَافَ الْكُتُبِ.","ro":"Kānat maktabātuhā taḍummu ālāfa al-kutubi."},{"fr":"Les savants y traduisaient les œuvres des philosophes anciens.","tgt":"كَانَ الْعُلَمَاءُ يُتَرْجِمُونَ فِيهَا أَعْمَالَ الْفَلَاسِفَةِ الْقُدَمَاءِ.","ro":"Kāna al-ʿulamāʾu yutarjimūna fīhā aʿmāla al-falāsifati al-qudamāʾi."},{"fr":"Le palais de l'Alhambra fascine toujours les visiteurs.","tgt":"مَا زَالَ قَصْرُ الْحَمْرَاءِ يَسْحَرُ الزُّوَّارَ.","ro":"Mā zāla qaṣru al-Ḥamrāʾi yasḥaru az-zuwwāra."},{"fr":"La musique andalouse est encore jouée à Fès et à Alger.","tgt":"مَا زَالَتِ الْمُوسِيقَى الْأَنْدَلُسِيَّةُ تُعْزَفُ فِي فَاسَ وَالْجَزَائِرِ.","ro":"Mā zālati al-mūsīqā al-andalusiyyatu tuʿzafu fī Fāsa wa-l-Jazāʾiri."},{"fr":"Le mouachah est une forme poétique née en Andalousie.","tgt":"الْمُوَشَّحُ شَكْلٌ شِعْرِيٌّ وُلِدَ فِي الْأَنْدَلُسِ.","ro":"Al-muwashshaḥu shaklun shiʿriyyun wulida fī al-Andalusi."},{"fr":"Beaucoup de mots français ont une origine arabe, comme sucre et algèbre.","tgt":"كَثِيرٌ مِنَ الْكَلِمَاتِ الْفَرَنْسِيَّةِ أَصْلُهَا عَرَبِيٌّ، مِثْلُ السُّكَّرِ وَالْجَبْرِ.","ro":"Kathīrun mina al-kalimāti al-faransiyyati aṣluhā ʿarabiyyun, mithlu as-sukkari wa-l-jabri."},{"fr":"Cet héritage montre la richesse des échanges entre les cultures.","tgt":"يُبَيِّنُ هَذَا الْإِرْثُ غِنَى التَّبَادُلِ بَيْنَ الثَّقَافَاتِ.","ro":"Yubayyinu hādhā al-irthu ghinā at-tabāduli bayna ath-thaqāfāti."},{"fr":"Je rêve de visiter Grenade et Séville un jour.","tgt":"أَحْلُمُ بِزِيَارَةِ غَرْنَاطَةَ وَإِشْبِيلِيَةَ يَوْمًا مَا.","ro":"Aḥlumu bi-ziyārati Gharnāṭata wa-Ishbīliyata yawman mā."}]},{"title":"La ville ou la campagne ?","phrases":[{"fr":"De plus en plus de jeunes quittent la campagne pour la ville.","tgt":"يَتْرُكُ الشَّبَابُ الرِّيفَ إِلَى الْمَدِينَةِ أَكْثَرَ فَأَكْثَرَ.","ro":"Yatruku ash-shabābu ar-rīfa ilā al-madīnati akthara fa-akthara."},{"fr":"Ils y cherchent du travail et de meilleures études.","tgt":"يَبْحَثُونَ فِيهَا عَنْ عَمَلٍ وَدِرَاسَةٍ أَفْضَلَ.","ro":"Yabḥathūna fīhā ʿan ʿamalin wa-dirāsatin afḍala."},{"fr":"Le Caire est une ville immense qui ne dort jamais.","tgt":"الْقَاهِرَةُ مَدِينَةٌ ضَخْمَةٌ لَا تَنَامُ أَبَدًا.","ro":"Al-Qāhiratu madīnatun ḍakhmatun lā tanāmu abadan."},{"fr":"Le bruit et les embouteillages fatiguent ses habitants.","tgt":"يُتْعِبُ الضَّجِيجُ وَالِازْدِحَامُ سُكَّانَهَا.","ro":"Yutʿibu aḍ-ḍajīju wa-l-izdiḥāmu sukkānahā."},{"fr":"À la campagne, la vie suit le rythme des saisons.","tgt":"فِي الرِّيفِ، تَسِيرُ الْحَيَاةُ عَلَى إِيقَاعِ الْفُصُولِ.","ro":"Fī ar-rīfi, tasīru al-ḥayātu ʿalā īqāʿi al-fuṣūli."},{"fr":"Mes grands-parents cultivent encore des oliviers près de Sfax.","tgt":"مَا زَالَ جَدَّايَ يَزْرَعَانِ أَشْجَارَ الزَّيْتُونِ قُرْبَ صَفَاقِسَ.","ro":"Mā zāla jaddāya yazraʿāni ashjāra az-zaytūni qurba Ṣafāqisa."},{"fr":"L'air y est pur et les gens se connaissent tous.","tgt":"الْهَوَاءُ هُنَاكَ نَقِيٌّ وَالنَّاسُ يَعْرِفُ بَعْضُهُمْ بَعْضًا.","ro":"Al-hawāʾu hunāka naqiyyun wa-n-nāsu yaʿrifu baʿḍuhum baʿḍan."},{"fr":"Pourtant, les services y manquent souvent.","tgt":"وَمَعَ ذَلِكَ، كَثِيرًا مَا تَنْقُصُهَا الْخِدْمَاتُ.","ro":"Wa-maʿa dhālika, kathīran mā tanquṣuhā al-khidmātu."},{"fr":"Certains citadins reviennent vivre au village.","tgt":"يَعُودُ بَعْضُ سُكَّانِ الْمُدُنِ لِلْعَيْشِ فِي الْقَرْيَةِ.","ro":"Yaʿūdu baʿḍu sukkāni al-muduni li-l-ʿayshi fī al-qaryati."},{"fr":"Le mieux serait de profiter des deux mondes.","tgt":"الْأَفْضَلُ أَنْ نَسْتَفِيدَ مِنَ الْعَالَمَيْنِ.","ro":"Al-afḍalu an nastafīda mina al-ʿālamayni."}]},{"title":"Entre les générations","phrases":[{"fr":"Mes parents ne voient pas le monde comme je le vois.","tgt":"لَا يَرَى وَالِدَايَ الْعَالَمَ كَمَا أَرَاهُ.","ro":"Lā yarā wālidāya al-ʿālama kamā arāhu."},{"fr":"Ma grand-mère se souvient d'une époque sans télévision.","tgt":"تَتَذَكَّرُ جَدَّتِي زَمَنًا بِلَا تِلْفَازٍ.","ro":"Tatadhakkaru jaddatī zamanan bi-lā tilfāzin."},{"fr":"Elle racontait des histoires le soir, au clair de lune.","tgt":"كَانَتْ تَحْكِي الْقِصَصَ مَسَاءً تَحْتَ ضَوْءِ الْقَمَرِ.","ro":"Kānat taḥkī al-qiṣaṣa masāʾan taḥta ḍawʾi al-qamari."},{"fr":"Les jeunes d'aujourd'hui vivent leur téléphone à la main.","tgt":"يَعِيشُ شَبَابُ الْيَوْمِ وَهَوَاتِفُهُمْ فِي أَيْدِيهِمْ.","ro":"Yaʿīshu shabābu al-yawmi wa-hawātifuhum fī aydīhim."},{"fr":"Les anciens tiennent beaucoup aux traditions.","tgt":"يَتَمَسَّكُ الْكِبَارُ بِالتَّقَالِيدِ كَثِيرًا.","ro":"Yatamassaku al-kibāru bi-t-taqālīdi kathīran."},{"fr":"Les jeunes veulent souvent davantage de liberté.","tgt":"يُرِيدُ الشَّبَابُ غَالِبًا مَزِيدًا مِنَ الْحُرِّيَّةِ.","ro":"Yurīdu ash-shabābu ghāliban mazīdan mina al-ḥurriyyati."},{"fr":"Le respect des aînés reste très présent dans nos familles.","tgt":"مَا زَالَ احْتِرَامُ الْكِبَارِ حَاضِرًا بِقُوَّةٍ فِي عَائِلَاتِنَا.","ro":"Mā zāla iḥtirāmu al-kibāri ḥāḍiran bi-quwwatin fī ʿāʾilātinā."},{"fr":"Chaque génération apprend quelque chose de l'autre.","tgt":"يَتَعَلَّمُ كُلُّ جِيلٍ شَيْئًا مِنَ الْآخَرِ.","ro":"Yataʿallamu kullu jīlin shayʾan mina al-ākhari."},{"fr":"J'ai appris à ma grand-mère à envoyer des messages vocaux.","tgt":"عَلَّمْتُ جَدَّتِي إِرْسَالَ الرَّسَائِلِ الصَّوْتِيَّةِ.","ro":"ʿAllamtu jaddatī irsāla ar-rasāʾili aṣ-ṣawtiyyati."},{"fr":"En échange, elle m'a appris ses meilleures recettes.","tgt":"وَفِي الْمُقَابِلِ، عَلَّمَتْنِي أَفْضَلَ وَصَفَاتِهَا.","ro":"Wa-fī al-muqābili, ʿallamatnī afḍala waṣafātihā."}]},{"title":"L'amitié et la sagesse des proverbes","phrases":[{"fr":"Un vieux proverbe dit : « L'ami, c'est dans la détresse qu'on le reconnaît. »","tgt":"يَقُولُ مَثَلٌ قَدِيمٌ: «الصَّدِيقُ وَقْتَ الضِّيقِ».","ro":"Yaqūlu mathalun qadīmun: «aṣ-ṣadīqu waqta aḍ-ḍīqi»."},{"fr":"Mon ami Karim m'a soutenu dans les moments difficiles.","tgt":"سَانَدَنِي صَدِيقِي كَرِيمٌ فِي الْأَوْقَاتِ الصَّعْبَةِ.","ro":"Sānadanī ṣadīqī Karīmun fī al-awqāti aṣ-ṣaʿbati."},{"fr":"Nous nous sommes connus à l'école primaire.","tgt":"تَعَارَفْنَا فِي الْمَدْرَسَةِ الِابْتِدَائِيَّةِ.","ro":"Taʿārafnā fī al-madrasati al-ibtidāʾiyyati."},{"fr":"On dit aussi : « Le voisin avant la maison. »","tgt":"يُقَالُ أَيْضًا: «الْجَارُ قَبْلَ الدَّارِ».","ro":"Yuqālu ayḍan: «al-jāru qabla ad-dāri»."},{"fr":"Le proverbe dit : « Il est des frères que ta mère n'a pas mis au monde. »","tgt":"يَقُولُ الْمَثَلُ: «رُبَّ أَخٍ لَكَ لَمْ تَلِدْهُ أُمُّكَ».","ro":"Yaqūlu al-mathalu: «rubba akhin laka lam talidhu ummuka»."},{"fr":"Pour moi, Karim est un frère de ce genre.","tgt":"كَرِيمٌ بِالنِّسْبَةِ إِلَيَّ أَخٌ مِنْ هَذَا النَّوْعِ.","ro":"Karīmun bi-n-nisbati ilayya akhun min hādhā an-nawʿi."},{"fr":"Nous sommes restés amis malgré la distance.","tgt":"بَقِينَا أَصْدِقَاءَ رَغْمَ الْمَسَافَةِ.","ro":"Baqīnā aṣdiqāʾa raghma al-masāfati."},{"fr":"On dit souvent : « La patience est la clé du soulagement. »","tgt":"كَثِيرًا مَا يُقَالُ: «الصَّبْرُ مِفْتَاحُ الْفَرَجِ».","ro":"Kathīran mā yuqālu: «aṣ-ṣabru miftāḥu al-faraji»."},{"fr":"Il m'a rappelé que « qui sème récolte ».","tgt":"ذَكَّرَنِي بِأَنَّ «مَنْ زَرَعَ حَصَدَ».","ro":"Dhakkaranī bi-anna «man zaraʿa ḥaṣada»."},{"fr":"Les proverbes résument la sagesse de nombreuses générations.","tgt":"تُلَخِّصُ الْأَمْثَالُ حِكْمَةَ أَجْيَالٍ عَدِيدَةٍ.","ro":"Tulakhkhiṣu al-amthālu ḥikmata ajyālin ʿadīdatin."}],"tip":{"title":"Les proverbes arabes","example":"Un vieux proverbe dit : « L'ami, c'est dans la détresse qu'on le reconnaît. » — يَقُولُ مَثَلٌ قَدِيمٌ: «<b>الصَّدِيقُ</b> وَقْتَ <b>الضِّيقِ</b>».","body":"Les Arabes adorent glisser un proverbe, un « mathal », dans la conversation. Ils sont courts et souvent rimés, ce qui les rend faciles à retenir. Notre exemple, « as-sadiqu waqta d-diq », se dit littéralement : l'ami, au moment de la détresse ; « sadiq » et « diq » riment. De même, « al-jaru qabla d-dar », le voisin avant la maison, conseille de bien choisir ses voisins, et « as-sabru miftahu l-faraj » dit que la patience est la clé du soulagement. Astuce : apprenez un proverbe par semaine et placez-le au bon moment, vos interlocuteurs seront ravis.","exampleRo":"Yaqūlu mathalun qadīmun: «aṣ-ṣadīqu waqta aḍ-ḍīqi».","lit":"dit · proverbe · ancien · l'ami · moment · la-détresse","say":{"mathal":"مَثَل","as-sadiqu waqta d-diq":"الصَّدِيقُ وَقْتَ الضِّيق","sadiq":"صَدِيق","diq":"ضِيق","al-jaru qabla d-dar":"الْجَارُ قَبْلَ الدَّار","as-sabru miftahu l-faraj":"الصَّبْرُ مِفْتَاحُ الْفَرَج"}}},{"title":"Donner du sens à son travail","phrases":[{"fr":"Pour moi, le travail ne se résume pas au salaire.","tgt":"بِالنِّسْبَةِ إِلَيَّ، لَا يَقْتَصِرُ الْعَمَلُ عَلَى الرَّاتِبِ.","ro":"Bi-n-nisbati ilayya, lā yaqtaṣiru al-ʿamalu ʿalā ar-rātibi."},{"fr":"Je cherche un métier qui a du sens.","tgt":"أَبْحَثُ عَنْ مِهْنَةٍ لَهَا مَعْنًى.","ro":"Abḥathu ʿan mihnatin lahā maʿnan."},{"fr":"Ma sœur a quitté la banque pour ouvrir une librairie à Amman.","tgt":"تَرَكَتْ أُخْتِي الْبَنْكَ لِتَفْتَحَ مَكْتَبَةً فِي عَمَّانَ.","ro":"Tarakat ukhtī al-banka li-taftaḥa maktabatan fī ʿAmmāna."},{"fr":"Elle gagne moins, mais elle est beaucoup plus heureuse.","tgt":"تَكْسِبُ أَقَلَّ، لَكِنَّهَا أَسْعَدُ بِكَثِيرٍ.","ro":"Taksibu aqalla, lākinnahā asʿadu bi-kathīrin."},{"fr":"L'artisanat traditionnel attire de nouveau les jeunes.","tgt":"تَجْذِبُ الْحِرَفُ التَّقْلِيدِيَّةُ الشَّبَابَ مِنْ جَدِيدٍ.","ro":"Tajdhibu al-ḥirafu at-taqlīdiyyatu ash-shabāba min jadīdin."},{"fr":"Le travail en équipe demande de l'écoute et de la patience.","tgt":"يَتَطَلَّبُ الْعَمَلُ الْجَمَاعِيُّ الْإِصْغَاءَ وَالصَّبْرَ.","ro":"Yataṭallabu al-ʿamalu al-jamāʿiyyu al-iṣghāʾa wa-ṣ-ṣabra."},{"fr":"Mon collègue tunisien m'a appris beaucoup de choses.","tgt":"عَلَّمَنِي زَمِيلِي التُّونِسِيُّ أَشْيَاءَ كَثِيرَةً.","ro":"ʿAllamanī zamīlī at-tūnisiyyu ashyāʾa kathīratan."},{"fr":"Le télétravail a changé notre rapport au bureau.","tgt":"غَيَّرَ الْعَمَلُ عَنْ بُعْدٍ عَلَاقَتَنَا بِالْمَكْتَبِ.","ro":"Ghayyara al-ʿamalu ʿan buʿdin ʿalāqatanā bi-l-maktabi."},{"fr":"Il est important de trouver un équilibre entre le travail et la vie privée.","tgt":"مِنَ الْمُهِمِّ أَنْ نَجِدَ تَوَازُنًا بَيْنَ الْعَمَلِ وَالْحَيَاةِ الْخَاصَّةِ.","ro":"Mina al-muhimmi an najida tawāzunan bayna al-ʿamali wa-l-ḥayāti al-khāṣṣati."},{"fr":"Le travail bien fait procure une vraie fierté.","tgt":"يَمْنَحُ الْعَمَلُ الْمُتْقَنُ شُعُورًا حَقِيقِيًّا بِالْفَخْرِ.","ro":"Yamnaḥu al-ʿamalu al-mutqanu shuʿūran ḥaqīqiyyan bi-l-fakhri."}]},{"title":"Une soirée de musique arabe","phrases":[{"fr":"Hier soir, nous avons écouté un concert de oud.","tgt":"اسْتَمَعْنَا مَسَاءَ أَمْسِ إِلَى حَفْلَةِ عُودٍ.","ro":"Istamaʿnā masāʾa amsi ilā ḥaflati ʿūdin."},{"fr":"Le musicien jouait les yeux fermés.","tgt":"كَانَ الْعَازِفُ يَعْزِفُ وَعَيْنَاهُ مُغْمَضَتَانِ.","ro":"Kāna al-ʿāzifu yaʿzifu wa-ʿaynāhu mughmaḍatāni."},{"fr":"Le public était plongé dans des émotions profondes.","tgt":"كَانَ الْجُمْهُورُ غَارِقًا فِي مَشَاعِرَ عَمِيقَةٍ.","ro":"Kāna al-jumhūru ghāriqan fī mashāʿira ʿamīqatin."},{"fr":"Les Arabes appellent cet état le « tarab ».","tgt":"يُسَمِّي الْعَرَبُ هَذِهِ الْحَالَةَ «الطَّرَبَ».","ro":"Yusammī al-ʿarabu hādhihi al-ḥālata «aṭ-ṭaraba»."},{"fr":"Les chansons d'Oum Kalthoum duraient parfois une heure entière.","tgt":"كَانَتْ أُغْنِيَاتُ أُمِّ كُلْثُومٍ تَدُومُ أَحْيَانًا سَاعَةً كَامِلَةً.","ro":"Kānat ughniyātu Ummi Kulthūmin tadūmu aḥyānan sāʿatan kāmilatan."},{"fr":"Mes parents écoutent encore ses disques le dimanche.","tgt":"مَا زَالَ وَالِدَايَ يَسْتَمِعَانِ إِلَى أُسْطُوَانَاتِهَا يَوْمَ الْأَحَدِ.","ro":"Mā zāla wālidāya yastamiʿāni ilā usṭuwānātihā yawma al-aḥadi."},{"fr":"La musique arabe repose sur des modes appelés maqâms.","tgt":"تَقُومُ الْمُوسِيقَى الْعَرَبِيَّةُ عَلَى أَنْغَامٍ تُسَمَّى الْمَقَامَاتِ.","ro":"Taqūmu al-mūsīqā al-ʿarabiyyatu ʿalā anghāmin tusammā al-maqāmāti."},{"fr":"Chaque maqâm exprime une humeur différente.","tgt":"يُعَبِّرُ كُلُّ مَقَامٍ عَنْ حَالَةٍ نَفْسِيَّةٍ مُخْتَلِفَةٍ.","ro":"Yuʿabbiru kullu maqāmin ʿan ḥālatin nafsiyyatin mukhtalifatin."},{"fr":"J'aimerais apprendre à jouer du oud.","tgt":"أَتَمَنَّى أَنْ أَتَعَلَّمَ الْعَزْفَ عَلَى الْعُودِ.","ro":"Atamannā an ataʿallama al-ʿazfa ʿalā al-ʿūdi."},{"fr":"La musique réunit des gens qui ne parlent pas la même langue.","tgt":"تَجْمَعُ الْمُوسِيقَى أُنَاسًا لَا يَتَكَلَّمُونَ اللُّغَةَ نَفْسَهَا.","ro":"Tajmaʿu al-mūsīqā unāsan lā yatakallamūna al-lughata nafsahā."}]},{"title":"Le plaisir de lire en arabe","phrases":[{"fr":"Les romans de Naguib Mahfouz décrivent la vie au Caire.","tgt":"تَصِفُ رِوَايَاتُ نَجِيبِ مَحْفُوظٍ الْحَيَاةَ فِي الْقَاهِرَةِ.","ro":"Taṣifu riwāyātu Najībi Maḥfūẓin al-ḥayāta fī al-Qāhirati."},{"fr":"Je lis un roman arabe chaque mois.","tgt":"أَقْرَأُ رِوَايَةً عَرَبِيَّةً كُلَّ شَهْرٍ.","ro":"Aqraʾu riwāyatan ʿarabiyyatan kulla shahrin."},{"fr":"Au début, j'avais toujours un dictionnaire à côté de moi.","tgt":"فِي الْبِدَايَةِ، كَانَ الْقَامُوسُ دَائِمًا بِجَانِبِي.","ro":"Fī al-bidāyati, kāna al-qāmūsu dāʾiman bi-jānibī."},{"fr":"Maintenant, je devine le sens de nombreux mots grâce au contexte.","tgt":"الْآنَ أُخَمِّنُ مَعْنَى كَلِمَاتٍ كَثِيرَةٍ بِفَضْلِ السِّيَاقِ.","ro":"Al-āna ukhamminu maʿnā kalimātin kathīratin bi-faḍli as-siyāqi."},{"fr":"La racine d'un mot aide souvent à comprendre son sens.","tgt":"كَثِيرًا مَا يُسَاعِدُ جَذْرُ الْكَلِمَةِ عَلَى فَهْمِ مَعْنَاهَا.","ro":"Kathīran mā yusāʿidu jadhru al-kalimati ʿalā fahmi maʿnāhā."},{"fr":"Les contes des Mille et Une Nuits ont fait rêver le monde entier.","tgt":"حِكَايَاتُ أَلْفِ لَيْلَةٍ وَلَيْلَةٍ جَعَلَتِ الْعَالَمَ كُلَّهُ يَحْلُمُ.","ro":"Ḥikāyātu alfi laylatin wa-laylatin jaʿalati al-ʿālama kullahu yaḥlumu."},{"fr":"Shéhérazade racontait une histoire chaque nuit pour sauver sa vie.","tgt":"كَانَتْ شَهْرَزَادُ تَرْوِي حِكَايَةً كُلَّ لَيْلَةٍ لِتُنْقِذَ حَيَاتَهَا.","ro":"Kānat Shahrazādu tarwī ḥikāyatan kulla laylatin li-tunqidha ḥayātahā."},{"fr":"Le Salon du livre du Caire attire des foules chaque année.","tgt":"يَجْذِبُ مَعْرِضُ الْقَاهِرَةِ لِلْكِتَابِ حُشُودًا كُلَّ عَامٍ.","ro":"Yajdhibu maʿriḍu al-Qāhirati li-l-kitābi ḥushūdan kulla ʿāmin."},{"fr":"Lire en arabe m'a ouvert un monde nouveau.","tgt":"فَتَحَتْ لِيَ الْقِرَاءَةُ بِالْعَرَبِيَّةِ عَالَمًا جَدِيدًا.","ro":"Fataḥat liya al-qirāʾatu bi-l-ʿarabiyyati ʿālaman jadīdan."},{"fr":"Je prête volontiers mes livres à mes amis.","tgt":"أُعِيرُ كُتُبِي لِأَصْدِقَائِي عَنْ طِيبِ خَاطِرٍ.","ro":"Uʿīru kutubī li-aṣdiqāʾī ʿan ṭībi khāṭirin."}]},{"title":"Rire de ses malentendus","phrases":[{"fr":"Le premier jour, j'ai commis une erreur amusante.","tgt":"فِي الْيَوْمِ الْأَوَّلِ، ارْتَكَبْتُ خَطَأً مُضْحِكًا.","ro":"Fī al-yawmi al-awwali, irtakabtu khaṭaʾan muḍḥikan."},{"fr":"J'ai confondu « chien » et « cœur ».","tgt":"خَلَطْتُ بَيْنَ «كَلْبٍ» وَ«قَلْبٍ».","ro":"Khalaṭtu bayna «kalbin» wa-«qalbin»."},{"fr":"Tout le monde a ri, et moi aussi.","tgt":"ضَحِكَ الْجَمِيعُ، وَضَحِكْتُ أَنَا أَيْضًا.","ro":"Ḍaḥika al-jamīʿu, wa-ḍaḥiktu anā ayḍan."},{"fr":"Depuis, je fais très attention à la prononciation.","tgt":"مُنْذُ ذَلِكَ الْحِينِ، أَنْتَبِهُ كَثِيرًا إِلَى النُّطْقِ.","ro":"Mundhu dhālika al-ḥīni, antabihu kathīran ilā an-nuṭqi."},{"fr":"Une autre fois, j'ai refusé un café par politesse.","tgt":"فِي مَرَّةٍ أُخْرَى، رَفَضْتُ الْقَهْوَةَ مِنْ بَابِ الْأَدَبِ.","ro":"Fī marratin ukhrā, rafaḍtu al-qahwata min bābi al-adabi."},{"fr":"Mon hôte a cru que je n'aimais pas son café.","tgt":"ظَنَّ مُضِيفِي أَنَّنِي لَا أُحِبُّ قَهْوَتَهُ.","ro":"Ẓanna muḍīfī annanī lā uḥibbu qahwatahu."},{"fr":"J'ai beaucoup appris sur la culture grâce à ces situations.","tgt":"تَعَلَّمْتُ الْكَثِيرَ عَنِ الثَّقَافَةِ مِنْ هَذِهِ الْمَوَاقِفِ.","ro":"Taʿallamtu al-kathīra ʿani ath-thaqāfati min hādhihi al-mawāqifi."},{"fr":"L'erreur fait partie intégrante de tout apprentissage.","tgt":"الْخَطَأُ جُزْءٌ لَا يَتَجَزَّأُ مِنْ كُلِّ تَعَلُّمٍ.","ro":"Al-khaṭaʾu juzʾun lā yatajazzaʾu min kulli taʿallumin."},{"fr":"Les gens apprécient toujours l'effort de celui qui parle leur langue.","tgt":"يُقَدِّرُ النَّاسُ دَائِمًا مَجْهُودَ مَنْ يَتَكَلَّمُ لُغَتَهُمْ.","ro":"Yuqaddiru an-nāsu dāʾiman majhūda man yatakallamu lughatahum."},{"fr":"Aujourd'hui, je raconte ces anecdotes en riant.","tgt":"الْيَوْمَ أَحْكِي هَذِهِ الطَّرَائِفَ وَأَنَا أَضْحَكُ.","ro":"Al-yawma aḥkī hādhihi aṭ-ṭarāʾifa wa-anā aḍḥaku."}]},{"title":"Imaginer l'avenir","phrases":[{"fr":"Comment imagines-tu le monde arabe dans vingt ans ?","tgt":"كَيْفَ تَتَخَيَّلُ الْعَالَمَ الْعَرَبِيَّ بَعْدَ عِشْرِينَ سَنَةً؟","ro":"Kayfa tatakhayyalu al-ʿālama al-ʿarabiyya baʿda ʿishrīna sanatan?"},{"fr":"Je pense que les jeunes y joueront un rôle essentiel.","tgt":"أَظُنُّ أَنَّ الشَّبَابَ سَيَلْعَبُونَ فِيهِ دَوْرًا أَسَاسِيًّا.","ro":"Aẓunnu anna ash-shabāba sa-yalʿabūna fīhi dawran asāsiyyan."},{"fr":"Les villes deviendront plus vertes et plus intelligentes.","tgt":"سَتُصْبِحُ الْمُدُنُ أَكْثَرَ خُضْرَةً وَذَكَاءً.","ro":"Sa-tuṣbiḥu al-mudunu akthara khuḍratan wa-dhakāʾan."},{"fr":"L'énergie solaire pourrait changer la vie dans le désert.","tgt":"قَدْ تُغَيِّرُ الطَّاقَةُ الشَّمْسِيَّةُ الْحَيَاةَ فِي الصَّحْرَاءِ.","ro":"Qad tughayyiru aṭ-ṭāqatu ash-shamsiyyatu al-ḥayāta fī aṣ-ṣaḥrāʾi."},{"fr":"J'espère que la langue arabe continuera à briller.","tgt":"أَتَمَنَّى أَنْ تَظَلَّ اللُّغَةُ الْعَرَبِيَّةُ مُتَأَلِّقَةً.","ro":"Atamannā an taẓalla al-lughatu al-ʿarabiyyatu mutaʾalliqatan."},{"fr":"Il faudra aussi protéger notre patrimoine.","tgt":"سَيَكُونُ عَلَيْنَا أَيْضًا أَنْ نَحْمِيَ تُرَاثَنَا.","ro":"Sa-yakūnu ʿalaynā ayḍan an naḥmiya turāthanā."},{"fr":"La technologie ne doit pas effacer les traditions.","tgt":"يَجِبُ أَلَّا تَمْحُوَ التِّكْنُولُوجِيَا التَّقَالِيدَ.","ro":"Yajibu allā tamḥuwa at-tiknūlūjiyā at-taqālīda."},{"fr":"Personnellement, je compte vivre quelque temps à Mascate.","tgt":"شَخْصِيًّا، أَنْوِي أَنْ أَعِيشَ فَتْرَةً فِي مَسْقَطَ.","ro":"Shakhṣiyyan, anwī an aʿīsha fatratan fī Masqaṭa."},{"fr":"Je ne sais pas ce que demain me réserve.","tgt":"لَا أَعْرِفُ مَاذَا يُخَبِّئُ لِيَ الْغَدُ.","ro":"Lā aʿrifu mādhā yukhabbiʾu liya al-ghadu."},{"fr":"Mais je regarde l'avenir avec optimisme.","tgt":"لَكِنَّنِي أَنْظُرُ إِلَى الْمُسْتَقْبَلِ بِتَفَاؤُلٍ.","ro":"Lākinnanī anẓuru ilā al-mustaqbali bi-tafāʾulin."}]},{"title":"Un au revoir à Marrakech","phrases":[{"fr":"Demain, je quitte Marrakech après six mois.","tgt":"غَدًا أُغَادِرُ مَرَّاكُشَ بَعْدَ سِتَّةِ أَشْهُرٍ.","ro":"Ghadan ughādiru Marrākusha baʿda sittati ashhurin."},{"fr":"Mes amis ont organisé un dîner d'adieu.","tgt":"نَظَّمَ أَصْدِقَائِي عَشَاءَ وَدَاعٍ.","ro":"Naẓẓama aṣdiqāʾī ʿashāʾa wadāʿin."},{"fr":"Ils ont préparé un tajine aux pruneaux, mon plat préféré.","tgt":"حَضَّرُوا طَاجِينًا بِالْبَرْقُوقِ، طَبَقِيَ الْمُفَضَّلَ.","ro":"Ḥaḍḍarū ṭājīnan bi-l-barqūqi, ṭabaqiya al-mufaḍḍala."},{"fr":"J'ai du mal à croire que ce séjour est terminé.","tgt":"لَا أَكَادُ أُصَدِّقُ أَنَّ هَذِهِ الْإِقَامَةَ انْتَهَتْ.","ro":"Lā akādu uṣaddiqu anna hādhihi al-iqāmata intahat."},{"fr":"Mon amie Salma m'a offert un petit tapis berbère.","tgt":"أَهْدَتْنِي صَدِيقَتِي سَلْمَى سَجَّادَةً أَمَازِيغِيَّةً صَغِيرَةً.","ro":"Ahdatnī ṣadīqatī Salmā sajjādatan amāzīghiyyatan ṣaghīratan."},{"fr":"« Ne nous oublie pas », m'a-t-elle dit les larmes aux yeux.","tgt":"قَالَتْ لِي وَالدُّمُوعُ فِي عَيْنَيْهَا: «لَا تَنْسَنَا».","ro":"Qālat lī wa-d-dumūʿu fī ʿaynayhā: «lā tansanā»."},{"fr":"Je lui ai promis de revenir l'été prochain.","tgt":"وَعَدْتُهَا بِأَنْ أَعُودَ فِي الصَّيْفِ الْقَادِمِ.","ro":"Waʿadtuhā bi-an aʿūda fī aṣ-ṣayfi al-qādimi."},{"fr":"Les adieux sont toujours plus difficiles qu'on ne le pense.","tgt":"الْوَدَاعُ دَائِمًا أَصْعَبُ مِمَّا نَظُنُّ.","ro":"Al-wadāʿu dāʾiman aṣʿabu mimmā naẓunnu."},{"fr":"Je porterai cette ville dans mon cœur.","tgt":"سَأَحْمِلُ هَذِهِ الْمَدِينَةَ فِي قَلْبِي.","ro":"Sa-aḥmilu hādhihi al-madīnata fī qalbī."},{"fr":"Nous ne disons pas adieu, mais à bientôt.","tgt":"لَا نَقُولُ وَدَاعًا، بَلْ إِلَى اللِّقَاءِ قَرِيبًا.","ro":"Lā naqūlu wadāʿan, bal ilā al-liqāʾi qarīban."}]},{"title":"Regarder en arrière sur ce parcours en arabe","phrases":[{"fr":"Quand j'ai commencé, l'alphabet arabe me semblait mystérieux.","tgt":"عِنْدَمَا بَدَأْتُ، كَانَتِ الْحُرُوفُ الْعَرَبِيَّةُ تَبْدُو لِي غَامِضَةً.","ro":"ʿIndamā badaʾtu, kānati al-ḥurūfu al-ʿarabiyyatu tabdū lī ghāmiḍatan."},{"fr":"Je ne savais même pas dire « bonjour ».","tgt":"لَمْ أَكُنْ أَعْرِفُ حَتَّى كَيْفَ أَقُولُ «صَبَاحَ الْخَيْرِ».","ro":"Lam akun aʿrifu ḥattā kayfa aqūlu «ṣabāḥa al-khayri»."},{"fr":"Les lettres aïn et ha m'ont donné beaucoup de mal.","tgt":"أَتْعَبَنِي حَرْفَا الْعَيْنِ وَالْحَاءِ كَثِيرًا.","ro":"Atʿabanī ḥarfā al-ʿayni wa-l-ḥāʾi kathīran."},{"fr":"Puis, petit à petit, la langue s'est ouverte à moi.","tgt":"ثُمَّ، شَيْئًا فَشَيْئًا، انْفَتَحَتْ لِيَ اللُّغَةُ.","ro":"Thumma, shayʾan fa-shayʾan, infataḥat liya al-lughatu."},{"fr":"J'ai appris à penser en racines de trois lettres.","tgt":"تَعَلَّمْتُ أَنْ أُفَكِّرَ بِالْجُذُورِ الثُّلَاثِيَّةِ.","ro":"Taʿallamtu an ufakkira bi-l-judhūri ath-thulāthiyyati."},{"fr":"Les premières conversations me rendaient très nerveux.","tgt":"كَانَتِ الْمُحَادَثَاتُ الْأُولَى تُوَتِّرُنِي كَثِيرًا.","ro":"Kānati al-muḥādathātu al-ūlā tuwattirunī kathīran."},{"fr":"Aujourd'hui, je peux débattre de culture en arabe.","tgt":"الْيَوْمَ أَسْتَطِيعُ أَنْ أُنَاقِشَ الثَّقَافَةَ بِالْعَرَبِيَّةِ.","ro":"Al-yawma astaṭīʿu an unāqisha ath-thaqāfata bi-l-ʿarabiyyati."},{"fr":"Mes trajets quotidiens sont devenus de vrais moments d'apprentissage.","tgt":"أَصْبَحَتْ رِحْلَاتِي الْيَوْمِيَّةُ لَحَظَاتِ تَعَلُّمٍ حَقِيقِيَّةً.","ro":"Aṣbaḥat riḥlātī al-yawmiyyatu laḥaẓāti taʿallumin ḥaqīqiyyatan."},{"fr":"Je suis fier du long chemin que j'ai parcouru en arabe.","tgt":"أَنَا فَخُورٌ بِالطَّرِيقِ الطَّوِيلِ الَّذِي قَطَعْتُهُ فِي الْعَرَبِيَّةِ.","ro":"Anā fakhūrun bi-ṭ-ṭarīqi aṭ-ṭawīli alladhī qaṭaʿtuhu fī al-ʿarabiyyati."},{"fr":"Chaque effort pour apprendre l'arabe en valait la peine.","tgt":"كَانَ كُلُّ جُهْدٍ لِتَعَلُّمِ الْعَرَبِيَّةِ يَسْتَحِقُّ الْعَنَاءَ.","ro":"Kāna kullu juhdin li-taʿallumi al-ʿarabiyyati yastaḥiqqu al-ʿanāʾa."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Ce dernier module nous a fait voyager à travers la culture arabe.","tgt":"جَعَلَتْنَا هَذِهِ الْوَحْدَةُ الْأَخِيرَةُ نُسَافِرُ عَبْرَ الثَّقَافَةِ الْعَرَبِيَّةِ.","ro":"Jaʿalatnā hādhihi al-waḥdatu al-akhīratu nusāfiru ʿabra ath-thaqāfati al-ʿarabiyyati."},{"fr":"Poésie, calligraphie, cuisine : nous avons tout exploré en arabe.","tgt":"الشِّعْرُ وَالْخَطُّ وَالْمَطْبَخُ: اسْتَكْشَفْنَا كُلَّ ذَلِكَ بِالْعَرَبِيَّةِ.","ro":"Ash-shiʿru wa-l-khaṭṭu wa-l-maṭbakhu: istakshafnā kulla dhālika bi-l-ʿarabiyyati."},{"fr":"Les cas, le duel et les mots de liaison nous sont désormais familiers.","tgt":"أَصْبَحَ الْإِعْرَابُ وَالْمُثَنَّى وَأَدَوَاتُ الرَّبْطِ مَأْلُوفَةً لَنَا.","ro":"Aṣbaḥa al-iʿrābu wa-l-muthannā wa-adawātu ar-rabṭi maʾlūfatan lanā."},{"fr":"Nous savons maintenant glisser un proverbe dans la conversation.","tgt":"نَعْرِفُ الْآنَ كَيْفَ نُدْخِلُ مَثَلًا فِي الْحَدِيثِ.","ro":"Naʿrifu al-āna kayfa nudkhilu mathalan fī al-ḥadīthi."},{"fr":"Le voyage ne s'arrête pas ici, bien au contraire.","tgt":"لَا تَتَوَقَّفُ الرِّحْلَةُ هُنَا، بَلْ عَلَى الْعَكْسِ تَمَامًا.","ro":"Lā tatawaqqafu ar-riḥlatu hunā, bal ʿalā al-ʿaksi tamāman."},{"fr":"Devant nous restent les dialectes, la littérature et bien plus encore.","tgt":"مَا زَالَتْ أَمَامَنَا اللَّهَجَاتُ وَالْأَدَبُ وَأَكْثَرُ مِنْ ذَلِكَ بِكَثِيرٍ.","ro":"Mā zālat amāmanā al-lahajātu wa-l-adabu wa-aktharu min dhālika bi-kathīrin."},{"fr":"Continue à écouter, à lire et surtout à parler.","tgt":"وَاصِلِ الِاسْتِمَاعَ وَالْقِرَاءَةَ، وَخَاصَّةً الْكَلَامَ.","ro":"Wāṣili al-istimāʿa wa-l-qirāʾata, wa-khāṣṣatan al-kalāma."},{"fr":"La meilleure façon de progresser, c'est de parler avec les gens.","tgt":"أَفْضَلُ طَرِيقَةٍ لِلتَّقَدُّمِ هِيَ الْحَدِيثُ مَعَ النَّاسِ.","ro":"Afḍalu ṭarīqatin li-t-taqaddumi hiya al-ḥadīthu maʿa an-nāsi."},{"fr":"Merci d'avoir partagé avec nous ce long voyage dans la langue arabe.","tgt":"شُكْرًا لِأَنَّكَ شَارَكْتَنَا هَذِهِ الرِّحْلَةَ الطَّوِيلَةَ فِي اللُّغَةِ الْعَرَبِيَّةِ.","ro":"Shukran li-annaka shāraktanā hādhihi ar-riḥlata aṭ-ṭawīlata fī al-lughati al-ʿarabiyyati."},{"fr":"Au revoir, et bonne chance dans ton voyage avec l'arabe !","tgt":"إِلَى اللِّقَاءِ، وَبِالتَّوْفِيقِ فِي رِحْلَتِكَ مَعَ الْعَرَبِيَّةِ!","ro":"Ilā al-liqāʾi, wa-bi-t-tawfīqi fī riḥlatika maʿa al-ʿarabiyyati!"}]}]}]}];
